insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 40, "Según el artículo 32 del Estatuto de autonomía de las Illes Balears, la Comunidad Autónoma de las Illes Balears tiene la competencia ejecutiva en materia:", "De legislación laboral.", "De régimen local.", "De espectáculos y actividades recreativas.", "De cultura."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 41, "Según el artículo 32 del Estatuto de autonomía de las Illes Balears, la Comunidad Autónoma de las Illes Balears tiene la competencia ejecutiva en materia:", "De ordenación de la hacienda de la Comunidad Autónoma, de acuerdo con lo que establece el Estatuto.", "De crédito, banca y seguros.", "De archivos, bibliotecas y museos que no sean de titularidad estatal.", "De servicio meteorológico de la comunidad autónoma."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 42, "Según el artículo 36 del Estatuto de autonomía de las Illes Balears, ¿qué tipo de competencias tiene la Comunidad Autónoma de las Illes Balears en la creación, la organización y el régimen de los centros públicos de enseñanza no universitaria?", "Competencia exclusiva.", "Competencia de desarrollo legislativo.", "Competencia de desarrollo legislativo y ejecución.", "Competencia ejecutiva."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 43, "Según el artículo 36 del Estatuto de autonomía de las Illes Balears, ¿qué tipo de competencias tiene la Comunidad Autónoma de las Illes Balears  sobre la expedición y la homologación de los títulos académicos y profesionales estatales de enseñanza no universitaria?", "Competencia exclusiva.", "Competencia de desarrollo legislativo.", "Competencia de desarrollo legislativo y ejecución.", "Competencia ejecutiva."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 44, "Según el artículo 39 del Estatuto de autonomía de las Illes Balears ,el sistema institucional autonómico está integrado:", "Por el Parlamento, el Gobierno y el presidente de la comunidad autónoma.", "Por el Parlamento, el Gobierno y los consejos insulares.", "Por el Parlamento, el Gobierno, los consejos insulares y los ayuntamientos.", "Por el Parlamento, el Gobierno ,el presidente de la comunidad autónoma y los consejos insulares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 45, "Según el artículo 40 del Estatuto de autonomía de las Illes Balears ¿cuáles son las funciones del Parlamento?", "Representa al pueblo de las Illes Balears.", "Ejerce la potestad legislativa.", "Elabora los presupuestos de la Comunidad Autónoma.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 46, "Según el artículo 41 del Estatuto de autonomía de las Illes Balears, los diputados del territorio autónomo que forman el Parlamento son elegidos:", "Por sufragio universal, igual, libre, directo y secreto.", "Por sufragio universal,  libre, directo y secreto.", "Por sufragio universal, proporcional, libre, directo y secreto.", "Por sufragio universal, igual, representativo, directo y secreto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 47, "Según el artículo 42 del Estatuto de autonomía de las Illes Balears, ¿ puede ser elegido diputado del Parlamento cualquier ciudadano español residente en las Illes Balears ?", "Sí , si está inscrito en el censo electoral de las Illes Balears.", "Sí , si está inscrito en el censo electoral de las Illes Balears y sean mayores de edad.", "Sí , si está inscrito en el censo electoral de las Illes Balears, sean mayores de edad y se hallen en pleno ejercicio de sus derechos civiles y políticos.", "No."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 48, "Según el artículo 44 del Estatuto de autonomía de las Illes Balears ,el voto de los diputados  del Parlamento es:", "Personal e intransferible.", "Personal, intransferible e indelegable.", "Personal, libre y único.", "Personal e indelegable."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 49, "Según el artículo 45 del Estatuto de autonomía de las Illes Balears, ¿qué tipo de norma regula la composición y las reglas de elección del Parlamento?", "Una ley del Parlamento.", "Un reglamento del Parlamento.", "Un decreto del Gobierno.", "Una ley de las Cortes Generales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 50, "Según el artículo 45 del Estatuto de autonomía de las Illes Balears, ¿cuándo se puede reunir el Parlamento en sesión extraordinaria?", "A petición del Gobierno.", "Por acuerdo de la Diputación Permanente o del Pleno, a propuesta de una quinta parte de los Diputados.", "Por acuerdo del Pleno, a propuesta de una cuarta parte de los Diputados.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 51, "Según el artículo 47 del Estatuto de autonomía de las Illes Balears, los consejos insulares pueden :", "Solicitar del Gobierno la adopción de un proyecto de ley.", "Solicitar del Parlamento la adopción de un proyecto de ley.", "Remitir a la Mesa del Parlamento una proposición de ley.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 52, "Según el artículo 48 del Estatuto de autonomía de las Illes Balears, al efecto de la entrada en vigor de las leyes del Parlamento rige :", "La fecha de publicación en el  Boletín Oficial del Estado.", "La fecha de publicación en el  Diario Oficial de la Unión Europea.", "La fecha de publicación en el Boletín Oficial de las Illes Balears.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 53, "Según el artículo 49 del Estatuto de autonomía de las Illes Balears , ¿cuándo puede dictar un decreto ley el Consejo de Gobierno?", "Nunca, es el Parlamento quien puede dictar un  decreto ley.", "En caso de extraordinaria y urgente necesidad.", "En caso de una emergencia en las Illes Balears.", "Cuando haya una delegación por parte del Parlamento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 54, "Según el artículo 49 del Estatuto de autonomía de las Illes Balears,  ¿Cuándo  queda derogado un decreto ley?", "Si en el plazo improrrogable de veinte días subsiguientes a su promulgación no es convalidado expresamente por el Parlamento.", "Si en el plazo improrrogable de treinta días subsiguientes a su promulgación no es convalidado expresamente por el Parlamento.", "Si en el plazo improrrogable de veinticinco días subsiguientes a su promulgación no es convalidado expresamente por el Parlamento.", "Si en el plazo improrrogable de treinta y cinco días subsiguientes a su promulgación no es convalidado expresamente por el Parlamento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 55, "Según el artículo  54 del Estatuto de autonomía de las Illes Balears, ¿con qué mayoría de los diputados del Parlamento se puede otorgar la confianza al candidato a presidente de las Illes Balears, en una  primera votación?", "Con la mayoría absoluta.", "Con la mayoría simple.", "Con la mayoría de tres quintas partes.", "Con la mayoría de dos tercios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 56, "Según el artículo 54 del Estatuto de autonomía de las Illes Balears,  si un candidato a presidente de las Illes Balears no obtiene la confianza del Parlamento, ¿cuántos días han de transcurrir a partir de la primera votación para la investidura para disolver el Parlamento y convocar nuevas elecciones?", "Treinta días.", "Cuarenta días.", "Cincuenta días.", "Sesenta días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 57, "Según el artículo 55 del Estatuto de autonomía de las Illes Balears, ¿cuándo no se puede disolver el Parlamento?", "Cuando esté en trámite una cuestión de confianza.", "Cuando esté en trámite una moción de censura.", "Cuando esté en proceso una elección de presidente de las Illes Balears.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 58, "Según el artículo 56 del Estatuto de autonomía de las Illes Balears, ¿quién ejerce la más alta representación de la comunidad autónoma, así como la ordinaria del Estado en las Illes Balears?", "El delegado del Gobierno.", "El presidente del Parlamento.", "El presidente de las Illes Balears.", "El rey."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 59, "Según el artículo 56 del Estatuto de autonomía de las Illes Balears ,en caso de ausencia o enfermedad del presidente de las Illes Balears ¿quién ejerce la  representación de las Illes Balears?", "El delegado del Gobierno.", "El presidente del Parlamento.", "El vicepresidente.", "El rey."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 60, "Según el artículo 57 del Estatuto de autonomía de las Illes Balears,  ¿qué norma establece la organización del Gobierno?", "Una ley del Parlamento.", "Un decreto del Gobierno.", "Un acuerdo del Consejo de Gobierno.", "Una ley orgánica de las Cortes Generales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 61, "Según el artículo 58 del Estatuto de autonomía de las Illes Balears, sobre las competencias que los consejos insulares asuman como propias, el Gobierno de las Illes Balears:", "Ejerce la tutela.", "Puede establecer los principios generales sobre la materia.", "Garantiza la potestad reglamentaria por parte de los consejos insulares.", "Las respuestas b)  y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 62, "Según el artículo 75 del Estatuto de autonomía de las Illes Balears,  ¿cuál es la entidad local básica de la organización territorial de las Illes Balears?", "La isla.", "El municipio.", "La provincia.", "La comunidad autónoma."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 63, "Según el artículo 76 del Estatuto de autonomía de las Illes Balears , el Consejo Consultivo de las Illes Balears:", "Es una entidad pública independiente.", "Es el órgano colegiado de participación, estudio, deliberación, asesoramiento y propuesta en materia económica y jurídica.", "Es el superior órgano de consulta de la Comunidad Autónoma de las Illes Balears.", "Es el supremo órgano colegiado de consulta jurídica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 64, "Según el artículo 81 del Estatuto de autonomía de las Illes Balears, las leyes del Parlamento estarán únicamente sujetas al control jurisdiccional siguiente:", "Control jurisdiccional del Tribunal Supremo.", "Control de constitucionalidad del Tribunal Constitucional.", "Control de régimen competencial del Tribunal Superior de Justicia.", "Control jurisdiccional de la Audiencia Provincial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 65, "Según el artículo 95 del Estatuto de autonomía de las Illes Balears, el presidente del Tribunal Superior de Justicia es nombrado por el rey a propuesta del:", "Del Consejo General del Poder Judicial.", "Del Tribunal Supremo.", "De la Audiencia Provincial.", "De magistrados del Tribunal Superior de Justicia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 66, "Según el artículo 139 del Estatuto de autonomía de las Illes Balears, la iniciativa de reforma del Estatuto  corresponde:", "Al Parlamento.", "Al Gobierno de la Comunidad Autónoma.", "A las Cortes Generales.", "Las respuestas a) b) y c) son correctas"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 6, 67, "Según el artículo 139 del Estatuto de autonomía de las Illes Balears, ¿qué se requiere para que  prospere la reforma del Estatuto?", "La aprobación del Consejo de Gobierno por mayoría absoluta.", "La aprobación del Parlamento por mayoría de  dos tercios de los diputados.", "La aprobación de las Cortes Generales a través de una ley orgánica.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 1, "¿Cual de estas aportaciones dinerarias no quedan excluidos del ámbito de aplicación de la Ley 38/2003, de 17 de noviembre, General de Subvenciones?", "Los premios que se otorguen con la previa solicitud del beneficiario.", "Las subvenciones previstas en la Ley Orgánica 5/1985, de 19 de junio, del Régimen Electoral General.", "Las subvenciones reguladas en la Ley Orgánica 3/1987, de 2 de julio, de Financiación de los Partidos Políticos.", "Las subvenciones a los grupos políticos de las corporaciones locales, según establezca su propia normativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 2, "De acuerdo con la Ley 38/2003, de 17 de noviembre, General de Subvenciones, las subvenciones financiadas con cargo a fondos de la Unión Europea, se regirán:", "Por Ley 38/2003, de 17 de noviembre, General de Subvenciones exclusivamente.", "Por Ley 38/2003, de 17 de noviembre, General de Subvenciones y su normativa de desarrollo.", "Por las normas comunitarias aplicables en cada caso y por las normas nacionales de desarrollo o transposición de aquéllas, teniendo carácter supletorio los procedimientos de concesión y de control de las subvenciones regulados en la Ley 38/2003.", "Por la Ley 38/2003, de 17 de noviembre, General de Subvenciones y su normativa de desarrollo, teniendo carácter supletorio las normas comunitarias aplicables en cada caso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 3, "Señale la respuesta incorrecta. De acuerdo con la Ley 38/2003, de 17 de noviembre, General de Subvenciones, la gestión de las subvenciones se realizará de acuerdo con los siguientes principios:", "Publicidad, transparencia, concurrencia, objetividad, igualdad y no discriminación.", "Agilidad en la liquidación de la justificación de la aplicación de los fondos.", "Eficacia en el cumplimiento de los objetivos fijados por la Administración otorgante.", "Eficiencia en la asignación y utilización de los recursos públicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 4, "De acuerdo con la Ley 38/2003, de 17 de noviembre, General de Subvenciones, ¿podrán acceder a la condición de beneficiario las agrupaciones de personas físicas o jurídicas, públicas o privadas, las comunidades de bienes o cualquier otro tipo de unidad económica o patrimonio separado, aun careciendo de personalidad jurídica?", "Siempre.", "Nunca.", "Cuando se prevea expresamente en las bases reguladoras.", "Cuando lo prevea la propia Ley 38/2003."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 5, "Señale la respuesta correcta en relación a las entidades colaboradoras, de acuerdo con la Ley 38/2003, de 17 de noviembre, General de Subvenciones:", "Será entidad colaboradora aquella que, actuando en nombre propio, entregue y distribuya los fondos públicos a los beneficiarios cuando así se establezca en las bases reguladoras.", "No podrán tener la condición de entidad colaboradora los que habiendo sido denominados beneficiarios conforme a la normativa comunitaria tengan encomendadas, exclusivamente, funciones propias de una entidad colaboradora.", "Las comunidades autónomas y las corporaciones locales nunca podrán actuar como entidades colaboradoras de las subvenciones concedidas por la Administración General del Estado, sus organismos públicos y demás entes que tengan que ajustar su actividad al derecho público.", "La Administración General del Estado y sus organismos públicos podrán actuar como entidades colaboradoras respecto de las subvenciones concedidas por las comunidades autónomas y corporaciones locales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 6, "Señale cual de las siguientes respuestas es una obligación de los beneficiarios, de acuerdo con la Ley 38/2003, de 17 de noviembre, General de Subvenciones:", "Comunicar, en el plazo de 3 meses, al órgano concedente o la entidad colaboradora la obtención de otras subvenciones, ayudas, ingresos o recursos que financien las actividades subvencionadas.", "Disponer de los libros contables, registros diligenciados y demás documentos debidamente auditados en los términos exigidos por la legislación mercantil y sectorial aplicable al beneficiario en cada caso.", "Conservar los documentos justificativos de la aplicación de los fondos recibidos, incluidos los documentos electrónicos, durante el plazo de 4 años desde la concesión de la subvención.", "Acreditar en el plazo máximo de un mes después de dictarse la propuesta de resolución de concesión que se halla al corriente en el cumplimiento de sus obligaciones tributarias y frente a la Seguridad Social."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 7, "Señale cual de las siguientes respuestas no es una obligación de las entidades colaboradoras, de acuerdo con la Ley 38/2003, de 17 de noviembre, General de Subvenciones:", "Entregar a los beneficiarios los fondos recibidos de acuerdo con los criterios establecidos en las bases reguladoras de la subvención.", "Comprobar la realización de la actividad y el cumplimiento de la finalidad que determinen la concesión.", "Justificar la entrega de los fondos percibidos ante el órgano concedente de la subvención.", "Resolver el reintegro de los fondos percibidos en caso de incumplimiento de la justificación de aplicación de los fondos o realización de la actividad subvencionada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 8, "De acuerdo con el artículo 18 de la Ley 38/2003, de 17 de noviembre, General de Subvenciones, la Base de Datos Nacional de Subvenciones operará como:", "Sistema nacional de control económico de subvenciones.", "Sistema nacional de control de legalidad de subvenciones.", "Sistema nacional de control financiero y del gasto público de subvenciones.", "Sistema nacional de publicidad de subvenciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 9, "Señale la respuesta correcta en relación con la Base de Datos Nacional de Subvenciones, de acuerdo con la Ley 38/2003, de 17 de noviembre, General de Subvenciones:", "La Intervención General de la Administración del Estado es el órgano responsable de la administración y custodia de la Base de Datos Nacional de Subvenciones.", "La Base de Datos recogerá información de las subvenciones, sin poder establecerse la inclusión de otras ayudas públicas.", "El contenido de la Base de Datos incluirá, al menos, referencia a las bases reguladoras de la subvención, pero no será obligatorio incluir la convocatoria de la subvención.", "El contenido de la Base de Datos incluirá, al menos, la convocatoria de la subvención, pero no será obligatorio incluir el programa y crédito presupuestario al que se imputan."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 10, "De acuerdo con la Ley 38/2003, de 17 de noviembre, General de Subvenciones, el procedimiento ordinario de concesión de subvenciones:", "Será la concesión directa.", "Se tramitará en régimen de concurrencia competitiva.", "Se tramitará por prorrateo, entre todos los beneficiarios, del importe global destinado a la subvención.", "Lo decide el órgano competente en cada caso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 11, "De acuerdo con la Ley 38/2003, de 17 de noviembre, General de Subvenciones, el procedimiento para la concesión de subvenciones en régimen de concurrencia competitiva:", "Se inicia siempre a solicitud del interesado", "Se inicia siempre de oficio.", "Se puede iniciar tanto de oficio como a solicitud del interesado indistintamente.", "La forma de inicio dependerá de lo establecido en la convocatoria aprobada por el órgano competente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 12, "De acuerdo con la Ley 38/2003, la convocatoria de una subvención no tendrá necesariamente el siguiente contenido:", "Objeto, condiciones y finalidad de la concesión de la subvención.", "Criterios de valoración de las solicitudes.", "Plazo estimado de resolución y notificación.", "Requisitos para solicitar la subvención y forma de acreditarlos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 13, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre, por el que se aprueba el texto refundido de la Ley de subvenciones, las normas especiales reguladoras de las ayudas al exterior:", "Tienen que aprobarse por ley del parlamento.", "Tienen que aprobarse por resolución del Consejero competente en materia de Hacienda y Presupuestos", "Tienen que aprobarse por decreto del Consejo de Gobierno.", "No se regulan las ayudas al exterior en el Decreto Legislativo 2/2005."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 14, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre, por el que se aprueba el texto refundido de la Ley de subvenciones, tienen que aprobarse uno o diversos planes estratégicos de subvenciones :", "Por acuerdo del Consejo de Gobierno, a propuesta del Consejero competente en materia de Hacienda y Presupuestos.", "Por resolución del Consejero competente en materia de Hacienda y Presupuestos.", "Por acuerdo del Consejo de Gobierno, a propuesta de cada uno de los Consejeros para cada consejería.", "Por resolución de cada uno de los Consejeros para cada consejería."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 15, "Señala cual de las siguientes respuestas no es una obligación a concretar en los planes estratégicos de subvenciones, de acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre:", "El alcance temporal.", "Los objetivos y los efectos que se pretenden", "Su plazo de consecución.", "Sus coste exacto de aprobación y sus fuentes de financiación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 16, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre, por el que se aprueba el texto refundido de la Ley de subvenciones, cuál de las siguientes casos supone una excepción a los principios de publicidad y concurrencia:", "Cuando por las características especiales del beneficiario o de la actividad subvencionada, no sea posible, objetivamente, promover su concurrencia pública.", "Cuando las subvenciones tengan asignación no nominativa en los presupuestos del ente público concedente.", "Cuando la concesión o la cuantía de las subvenciones venga impuesta por un reglamento.", "Cuando así lo considere el órgano concedente a pesar de que sea posible promover su concurrencia pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 17, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre, por el que se aprueba el texto refundido de la Ley de subvenciones, ¿cuáles son órganos competentes para la concesión de subvenciones?", "En las consejerías y en sus entidades de derecho público dependientes, el titular de la consejería correspondiente o el órgano que determinen las bases reguladoras", "En las consejerías, el órgano directivo competente.", "El Consejo de Gobierno en las consejerías y el consejero competente en las entidades de derecho público dependientes.", "En las entidades de derecho público dependientes, los órganos de dirección de estas entidades."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 18, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre, por el que se aprueba el texto refundido de la Ley de subvenciones, el acto de concesión:", "Lleva implícita la aprobación del gasto correspondiente.", "Lleva implícita la aprobación y disposición del gasto correspondiente.", "Lleva implícita la disposición pero no la aprobación del gasto correspondiente.", "No lleva implícita ninguna fase del procedimiento de gestión de gasto del presupuesto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 19, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre, por el que se aprueba el texto refundido de la Ley de subvenciones, ¿cuál de las siguientes circunstancias supone una prohibición para ser beneficiario?", "Haber sido condenadas mediante sentencia, sea firme o no, a la pena de pérdida de la posibilidad de obtener subvenciones o ayudas públicas.", "Haber sido inhabilitados de acuerdo con la Ley concursal y que haya concluido el periodo de inhabilitación fijado en la sentencia de calificación del concurso.", "No estar al corriente de pago de obligaciones por reintegro de subvenciones en los términos que se determinen por reglamento.", "Haber dado lugar, por una causa de la que hayan sido declaradas culpables, a la resolución provisional de cualquier contrato subscrito con la administración."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 20, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre, por el que se aprueba el texto refundido de la Ley de subvenciones, no puede iniciarse el procedimiento de concesión de subvenciones:", "Sin que el Consejo de Gobierno haya establecido previamente por decreto, en uso de su potestad reglamentaria, las bases reguladoras correspondientes.", "Sin que el consejero competente haya establecido previamente por orden, en uso de su potestad reglamentaria, las bases reguladoras correspondientes.", "Sin que el consejero competente en materia de Hacienda y Presupuestos haya establecido previamente por orden, en uso de su potestad reglamentaria, las bases reguladoras correspondientes.", "Sin que el director general competente haya establecido previamente por orden, en uso de su potestad reglamentaria, las bases reguladoras correspondientes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 21, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre, por el que se aprueba el texto refundido de la Ley de subvenciones, ¿en qué supuestos puede iniciarse el procedimiento de subvención sin establecer bases reguladoras?", "Cuando los beneficiarios sean Entidades Locales y la entidad concedente el Estado.", "Cuando las subvenciones deriven de convenios formalizados entre Administraciones Públicas o entidades de derecho público dependientes, con la finalidad de regular el otorgamiento de subvenciones a favor de terceras personas.", "Cuando la convocatoria así lo establezca.", "No existen supuestos que exceptúen el establecimiento de bases reguladoras."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 22, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre, por el que se aprueba el texto refundido de la Ley de subvenciones, el texto de la convocatoria:", "Solo se publicará en la Base de Datos Nacional de Subvenciones (BDNS).", "Solo se publicará en el «Butlletí Oficial de les Illes Balears».", "Se publicará en la Base de Datos Nacional de Subvenciones (BDNS) y se comunicará al «Butlletí Oficial de les Illes Balears».", "Se comunicará a la Base de Datos Nacional de Subvenciones (BDNS) y se publicará en el «Butlletí Oficial de les Illes Balears»."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 23, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre, por el que se aprueba el texto refundido de la Ley de subvenciones, la convocatoria de una subvención no tendrá necesariamente el siguiente contenido:", "Los requisitos generales que deben cumplir los beneficiarios de la subvención, la forma de acreditarlos y, si procede, el período durante el cual deben mantenerse.", "El importe máximo que se destina a la convocatoria.", "La documentación necesaria para la justificación del cumplimiento de la finalidad de la subvención.", "El importe de las subvenciones, o la forma de determinarlo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 24, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre, el acto de convocatoria de una subvención dictado sin la consignación previa del crédito presupuestario correspondiente:", "Es un acto anulable.", "Es un acto que adolece de una irregularidad no invalidante.", "Es un acto válido.", "Es un acto nulo de pleno derecho."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 25, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre, la instrucción de los procedimientos de concesión de subvenciones corresponde:", "Al órgano que determinen las bases reguladoras.", "Al consejero competente por razón de la materia.", "Al director general competente por razón de la materia", "Al órgano que determine la convocatoria de la subvención."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 26, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre, ¿cuál de las siguientes actuaciones no es competencia del órgano instructor?", "Solicitar, si procede, los informes de la comisión evaluadora.", "Evaluar las solicitudes de acuerdo con los criterios de valoración establecidos en las bases reguladoras y en la convocatoria.", "Dictar la resolución expresa que finaliza el procedimiento de concesión de subvenciones.", "Determinar los participantes admitidos a la convocatoria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 27, "¿De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre, cuando se crean derechos a favor de los beneficiarios?", "Cuando dicte la resolución de concesión y se notifique o publique la misma.", "Cuando dicte la propuesta de resolución de concesión y se notifique o publique la misma.", "Cuando dicte la resolución de concesión , incluso antes de que se notifique o publique la misma.", "Cuando dicte la propuesta de resolución de concesión, incluso antes de que se notifique o publique la misma."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 28, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, ¿qué indica en relación al concurso?", "El concurso es la única vía de selección de los beneficiarios.", "El concurso constituye la vía ordinaria de selección de los beneficiarios.", "El concurso no constituye una vía de selección de los beneficiarios.", "El concurso constituye la vía extraordinaria de selección de los beneficiarios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 29, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, ¿cuándo es posible el prorrateo del importe global máximo destinado a la convocatoria?", "El prorrateo está explícitamente prohibido.", "Cuando las características de la subvención lo permitan aun cuando no esté previsto en las bases reguladoras.", "Cuando las características de la subvención lo permitan y así lo prevean las bases reguladoras.", "El prorrateo puede realizarse en cualquier convocatoria de subvenciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 30, "Indica cuál de las siguientes tareas corresponde a las comisiones evaluadoras, de acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones:", "Formular la propuesta de resolución.", "Determinar los participantes admitidos a la convocatoria.", "Abrir, cuando proceda, el trámite de audiencia e incorporar su resultado al expediente.", "Examinar las solicitudes presentadas y emitir un informe que ha de servir de base para la elaboración de la propuesta de resolución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 31, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, las comisiones evaluadoras se constituirán, preceptivamente, en los procedimientos de concurso, siempre que:", "El importe global de los fondos previstos en la convocatoria sea superior a 50.000,00 euros, o el importe individual máximo sea superior a 7.000,00 euros.", "El importe global de los fondos previstos en la convocatoria sea superior a 70.000,00 euros, o el importe individual máximo sea superior a 7.000,00 euros.", "El importe global de los fondos previstos en la convocatoria sea superior a 50.000,00 euros, o el importe individual máximo sea superior a 5.000,00 euros.", "El importe global de los fondos previstos en la convocatoria sea superior a 70.000,00 euros, o el importe individual máximo sea superior a 5.000,00 euros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 32, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones,  las comisiones evaluadoras estarán constituidas por...", "Un presidente, un secretario y un número de vocales no inferior a cinco, designados en la resolución de convocatoria.", "Un presidente, un secretario y un número de vocales no inferior a tres, designados en la resolución de convocatoria.", "Un presidente, un secretario y un número de vocales no inferior a cinco, designados en las bases reguladoras.", "Un presidente, un secretario y un número de vocales no inferior a tres, designados en las bases reguladoras."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 33, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, la resolución expresa que finaliza el procedimiento de concesión de subvenciones:", "No tiene obligación de ser motivada y debe fijar, con carácter definitivo, la cuantía acumulada de las subvenciones concedidas.", "No tiene obligación de ser motivada y debe fijar, con carácter definitivo, la cuantía individual de las subvenciones concedidas.", "Debe ser motivada y debe fijar, con carácter definitivo, la cuantía acumulada de las subvenciones concedidas.", "Debe ser motivada y debe fijar, con carácter definitivo, la cuantía individual de las subvenciones concedidas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 34, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, indique la respuesta correcta en relación a la notificación de la resolución de concesión:", "La resolución debe notificarse individualmente o mediante publicación en el Boletín Oficial de las Illes Balears.", "La resolución debe notificarse individualmente, sin estar prevista la publicación en el Boletín Oficial de las Illes Balears.", "La resolución debe notificarse individualmente y también publicarse en el Boletín Oficial de las Illes Balears.", "La resolución debe publicarse en el Boletín Oficial de las Illes Balears, sin estar prevista la notificación individual."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 35, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, cuando la Administración decida que la entrega de los fondos públicos a los beneficiarios o la realización de otras funciones de gestión se efectúe mediante una entidad colaboradora:", "Ambas partes tienen que formalizar un contrato en el cual tienen que concretarse los términos de la colaboración.", "Ambas partes tienen que formalizar un convenio en el cual tienen que concretarse los términos de la colaboración.", "Los términos de la colaboración se concretan en las bases reguladoras.", "Ambas partes tienen que formalizar una encomienda de gestión en la cual tienen que concretarse los términos de la colaboración."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 36, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, indique cuál de las siguientes respuestas no es una obligación de las entidades colaboradoras:", "Recibir de la entidad concedente los fondos recibidos de acuerdo con los criterios establecidos en las normas reguladoras de la subvención o ayuda.", "Entregar a los beneficiarios los fondos recibidos de acuerdo con los criterios establecidos en las normas reguladoras de la subvención o ayuda.", "Verificar, si procede, el cumplimiento y la efectividad de las condiciones para su otorgamiento.", "Justificar la aplicación de los fondos percibidos a la entidad concedente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 37, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, indique, con carácter general, cuando se debe realizar el pago:", "El importe de las subvenciones se tiene que abonar, una vez notificada la resolución de concesión.", "El importe de las subvenciones se tiene que abonar, indistintamente una vez notificada la resolución de concesión o una vez justificado el cumplimiento de la finalidad.", "El importe de las subvenciones se puede abonar cuando lo considere el órgano concedente.", "El importe de las subvenciones se tiene que abonar, una vez justificado el cumplimiento de la finalidad para la que se concedieron."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 38, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, ¿cuándo se entenderá del todo justificada la aplicación de los fondos percibidos?", "Cuando se haya acreditado, como mínimo, el importe de la subvención recibida.", "Cuando se haya acreditado, como mínimo, el importe del proyecto de actuación que sirvió de base a la concesión de la subvención.", "Cuando se haya acreditado, como máximo, el importe de la subvención recibida.", "Cuando se haya acreditado, como máximo, el importe del proyecto de actuación que sirvió de base a la concesión de la subvención."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 39, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, indique la respuesta incorrecta en relación a la obligación de documentación de la justificación de los fondos recibidos por parte del beneficiario:", "Puede acreditarse dicho gasto por módulos", "Puede acreditarse dicho gasto mediante cuenta justificativa del gasto realizado.", "Puede acreditarse dicho gasto mediante la presentación de estados contables.", "Puede acreditar estar exento de justificación de acuerdo con la legislación vigente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 40, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, en el supuesto de adquisición de bienes inmuebles, además de la justificación general de la aplicación de fondos:", "Debe aportarse escritura pública de compra-venta para garantizar el valor del inmueble.", "Debe aportarse inscripción en el registro de la propiedad para garantizar el valor del inmueble.", "Debe aportarse certificado de tasador independiente debidamente acreditado e inscrito en el correspondiente registro oficial.", "Debe aportarse, como mínimo, una opción de compra del inmueble."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 41, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, indique cuál de los siguientes gastos no serán gastos subvencionables en ningún caso:", "Los gastos de asesoría jurídica.", "Los intereses deudores de las cuentas bancarias.", "Los gastos notariales.", "Los gastos periciales para la realización del proyecto subvencionado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 42, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, indique cuál de los siguientes gastos no serán gastos subvencionables en ningún caso:", "Los gastos financieros.", "Los gastos de procedimientos judiciales.", "Los gastos de asesoría financiera.", "Los gastos registrales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 43, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, indique cuál de los siguientes no es un medio de comprobación del valor de mercado de los gastos subvencionados por parte de la administración:", "Cotizaciones en mercados nacionales y extranjeros.", "Estimación por referencia a los valores que figuren en los registros oficiales de carácter fiscal.", "Precios estimados por el órgano concedente.", "Tasación pericial contradictoria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 44, "De acuerdo con el Decreto Legislativo 2/2005, la tasación del perito del beneficiario servirá de base para el cálculo de la subvención cuando la diferencia entre el valor comprobado por la Administración y la tasación practicada por el perito del beneficiario:", "Es inferior a 120.000 euros y al 10% del valor comprobado por la Administración.", "Es inferior a 100.000 euros y al 20% del valor comprobado por la Administración.", "Es superior a 120.000 euros y al 10% del valor comprobado por la Administración.", "Es superior a 100.000 euros y al 20% del valor comprobado por la Administración."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 45, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, la administración concedente debe comprobar el cumplimiento de la finalidad de la subvención mediante acta o informe de comprobación material:", "Para pagar las subvenciones de capital superiores a 100.000,00 euros.", "Para pagar las subvenciones de capital superiores a 200.000,00 euros.", "Para pagar las subvenciones de capital superiores a 300.000,00 euros.", "Para pagar las subvenciones de capital superiores a 500.000,00 euros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 46, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, la liquidación de la subvención se dictará y notificará en el plazo de prescripción de:", "Cuatro años a contar desde la presentación de la justificación por la persona o entidad interesada o, en su caso, desde el día siguiente del plazo máximo para presentarla.", "Tres meses a contar desde la presentación de la justificación por la persona o entidad interesada o, en su caso, desde el día siguiente del plazo máximo para presentarla.", "Dos años a contar desde la presentación de la justificación por la persona o entidad interesada o, en su caso, desde el día siguiente del plazo máximo para presentarla.", "Seis meses a contar desde la presentación de la justificación por la persona o entidad interesada o, en su caso, desde el día siguiente del plazo máximo para presentarla."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 47, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, indique cuándo procede la revocación de la subvención:", "Cuando la resolución se ha concedido de forma inválida o no ajustada a derecho.", "Cuando el beneficiario solicita la revocación de la subvención.", "Cuando, después de la resolución de concesión ajustada a derecho, el beneficiario incumple las obligaciones o los compromisos contraídos a los que se halla condicionada la eficacia del acto de concesión de la subvención.", "Cuando el beneficiario no esté al corriente del pago de las obligaciones fiscales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 48, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, indique en cuál de los siguientes casos no procede el reintegro de las cantidades percibidas:", "Cuando hay incumplimiento total o parcial del objetivo, de la actividad o del proyecto.", "Cuando hay incumplimiento de la obligación de justificación o justificación insuficiente.", "Cuando para la obtención de la subvención se hayan falseado las condiciones requeridas para ello u ocultado aquéllas que lo hubieran impedido y cualquier otro supuesto que de lugar a la anulación de la resolución de concesión.", "Cuando se reciban subvenciones compatibles, cuyo importe no alcance una cuantía que supere el coste de la actividad que el beneficiario debe realizar o el valor de la situación objeto de financiación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 49, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, indique cuál de las siguientes es una infracción leve:", "La presentación fuera de plazo de las cuentas justificativas de la aplicación de los fondos percibidos.", "El incumplimiento de las condiciones establecidas que alteren sustancialmente los fines para los que la subvención fue concedida.", "La falta de justificación del empleo dado a los fondos recibidos una vez transcurrido el plazo establecido para su presentación.", "La obtención de la condición de entidad colaboradora falseando los requisitos requeridos en las bases reguladoras de la subvención u ocultando los que la hubiesen impedido."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 50, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, indica cuál de las siguientes es una infracción grave:", "La presentación fuera de plazo de las cuentas justificativas de la aplicación de los fondos percibidos.", "El incumplimiento de las condiciones establecidas que alteren sustancialmente los fines para los que la subvención fue concedida.", "La presentación de cuentas justificativas inexactas o incompletas.", "El incumplimiento de las obligaciones de conservación de justificantes o documentos equivalentes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 51, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, indica cuál de las siguientes es una infracción grave:", "La resistencia, obstrucción, excusa o negativa a las actuaciones de control financiero.", "La falta de justificación del empleo dado a los fondos recibidos una vez transcurrido el plazo establecido para su presentación", "El incumplimiento de obligaciones de índole contable o registral.", "El incumplimiento de las obligaciones de conservación de justificantes o documentos equivalentes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 52, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, indique cuál de las siguientes es una infracción muy grave:", "La obtención de la condición de entidad colaboradora falseando los requeridos en las bases reguladoras de la subvención u ocultando los que la hubiesen impedido", "La falta de justificación del empleo dado a los fondos recibidos una vez transcurrido el plazo establecido para su presentación.", "El incumplimiento de las condiciones establecidas alterando sustancialmente los fines para los que la subvención fue concedida.", "La obtención de una subvención falseando las condiciones requeridas para su concesión u ocultando las que la hubiesen impedido o limitado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 53, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, indique cuál de las siguientes respuestas no indica un posible infractor en materia de subvenciones:", "Las entidades colaboradoras.", "Los beneficiarios de subvenciones.", "Las personas o entidades, relacionadas con el objeto de la subvención o su justificación, obligadas a prestar la colaboración.", "Las personas sin capacidad de obrar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 54, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, las infracciones previstas en la presente Ley prescribirán:", "En el plazo de cuatro años.", "En el plazo de dos años.", "En el plazo de un año.", "En el plazo de cuatro años las muy graves, dos años las graves y un año las leves."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 55, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, las sanciones previstas en la presente Ley prescribirán:", "En el plazo de cuatro años.", "En el plazo de tres años.", "En el plazo de dos años.", "En el plazo de cuatro años las muy graves, dos años las graves y un año las leves."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 56, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, indique cuál de las siguientes sanciones se aplicará en caso de infracción administrativa muy grave:", "Multa de más del triple al cuádruple de la cantidad obtenida indebidamente.", "Pérdida, durante el plazo de uno a tres años, del derecho a obtener ayudas o subvenciones de la Administración de la Comunidad Autónoma o de las entidades de derecho público dependientes.", "Prohibición de contratar con la Administración de la Comunidad Autónoma o con las entidades de derecho público dependientes por un plazo de uno a tres años", "Pérdida, durante el plazo de tres a cinco años, del derecho a ser designados como entidad colaboradora."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 57, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, indica cuál de las siguientes sanciones se aplicará en caso de infracción administrativa grave:", "Multa de más del doble al triple de la cantidad obtenida indebidamente.", "Pérdida, durante el plazo de uno a tres años, del derecho a obtener ayudas o subvenciones de la Administración de la Comunidad Autónoma o de las entidades de derecho público dependientes.", "Prohibición de contratar con la Administración de la Comunidad Autónoma o con las entidades de derecho público dependientes por un plazo de tres a cinco años", "Pérdida, en el supuesto de entidades colaboradoras, durante el plazo de tres a cinco años, del derecho a ser designados como entidad colaboradora."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 58, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, cuál de las siguientes circunstancias no se considerarán para la graduación de las sanciones:", "Cuantía del beneficio obtenido ilícitamente.", "Reincidencia de la conducta infractora.", "Repercusión social de la infracción", "Intencionalidad del infractor."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 59, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, las sanciones previstas en la presente Ley:", "No eximen de la obligación de reintegro que prevé esta Ley, ni de las indemnizaciones de daños y perjuicios que se pudieran exigir.", "Eximen de la obligación de reintegro que prevé esta Ley, pero no de las indemnizaciones de daños y perjuicios que se pudieran exigir.", "No eximen de la obligación de reintegro que prevé esta Ley, pero sí de las indemnizaciones de daños y perjuicios que se pudieran exigir.", "Eximen de la obligación de reintegro que prevé esta Ley, así como de las indemnizaciones de daños y perjuicios que se pudieran exigir."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 60, "De acuerdo con el Decreto Legislativo 2/2005, son competentes para la resolución del procedimiento sancionador, cuando la potestad sancionadora corresponda a la Administración de la Comunidad Autónoma, los siguientes órganos:", "Por la comisión de infracciones leves, el titular de la Dirección General que conceda la subvención.", "Por la comisión de infracciones graves, el titular de la Consejería que conceda la subvención.", "Por la comisión de infracciones graves y muy graves, el Consejo de Gobierno.", "Por la comisión de infracciones graves, el órgano superior de los entes del sector público instrumental de la comunidad autónoma."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 61, "De acuerdo con el artículo 9 de la Ley 38/2003, de 17 de noviembre, General de Subvenciones, el otorgamiento de una subvención debe cumplir el siguiente requisito:", "La aprobación del gasto por el órgano competente, con carácter previo a la concesión.", "La aprobación y disposición del gasto por el órgano competente.", "La remisión a fiscalización de los actos administrativos de contenido económico, en los términos previstos en las leyes.", "La competencia del órgano administrativo concedente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 62, "De acuerdo con la la Ley 38/2003, de 17 de noviembre, general de subvenciones, indica cual de las siguientes NO es una finalidad de la Base de datos Nacional de Subvenciones:", "Promover la transparencia.", "Mejorar la eficiencia en la tramitación de subvenciones y ayudas públicas.", "Servir como instrumento para la planificación de las políticas públicas.", "Mejorar la gestión y colaborar en la lucha contra el fraude de subvenciones y ayudas públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 63, "De acuerdo con la la Ley 38/2003, de 17 de noviembre, general de subvenciones, los convenios de colaboración no podrá tener un plazo de vigencia superior a:", "Cuatro años.", "Tres años.", "Cinco años.", "Un año."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 64, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre,  por el que se aprueba el texto refundido de la Ley de subvenciones, el procedimiento para la concesión de subvenciones se inicia:", "De oficio.", "De oficio o a solicitud de persona interesada.", "A solicitud de persona interesada.", "A solicitud de de parte."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 65, "De acuerdo con la Ley General de Subvenciones, el plazo de rendición de la cuenta justificativa, si las bases reguladoras no lo preveen:", "Es de seis meses desde la finalización del plazo para la realización de la actividad.", "Es de cuatro meses desde la finalización del plazo para la realización de la actividad.", "Es de dos meses desde la finalización del plazo para la realización de la actividad.", "Es de tres meses desde la finalización del plazo para la realización de la actividad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 66, "De acuerdo con la Ley General de Subvenciones, indica cuáles serán los instrumentos habituales para canalizar las subvenciones previstas nominativamente en los Presupuestos Generales:", "Los contratos.", "Los pactos.", "Los convenios.", "Las encomiendas de gestión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 18, 67, "De acuerdo con la Ley General de Subvenciones, el órgano instructor, a la vista del expediente y del informe del órgano colegiado, formulará la propuesta de resolución provisional, debidamente motivada, que deberá notificarse a los interesados en la forma que establezca la convocatoria, y se concederá un plazo para presentar alegaciones:", "De 10 días.", "De 15 días.", "De 20 días.", "De 30 días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 1, "La delegación legislativa, cuando su objeto sea la formación de textos articulados:", "Tiene que otorgarse por una ley de bases.", "Tiene que otorgarse por una ley marco.", "Tiene que otorgarse por una ley de delegación.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 2, "La delegación legislativa, cuando su objeto sea refundir varios textos legales en uno sólo:", "Tiene que otorgarse por una ley de bases.", "Tiene que otorgarse por una ley marco.", "Tiene que otorgarse por una ley ordinaria.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 3, "La delegación legislativa tiene que otorgarse en el Gobierno:", "De forma expresa y para materia concreta.", "De forma expresa y para materia determinada o determinable.", "De forma expresa y para materia concreta, con fijación del procedimiento que se tiene que seguir.", "De forma expresa y para materia concreta, con fijación del plazo para su ejercicio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 4, "La delegación legislativa:", "No se agota por el uso que haga el Gobierno si la materia todavía no ha sido totalmente reglamentada.", "Sí que se agota por el uso que haga el Gobierno mediante la publicación de la norma correspondiente.", "Sí que se agota por el uso que haga el Gobierno mediante la publicación de la norma correspondiente, salvo que la materia no se hubiera reglamentado completamente.", "Sí que se agota por el uso que haga el Gobierno mediante la publicación de la norma correspondiente, salvo que la materia no se hubiera reglamentado completamente o, incluso en este caso, restara tiempo del plazo fijado por las Cortes para el ejercicio de esta delegación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 5, "La delegación legislativa:", "Puede concederse de forma implícita.", "Se tiene que conceder con fijación de plazo para su ejercicio.", "Puede concederse por tiempo indeterminado.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 6, "La delegación legislativa se puede llevar a cabo:", "En el Gobierno.", "En el Gobierno o a su presidente.", "En el Gobierno, a su presidente y a los ministros.", "En el Gobierno y a los ministros, en asuntos propios de su ministerio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 7, "En supuestos de delegación legislativa:", "Es posible la subdelegación.", "No es posible ninguna subdelegación.", "Es posible la subdelegación sólo si lo prevé expresamente la ley de delegación.", "Es posible la subdelegación sólo si lo prevé, expresa o implícitamente, la ley de delegación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 8, "Las leyes de bases:", "Delimitarán con precisión el objeto y el alcance de la delegación legislativa.", "Delimitarán con precisión el objeto y el alcance de la delegación legislativa, con previsión genérica de los principios y los criterios que tienen que seguirse en su ejercicio.", "Delimitarán con precisión el objeto y el alcance de la delegación legislativa y los principios y criterios que tienen que seguirse en su ejercicio.", "Delimitarán con precisión el objeto y alcance de la delegación legislativa, con la posibilidad de prever los principios y los criterios que tienen que seguirse en su ejercicio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 9, "El ejercicio de la delegación normativa la controlan:", "Los tribunales.", "Los sistemas de control que prevé la misma ley de delegación.", "Los sistemas de control que prevé la misma ley de delegación y, si no hay, los tribunales.", "Los tribunales y los sistemas de control que prevean la misma ley de delegación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 10, "La autorización para refundir textos legales:", "Determinará el ámbito normativo al cual se refiere el contenido de la delegación.", "Determinará el ámbito normativo al cual se refiere el contenido de la delegación, y tendrá que especificar si se circunscribe a la mera formulación de un texto único o si incluye la autorización para aclarar los textos legales que tienen que ser refundidos.", "Determinará el ámbito normativo al cual se refiere el contenido de la delegación, y tendrá que especificar si se circunscribe a la mera formulación de un texto único o si incluye la autorización para regularizar, aclarar y armonizar los textos legales que tienen que ser refundidos.", "Determinará el ámbito normativo al cual se refiere el contenido de la delegación, y tendrá que especificar qué normas concretas serán refundidas y si la autorización se circunscribe a la mera formulación de un texto único o si se incluye la autorización para regularizar, aclarar y armonizar los textos legales que tienen que ser refundidos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 11, "Según lo que dispone la Constitución española, son leyes orgánicas:", "Las relativas al desarrollo de los derechos fundamentales y de las libertades públicas.", "Las que aprueben estatutos de autonomía.", "Las respuestas a) y b) son correctas.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 12, "La Constitución española dispone también que tienen el carácter de ley orgánica:", "Las que aprueben el régimen electoral general.", "Las que aprueben el régimen electoral general y las otras que prevé la Constitución.", "Las que aprueben el régimen electoral general, las otras que prevé la Constitución y las que prevean otras leyes orgánicas.", "Las que aprueben el régimen electoral general, las otras que prevé la Constitución, expresa o implícitamente, y las que prevean otras leyes orgánicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 13, "La aprobación de las leyes orgánicas exige:", "Mayoría absoluta del Congreso y del Senado, en una votación final sobre el conjunto del proyecto.", "Mayoría absoluta del Congreso, en una votación final sobre el conjunto del proyecto.", "Mayoría absoluta del Congreso y del Senado, en una votación final comuna sobre el conjunto del proyecto.", "Mayoría absoluta del Congreso y del Senado, en una votación final comuna después de sesión compartida sobre el conjunto del proyecto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 14, "La modificación de las leyes orgánicas exige:", "Mayoría absoluta del Congreso y del Senado, en una votación final sobre el conjunto del proyecto.", "Mayoría absoluta del Congreso, en una votación final sobre el conjunto del proyecto.", "Mayoría absoluta del Congreso y del Senado, en una votación final comuna sobre el conjunto del proyecto.", "Mayoría absoluta del Congreso y del Senado, en una votación final comuna después de sesión compartida sobre el conjunto del proyecto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 15, "La derogación de las leyes orgánicas exige:", "Mayoría simple del Congreso.", "Mayoría absoluta del Congreso, en una votación final sobre el conjunto del proyecto.", "Mayoría absoluta del Congreso y del Senado, en una votación final comuna después de sesión compartida sobre el conjunto del proyecto.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 16, "Indicad cuál qué de las siguientes afirmaciones es cierta:", "Las Cortes Generales podrán delegar en el Gobierno la potestad de dictar normas con rango de ley.", "Las Cortes Generales podrán delegar en el Gobierno la potestad de dictar normas con rango de ley sobre materias no incluidas en el artículo 83 de la Constitución española.", "Las Cortes Generales podrán delegar en el Gobierno la potestad de dictar normas con rango de ley sobre materias determinadas no incluidas en el artículo 81 de la Constitución española.", "Las Cortes Generales podrán delegar en el Gobierno la potestad de dictar normas con rango de ley sobre materias determinadas que relaciona la propia Constitución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 17, "Indicad cuál de las siguientes afirmaciones es cierta:", "Las Cortes Generales, por una ley orgánica, pueden, por motivos de interés local, autorizar o acordar, si procede, un Estatuto de autonomía para territorios que no estén integrados en la organización provincial.", "En ningún caso se admite la federación de comunidades autónomas.", "Las Cortes Generales, por una ley ordinaria, pueden sustituir la iniciativa de las corporaciones locales al hecho que se refiere el apartado 2 del artículo 143 de la Constitución española.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 18, "La reforma de los estatutos, según lo que dispone la Constitución española:", "Se tiene que ajustar al procedimiento que estos establecen.", "Se tiene que ajustar al procedimiento que estos establecen y requiere, en todo caso, la aprobación por las Cortes Generales por una ley orgánica.", "Se tiene que ajustar al procedimiento que estos establecen y, si no hay, lo que prevé la misma Constitución, y requiere , en todo caso, la aprobación por las Cortes Generales por una ley orgánica.", "Todas las respuestas anteriores son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 19, "Los estatutos de autonomía son, según lo que dispone la Constitución española:", "La norma institucional básica de cada comunidad autónoma.", "La norma institucional básica de cada comunidad autónoma, y el Estado los reconoce como parte integrante de su ordenamiento jurídico.", "La norma institucional básica de cada comunidad autónoma, y el Estado los reconoce y los ampara como parte integrante de su ordenamiento jurídico.", "La norma institucional básica de cada comunidad autónoma, y el Estado los ampara en la medida en qué son parte integrante de su ordenamiento jurídico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 20, "Los estatutos de autonomía tienen que contener:", "Las competencias asumidas dentro del marco que establece la Constitución.", "La delimitación del territorio de la comunidad autónoma.", "La denominación de la comunidad que mejor corresponda a su identidad histórica.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 21, "El Estado, según lo que dispone la Constitución, puede transferir o delegar a las comunidades autónomas facultades correspondientes:", "A cualquier materia de titularidad estatal.", "A materias de titularidad estatal que no sean de la competencia exclusiva del Estado.", "A materias de titularidad estatal que por su propia naturaleza sean susceptibles de transferencia o delegación.", "A materias de titularidad estatal cuando así lo exija el interés público."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 22, "Serán nulas de pleno derecho las disposiciones administrativas:", "Que vulneren la Constitución.", "Que vulneren la Constitución o las leyes.", "Que vulneren la Constitución, las leyes u otras disposiciones administrativas de rango superior.", "Que vulneren la Constitución, las leyes u otras disposiciones administrativas de rango igual o superior."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 23, "Serán nulas de pleno derecho las disposiciones administrativas:", "Que regulen materias reservadas a la ley.", "Que establezcan la retroactividad de disposiciones sancionadoras no favorables o restrictivas de derechos.", "Las respuestas a) y b) son correctas.", "Las respuestas a) y b) son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 24, "Indicad cuál de las afirmaciones siguientes es cierta:", "Las leyes de bases no pueden facultar para dictar normas con carácter retroactivo en ningún caso.", "Las leyes de bases pueden facultar para dictar normas con carácter retroactivo.", "Las leyes de bases pueden facultar para dictar normas con carácter retroactivo, si este carácter no perjudica a derechos o intereses de terceros.", "Las leyes de bases pueden facultar para dictar normas con carácter retroactivo, si este carácter no perjudica intereses de terceros o son limitativas de derechos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 25, "Reciben el nombre de decreto legislativo:", "Las leyes que delegan la potestad de dictar normas con rango de ley.", "Las disposiciones del Gobierno que contienen legislación delegada en virtud de una ley de bases.", "Las disposiciones del Gobierno que contienen legislación delegada y consistan en refundir textos.", "Las disposiciones del Gobierno que contienen legislación delegada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 26, "Los decretos ley:", "Únicamente pueden ser dictados en casos extraordinarios.", "Únicamente pueden ser dictados en casos de necesidad.", "Únicamente pueden ser dictados en supuestos de urgencia.", "Únicamente pueden ser dictados en casos de extraordinaria y urgente necesidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 27, "Es una característica de los decretos ley:", "Que se trata de disposiciones legislativas provisionales.", "Que se trata de disposiciones gubernativas provisionales.", "Que se trata de disposiciones legislativas la vigencia de las cuales decae en el plazo máximo de un mes.", "Que se trata de disposiciones gubernativas la vigencia de las cuales decae en el plazo máximo de un mes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 28, "Los decretos ley:", "No pueden afectar el ordenamiento de las instituciones básicas del Estado.", "No pueden afectar el régimen de las comunidades autónomas.", "Las respuestas a) y b) son correctas.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 29, "Los decretos ley:", "No pueden afectar el derecho electoral general.", "No pueden afectar el régimen de los municipios.", "Las respuestas a) y b) son correctas.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 30, "Los decretos ley:", "No pueden afectar los derechos, los deberes y las libertades que regula la sección primera del capítulo I del título I de la Constitución española.", "No pueden afectar los derechos, los deberes y las libertades que regula el capítulo I del título I de la Constitución.", "No pueden afectar los derechos, los deberes y las libertades que regula el título I de la Constitución.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 31, "Los decretos ley tienen que ser inmediatamente sometidos a debate y votación de totalidad:", "En el Congreso.", "En el Senado.", "A las Cortes.", "En el Congreso y el Senado reunir a tal efecto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 32, "El debate y la votación de los decretos ley tienen que producirse en el plazo:", "De los diez días siguientes a su promulgación.", "De los veinte días siguientes a su promulgación.", "De los treinta días siguientes a su promulgación.", "De los dos meses siguientes a su promulgación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 33, "Según la Constitución española:", "Las asambleas de las comunidades autónomas pueden solicitar del Gobierno la adopción de un proyecto de ley.", "Las asambleas de las comunidades autónomas pueden remitir a la Mesa del Congreso una proposición de ley.", "Las asambleas de las comunidades autónomas pueden remitir a la Mesa del Congreso o del Senado una proposición de ley.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 34, "Una vez remitida una proposición de ley por parte de las comunidades autónomas:", "Se tienen que delegar ante el órgano correspondiendo un máximo de cinco miembros de la asamblea encargados de su defensa.", "Se tienen que delegar ante el órgano correspondiendo un máximo de siete miembros de la asamblea encargados de su defensa.", "Se tienen que delegar ante el órgano correspondiendo un máximo de nuevo miembros de la asamblea encargados de su defensa.", "Se tienen que delegar ante el órgano correspondiendo un máximo de tres miembros de la asamblea encargados de su defensa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 35, "Se tienen que regular por una ley orgánica:", "Los requisitos de la iniciativa popular para la presentación de proposiciones de ley.", "Las formas de ejercicio de la iniciativa popular para la presentación de proposiciones de ley.", "Las respuestas a) y b) son correctas.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 36, "Según lo que dispone la Constitución española, en relación con la iniciativa legislativa popular:", "Como regla, se exigen más de 500.000 firmas acreditadas.", "En todo caso, se exigen más de 500.000 firmas acreditadas.", "Como regla, se exigen no menos de 500.000 firmas acreditadas.", "En todo caso, se exigen no menos de 500.000 firmas acreditadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 37, "La iniciativa legislativa popular no es procedente:", "En materias propias de ley orgánica.", "En materias tributarias.", "Las respuestas a) y b) son correctas.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 38, "La iniciativa legislativa popular no es procedente:", "En materias civiles.", "En materias de carácter internacional.", "Las respuestas a) y b) son correctas.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 39, "La iniciativa legislativa popular no es procedente:", "Respecto a la prerrogativa de gracia.", "En materias de competencia exclusiva de las comunidades autónomas.", "Las respuestas a) y b) son correctas.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 40, "El Consejo de Ministros aprueba:", "Los proyectos de ley.", "Las proposiciones de ley presentadas por los grupos parlamentarios que apoyan en el Gobierno.", "Las respuestas a) y b) son correctas.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 41, "Las leyes aprobadas por las Cortes Generales tienen que ser sancionadas en el plazo:", "De cinco días desde su aprobación.", "De tres días desde su aprobación.", "De quince días desde su aprobación.", "De treinta días desde su aprobación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 42, "Una vez sancionadas las leyes:", "El rey las promulgará.", "Las Cortes las promulgarán.", "El rey ordenará la promulgación.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 43, "Una vez aprobado un proyecto de ley orgánica por el Congreso, el Senado puede oponer su veto o introducir enmiendas. En caso de veto, una vez transcurrido un mes desde su interposición, el proyecto puede ser sometido al rey para sanción si el Congreso ratifica el texto inicial:", "Por mayoría simple.", "Por mayoría de dos terceras partes de sus miembros.", "Por mayoría de tres quintas partes de sus miembros.", "Por mayoría absoluta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 44, "A través de una ley marco:", "Se establecerá la modalidad de control sobre las normas legislativas de las comunidades autónomas.", "Se establecerá la modalidad de control sobre las normas de las comunidades autónomas.", "Se establecerá la modalidad de control sobre las normas no legislativas de las comunidades autónomas.", "Se establecerá la modalidad de control sobre las normas administrativas de las comunidades autónomas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 45, "El control ejercito a través de una ley marco corresponde, según la Constitución española:", "Al Congreso.", "Al Senado.", "A las Cortes Generales.", "Al Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 46, "La institución encargada de atribuir a todas o a alguna de las comunidades autónomas facultades legislativas través de una ley marco es:", "El Congreso.", "El Senado.", "Las Cortes Generales.", "El Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 47, "En los supuestos de transferencia de facultades por parte del Estado a las comunidades autónomas:", "Tiene que preverse en cada caso la correspondiente transferencia de medios financieros.", "Tiene que preverse las formas de control del Estado.", "Las respuestas a) y b) son correctas.", "Todas las respuestas anteriores son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 48, "Una vez aprobado un proyecto de ley ordinaria u orgánica por el Congreso de los Diputados, el Senado puede interponer su veto o introducir enmiendas:", "En el plazo de dos meses.", "En el plazo de tres meses.", "En el plazo de un mes.", "En el plazo de cuatro meses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 49, "La iniciativa legislativa, según la Constitución española, corresponde:", "Al Gobierno, en el Congreso y en el Senado.", "Al Gobierno.", "Al Congreso y al Senado.", "Al Gobierno y al Congreso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 50, "Una vez promulgada una ley, el rey:", "Ordenará la publicación.", "Ordenará la inmediata publicación.", "Ordenará la rápida publicación.", "Ordenará la urgente publicación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 51, "Una vez aprobado un proyecto de ley ordinaria por el Congreso, su presidente:", "Dará cuenta al presidente del Senado.", "Dará cuenta en un breve plazo de tiempo al presidente del Senado.", "Dará cuenta inmediata al presidente del Senado.", "Dará cuenta al presidente del Senado en el plazo de tres días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 52, "El plazo para que el Senado pueda oponer su veto o introducir enmiendas a un proyecto de ley empieza:", "A partir del día siguiente al de la recepción del texto.", "A partir del día de la recepción del texto.", "A partir del primer día hábil siguiente al de la recepción del texto.", "La Constitución no dice nada sobre este aspecto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 53, "Para interponer un veto a un proyecto de ley por parte del Senado:", "Será necesario mensaje motivado.", "Será aconsejable mensaje motivado.", "El Senado podrá decidir motivarlo a través de mensaje.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 54, "El senado podrá introducir enmiendas en el texto recepcionado de un proyecto de ley. Para lo cual, dispondrá de un plazo:", "De cinco días.", "De diez días.", "De un mes.", "De dos meses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 55, "El veto del Senado a un proyecto de ley remitido por el Congreso tendrá que ser aprobado, si procede:", "Por mayoría.", "Por mayoría de dos terceras partes de los miembros del Senado.", "Por mayoría de tres quintas partes de los miembros del Senado.", "Por mayoría absoluta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 56, "En caso de veto del Senado a un proyecto de ley, no  se podrá someter al rey para sanción sin que el Congreso ratifique el texto inicial:", "Por mayoría simple.", "Por mayoría de dos terceras partes de sus miembros.", "Por mayoría de tres quintas partes de sus miembros.", "Por mayoría absoluta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 57, "Señalad la respuesta correcta. En relación con las fuentes del derecho administrativo:", "La jurisprudencia es una fuente indirecta del derecho administrativo.", "Las normas jurídicas contenidas en los tratados internacionales siempre serán de aplicación directa en España.", "Los principios generales del derecho no son fuente del derecho.", "La costumbre sólo regirá a falta de principios generales del derecho, siempre que no sea contrario a la moral o al orden público y que resulte probado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 58, "El derecho administrativo:", "Es un derecho público.", "Es un derecho común.", "Es un derecho limitativo.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 59, "De acuerdo con lo que prevé el Código civil, las normas jurídicas contenidas en los tratados internacionales:", "No tienen aplicación directa en España.", "Aunque no pueden llegar a tener aplicación directa en España, tendrán carácter informador del ordenamiento jurídico interno.", "Serán de aplicación directa en España desde la firma del tratado internacional correspondiente.", "No serán de aplicación directa en España en tanto que no hayan pasado a formar parte del ordenamiento interno mediante su publicación íntegra en Boletín Oficial del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 60, "¿Cuándo se aplica la costumbre como fuente del derecho?", "A falta de ley aplicable, siempre que no sea contraria a la moral o al orden público, y que resulte probada.", "Cuando resulte de aplicación por razón de la materia.", "En cualquier caso, aunque haya ley aplicable.", "Cuando no haya principios generales del derecho aplicables al caso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 61, "¿Qué artículo del Código civil establece las fuentes del derecho?", "Ninguno.", "El artículo 1.", "El artículo 18.", "El artículo 35."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 62, "El principio de legalidad viene establecido en la Constitución:", "En el artículo 1.", "En el artículo 9.", "En el artículo 103.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 63, "El principio de jerarquía de las fuentes del derecho administrativo:", "Determina la invalidez de la norma inferior que contradiga lo que dispone la superior.", "Se regula en el artículo 9.3 de la Constitución.", "No se aplica en las relaciones entre las leyes ordinarias y las orgánicas.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 64, "Los principios generales del derecho:", "Son fuente indirecta.", "Tienen un valor normativo superior a la costumbre.", "Son fuente de aplicación a falta de ley y costumbre, sin perjuicio de su carácter informador del ordenamiento jurídico.", "Tienen un valor normativo superior a la costumbre, sin perjuicio de su carácter informador del ordenamiento jurídico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 65, "El principio de reserva de ley significa:", "Que la ley se sitúa en la posición más elevada de la pirámide normativa.", "Que no es posible negarse a la aplicación o al cumplimiento de la ley.", "Que el enjuiciamiento de la ley compite en exclusiva o está reservado a los tribunales.", "Que determinadas materias que establece la Constitución sólo las puede regular una norma con rango legal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 66, "De acuerdo con el Código civil, en relación con las fuentes del derecho:", "La costumbre sólo regirá a falta de ley aplicable, siempre que no sea contraria a la moral o al interés social y que resulte probado.", "La jurisprudencia complementará el ordenamiento jurídico con la doctrina que, de manera reiterada, establezca el Tribunal Supremo al interpretar y aplicar la ley y la costumbre.", "Los principios generales del derecho se aplican a falta de ley, sin perjuicio de su carácter informador del ordenamiento jurídico.", "La jurisprudencia complementará el ordenamiento jurídico con la doctrina que, de manera reiterada, establezca el Tribunal Supremo al interpretar y aplicar la ley, la costumbre y los principios generales del derecho."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 10, 67, "¿Qué otro principio, además del de jerarquía normativa, se debe tener en cuenta para explicar la relación entre las diferentes fuentes del ordenamiento jurídico?", "El principio de cooperación.", "El principio de colaboración.", "El principio de coordinación.", "El principio de competencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 1, "El Reglamento de Bienes de las Entidades Locales fue aprobado por el", "Real Decreto Legislativo 1372/1986 de 13 de junio", "Real Decreto 1372/1986 de 3 de junio", "Real Decreto 1372/1986 de 13 de junio", "Real Decreto Legislativo 1372/1986 de 3 de junio"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 2, "Conforme el artículo 79 de la Ley 7/1985 de 2 de abril, reguladora de las Bases de Régimen Local, el patrimonio de las entidades locales está constituido", "Por todos los bienes materiales e inmateriales de que sean titulares", "Por el conjunto de bienes, derechos y acciones que les pertenezcan", "Por el conjunto de bienes, derechos y acciones que posean", "Por el conjunto de bienes inmuebles y derechos materiales que les pertenezcan"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 3, "Los bienes de las entidades locales se clasifican en:", "Bienes demaniales, comunales y privados", "Bienes de dominio público, bienes de dominio privado y bienes comunales", "Bienes de uso público y bienes de uso privado", "Bienes de dominio público y bienes patrimoniales"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 4, "Los bienes de dominio público son:", "Los destinados a un uso o servicio público", "Los utilizados por el común de los vecinos", "Los destinados a un servicio público", "Los bienes patrimoniales, los destinados a un servicio público y los bienes comunales"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 5, "Aquellos bienes que siendo de dominio público, su aprovechamiento pertenece al común de los vecinos, tienen la consideración de:", "Bienes de uso público vecinal", "Bienes patrimoniales municipales", "Bienes comunales", "Bienes demaniales provativos"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 6, "Las calles, paseos y parques, conforme el artículo 3.1 del Reglamento de Bienes son:", "Bienes patrimoniales municipales", "Bienes patrimoniales", "Bienes de uso público local", "Bienes de servicio público"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 7, "Los bienes destinados directamente al cumplimiento de fines públicos de responsabilidad de las entidades locales, son:", "Bienes patrimoniales", "Bienes de uso público", "Bienes de servicio público", "Bienes comunales"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 8, "Los bienes comunales son:", "Enajenables e imprescriptibles", "Inalienables, inembargables y sujetos a prescripción", "Inalienables, inembargables y sujetos a los tributos autonómicos y estatales.", "Inalienables, inembargables, imprescriptibles"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 9, "Las parcelas sobrantes y efectos no utilizables se clasifican como:", "Bienes demaniales", "Bienes de uso público", "Bienes de servicio público", "Bienes patrimoniales"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 10, "La alteración de la calificación jurídica de los bienes de las entidades locales requiere de un expediente en el que se acredite:", "Su baja del inventario municipal", "Su oportunidad y legalidad", "Su inembargabilidad e imprescriptibilidad", "Su disponibilidad y legalidad"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 11, "El expediente de alteración jurídica de los bienes de las entidades locales debe ser resuelto", "Por acuerdo adoptado por la correspondiente diputación provincial o consejo insular por mayoría absoluta del número legal de miembros de sus órganos de gobierno", "Por la corporación local respectiva mediante acuerdo adoptado con el voto favorable de la mayoría absoluta del número legal de miembros de la misma", "Por acuerdo del consejo de gobierno de la respectiva comunidad autónoma adoptado por mayoría simple de sus miembros", "Dado el carácter imprescriptible de estos bienes no es posible su alteración jurídica"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 12, "La alteración de la calificación jurídica de los bienes se produce automáticamente sin necesidad de que se tramite un expediente de alteración", "Aprobación inicial de los planes de ordenación urbana", "Aprobación definitiva de los planes de ordenación urbana", "Adscripción de bienes patrimoniales por más de veinte años a un uso o servicio público o comunal", "Adscripción de bienes de dominio público por más de veinticinco años a un uso o servicio público"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 13, "¿Cuál de las siguientes afirmaciones es correcta?", "Los acuerdos para el ejercicio de las acciones en defensa de los bienes de las entidades locales se adoptan directamente por el Alcalde de la respectiva corporación previo dictamen favorable del plenario municipal", "Las entidades locales tienen capacidad jurídica limitada para adquirir bienes de diferente naturaleza", "Las entidades locales tienen la obligación de ejercer las acciones necesarias para la defensa de sus bienes y derechos", "Las entidades locales pueden ejercer las acciones necesarias para la defensa de sus bienes y derechos"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 14, "Las Corporaciones locales pueden adquirir bienes y derechos, entre otros, por los siguientes medios", "Por prescripción, por ocupación y por donación", "Por prescripción previa tramitación de expediente que acredite su oportunidad", "Por ocupación, precedida de justo título y buena fe", "Por cualquiera de los medios previstos el reglamento orgánico de la corporación"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 15, "La adquisición de bienes a título oneroso por parte de las Corporaciones locales", "Las Corporaciones locales no pueden adquirir bienes y derechos a título oneroso aunque puedan hacerlo a título gratuito", "Exige el cumplimiento de los requisitos exigidos en la normativa sobre expropiación forzosa", "Exige el cumplimiento de los requisitos exigidos en la legislación urbanística y de expropiaciones", "Exige el cumplimiento de los requisitos contemplados en la normativa de contratación de las entidades locales"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 16, "La aceptación de herencias por las entidades locales", "Se entenderá siempre con renuncia a los derechos de excusión y prelación", "Se entenderá con renuncia al derecho de prelación", "Se formalizará con renuncia al derecho de excusión", "Se entenderá a beneficio de inventario"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 17, "Entre las prerrogativas de que gozan las entidades locales respecto de sus bienes patrimoniales encontramos", "La de recuperar por si mismas su posesión en cualquier momento", "La de recuperar por si mismas su posesión en el plazo de un año", "La de recuperar por si mismas su posesión en el plazo de tres años", "La de recuperar por si mismas su posesión en el plazo de cinco años"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 18, "¿Cuál de entre las siguientes potestades no tienen las entidades locales respecto de sus bienes?", "La potestad de investigación", "La potestad de desahucio administrativo", "La potestad expropiatoria", "La potestad de deslinde"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 19, "Conforme dispone el artículo 55 del Reglamento de Bienes de las EELL, el conocimiento de las cuestiones de naturaleza civil que se susciten con ocasión de la investigación de las entidades locales respecto de los bienes y derechos que se presuman de su propiedad", "Corresponde a la jurisdicción ordinaria", "Corresponde a los órganos de la respectiva comunidad autónoma competentes en la materia de que se trate", "Corresponde al pleno de la Corporación, salvo que la materia esté delegada en las juntas de gobierno local", "Corresponde, siempre y en todo caso, al Alcalde quien dará cuenta al pleno en la primera sesión que celebre"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 20, "Los afectados por la resolución de un expediente de investigación tramitado por una entidad local podrán impugnarla", "Ante la jurisdicción ordinaria, ya sea en la vía civil o contenciosa, quedando vedada la jurisdicción penal", "En vía civil", "En vía contencioso-administrativa", "La impugnación no es posible, quedando a salvo la indemnización que en su caso corresponda a los afectados"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 21, "En el ejercicio de la potestad de deslinde y una vez iniciado el procedimiento administrativo a tal efecto", "Podrá plantearse conflicto de competencia ante la comunidad autónoma o consejo insular siempre que éste tenga atribuida la competencia en materia de defensa de bienes de las entidades locales", "Podrá instarse procedimiento judicial contra el acuerdo de inicio del procedimiento administrativo que supondrá la paralización de éste entretanto no recaiga sentencia definitiva y firme", "No podrá instarse procedimiento judicial con igual pretensión ni se admitirán interdictos sobre el estado posesorio de las fincas mientras no se lleve a cabo el deslinde", "No podrá instarse procedimiento judicial con igual pretensión aunque se admitirán interdictos sobre el estado posesorio de las fincas mientras no se lleve a cabo el deslinde."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 22, "El amojonamiento", "Es un acto que tiene lugar una vez que el acuerdo de deslinde es firme, con intervención de los interesados", "Es el acto que tiene lugar, previo al inicio del procedimiento de deslinde, para que los interesados fijen sus pretensiones", "Es un acto que sólo tiene lugar en los procedimientos de desahucio administrativo", "Es un acto que tiene lugar una vez que el acuerdo de deslinde es firme, sin intervención de los interesados dada la firmeza del acuerdo de deslinde"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 23, "¿Pueden las Corporaciones locales ejecutar en vía administrativa la investigación, el deslinde y reivindicación de los bienes situados fuera del término de su jurisdicción?", "En ningún caso, dado que las entidades locales no pueden poseer bienes fuera del término de su jurisdicción", "Sí, mediante exhorto a la entidad en cuyo territorio radicaren para que, por su mediación, se desarrollen los actos correspondientes.", "No, salvo que medie acuerdo del Consejo de Gobierno de la respectiva comunidad autónoma", "Sí, pero la tramitación del procedimiento en estos casos será competencia de la respectiva diputación provincial, cabildo o consejo a cuyo territorio pertenezca la entidad local"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 24, "En el caso de una demanda judicial que afectare al dominio y demás derechos reales del patrimonio de las entidades locales, éstas:", "No podrán allanarse", "Podrán allanarse aunque no desistir del procedimiento", "Podrán allanarse y desistir del procedimiento siempre que el mismo no se halle visto para sentencia", "Podrán allanarse y desistir del procedimiento cualquiera que sea el estado de tramitación del procedimiento"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 25, "Las Corporaciones locales, en relación al inventario y registro de sus bienes:", "Están obligadas a formar inventario de todos sus bienes y derechos, cualquiera que sea su naturaleza o forma de adquisición", "Podrán formar inventario de todos sus bienes o derechos cualquiera que sea su naturaleza o forma de adquisición", "Están obligadas a formar inventario de todos sus bienes y derechos salvo en el caso de adquisiciones de bienes a título lucrativo en que tendrá carácter potestativo", "Están obligadas a formar inventario de todos sus bienes y derechos salvo en el caso de adquisiciones de bienes a título oneroso en que tendrá carácter potestativo"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 26, "Los bienes y derechos pertenecientes a entidades con personalidad propia y dependientes de las Corporaciones locales:", "Los bienes y derechos de dichas entidades se consideran de titularidad de la entidad local a la que pertenecen por lo que se incluirán en el inventario de la propia entidad local", "Los bienes, derechos y acciones que les sean propio se incluirán en el inventario consolidado de la Corporación local a la que pertenezcan pero sin formar un inventario separado", "Formarán inventarios separados de los bienes y derechos que les pertenezcan", "Estas entidades, en la medida en que dependen de una Corporación local, no pueden poseer bienes ni derechos sino a través de la propia Corporación local a la que pertenecen"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 27, "De conformidad con lo establecido en el artículo 19 del Reglamento de Bienes de las Entidades locales, la reseña de los bienes en el inventario se efectuará:", "De acuerdo con lo que se establezca en el Reglamento Orgánico de Funcionamiento de la respectiva Corporación", "Dependiendo del epígrafe en el que se incluyan, alfabéticamente o con numeración correlativa", "Alfabéticamente dentro del respectivo epígrafe", "Con numeración correlativa por cada uno de ellos dentro del respectivo epígrafe"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 28, "El inventario de créditos y derechos personales de la Corporación expresará", "Concepto y valor", "Concepto, nombre del deudor, valor, título de adquisición y vencimiento, en su caso", "Nombre del deudor, valor y vencimiento", "Los créditos y derechos personales no se incluyen en el inventario de la Corporación"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 29, "Los bienes cedidos por la Corporación, condicionalmente o a plazo, así como las concesiones y los arrendamientos otorgados sobre bienes municipales, se reseñarán bajo el epígrafe de:", "Derechos reales", "Valores mobiliarios, créditos y derechos, de carácter personal de la Corporación", "Bienes subsidiarios de carácter accesorio", "Bienes y derechos revertibles"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 30, "Todos los documentos que refrendan los datos del inventario y, en especial, títulos de dominio,  actas de deslinde y valoración, planos y fotografías:", "Se archivarán junto con la demás documentación municipal", "Se archivarán con separación de la demás documentación municipal", "Se archivarán en el Registro de la Propiedad a cuya demarcación pertenezca la Corporación", "Se archivarán en los respectivos Registros de la Propiedad y Registros de Bienes Muebles a cuya demarcación pertenezca la Corporación"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 31, "Los inventarios de las Corporaciones locales son autorizados", "Por el Presidente de la Corporación dando cuenta al Pleno corporativo", "Por el Alcalde con el visto bueno del Secretario de la Corporación", "Por el Secretario de la Corporación con el visto bueno del Presidente", "Por el Secretario de la Corporación con el visto bueno del Interventor y Tesorero de la Corporación"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 32, "Una copia del inventario debidamente autorizado, así como de sus rectificaciones, se remitirá", "A la Administración del Estado", "A la Administración de la Comunidad Autónoma", "A la diputación provincial, los consejos o cabildos insulares", "A la Administración del Estado y de la Comunidad Autónoma"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 33, "La rectificación del inventario se verificará:", "Anualmente", "Cada tres años, salvo que el Presidente de la Corporación acuerde otro período que nunca podrá ser superior a los cinco años", "Cada tres años", "Dentro de los tres meses siguientes al comienzo de cada legislatura"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 34, "El órgano competente para acordar la aprobación del inventario ya formado, su rectificación y comprobación, será:", "El Alcalde o Presidente de la Corporación", "La Junta de Gobierno Local", "El órgano de gobierno de la comunidad autónoma en la que radique la respectiva Corporación local", "El Pleno de la Corporación local."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 35, "Las Corporaciones locales, en relación a sus bienes inmuebles y derechos reales", "Deberán inscribirlos en el Registro de la Propiedad de acuerdo con lo previsto en la legislación hipotecaria", "Podrán inscribirlos en el Registro de la Propiedad de acuerdo con lo previsto en la legislación hipotecaria", "Deberán inscribir el derecho de dominio en el Registro de la Propiedad pudiendo inscribir con carácter potestativo el resto de derechos reales de que sean titulares", "No precisan de su inscripción en el Registro de la Propiedad por cuanto el inventario autorizado con el visto bueno del Secretario de la Corporación otorga a esta clase de bienes la protección prevista en la legislación hipotecaria"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 36, "El texto refundido de la Ley reguladora de las Haciendas Locales se aprobó por el:", "Real Decreto-ley 2/2004 de 15 de marzo", "Real Decreto Legislativo 2/2014 de 5 de marzo", "Real Decreto Legislativo 2/2004 de 5 de marzo", "Decreto Ley 2/2004 de 15 de marzo"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 37, "Las entidades locales, de acuerdo con lo previsto en la legislación del Estado y en las leyes que dicten las comunidades autónomas", "Tienen autonomía para exigir tributos pero no para establecerlos", "Tienen autonomía para establecer y exigir tributos", "Tienen autonomía para establecer tributos pero su exigencia corresponde al órgano de recaudación competente de la respectiva comunidad autónoma", "Tienen autonomía para establecer y exigir tasas y contribuciones especiales pero no impuestos"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 38, "¿Cuál de entre las siguientes afirmaciones es correcta?", "Las adquisiciones a títulos de herencia, legado o donación no constituyen ingresos de derecho privado de las entidades locales", "Las adquisiciones a títulos de herencia, legado o donación constituyen ingresos de derecho privado de las entidades locales", "Las adquisiciones a títulos de herencia, legado o donación constituyen ingresos de derecho público de las entidades locales", "Las adquisiciones a títulos de herencia, legado o donación constituyen ingresos de derecho público o privado de las entidades locales, según la naturaleza público o privada del causante o donante"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 39, "Las facultades de gestión, liquidación, inspección y recaudación tributarias que el texto refundido de la Ley reguladora de Haciendas Locales atribuye a las entidades locales:", "Habrán de ser ejercidas, siempre y en todo caso, por la propia entidad local, sin que puedan ser objeto de delegación", "Podrán ser delegadas en la comunidad autónoma o en otras entidades locales en cuyo territorio estén integradas", "Las facultades de inspección y recaudación podrán ser delegadas en la comunidad autónoma, pero no las facultades de gestión y liquidación", "Solamente la facultad de recaudación de los tributos locales podrá ser delegada a la respectiva comunidad autónoma a la que pertenezca la entidad local"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 40, "Las actuaciones en materia de inspección o recaudación ejecutiva que hayan de efectuarse fuera del territorio de la respectiva entidad local en relación con los ingresos de derecho público propios de ésta:", "Serán practicadas por los órganos competentes de la correspondiente comunidad autónoma cuando deban realizarse en el ámbito territorial de ésta, y por los órganos competentes del Estado en otro caso, previa solicitud del presidente de la Corporación", "Serán practicadas por los órganos competentes de la correspondiente comunidad autónoma cuando deban realizarse en el ámbito territorial de ésta, y por los órganos competentes del Estado en otro caso, siempre que se hayan delegado las facultades en materia de inspección o recaudación", "Serán practicadas por los órganos competentes de la correspondiente entidad local sin que rija el principio de territorialidad", "Serán practicadas por los inspectores y recaudadores expresamente designados por el Pleno de la Corporación local"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 41, "De acuerdo con lo prevenido en el artículo 9.1 del texto refundido de la Ley reguladora de las Haciendas Locales ¿cuál de las siguientes afirmaciones es correcta?", "En los tributos locales, no podrán reconocerse los beneficios fiscales previstos en las normas del estado, de las comunidades autónomas y en los tratados internacionales", "El reconocimiento de los beneficios fiscales tiene siempre carácter potestativo", "En los tributos locales, no podrán reconocerse otros beneficios fiscales que los expresamente previstos en las normas con rango de ley o los derivados de la aplicación de los tratados internacionales", "El reconocimiento de los beneficios fiscales tiene siempre carácter obligatorio, salvo que una norma de la Unión Europea establezca su carácter potestativo"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 42, "En la exacción de los tributos locales y de los restantes ingresos de derecho público de las entidades locales, los recargos e intereses de demora:", "Se exigirán y determinarán en los mismos casos, forma y cuantía que en la exacción de los tributos del Estado", "Se exigirán y determinarán en los casos, forma y cuantía previstos en las respectivas ordenanzas fiscales y que podrán ser diferentes a los previstos para la exacción de los tributos del Estado", "Se exigirán y determinarán en los mismos casos, forma y cuantía que en la exacción de los tributos de la respectiva comunidad autónoma", "En la exacción de los tributos locales, las entidades locales pueden imponer recargos pero no los intereses de demora, excepto en los casos de ingresos indebidos"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 43, "Contra los actos de aplicación y efectividad de los tributos  y restantes ingresos de derecho público sólo podrá interponerse el recurso de reposición regulado en:", "El artículo 112 de la Ley 39/2015 de 1 de octubre", "Artículos 222 y siguientes de la Ley 58/2003 de 17 de diciembre, General Tributaria", "Artículo 14 del RD Legislativo 2/2004 de 5 de marzo", "Artículo 24 del RD Legislativo 2/2004 de 5 de marzo"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 44, "La competencia para conocer y resolver el recurso de reposición interpuesto frente a los actos de aplicación y efectividad de los tributos corresponde a:", "Al Presidente de la Corporación", "Al Pleno de la Corporación", "Al órgano de la entidad local que haya dictado el acto impugnado", "Al superior jerárquico del órgano que ha dictado el acto impugnado"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 45, "Cuando el recurso de reposición contra un acto de aplicación y efectividad de los tributos locales no sea resuelto en el plazo legalmente previsto", "El recurso se entenderá estimado", "El recurso se entenderá desestimado", "Se entenderá desestimado, salvo las excepciones previstas en la ley, en que el sentido del silencio es positivo", "Por tratarse de una impugnación de actos tributarios, se tiene que estar siempre y en todo caso al sentido de la resolución expresa"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 46, "La resolución expresa de un recurso de reposición interpuesto contra  un acto de aplicación y efectividad de los tributos locales, deberá ser notificada al recurrente", "En el plazo máximo de un mes desde que se dicte", "En el plazo máximo de diez días desde que se dicte la resolución", "El recurso será resuelto y notificado en el plazo de un mes a contar desde el día siguiente al de su presentación", "Se notificará a la mayor brevedad posible por medios electrónicos"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 47, "Salvo en los supuestos en que la ley prevé la interposición de reclamaciones económico-administrativas, contra la resolución del recurso de reposición, los interesados", "Podrán volver a plantear el recurso de reposición, salvo cuando se trate de una desestimación presunta", "Podrán interponer recurso de alzada", "Deberán interponer recurso de alzada para poner fin a la vía administrativa", "Podrán interponer directamente recurso contencioso-administrativo"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 48, "¿Cuáles de entre los siguientes impuestos son de exigencia obligatoria por parte de los ayuntamientos?", "El Impuesto sobre Bienes Inmuebles y el Impuesto sobre el Incremento de Valor de los Terrenos de Naturaleza Urbana", "El Impuesto sobre Construcciones, Instalaciones y Obras, y el Impuesto sobre Vehículos de Tracción Mecánica", "El Impuesto sobre Bienes Inmuebles y el Impuesto sobre Actividades Económicas", "El Impuesto sobre Bienes Inmuebles, el Impuesto sobre Actividades Económicas, el Impuesto sobre Vehículos de Tracción Mecánica y el Impuesto sobre el Incremento de Valor de los Terrenos de Naturaleza Urbana"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 49, "El Impuesto sobre Bienes Inmuebles", "Es un tributo directo de carácter real", "Es un tributo directo de carácter personal", "Es un tributo indirecto de carácter real", "Es un tributo directo que puede tener carácter real o personal"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 50, "El Impuesto sobre Actividades Económicas", "Es un tributo directo de carácter personal, cuyo hecho imponible está constituido por el mero ejercicio, en territorio nacional, de una actividad empresarial, profesional o artística", "Es un tributo indirecto de carácter real", "Es un tributo directo de carácter real", "Es un tributo directo que puede tener carácter real o personal en función de la naturaleza de la actividad empresarial, profesional o artística gravada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 51, "Los ayuntamientos, por la realización de obras o por el establecimiento o ampliación de servicios municipales, podrán establecer y exigir", "Tributos", "Tasas", "Contribuciones especiales", "Tasas o contribuciones especiales, indistintamente"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 52, "Los ayuntamientos, por la prestación de servicios o la realización de actividades de su competencia o el aprovechamiento especial de los bienes del dominio público municipal, podrán establecer y exigir", "Tributos", "Tasas", "Contribuciones especiales", "El impuesto que corresponda en función de la concreta actividad de que se trate"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 53, "La base imponible del Impuesto sobre Bienes Inmuebles está constituida", "Por el valor catastral de los bienes inmuebles", "Por el valor base que corresponda al inmueble previa determinación de la base liquidable", "Por la base que se determine en la ponencia de valores", "Por la base que se determine en los procedimientos de valoración colectiva"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 54, "Los vehículos oficiales de las comunidades autónomas adscritos a la seguridad ciudadana, en relación con el Impuesto sobre Vehículos de Tracción Mecánica", "Están exentos del Impuesto sobre Vehículos de Tracción Mecánica", "Pueden disfrutar de una bonificación de hasta el 75 por ciento en función de la clase de carburante", "Pueden disfrutar de una bonificación de hasta el 50 por ciento en función de la clase de carburante", "Pueden disfrutar de una bonificación de hasta el 25 por ciento en función de la clase de carburante"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 55, "Los bienes inmuebles que sean propiedad de la Cruz Roja Española, en relación con el Impuesto sobre Bienes Inmuebles", "Gozarán de una bonificación del 75 por ciento de la cuota íntegra del impuesto, siempre y en todo caso", "Gozarán de una bonificación del 75 por ciento de la cuota íntegra del impuesto, siempre que así lo recojan las ordenanzas fiscales", "Gozarán de una bonificación de hasta el 75 por ciento de la cuota íntegra del impuesto, siempre que así lo recojan las ordenanzas fiscales", "Están exentos del Impuesto sobre Bienes Inmuebles."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 56, "Conforme el artículo 107.2 de la Ley de Bases del Régimen Local, las ordenanzas fiscales obligan en el territorio de la respectiva entidad local y se aplican conforme a los principios de:", "Municipalidad y territorialidad", "Residencia, municipalidad y territorialidad", "Residencia efectiva y territorialidad", "Residencia, municipalidad y territorialidad efectiva"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 57, "Conforme el artículo 107.1 de la Ley de Bases de Régimen Local, en el caso de las entidades locales radicadas en Illes Balears, las ordenanzas fiscales reguladoras de sus tributos locales, salvo que en ellas se señale otra cosa, comienzan a aplicarse", "Una vez publicadas en el Boletín Oficial del Estado o de la Comunidad Autónoma, indistintamente", "Siempre y en todo caso, a partir del día 1 de enero siguiente al de la fecha de su publicación", "En el momento de su publicación definitiva en el Boletín Oficial de la Comunidad Autónoma", "En el momento de su publicación definitiva en el Boletín Oficial del Estado, previa su publicación en el Boletín Oficial de la Comunidad Autónoma"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 58, "De conformidad con el artículo 105 de la Ley de Bases del Régimen Local, las Haciendas Locales se nutren", "De los tributos del Estado, y de los tributos de las Comunidades Autónomas", "De los tributos propios, de los del Estado y de los de las Comunidades Autónomas", "Además de los tributos propios y de las participaciones reconocidas en los del Estado y de las Comunidades Autónomas, de aquellos otros recursos que prevea la Ley", "De las cantidades asignadas en los Presupuestos Generales del Estado para el cumplimiento de los fines que les son propios"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 59, "De acuerdo con el artículo 106.1 de la Ley de Bases del Régimen Local, las entidades locales", "Tendrán autonomía para exigir tributos de acuerdo con los que vengan establecidos en la legislación del Estado y de las Comunidades Autónomas en materia de haciendas locales.", "Tendrán autonomía para establecer y exigir tributos de acuerdo en la legislación del Estado reguladora de las Haciendas Locales y en las leyes que dicten las Comunidades Autónomas en los supuestos expresamente previstos en aquélla", "Tendrán potestad para liquidar y gestionar los tributos cuyas facultades de liquidación y gestión les vengan atribuidas por la legislación del Estado y de las Comunidades Autónomas en los supuestos expresamente previstos en aquélla", "Podrán tener autonomía para establecer y exigir tributos de conformidad con lo que expresamente se prevea en la legislación del Estado, de las Comunidades Autónomas y la emanada en ejercicio de su potestad reglamentaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 60, "De acuerdo con el artículo 106.2 de la Ley de Bases del Régimen Local, la potestad reglamentaria de las entidades locales en materia tributaria", "Se ejercerá a través de las disposiciones generales en materia tributaria emanadas de sus órganos de gobierno", "Se ejercerá de conformidad con lo dispuesto en las leyes del Estado y de las Comunidades Autónomas en los supuestos y en las condiciones que expresamente se definan", "Se ejercerá a través de ordenanzas fiscales reguladoras de sus tributos propios y de ordenanzas generales de gestión, recaudación e inspección", "Corresponde al Pleno de la Corporación y se ejercerá mediante acuerdos generales adoptados por la mayoría absoluta de sus miembros"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 61, "Los acuerdos provisionales adoptados para la aprobación y modificación de las ordenanzas fiscales se expondrán en el tablón de anuncios de la entidad", "Durante treinta días, como mínimo", "Durante un mes", "Entre treinta días, como mínimo y un máximo de sesenta", "Por el tiempo determinado en el acuerdo provisional adoptado"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 62, "En el caso de un ayuntamiento con una población de 20.000 habitantes, los anuncios de exposición de los acuerdos provisionales de aprobación de las ordenanzas fiscales", "Se publicarán en el boletín oficial de la provincia, o, en su caso, en el de la Comunidad Autónoma uniprovincial", "Se publicarán en un diario de los de mayor difusión de la provincia o de la comunidad autónoma uniprovincial", "Los anuncios de exposición de los acuerdos provisionales de aprobación de las ordenanzas fiscales no son objeto de publicación, por su carácter provisional, publicándose sólo los acuerdos definitivos", "Se publicarán en el boletín oficial de la provincia, o, en su caso, en el de la Comunidad Autónoma uniprovincial y, además, en un diario de los de mayor difusión de la provincia o de la comunidad autónoma uniprovincial"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 63, "Si en el procedimiento de aprobación de las ordenanzas fiscales de las entidades locales, durante el período de exposición pública no se presentan reclamaciones", "Se entenderá definitivamente adoptado el acuerdo, hasta entonces provisional, mediante acuerdo plenario adoptado por mayoría simple", "Se entenderá definitivamente adoptado el acuerdo, hasta entonces provisional, mediante acuerdo plenario adoptado por mayoría absoluta del número legal de miembros", "Se prorrogará el período de exposición pública por otros sesenta días, transcurrido el cual sin que se hayan presentado reclamaciones o alegaciones, se entenderá definitivamente adoptado el acuerdo sin necesidad de acuerdo del pleno del aentidad", "Se entenderá definitivamente adoptado el acuerdo, hasta entonces provisional, sin necesidad de acuerdo plenario"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 64, "Los acuerdos provisionales de aprobación de las ordenanzas fiscales de las entidades locales, elevados automáticamente a definitivos, habrán de ser publicados", "En el boletín oficial de la provincia, o, en su caso, de la comunidad autónoma uniprovincial", "En el boletín oficial de la provincia, o en su caso, de la comunidad autónoma uniprovincial y en uno de los diarios de los de mayor difusión de la provincia o de la comunidad autónoma uniprovincial", "En el boletín oficial de la provincia, o en su caso, de la comunidad autónoma uniprovincial o en uno de los diarios de los de mayor difusión de la provincia o de la comunidad autónoma uniprovincial", "Al haber sido obligatoriamente publicado el acuerdo de aprobación provisional, no resulta necesaria la publicación del acuerdo elevado automáticamente a definitivo por falta de presentación de reclamaciones"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 65, "La edición del texto íntegro de las ordenanzas fiscales dentro del primer cuatrimestre del ejercicio económico correspondiente resulta obligatoria para las siguientes entidades", "Las diputaciones provinciales, consejos, cabildos insulares, y en todo caso, las demás entidades locales cuando su población sea superior a los 20.000 habitantes", "Las diputaciones provinciales, consejos, cabildos insulares, y en todo caso, las demás entidades locales cuando su población sea superior a los 10.000 habitantes", "Las diputaciones provinciales, consejos, cabildos insulares, y en todo caso, las demás entidades locales cuando su población sea superior a los 50.000 habitantes", "Las diputaciones provinciales, consejos, cabildos insulares y demás entidades locales"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 66, "Tienen la condición de interesados a los efectos de reclamar contra los acuerdos provisionales de aprobación o modificación de las ordenanzas fiscales", "Los que tuvieren un interés directo o resulten afectados por tales acuerdos", "Los que tuvieren un interés directo o resultes afectados por tales acuerdos siempre que residan en el territorio de la entidad local que haya adoptado el acuerdo provisional", "Los que tuvieren un interés directo o resultes afectados por tales acuerdos siempre que tengan la condición de vecino de la entidad local que haya adoptado el acuerdo provisional", "Cualquier interesado en reclamar, sea o no residente y tenga o no interés directo en el asunto"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 67, "Contra las ordenanzas fiscales de las entidades locales podrá interponerse", "Reclamación económico administrativa ante el Tribunal Económico Administrativo Central", "Reclamación económico administrativa ante el Tribunal Económico Administrativo Regional", "Recurso de reposición regulado en el artículo 14 de la Ley reguladora de las Haciendas Locales", "Recurso contencioso-administrativo"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 68, "Si por resolución judicial firme resulta anulado el texto de una ordenanza fiscal", "Se mantendrán los actos firmes o consentidos dictados al amparo de la ordenanza que posteriormente resulte anulada o modificada, salvo que expresamente lo prohibiera la sentencia.", "Se mantendrán los actos firmes o consentidos dictados al amparo de la ordenanza que posteriormente resulte anulada o modificada, siempre y en todo caso", "Se mantendrán los actos firmes o consentidos dictados al amparo de la ordenanza que posteriormente resulte anulada o modificada, siempre y en todo caso, salvo acuerdo del órgano que hubiere adoptado el acuerdo de aprobación definitiva de la ordenanza anulada", "Los actos firmes o consentidos quedarán afectados inmediatamente, por efectos de la sentencia, por la declaración de nulidad"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 69, "Si por resolución judicial firme resultaren anulados o modificados los acuerdos locales o el texto de las ordenanzas fiscales", "La entidad local vendrá obligada a adecuar a los términos de la sentencia todas las actuaciones que lleve a cabo con posterioridad a la fecha en que aquélla le sea notificada.", "La entidad local podrá adecuar a los términos de la sentencia todas las actuaciones que lleve a cabo con posterioridad a la fecha en que aquélla le sea notificada.", "La entidad local iniciará de oficio procedimiento para indemnizar los daños y perjuicios que se hubieren causado a los afectados por las ordenanzas anuladas o modificadas", "La entidad local podrá iniciar, de oficio o a instancia de la parte legitimada, procedimiento para indemnizar los daños y perjuicios que se hubieren causado a los afectados por las ordenanzas anuladas o modificadas"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 9, 70, "Las entidades locales habrán de expedir copias de las ordenanzas fiscales publicadas a quienes las demanden", "Siempre que se acredite un interés legítimo", "Siempre que se acredite un interés legítimo o quienes las demanden resulten afectados por las ordenanzas cuyas copias solicitan", "No existe obligación de expedir dichas copias al haber sido las ordenanzas fiscales objeto de publicación", "Siempre y en todo caso"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 1, "El Decreto 12/2014, de 28 de febrero, de la Comunidad Autónoma de las Illes Balears (modificado por el Decreto 12/2017 de 31 de marzo), creó:", "La Comisión Técnica de Seguimiento del Plan de Igualdad y la Comisión de Igualdad.", "La Comisión Técnica de Evaluación del Plan de Igualdad y la Comisión de Igualdad.", "La Comisión de Seguimiento de las Políticas de Igualdad.", "La Comisión de Evaluación de las Políticas de Igualdad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 2, "De conformidad con el artículo 3 de la Ley orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres:", "El principio de igualdad de trato entre mujeres y hombres supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo.", "El principio de igualdad de trato entre mujeres y hombres supone un trato no igualitario y no discriminatorio entre mujeres y hombres.", "El principio de igualdad de trato entre mujeres y hombres supone un retroceso en la convivencia en nuestra sociedad.", "El principio de igualdad de trato entre mujeres y hombres supone un reto importante por nuestra sociedad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 3, "Indique la respuesta correcta en relación con las acciones positivas que establece la Ley orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres:", "Los poderes públicos adoptarán medidas específicas en favor de las mujeres para corregir situaciones patentes de desigualdad de hecho respecto de los hombres.", "Las medidas tienen que ser aplicables en tanto que subsistan las situaciones de desigualdad.", "Las medidas tienen que ser razonables y proporcionadas en relación con el objetivo perseguido en cada caso.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 4, "Indique la respuesta incorrecta en relación con el fomento de la igualdad, que regula el artículo 6 de la Ley orgánica1/2004, de 28 de diciembre, de medidas de protección integral contra la violencia de género:", "Las administraciones educativas velarán para que en todos los materiales educativos se eliminen los estereotipos sexistas.", "Las administraciones educativas velarán para que todos los materiales educativos fomenten el igual valor de hombres y de mujeres.", "Las administraciones educativas fomentarán la educación desagregada por sexos.", "Las administraciones educativas velarán para que en todos los materiales educativos se eliminen los estereotipos discriminatorios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 5, "Las acreditaciones de víctimas de violencia de género, que regula la Ley orgánica1/2004, de 28 de diciembre, de medidas de protección integral contra la violencia de género:", "Se podrán realizar mediante documentos sanitarios oficiales de comunicación a la Fiscalía o al órgano judicial.", "Se podrán realizar mediante declaraciones de otros menores de edad ante las fuerzas y cuerpos de seguridad del Estado.", "Se podrán realizar mediante declaraciones de familiares ante las fuerzas y cuerpos de seguridad del Estado.", "Las personas menores de edad no pueden ser víctimas de violencia de género."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 6, "Diseñar los procedimientos básicos que permiten poner en marcha los sistemas de acreditación de las situaciones de violencia de género regulados por la Ley orgánica1/2004, de 28 de diciembre, de medidas de protección integral contra la violencia de género, es una competencia que corresponde:", "Al Gobierno central.", "A las administraciones autonómicas.", "A las comisiones de igualdad de cada administración autonómica.", "Al Gobierno central y a las comunidades autónomas, de mutuo acuerdo, en el marco de la conferencia sectorial de igualdad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 7, "De acuerdo con la Ley orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres:", "Constituye discriminación directa por razón de sexo cualquier trato desfavorable relacionado con el embarazo o la maternidad.", "Constituye discriminación indirecta por razón de sexo cualquier trato desfavorable relacionado con el embarazo o la maternidad.", "Constituye acción directa cualquier trato favorable relacionado con el embarazo o la maternidad.", "El embarazo y la maternidad no tienen nada que ver con la discriminación por razón de sexo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 8, "Según la Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres:", "Las mujeres víctimas de violencia de género serán consideradas colectivos prioritarios en el acceso a viviendas de protección oficial.", "Las mujeres víctimas de violencia de género serán consideradas colectivos prioritarios en el acceso a residencias públicas por gente mayor.", "Las mujeres víctimas de violencia de género solo tendrán prioridad para acceder a residencias privadas.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 9, "De acuerdo con la Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres:", "Las administraciones públicas de las Illes Balears tienen que tomar medidas con el objeto de fomentar la corresponsabilidad en la vida laboral, la familiar y la personal de las mujeres y los hombres.", "Las administraciones públicas de las Illes Balears tienen que tomar medidas con el objeto de fomentar la corrseponsabilitat en la vida laboral, la familiar y la personal de las mujeres y los hombres, teniendo en cuenta los nuevos modelos de familia.", "Las administraciones públicas tienen que tomar medidas de conciliación solo en casos de familias numerosas.", "Las administraciones públicas tienen que tomar medidas de conciliación solo en casos de familias monoparentales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 10, "Según la Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres:", "También se consideran víctimas de violencia las personas que convivan con la víctima.", "También se consideran víctimas de violencia las personas que tengan parentesco con la víctima.", "También se consideran víctimas las hijas y los hijos de la madre víctima de la violencia.", "solo se consideran víctimas las mujeres."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 11, "Según la Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres, ¿cuál es el máximo órgano de participación de carácter autonómico que tiene la finalidad de favorecer el asociacionismo y la participación de las mujeres en los temas que les puedan afectar?", "El Consejo de Participación de la Mujer Trabajadora.", "El Consejo de Participación de la Mujer.", "El Observatorio de Participación de las Mujeres.", "La Comisión de Participación de la Mujer."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 12, "Indique la respuesta correcta en relación con el V Plan Estratégico de Igualdad entre Mujeres y Hombres de las Illes Balears (2021-2023):", "El Instituto Balear de la Mujer es el órgano encargado de elaborarlo, con la colaboración de las consejerías correspondientes.", "Tienen que participar en él los consejos insulares y las entidades sociales.", "Tienen que participar en él los agentes sociales y económicos y las asociaciones en defensa de los derechos de las mujeres de las Illes Balears.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 13, "De acuerdo con la Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres:", "Las administraciones públicas de las Illes Balears tienen que garantizar un uso no sexista del lenguaje.", "Las administraciones públicas de las Illes Balears podrán garantizar un uso no sexista del lenguaje.", "Las administraciones públicas de las Illes Balears podrán fomentar el uso del lenguaje sexista.", "Las administraciones públicas de las Illes Balears no pueden interferir en el uso del lenguaje sexista."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 14, "Según la Ley orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres:", "El principio de igualdad de trato y de oportunidades entre mujeres y hombres informará la actuación de todos los poderes públicos.", "El principio de igualdad de trato y de oportunidades entre mujeres y hombres informará, con carácter transversal, la actuación de todos los poderes públicos.", "El principio de igualdad de trato y de oportunidades entre mujeres y hombres no hace falta que se integre, de forma activa, en la adopción y la ejecución de disposiciones normativas.", "El principio de igualdad de trato y de oportunidades entre mujeres y hombres no está regulado en esta normativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 15, "Indique la respuesta correcta en relación con la definición de planes de igualdad de las empresas en conformidad con la Ley orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres:", "Son un conjunto ordenado de medidas, adoptadas después de realizar un diagnóstico de situación, con la intención de lograr la igualdad de trato y de oportunidades entre mujeres y hombres.", "Son un conjunto ordenado de medidas, adoptadas después de realizar un diagnóstico de situación, con la intención de eliminar la discriminación por razón de sexo.", "Son un conjunto ordenado de medidas con la intención de hacer una evaluación de las conductas sexistas de las empresas.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 16, "Indique la respuesta correcta en relación con la obligatoriedad de las empresas de disponer de un plan de igualdad según la normativa en vigor:", "Están obligadas a disponer de planes de igualdad las empresas de cincuenta o más personas trabajadoras.", "Están obligadas a disponer de planes de igualdad las empresas entre cien y ciento cincuenta personas trabajadoras.", "Están obligadas a disponer de planes de igualdad las empresas de más de ciento cincuenta personas trabajadoras.", "No existe ningún tramo relacionado con el número de personas trabajadoras."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 17, "Señale la respuesta incorrecta en relación con los derechos de las mujeres víctimas de violencia de género, que regula la Ley orgánica 1/2004, de 28 de diciembre, de medidas de protección integral contra la violencia de género:", "Las mujeres víctimas de violencia de género tienen derecho a servicios sociales de atención.", "Las mujeres víctimas de violencia de género tienen derecho a servicios de apoyo, de acogida y de recuperación integral.", "Las mujeres víctimas de violencia de género no tienen derecho a servicios de emergencia.", "Las mujeres víctimas de violencia de género tienen derecho a recibir información plena y asesoramiento adecuado a su situación personal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 18, "El Convenio del Consejo de Europa sobre prevención y lucha contra la violencia contra la mujer y la violencia doméstica:", "Se firmó en Estambul el 11 de mayo de 2011.", "Fue ratificado por España en marzo del 2014.", "Todavía no está ratificado por España.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 19, "La Carta de los Derechos Fundamentales de la Unión Europea:", "Contiene un artículo sobre no discriminación.", "Contiene un artículo sobre no estigmatización.", "Contiene un artículo sobre buen trato.", "No contiene ninguno de los artículos anteriores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 20, "La Directiva 2004/113/CE del Consejo de Europa, de 13 de diciembre de 2004, por la que se aplica el principio de igualdad de trato entre hombres y mujeres en el acceso a los bienes y servicios y a su suministro:", "Establece la distinción entre discriminación directa y discriminación indirecta.", "Establece la distinción entre discriminación múltiple y orden de discriminar.", "Establece la distinción entre acoso y acoso sexual.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 21, "Indique la respuesta incorrecta de acuerdo con el Estatuto de autonomía de las Illes Balears, cuando establece que las administraciones públicas de las Illes Balears se tienen que centrar, primordialmente, en los ámbitos siguientes:", "La igualdad de derechos de mujeres y hombres en todos los ámbitos.", "La protección social contra la violencia, especialmente contra la violencia de género.", "El desarrollo sostenible del turismo.", "La protección específica y la tutela social del menor."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 22, "Según dispone el Estatuto de autonomía de las Illes Balears en el artículo 17 «no discriminación por razón de sexo»:", "Todas las mujeres y hombres tienen derecho al libre desarrollo de su personalidad y capacidad personal.", "Todas las mujeres y hombres tienen derecho a vivir con dignidad, seguridad y autonomía.", "Todas las personas tienen derecho a no ser discriminadas por razón de su orientación sexual.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 23, "Indique la respuesta correcta en relación con la definición de perspectiva de género que establece la Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres:", "Es la toma en consideración de las diferencias entre mujeres y hombres en un a?mbito o una actividad para el análisis, la planificación, el diseño y la ejecución de poli?ticas.", "Es la toma en consideración de las similitudes entre hombres y mujeres para la ejecución de las políticas.", "Es tener en cuenta la manera en que las diversas actuaciones, situaciones y necesidades afectan a los hombres.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 24, "Indique la respuesta incorrecta de acuerdo con lo que la Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres establece como violencia machista:", "La violencia económica, que incluye la privación intencionada, y no justificada legalmente, de recursos para el bienestar físico o psicológico.", "La violencia simbólica, que incluye los iconos, representaciones, narrativas, imágenes, etc., que reproducen o transmiten relaciones de dominación de los hombres respecto de las mujeres, así como desigualdades de poder entre sexos y de segregación.", "La violencia institucional, producida desde los servicios públicos y que revictimitza las víctimas.", "El feminicidio, asesinato de mujeres por el hecho de ser mujeres, al margen de que haya o haya habido relacio?n de pareja."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 25, "Señale la respuesta correcta en relación con el informe de evaluación de impacto de género, regulado por la Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres:", "La Administración de la Comunidad Autónoma de las Illes Balears tiene que aprobar las directrices en que se establezcan las pautas que se deben seguir para realizar el informe de evaluación de impacto de género.", "La Administración de la Comunidad Autónoma de las Illes Balears, a propuesta del Instituto Balear de la Mujer, tiene que aprobar las directrices en que se establezcan las pautas que se deben seguir para realizar el informe de evaluación de impacto de género.", "La Comisión de Paridad tiene que aprobar las pautas que se deben seguir para realizar el informe de evaluación de impacto de género.", "El Observatorio para la Equidad tiene que aprobar las directrices que se deben seguir para realizar el informe de evaluación de impacto de género."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 26, "El órgano colegiado encargado de coordinar las poli?ticas y los programas que realizan las administraciones autonómica, insular y local en materia de igualdad de mujeres y hombres, es:", "La Comisión de Igualdad.", "El Observatorio para la Igualdad.", "La Comisión para la Igualdad de G èneres.", "La Comisión para la Igualdad de S exes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 27, "El Observatorio para la Igualdad, regulado por el Decreto 1/2018, de 2 de febrero, tiene, entre otras, las funciones siguientes:", "Proponer un sistema de indicadores para tomar conocimiento de manera actualizada de la evolución de las desigualdades entre hombres y mujeres y la violencia machista, y para realizar su seguimiento y su evaluación.", "Analizar la evolución y los motivos de la persistencia de las desigualdades entre sexos y sexualidades y la violencia machista.", "Promover la elaboración de estudios, informes técnicos y evaluaciones comparables.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 28, "Señale la respuesta incorrecta en relación con cuáles son las áreas de intervención del Observatorio para la Igualdad, regulado por el Decreto 1/2018, de 2 de febrero:", "La violencia machista.", "El techo de cristal en el acceso al mercado de trabajo.", "La imagen pública de las mujeres.", "La sexualidad y la salud de las mujeres."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 29, "Señale la respuesta correcta en relación con el Decreto de traspaso de competencias en materia de políticas de género y mujer:", "Es el Decreto 26/2004, de 21 de diciembre, de traspaso a los consejos insulares de las funciones y los servicios inherentes a las competencias propias de estos consejos insulares que actualmente ejerce la Administración de la Comunidad Autónoma de las Illes Balears en materia de políticas de género y mujer.", "Es el Decreto 46/2018, de 21 de diciembre, de traspaso a los consejos insulares de las funciones y los servicios inherentes a las competencias propias de estos consejos insulares que actualmente ejerce la Administración de la Comunidad Autónoma de las Illes Balears en materia de políticas de género y mujer.", "Es el Decreto 46/2018, de 21de diciembre, de traspaso a los consejos insulares de las funciones y los servicios inherentes a las competencias propias de estos consejos insulares que actualmente ejerce la Administración de la Comunidad Autónoma de las Illes Balears en materia de políticas de corresponsabilidad.", "No se han transferido todavía estas competencias a los consejos insulares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 30, "Señale cuál de las normas de ámbito estatal siguientes se ha aprobado recientemente en materia de no discriminación:", "La Ley 15/2022, de 12 de julio, integral para la igualdad de trato y la no discriminación.", "La Ley 15/2022, de 12 de julio, para la discriminación y la igualdad de trato.", "La Ley 16/2022, de 18 de noviembre, para combatir la desigualdad de género y la no discriminación.", "La Ley 17/2021, de 20 de diciembre, para atender las desigualdades y las discriminaciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 31, "Indique la respuesta correcta en relación con la Ley 6/2022, de 31 de marzo, de modificación del Texto refundido de la Ley general de derechos de las personas con discapacidad y de su inclusión social:", "Introduce un nuevo artículo para establecer las condiciones básicas de accesibilidad cognitiva, así como para prever su desarrollo normativo posterior mediante un reglamento específico.", "Establece las condiciones básicas de accesibilidad cognitiva sin prever ningún desarrollo normativo posterior.", "La modificación no prevé establecer ninguna condición básica de accesibilidad cognitiva.", "La modificación solo afecta el apartado de la inclusión social."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 32, "El artículo 14 de la Constitución española proclama el derecho a la igualdad y a la no discriminación por motivos de:", "Nacimiento, raza, sexo, nacionalidad y opinión.", "Nacimiento raza, sexo, religión y opinión.", "Nacimiento, raza, sexo, religión, opinión o cualquier otra circunstancia personal o social.", "Lugar de origen, etnia, espiritualidad, opinión y cualquier otra circunstancia personal o social."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 33, "Indique la respuesta correcta en relación con los derechos de las funcionarias públicas víctimas de violencia de género según el que establece la Ley orgánica 1/2004, de 28 de diciembre, de medidas de protección integral contra la violencia de género:", "La funcionaria víctima de violencia de género tendrá derecho a la reducción o a la reordenación de su tiempo de trabajo.", "La funcionaria víctima de violencia de género tendrá derecho a la movilidad geográfica del centro de trabajo.", "La funcionaria víctima de violencia de género tendrá acceso a servicios específicos de atención.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 34, "La Estrategia para la igualdad de las personas Lesbianas, Gays, Bisexuals, Trans, Intersexuales y Queer (LGTBIQ) de la Unión Europea:", "Tiene previsto integrar la lucha contra la discriminación que afecta a las personas LGTBIQ en todas las políticas que se realicen en la Unión Europea.", "Está pensada para el periodo 2020-2025.", "Está basada, entre otras fuentes, en el informe sobre los derechos fundamentales de la Agencia Europea de Derechos Fundamentales (FRA) del 2020.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 35, "Indique la respuesta correcta en relación con el objeto de la Ley 8/2016, de 30 de mayo, para garantizar los derechos de lesbianas, gays, trans, bisexuales e intersexuales y para erradicar la LGTBI-fobia:", "Establecer y regular los principios, los medios y las medidas para garantizar plenamente la igualdad real y efectiva en el ejercicio de los derechos de las personas lesbianas, gays, trans (transexuales y transgèneres), bisexuales e intersexuales (LGTBI).", "Establecer y regular los principios para garantizar los derechos de las personas no heterosexuales.", "Establecer y regular los principios para fomentar los derechos de las personas gays y lesbianas.", "Establecer y regular los principios para promover los derechos de las personas trans e intersexuales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 36, "Indique la respuesta correcta en relación con la evaluación de impacto sobre orientación sexual e identidad de género que establece la Ley 8/2016, de 30 de mayo, para garantizar los derechos de lesbianas, gays, trans, bisexuales e intersexuales y para erradicar la LGTBI-fobia:", "Esta evaluación se tiene que incorporar sobre todas las disposiciones legales o reglamentarias que se impulsen dentro del territorio de la comunidad autónoma.", "Esta evaluación se tiene que incorporar sobre algunas disposiciones legales o reglamentarias concretas que se impulsen dentro del territorio de la comunidad autónoma.", "Esta evaluación tiene que garantizar la integración del principio de igualdad y no discriminación de las personas LGTBI.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 37, "De acuerdo con la Ley 8/2016, de 30 de mayo, para garantizar los derechos de lesbianas, gays, trans, bisexuales e intersexuales y para erradicar la LGTBI-fobia y la discriminación por asociación es:", "La situacio?n en que una persona o un grupo de personas son objeto de discriminación por orientación sexual, identidad de género o expresión de género como consecuencia de una apreciación errónea.", "La situación en que una persona es objeto de discriminación por orientación sexual, identidad de género o expresión de género como consecuencia de su relacio?n con una persona o un grupo LGTBI.", "La situación en que una persona activista por los derechos de las personas gays es discriminada.", "La situación en que un grupo de personas activistas por los derechos de las personas lesbianas son discriminadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 38, "¿Qué Tratado marcó un hito en la lucha contra la discriminación en la Unión Europea cuando empezó a vigir el 1 de mayo de 1999?", "El Tratado de Maastricht.", "El Tratado de Amsterdam.", "El Tratado de Oslo.", "El Tratado de Milán."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 39, "¿Qué directiva del Consejo de Europa prohíbe la discriminación por origen racial o étnico en cualquier ámbito?", "La Directiva 1998/53/CE, de 18 de mayo de 1996.", "La Directiva 2000/43/CE, de 29 de junio de 2000.", "La Directiva 2020/32/CE, de 29 de abril de 2019.", "No hay ninguna directiva que prohíba esta discriminación a la Unión Europea."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 40, "¿En qué Ley se transpuso en España la Directiva del Consejo de Europa que prohíbe la discriminación por origen racial o étnico?", "Mediante la Ley 62/2003, de 30 de diciembre, de medidas fiscales, administrativas y de orden social.", "Mediante la Ley 62/2011, de 30 de diciembre, de medidas fiscales, administrativas y de orden social.", "Mediante la Ley 17/2014, de 30 de diciembre, de medidas fiscales, administrativas y de orden social.", "Mediante la Ley 19/2015, de 30 de diciembre, de medidas fiscales, administrativas y de orden social."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 41, "La entrada en vigor del Tratado de Lisboa el 1 de diciembre de 2009 ha reforzado en la Unión Europea:", "La protección de los derechos fundamentales.", "La protección de los derechos sociales.", "La protección de los derechos civiles.", "La protección de los derechos a la infancia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 42, "El Consejo de la Unión Europea, por unanimidad, y previa aprobación del Parlamento Europeo, podrá adoptar acciones adecuadas para luchar:", "La discriminación por motivos de género, lugar de nacimiento, nacionalidad o discapacidad.", "La discriminación por motivos de sexo, país de origen, color de piel o capacidad.", "La discriminación por motivos de sexo, de origen racial o étnico, religión o convicciones, discapacidad, edad u orientación sexual.", "La discriminación por motivos de raza, religión, ideología y condición sexual."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 43, "Indique la respuesta correcta en relación con lo que dispone la Recomendación CM/Rec (2019) del Comité de Ministros a los Estados miembros para prevenir y combatir el sexismo, adoptada el 27 de marzo de 2019:", "Afirma que el sexismo se refuerza por los estereotipos de género que afectan a mujeres y hombres, niñas y niños, e impide la consecución de la igualdad de género y el establecimiento de sociedades inclusivas.", "Recuerda que el sexismo es una manifestación de las relaciones de poder históricamente desiguales entre mujeres y hombres, que provoca discriminación y que impide el pleno avance de las mujeres en la sociedad.", "Observa que mujeres y niñas pueden ser objeto de discriminación múltiple e interseccional y que pueden enfrentarse a un sexismo combinado con otras normas o comportamientos discriminatorios, de odio o nocivos.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 44, "¿En qué ley de ámbito autonómico está reconocido el derecho a la no discriminación de las personas menores de edad?", "En la Ley 9/2019, de 19 de febrero, de la atención y los derechos de la infancia y la adolescencia de las Illes Balears.", "En la Ley 9/2019, de 19 de febrero, de protección a jóvenes menores de edad de las Illes Balears.", "En la Ley 6/2018, de 18 de marzo, de no discriminación de niños y de adolescentes en las Illes Balears.", "Este derecho no está reconocido en ninguna normativa autonómica en vigor."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 45, "¿Qué ley de ámbito autonómico tiene por objeto garantizar la igualdad de oportunidades, la no discriminación y la accesibilidad universal para permitir la autonomía personal de todas las personas y, particularmente, de las personas con discapacidad?", "La Ley 8/2017, de 3 de agosto, para la accesibilidad de las personas con discapacidades de las Illes Balears.", "La Ley 8/2017, de 3 de agosto, de accesibilidad universal de las Illes Balears.", "La Ley 4/2020, de 8 de mayo, para mejorar la accesibilidad de todas las personas de las Illes Balears.", "La Ley 5/2021, de 10 de abril, de no discriminación de las personas con diversidad funcional de las Illes Balears."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 46, "¿Qué ley de ámbito autonómico tiene un título de medidas para garantizar la igualdad real y efectiva de las personas atendiendo a su identidad y a la expresión de género?", "La Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres.", "La Ley 5/2003, de 4 de abril, de salud de las Illes Balears.", "La Ley 8/2016, de 30 de mayo, para garantizar los derechos de lesbianas, gays, trans, bisexuales e intersexuals y para erradicar la LGTBI-fobia.", "La Ley 8/2018, de 31 de julio, de apoyo a las familias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 47, "¿De qué ministerio depende el Pacto de Estado contra la Violencia de Género?", "Del Ministerio de Igualdad.", "Del Ministerio de Trabajo y Economía Social.", "Del Ministerio de Sanidad.", "Del Ministerio de Justicia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 48, "El Gobierno, mediante la Delegación del Gobierno para la Violencia de Género, desarrolla el Pacto de Estado contra la Violencia de Género impulsando:", "Medidas de coordinación con el resto de ministerios y organismos autónomos que dependen de estos.", "Medidas de coordinación con las comunidades autónomas.", "Medidas de coordinación con las entidades locales representadas por la Federación Española de Municipios y Provincias.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 49, "El Convenio europeo para la protección de los derechos humanos y de las libertades fundamentales, más conocido como la Convención europea de derechos humanos (CEDH), establece una prohibición general de discriminación, entre otros, por razones de sexo en relación con:", "El disfrute de algunos de los derechos laborales", "El disfrute de todos los derechos reconocidos por ley", "El disfrute de derechos del ámbito público", "El disfrute de algunos derechos reconocidos por ley"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 50, "El Convenio del Consejo de Europa sobre prevención y lucha contra la violencia contra las mujeres y la violencia doméstica establece como delito todas las formas de violencia contra la mujer. Esto implica para los estados miembros que:", "Pueden desarrollar estos delitos en sus sistemas jurídicos", "Ya no es necesario que introduzcan estos delitos en sus sistemas jurídicos", "Pueden introducir estos delitos en sus sistemas jurídicos.", "Deben introducir estos delitos en sus sistemas jurídicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 51, "La Convención sobre la eliminación de todas las formas de discriminación contra la mujer, aprobada por la Asamblea General de Naciones Unidas en diciembre de 1979, proclama el principio de igualdad de mujeres y hombres. En su art. 2 los miembros se comprometen a:", "Asegurar por ley u otros medios apropiados la realización práctica de este principio", "Instruir por ley u otros medios apropiados la realización de este principio", "Asegurar por ley u otros medios apropiados la valoración práctica de este principio", "Instruir por los medios que se consideren apropiados la realización teórica de este principio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 52, "El Tratado de Amsterdam formaliza el objetivo marcado explícitamente de que todas las actividades de la Unión Europea deben dirigirse a:", "Eliminar las desigualdades y promover la igualdad entre personas diferentes.", "Denunciar las desigualdades y promover la igualdad entre hombres y mujeres", "Eliminar las desigualdades y promover la igualdad entre hombres y mujeres.", "Evaluar las desigualdades existentes entre hombres y mujeres y promover la igualdad social."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 53, "El Convenio del Consejo de Europa sobre prevención y lucha contra la violencia contra las mujeres y la violencia doméstica establece que se entenderán por @violencia doméstica@:", "Todos los actos de violencia física, sexual, psicológica o económica que se producen en la familia o en el hogar o entre cónyuges o parejas de hecho antiguos o actuales, independientemente de que el autor del delito comparta o haya compartido el domicilio con la víctima.", "Todos los actos de violencia física, sexual, psicológica o económica que se producen en la familia o en el hogar o entre cónyuges o parejas de hecho actuales, independientemente de que el autor del delito comparta o haya compartido el domicilio con la víctima.", "Todos los actos de violencia física, sexual, psicológica o económica que se producen en la familia o en el hogar o entre cónyuges o parejas de hecho antiguos o actuales cuando el autor del delito comparta o haya compartido el domicilio con la víctima.", "Todos los actos de violencia física, sexual, psicológica o económica que se producen en la familia entre cónyuges o parejas de hecho actuales, independientemente de que el autor del delito comparta o haya compartido el domicilio con la víctima."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 54, "El objetivo de la Directiva (UE) 2019/1158 del Parlamento Europeo y del Consejo, de 20 de junio de 2019, relativa a la conciliación de la vida familiar y la vida profesional de los progenitores y cuidadores es:", "Establecer requisitos mínimos destinados a alcanzar la igualdad entre hombres y mujeres con respecto a las oportunidades en el mercado laboral y en el trato al trabajo, facilitando a todos los trabajadores la conciliación de la vida personal.", "Establecer una serie de normas de obligado cumplimiento destinadas a alcanzar la igualdad entre todos los hombres con respecto a las oportunidades en el mercado laboral y en el trato al trabajo, facilitando a los trabajadores que sean progenitores o cuidadores la conciliación de la vida familiar y profesional.", "Establecer requisitos mínimos destinados a alcanzar la igualdad entre hombres y mujeres con respecto a las oportunidades en el mercado laboral y en el trato al trabajo, facilitando a los trabajadores que sean progenitores o cuidadores la conciliación de la vida familiar y profesional.", "Establecer una serie de normas de obligado cumplimiento destinadas a alcanzar la igualdad entre hombres y mujeres con respecto a las oportunidades en el mercado laboral y en el trato al trabajo, facilitando a los trabajadores que sean progenitores o cuidadores la conciliación de la vida familiar y profesional"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 55, "El Convenio del Consejo de Europa sobre prevención y lucha contra la violencia contra las mujeres y la violencia doméstica establece que se entiende por @violencia contra la mujer por razones de género@:", "Toda violencia contra una mujer porque es una mujer y que afecta a las mujeres de manera proporcionada.", "Toda violencia contra una mujer porque es una mujer y que afecta a las mujeres de manera desproporcionada.", "La violencia física y psíquica contra una mujer porque es una mujer o que afecta a las mujeres de manera desproporcionada.", "Toda violencia contra una mujer porque es una mujer o que afecta a las mujeres de manera desproporcionada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 56, "¿Cuál de los siguientes no es un objetivo del Convenio del Consejo de Europa sobre prevención y lucha contra la violencia contra las mujeres y la violencia doméstica?:", "Proteger a las mujeres contra todas las formas de violencia y prevenir, y perseguir y eliminar la violencia contra la mujer y la violencia doméstica.", "Contribuir a eliminar toda forma de discriminación contra la mujer y promover la igualdad real entre mujeres y hombres, incluyendo el empoderamiento de las mujeres.", "Concebir un sistema penal específico, sistemas de detección y de medidas de asistencia legal a todas las víctimas de violencia contra la mujer y la violencia doméstica.", "Dar apoyo a las organizaciones y las fuerzas y cuerpos de seguridad para cooperar de manera eficaz para adoptar un enfoque integrado con vistas a eliminar la violencia contra la mujer y la violencia doméstica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 57, "Señalad cuál de los enunciados siguientes es falso:", "La Constitución española propugna como valores superiores de su ordenamiento jurídico la libertad, la justicia, la igualdad y el pluralismo político.", "La Constitución española establece que todos los españoles son iguales ante la ley, sin que pueda prevalecer discriminación alguna por razón de nacimiento, raza, sexo, religión, opinión o cualquier otra condición o circunstancia personal o social.", "La Constitución española ordena la sucesión al trono siguiendo el orden regular de primogenitura y representación, y será preferida siempre la línea anterior a las posteriores; en la misma línea, el grado más próximo al más remoto; en el mismo grado, la persona mayor, y en la misma edad, el hombre a la mujer.", "La Constitución española dicta que el hombre y la mujer tienen derecho a contraer matrimonio con plena igualdad jurídica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 58, "La finalidad de las medidas de protección integral establecidas por la Ley orgánica 1/2004, de 28 de diciembre, de medidas de protección integral contra la violencia de género es:", "Prevenir, sancionar y erradicar la violencia de género y prestar asistencia a las mujeres, a sus hijos menores y a los menores sujetos a su tutela, o guarda y custodia, que la sufran.", "Evaluar, sancionar y erradicar las desigualdades acaecidas por razón de género, y prestar asistencia a las mujeres, a sus hijos menores y a los menores sujetos a su tutela, o guarda y custodia, que la sufran.", "Prevenir, sancionar y erradicar la violencia de género y prestar asistencia a las mujeres, a sus hijos y a los menores sujetos a su tutela, o guarda y custodia, que la sufran.", "Evaluar, estructurar y erradicar la violencia de género y prestar asistencia a las mujeres, a sus hijos y a los menores sujetos a su tutela, o guarda y custodia, que la sufran."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 59, "De acuerdo con la Ley orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres, la igualdad de trato y de oportunidades entre mujeres y hombres es un principio informador del ordenamiento jurídico y como tal:", "Debe integrarse y observarse en la aplicación de las normas jurídicas", "Se puede integrar y observar en la interpretación y aplicación de las normas jurídicas.", "Debe integrarse y observarse en la interpretación y aplicación de las normas jurídicas.", "Se debe integrar y observar en la interpretación y aplicación de las sentencias"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 60, "¿Qué se considera discriminación indirecta por razón de sexo?:", "La situación en que se encuentra una persona que sea, haya sido o pueda ser tratada, teniendo en cuenta su sexo, de manera menos favorable que otra en situación comparable.", "La situación en que una disposición, un criterio o una práctica aparentemente neutras pone a personas de un sexo en desventaja particular respecto de personas del otro sexo, salvo que esta disposición, criterio o práctica se pueda justificar objetivamente en atención a una finalidad legítima y que los medios para alcanzar esta finalidad sean necesarios y adecuados.", "La situación en que se encuentra una persona que sea, haya sido o pueda ser tratada, sin tener en cuenta su sexo, de manera menos favorable que otra en situación comparable.", "La situación en que una disposición, un criterio o una práctica aparentemente neutras pone a personas de diferentes sexos en desventaja particular respecto de personas de los otros sexos, teniendo en cuenta que esta disposición, criterio o práctica se pueda justificar objetivamente en atención a una finalidad legítima y que los medios para alcanzar esta finalidad sean necesarios y adecuados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 61, "¿Cuál es el órgano responsable de adoptar planes y programas conjuntos de actuación para que la AGE y las administraciones de las comunidades autónomas cooperen para integrar el derecho de igualdad entre mujeres y hombres en el ejercicio de las competencias respectivas?:", "La Conferencia Sectorial de la Mujer.", "El Instituto de la Mujer.", "El Observatorio Estatal de Igualdad.", "La Conferencia Estatal de la Mujer."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 62, "¿Cuál de estas acciones no se prevé como un deber de las administraciones públicas, en el ámbito de las competencias respectivas y en aplicación del principio de igualdad entre mujeres y hombres?:", "Remover los obstáculos que implican la pervivencia de cualquier tipo de discriminación con el fin de ofrecer condiciones de igualdad efectiva entre mujeres y hombres al acceso al empleo público y en el desarrollo de la carrera profesional.", "Facilitar la conciliación de la vida personal, familiar y laboral, sin detrimento de la promoción profesional.", "Fomentar la formación en igualdad, tanto en el acceso al empleo público como a lo largo de la carrera profesional.", "Promover la presencia equilibrada de mujeres de todas las edades en los órganos de selección y valoración."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 63, "¿En qué casos no es necesario que se adjunte un informe de impacto de género a la aprobación de convocatorias de pruebas selectivas para el acceso al empleo público?:", "Si se trata de profesiones neutras", "En casos de urgencia y siempre sin perjuicio de la prohibición de discriminación por razón de sexo", "En casos en que en convocatorias similares ya haya cualquier prohibición de discriminación por razón de sexo.", "En casos de urgencia, si no hay una prohibición de discriminación por razón de sexo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 64, "¿En qué casos se puede establecer en las bases de los concursos para la provisión de puestos de trabajo que el tiempo de excedencia por cuidado de un hijo se compute a efectos de valoración del trabajo desarrollado y de los méritos correspondientes?:", "En cualquier caso.", "Cuando el aspirante sea una mujer", "Cuando el aspirante sea un hombre", "En cualquier caso, si se trata de una familia monoparental."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 65, "¿Cuáles de estos principios es imperativo en un protocolo de actuación para la prevención del acoso sexual y del acoso por razón de sexo de una administración pública?:", "El compromiso político de prevenir y no tolerar el acoso sexual y el acoso por razón de sexo.", "La instrucción a todo el personal sobre su deber de respetar la dignidad de las personas y el derecho a la intimidad, así como la igualdad de trato entre mujeres y hombres.", "El tratamiento público de las denuncias de hechos que puedan constituir acoso sexual o acoso por razón de sexo, sin perjuicio de lo que establece la normativa de régimen disciplinario.", "El anonimato de las personas responsables de atender a quienes formulan una queja o denuncia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 66, "¿Cuál es el objetivo de las acciones de responsabilidad social en materia de igualdad que pueden realizar las empresas?:", "Promover condiciones de igualdad entre las mujeres y los hombres en el seno de la empresa o en su entorno social.", "Velar para que se cumplan las condiciones de igualdad entre las mujeres y los hombres implantadas por la administración de cada comunidad autónoma en el seno de la empresa o en su entorno social.", "Promover condiciones de igualdad para las mujeres en el seno de la empresa o en su entorno social.", "Concertar con la comunidad autónoma condiciones de igualdad entre las mujeres y los hombres en el seno de la empresa o en su entorno social."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 28, 67, "¿Qué es el Consejo de Participación de la Mujer?:", "Es una secretaría general de consulta, vigilancia y asesoramiento, con la finalidad esencial de participar mediante diferentes vías en la consecución efectiva del principio de igualdad de trato.", "Es una secretaría general de consulta y asesoramiento, con la finalidad esencial de servir de vía para la participación de las mujeres en la consecución efectiva del principio de igualdad de trato y de oportunidades entre mujeres y hombres, y de luchar contra la discriminación por razón de sexo.", "Es un órgano colegiado de consulta, asesoramiento y vigilancia, con la finalidad esencial de servir de vía para la participación de las mujeres en la consecución efectiva del principio de igualdad de trato y de oportunidades entre mujeres y hombres, y de luchar contra la discriminación por razón de sexo.", "Es un órgano colegiado de consulta y asesoramiento, con la finalidad esencial de servir de vía para la participación de las mujeres en la consecución efectiva del principio de igualdad de trato y de oportunidades entre mujeres y hombres, y de luchar contra la discriminación por razón de sexo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 1, "El estatuto básico del empleado público refleja los siguientes fundamentos de actuación:", "Servicio a los ciudadanos y a sus intereses.", "Igualdad, mérito y comodidad en el acceso y en la promoción profesional.", "Sometimiento pleno a la ley y al decreto.", "Cooperación entre las Administraciones Públicas en la regulación y gestión del empleo público"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 2, "El estatuto básico del empleado público no se aplica al personal funcionario:", "De las Universidades Públicas y los centros de enseñanza sostenidos total o parcialmente con fondos públicos.", "De las Administraciones de las entidades locales.", "De los organismos públicos, agencias y demás entidades de derecho público con personalidad jurídica propia, vinculadas o dependientes de cualquiera de las Administraciones Públicas.", "De los cuerpos de Policía Local."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 3, "Al personal del Centro Nacional de Inteligencia le son de aplicación directa las disposiciones del estatuto básico del empleado público:", "Nunca.", "Siempre, pues forma parte de su legislación específica propia.", "Cuando así lo disponga su legislación específica.", "El centro Nacional de Inteligencia no existe en España recibe el nombre de Centro de Investigaciones Sociológicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 4, "El personal laboral al servicio de las Administraciones públicas se rige:", "b), c) y d) son correctas.", "Por la legislación laboral.", "Por los preceptos del estatuto básico del empleado público que así lo dispongan", "En materia de permisos de nacimiento, adopción, del progenitor diferente de la madre biológica y lactancia, se regirá por lo previsto en el estatuto básico del empleado público."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 5, "Quienes, al servicios de los intereses generales, desempeñan funciones retribuidas en las Administraciones públicas son:", "Los altos cargos de la administración.", "El personal retribuido por arancel.", "Los empleados públicos.", "Los intereses generales no tienen servicios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 6, "Los empleados públicos se clasifican en:", "Personal laboral, funcionarios interinos, personal eventual y funcionarios de carrera.", "Funcionarios de carrera.", "Funcionarios interinos y funcionarios de carrera.", "Personal eventual, funcionarios de carrera y funcionarios interinos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 7, "Quienes, en virtud de nombramiento legal, están vinculados a una Administración Pública por una relación estatutaria regulada por el Derecho Administrativo para el desempeño de servicios profesionales retribuidos de carácter permanente son:", "Personal Eventual.", "Funcionarios de carrera.", "Funcionarios interinos.", "Personal laboral fijo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 8, "Son funcionarios interinos:", "Quienes, por razones expresamente justificadas de necesidad y urgencia, son nombrados como tales con carácter temporal.", "Quienes, por razones expresamente justificadas de necesidad, son nombrados como tales con carácter temporal.", "Quienes, por razones de necesidad y urgencia, son nombrados como tales con carácter temporal.", "Quienes, por razones expresamente justificadas de necesidad y urgencia, son nombrados como tales con carácter permanente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 9, "Es personal laboral el que en virtud de contrato de trabajo, presta servicios para el desempeño de puestos de trabajo", "Cuyas funciones implican la participación directa o indirecta en el ejercicio de las potestades públicas o en la salvaguardia de los intereses generales.", "Cuyas funciones implican la participación indirecta en el ejercicio de las potestades públicas o en la salvaguardia de los intereses generales.", "Cuyas funciones no implican la participación directa o indirecta en el ejercicio de las potestades públicas o en la salvaguardia de los intereses generales.", "Cuyas funciones implican la participación directaen el ejercicio de las potestades públicas o en la salvaguardia de los intereses generales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 10, "Quién en virtud de nombramiento y con carácter no permanente, sólo realiza funciones expresamente calificadas como de confianza o asesoramiento especial:", "El nombramiento y cese tendrán lugar cuando así lo soliciten.", "Su condición no podrá constituir mérito para el acceso a la Función Pública o para la promoción interna.", "Le será aplicable el régimen general de los funcionarios interinos.", "Le será aplicable el régimen del personal laboral temporal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 11, "Quién desarrolla funciones directivas profesionales designado atendiendo a principios de mérito y capacidad y a criterios de idoneidad:", "Ocupa plazas cuyo sistema de provisión es la libre designación.", "Es un alto cargo de la administración.", "Estará sujeto a evaluación con arreglo a los criterios de eficacia y eficiencia, responsabilidad por su gestión y control de resultados en relación con los objetivos que les hayan sido fijados .", "La determinación de sus condiciones de empleo  tendrá la consideración de materia objeto de negociación colectiva."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 12, "Para los empleados públicos, la formación continua y la actualización permanente de sus conocimientos y capacidades profesionales es:", "Una obligación.", "Un derecho individual.", "Un derecho y una obligación.", "Un derecho."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 13, "¿Cuál de éstos no es un derecho individual de los empleados públicos?", "El desempeño efectivo de las funciones o tareas propias de su condición profesional y de acuerdo con la progresión alcanzada en su carrera profesional.", "El ejercicio de la huelga, con la garantía del mantenimiento de los servicios esenciales de la comunidad.", "La defensa jurídica y protección de la Administración Pública en los procedimientos que se sigan ante cualquier orden jurisdiccional como consecuencia del ejercicio legítimo de sus funciones o cargos públicos.", "La adopción de medidas que favorezcan la conciliación de la vida personal, familiar y laboral."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 14, "Los empleados públicos tienen los siguientes derechos individuales que se ejercen de forma colectiva, indica cuál de ellos no lo es:", "A la libertad sindical.", "Al de reunión, en los términos establecidos en el artículo 46 de este Estatuto.", "A la libre asociación profesional.", "Al ejercicio de la huelga, con la garantía del mantenimiento de los servicios esenciales de la comunidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 15, "El ascenso desde un cuerpo o escala de un Subgrupo, o Grupo de clasificación profesional en el supuesto de que éste no tenga Subgrupo, a otro superior, es la definición de:", "La carrera horizontal.", "La promoción interna horizontal.", "La carrera vertical.", "Ninguna de las anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 16, "Las leyes de función pública podrán regular la carrera horizontal de los funcionarios de carrera, pudiendo aplicar, entre otras, se deberán valorar:", "La trayectoria y actuación profesional.", "La cantidad de trabajos realizados.", "Los conocimientos individuales del empleado público.", "El resultado del examen del desempeño."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 17, "La promoción interna se realizará mediante procesos selectivos que garanticen el cumplimiento de los principios constitucionales de igualdad, mérito y capacidad, de acuerdo con lo previsto en el texto refundido de la Ley del Estatuto Básico del Empleado Público, los funcionarios deberán:", "Poseer los requisitos exigidos para el ingreso, salvo que algún decreto ley les exima de su cumplimiento.", "Tener una antigüedad de, al menos, dos años de servicio activo, o equivalente, en el anterior Subgrupo, o Grupo de clasificación profesional, en el supuesto de que éste no tenga Subgrupo.", "Superar las correspondientes pruebas selectivas.", "Cumplir más de cinco años en comisión de servicios en el mismo puesto implicará la promoción interna por concurso sin prueba alguna."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 18, "La carrera profesional y la promoción del personal laboral se hará efectiva a través de los procedimientos previstos:", "En el estatuto básico del empleado público.", "En los convenios colectivos según los acuerdos adoptados.", "Se realizarán según lo que prevea la normativa de selección del SOIB.", "En el Estatuto de los Trabajadores o en los convenios colectivos siempre que sean públicos, rigiéndose en todo caso por los principios de igualdad, mérito y capacidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 19, "El procedimiento mediante el cual se mide y valora la conducta profesional y el rendimiento o el logro de resultados de los empleados públicos", "Es la evaluación según la LOMLOE.", "Es el examen o prueba de selección para el acceso a un empleo público.", "Es la evaluación del desempeño.", "Es la prueba o examen del desempeño."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 20, "Los sistemas de evaluación del desempeño se adecuarán, en todo caso,", "A criterios de transparencia, objetividad, imparcialidad y no discriminación y se aplicarán sin menoscabo de los derechos de los empleados públicos.", "A criterios de transparencia, carrera, imparcialidad y no discriminación y se aplicarán sin menoscabo de los derechos de los empleados públicos.", "A criterios de transparencia, objetividad, discrecionalidad y no discriminación y se aplicarán sin menoscabo de los derechos de los empleados públicos.", "A criterios de transparencia, objetividad, imparcialidad y no discriminación y se aplicarán sin menosprecio de los derechos de los empleados públicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 21, "La continuidad en un puesto de trabajo obtenido por concurso quedará vinculada a la evaluación del desempeño de acuerdo con los sistemas de evaluación que cada Administración Pública determine, dándose audiencia al interesado, y por la correspondiente resolución motivada.", "Es falso, los funcionarios son inamovibles de su puesto de trabajo salvo por expediente disciplinario o sentencia judicial firme.", "Es falso, solamente afecta a la continuidad en un puesto de trabajo obtenido por libre designación.", "Es cierto pero requiere la aprobación previa de un sistema objetivo que permita evaluar el desempeño.", "Es parcialmente cierto, puesto que también afecta a la continuidad en un puesto obtenido por libre designación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 22, "Las cuantías de las retribuciones básicas y el incremento de las cuantías globales de las retribuciones complementarias de los funcionarios, así como el incremento de la masa salarial del personal laboral.", "Deberán reflejarse para cada ejercicio presupuestario en la correspondiente ley de presupuestos y no podrán acordarse incrementos retributivos que globalmente supongan un incremento de la masa salarial superior a los límites fijados anualmente en la Ley de Presupuestos Generales de la Comunidad Autónoma respectiva.", "Deberán reflejarse para cada ejercicio presupuestario en la correspondiente ley de presupuestos y no podrán acordarse incrementos retributivos que supongan un incremento de la masa salarial superior a los límites fijados anualmente en la Ley de Presupuestos Generales del Estado para el personal.", "Deberán reflejarse para cada ejercicio presupuestario en la correspondiente ley de presupuestos y no podrán acordarse incrementos retributivos que globalmente supongan un incremento de la masa salarial superior a los límites fijados anualmente en la Ley de Presupuestos Generales del Estado para el personal laboral.", "Deberán reflejarse para cada ejercicio presupuestario en la correspondiente ley de presupuestos y no podrán acordarse incrementos retributivos que globalmente supongan un incremento de la masa salarial superior a los límites fijados anualmente en la Ley de Presupuestos Generales del Estado para el personal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 23, "Las retribuciones de los funcionarios de carrera se clasifican en básicas y complementarias.", "Falso, se clasifican en básicas, complementaria y residencia.", "Cierto, pero las de los funcionarios interinos también.", "Falso, se clasifican en básicas, pagas extraordinarias y complementarias.", "Falso, se clasifican en básicas y complementos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 24, "Son retribuciones básicas.", "Las que retribuyen al funcionario según la adscripción de su cuerpo o escala a un determinado Subgrupo o Grupo de clasificación profesional, en el supuesto de que éste no tenga Subgrupo, y por su antigüedad en el mismo.", "Los componentes de sueldo, trienios, complemento de destino y complemento especifico de las pagas extraordinarias.", "Los componentes de sueldo, trienios y complemento de destino de las pagas extraordinarias.", "Los componentes de sueldo, trienios y complemento especifico de las pagas extraordinarias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 25, "La cuantía y estructura de las retribuciones complementarias de los funcionarios se establecerán por las correspondientes leyes de cada Administración Pública atendiendo, entre otros, a los siguientes factores:", "El tipo de interés, iniciativa o esfuerzo con que el funcionario desempeña su trabajo y el rendimiento o resultados obtenidos.", "Los servicios extraordinarios prestados fuera de la jornada normal de trabajo.", "La especial dificultad técnica, responsabilidad, dedicación exclusiva, incompatibilidad exigible para el desempeño de determinados puestos de trabajo o las condiciones en que se desarrolla el trabajo.", "La progresión alcanzada por el funcionario dentro del sistema de carrera administrativa vertical."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 26, "Las retribuciones que, como mínimo, se corresponderán a las del sueldo del Subgrupo o Grupo, en el supuesto de que éste no tenga Subgrupo, en que aspiren a ingresar.", "Son las retribuciones del personal laboral en prácticas.", "Son las retribuciones de los llamados -IR, o personal residente en la formación sanitaria especializada.", "Son la retribuciones de los funcionarios en prácticas.", "Son la retribuciones de los funcionarios interinos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 27, "Las retribuciones del personal laboral se determinarán de acuerdo con la legislación laboral, el convenio colectivo que sea aplicable y el contrato de trabajo.", "Cierto. Respetando en todo caso el incremento de la masa salarial reflejado para cada ejercicio presupuestario en la correspondiente ley de presupuestos.", "Parcialmente cierto. Solamente se determinarán de acuerdo con la legislación laboral y el convenio colectivo que sea aplicable.", "Falso. Las retribuciones del personal laboral se determinarán de acuerdo con la Ley de presupuestos generales del Estado.", "a) i b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 28, "Serán objeto de negociación colectiva, en su ámbito respectivo y en relación con las competencias de cada Administración Pública y con el alcance que legalmente proceda en cada caso, las materias siguientes:", "Los poderes de dirección y control propios de la relación jerárquica.", "Los planes de Previsión Social Complementaria.", "La regulación del ejercicio de los derechos de los usuarios de los servicios públicos.", "Las decisiones de las Administraciones Públicas que afecten a sus potestades de organización salvo las que afecten a la puesta en funcionamiento del transporte por tranvía, que se hará de acuerdo con lo que disponga el comité de empresa de la empresa pública correspondiente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 29, "Quedan excluidas de la obligatoriedad de la negociación colectiva, las materias siguientes:", "Los criterios generales para la determinación de prestaciones sociales y pensiones de clases pasivas.", "La determinación y aplicación de las retribuciones complementarias de los funcionarios.", "La regulación y determinación concreta, en cada caso, de los sistemas, criterios, órganos y procedimientos de acceso al empleo público y la promoción profesional.", "La aplicación del incremento de las retribuciones del personal al servicio de las Administraciones Públicas que se establezca en la Ley de Presupuestos Generales del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 30, "Las Juntas de Personal y los Delegados de Personal, en su caso, tendrán las siguientes funciones, en sus respectivos ámbitos:", "De vigilancia en el cumplimiento de las normas vigentes en materia laboral, de seguridad social y de empleo formulando, en su caso, las acciones legales oportunas ante el empresario y los organismos o tribunales competentes.", "Vigilar el cumplimiento de las normas vigentes en materia de condiciones de trabajo, prevención de riesgos laborales, Seguridad Social y empleo y ejercer, en su caso, las acciones legales oportunas ante los organismos competentes.", "De vigilancia en el cumplimiento de las normas vigentes en materia laboral, excepto en los supuestos de fraude de ley en la contratación, de seguridad social y de empleo formulando, en su caso, las acciones legales oportunas ante el empresario y los organismos o tribunales competentes.", "Vigilar el cumplimiento de las normas vigentes en materia de condiciones de trabajo, excepto el abuso de temporalidad, prevención de riesgos laborales, Seguridad Social y empleo y ejercer, en su caso, las acciones legales oportunas ante los organismos competentes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 31, "Los miembros de las Juntas de Personal y los Delegados de Personal, en su caso, como representantes legales de los funcionarios, dispondrán en el ejercicio de su función representativa de las siguientes garantías y derechos:", "No ser trasladados ni sancionados por causas relacionadas con el ejercicio de su mandato representativo, ni durante la vigencia del mismo, ni en el año siguiente a su extinción, exceptuando la extinción que tenga lugar por revocación o dimisión.", "Un crédito de horas mensuales dentro de la jornada de trabajo y retribuidas como de trabajo efectivo, de acuerdo con la siguiente escala: ? Hasta 100 funcionarios: 15. ? De 101 a 250 funcionarios: 20. ? De 251 a 500 funcionarios: 30. ? De 501 a 750 funcionarios: 35. ? De 751 en adelante: 40.", "El acceso y libre circulación por las dependencias de su unidad electoral, sin que se entorpezca el normal funcionamiento de las correspondientes unidades administrativas, dentro de los horarios habituales de trabajo.", "Todas las anteriores son ciertas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 32, "Las Leyes de Función Pública deberán", "Establecer el máximo de días adicionales de vacaciones en función del tiempo de servicios prestados por los funcionarios públicos.", "Establecer hasta dos días adicionales de permiso por asuntos particulares al cumplir el sexto trienio.", "Elaborar y aplicar un plan de igualdad a desarrollar en el convenio colectivo o acuerdo de condiciones de trabajo del personal funcionario que sea aplicable, en los términos previstos en el mismo.", "Todas las anteriores son ciertas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 33, "El desarrollo del Estatuto Básico del empleado público es competencia", "De las Cortes Generales.", "De las asambleas legislativas de las comunidades autónomas en el ámbito de sus competencias.", "De las Cortes Generales y las asambleas legislativas de las comunidades autónomas, en el ámbito de sus competencias.", "De las Cortes Generales y las asambleas legislativas de las comunidades autónomas, y de los órganos de Gobierno de la ciudades autónomas de Ceuta y Melilla, en el ámbito de sus competencias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 34, "Cuál de las siguientes no es una competencia de las Comunidades Autónomas en el desarrollo del Estatuto Básico del Empleado Público.", "Ampliar hasta doce meses la duración de los programas de carácter temporal ejecutados por funcionarios interinos.", "Previa negociación en la mesa correspondiente, determinar el número máximo de personal eventual.", "Establecer los criterios para la determinación de los puestos de trabajo que pueden ser desempeñados por personal laboral.", "Determinar los órganos de gobierno de las Administración Autonómica  que podrán disponer de personal eventual."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 35, "Son competencias del Estado, en el desarrollo del Estatuto Básico del Empleado Público.", "Regular la carrera profesional aplicable en cada ámbito.", "Regular la carrera horizontal de los funcionarios de carrera.", "Articular los sistemas para realizar la promoción interna, así como  determinar los cuerpos y escalas a los que podrán acceder los funcionarios de carrera pertenecientes a otros de su mismo Subgrupo.", "Todas las anteriores son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 36, "Determinar los cuerpos y escalas a los que podrán acceder los funcionarios de carrera pertenecientes a otros de su mismo Subgrupo.", "Es una competencia de las Comunidades Autónomas que deberá desarrollarse aprobando la correspondiente Ley de Función Pública en desarrollo del Estatuto Básico del Empleado Público.", "Es una competencia exclusiva de aquellas Comunidades Autónomas, constituidas de acuerdo con el artículo 143 de la Constitución Española.", "Es una competencia compartida de aquellas Comunidades Autónomas, constituidas de acuerdo con el artículo 144 de la Constitución Española.", "Ninguna de las anteriores es incorrecta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 37, "Las Leyes de Función Pública aprobadas por las asambleas legislativas de las Comunidades Autónoma en desarrollo del Estatuto Básico del Empleado Público...", "Adoptarán medidas que incentiven la gestión de su personal en los procesos selectivos de promoción interna y para la progresión en la carrera profesional.", "Podrán prolongar la permanencia en el servicio activo como máximo hasta que se cumpla setenta años de edad.", "No podrán establecer otros procedimientos de provisión en los supuestos de movilidad a que se refiere el artículo 81.2, permutas entre puestos de trabajo, movilidad por motivos de salud o rehabilitación del funcionario, reingreso al servicio activo, cese o remoción en los puestos de trabajo y supresión de los mismos.", "Establecerán los criterios para determinar los puestos que por su especial responsabilidad y confianza puedan cubrirse por el procedimiento de libre configuración con convocatoria pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 38, "Quedan reservadas al Estado, las competencias en desarrollo del Estatuto Básico del Empleado Público", "Establecer el plazo mínimo de ocupación de los puestos obtenidos por concurso para poder participar en otros concursos de provisión de puestos de trabajo.", "Establecer los criterios para determinar los puestos que por su especial responsabilidad y confianza puedan cubrirse por el procedimiento de libre designación con convocatoria pública.", "Determinar los supuestos para la declaración de la situación de servicios especiales.", "Todas las anteriores son competencias de las Comunidades Autónomas y se se podrán reflejarse en los supuestos que se determinen en las leyes de Función Pública que se dicten en desarrollo del Estatuto Básico del Empleado Público."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 39, "Las leyes de Función Pública que se dicten en desarrollo del Estatuto Básico del Empleado Público determinarán", "El régimen aplicable a las faltas leves.", "El régimen aplicable a las faltas muy graves.", "El régimen aplicable a las faltas graves.", "El alcance de las sanciones por la comisión de una falta grave o muy grave."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 40, "El permiso por fallecimiento, accidente o enfermedad graves, hospitalización o intervención quirúrgica sin hospitalización que precise de reposo domiciliario, de un familiar será:", "Si el familiar es de primer grado de consanguinidad o afinidad, tres días hábiles cuando el suceso se produzca en la misma localidad, y seis días hábiles cuando sea en distinta localidad.", "Si el familiar es de primer grado de consanguinidad o afinidad, tres días hábiles cuando el suceso se produzca en la misma localidad, y cinco días hábiles cuando sea en distinta localidad.", "Si el familiar es de primer o segundo grado de consanguinidad o afinidad, tres días hábiles cuando el suceso se produzca en la misma localidad, y cinco días hábiles cuando sea en distinta localidad.", "Si el familiar es de primer o segundo grado de consanguinidad o afinidad, dos días hábiles cuando se produzca en la misma localidad y de cuatro días hábiles cuando sea en distinta localidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 41, "Las Administraciones Públicas podrán establecer hasta dos días adicionales de permiso por asuntos particulares", "Al cumplir el sexto trienio, incrementándose, como máximo, en un día adicional por cada trienio cumplido a partir del octavo.", "Al cumplir el sexto trienio, incrementándose, como máximo, en un día adicional por cada trienio cumplido a partir del séptimo.", "Los días adicionales de permiso por asuntos particulares los establece el Estado.", "Las Administraciones Públicas podrán establecer hasta dos días adicionales de permiso por asuntos particulares en el momento de cumplir el trienio que consideren oportuno, incrementándose, como máximo, en un día adicional por cada trienio cumplido a partir del octavo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 42, "Los funcionarios de carrera no podrán hallarse en la situación administrativa", "Servicio activo.", "Servicios especiales.", "Servicio en otras Administraciones Públicas.", "Excedencia forzosa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 43, "Se hallarán en situación de servicio activo quienes", "Quienes presten servicios ocupando un puesto de trabajo en comisión de servicios.", "Quienes sean activados como reservistas voluntarios para prestar servicios en las Fuerzas Armadas.", "Quienes sean autorizados para realizar una misión por periodo determinado superior a seis meses en organismos internacionales, gobiernos o entidades públicas extranjeras o en programas de cooperación internacional.", "Quienes hayan sido declarados en suspensión de funciones con carácter provisional."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 44, "Quienes se encuentren en situación de excedencia por interés particular", "Podrán permanecer en dicha situación un máximo de quince años.", "Les será computable el tiempo que permanezcan en tal situación a efectos de ascensos.", "No devengarán retribuciones.", "Seguirán en situación de alta en el régimen de Seguridad Social que les sea de aplicación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 45, "Los funcionarios de carrera tendrán derecho a un período de excedencia de duración no superior a tres años", "Para atender al cuidado de un familiar que se encuentre a su cargo, hasta el segundo grado inclusive de consanguinidad o afinidad que por razones de voluntad, accidente, enfermedad o discapacidad no pueda valerse por sí mismo y no desempeñe actividad retribuida.", "Para atender al cuidado de cada hijo, tanto cuando lo sea por naturaleza como por adopción o menor en acogimiento permanente.", "Por agrupación familiar sin el requisito de haber prestado servicios efectivos en cualquiera de las Administraciones Públicas durante el periodo establecido a los funcionarios cuyo cónyuge resida en otra localidad por haber obtenido y estar desempeñando un puesto de trabajo de carácter definitivo como funcionario de carrera o como laboral fijo en cualquiera de las Administraciones Públicas.", "Ninguna de las anteriores es incorrecta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 46, "Podrán participar en los cursos de formación que convoque la Administración aquellos funcionarios en situación administrativa", "De excedencia forzosa.", "De excedencia por cuidado de familiares.", "De servicios especiales.", "De comisión de servicios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 47, "Los funcionarios de carrera serán declarados en situación de excedencia forzosa", "Cuando sean designados miembros del Gobierno o de los órganos de gobierno de las comunidades autónomas.", "Cuando accedan a la condición de Diputado o Senador de las Cortes Generales o miembros de las asambleas legislativas de las comunidades autónomas si perciben retribuciones periódicas por la realización de la función.", "Cuando sean designados como personal eventual por ocupar puestos de trabajo con funciones expresamente calificadas como de confianza o asesoramiento político y no opten por permanecer en la situación de servicio activo.", "En ningún caso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 48, "¿Qué funcionarios de carrera serán declarados en situación de servicio en otras Administraciones Públicas?", "Aquellos que en virtud de los procesos de transferencias obtengan destino en una Administración Pública distinta.", "Aquellos que por comisión de servicios obtengan destino en una Administración Pública distinta.", "Aquellos que adquieran la condición de funcionarios al servicio de organizaciones internacionales.", "Ninguna de las anteriores es incorrecta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 49, "Las situaciones del personal laboral", "No existen.", "Serán las mismas que los funcionarios.", "Serán las establecidas por el Estatuto de los Trabajadores y por los Convenios Colectivos que les sean de aplicación.", "Los convenios colectivos determinarán la aplicación del capítulo de situaciones administrativas de los funcionarios al personal incluido en su ámbito de aplicación en lo que resulte compatible con el Estatuto de los Trabajadores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 50, "El régimen disciplinario del personal laboral", "Se regirá por el Estatuto de los Trabajadores y por los Convenios Colectivos que les sean de aplicación y en lo no previsto se regirá por el régimen disciplinario de los funcionarios.", "Se regirá por lo previsto en el título del régimen disciplinario de los funcionarios públicos, y en lo no previsto en dicho título se regirá por la legislación laboral.", "El código penal español únicamente prevé delitos cometidos por funcionarios públicos, no por el personal laboral.", "Cada administración determinará que régimen disciplinario se aplica al personal laboral."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 51, "Son faltas muy graves", "El abandono del servicio durante un mínimo de dos días.", "No hacerse cargo de las tareas o funciones que tienen encomendadas.", "La publicación o utilización indebida de la documentación o información a que tengan o hayan tenido acceso por razón de su cargo o función.", "La prevalencia de la condición de empleado público para obtener un beneficio debido para sí o para otro."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 52, "Por la comisión de faltas graves podrán imponerse las siguientes sanciones", "Separación del servicio de los funcionarios.", "Despido disciplinario del personal laboral.", "Suspensión firme de funciones, o de empleo y sueldo en el caso del personal laboral, con una duración máxima de 6 años.", "Suspensión firme de funciones, o de empleo y sueldo en el caso del personal laboral, con una duración máxima de 6 meses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 53, "La Ley 3/2007, de 27 de marzo, de la Función Pública de la Comunidad Autónoma de las Illes Balears consta", "De un título preliminar y 145 artículos organizados en diez títulos.", "De un preámbulo y 145 artículos organizados en diez títulos.", "De un título preliminar y 145 artículos organizados en once títulos.", "De un preámbulo y 145 artículos organizados en once títulos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 54, "La Ley 3/2007, de 27 de marzo, de la Función Pública de la Comunidad Autónoma de las Illes Balears consta", "De 19 Disposiciones Adicionales y  8 Disposiciones transitorias, de las cuáles hay 2 séptimas.", "De 18 Disposiciones Adicionales y  9 Disposiciones transitorias, de las cuáles hay 2 séptimas.", "De 19 Disposiciones Adicionales y  9 Disposiciones transitorias, de las cuáles hay 2 séptimas.", "De 18 Disposiciones Adicionales y  8 Disposiciones transitorias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 55, "El capítulo I del título II, de la Ley 3/2007, de 27 de marzo, de la Función Pública de la Comunidad Autónoma de las Illes Balears regula", "Los entes competentes en materia de función pública.", "Órganos competentes en materia de función pública.", "La escuela balear de administración pública.", "Órganos y entes competentes en materia de función pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 56, "Queda excluido de la aplicación de la ley de función pública de la Comunidad Autónoma de les Illes Balears el siguiente personal", "Personal del Consejo Consultivo y del Consejo Económico y Social.", "Personal de la Sindicatura de Greuges y de la Sindicatura de Cuentas de las Illes Balears.", "Personal de las universidades públicas radicadas en la Comunidad Autónoma de las Illes Balears que no forme parte de los cuerpos docentes e investigadores.", "Personal de la Agencia Tributaria de las Illes Balears."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 57, "El título III, de la Ley 3/2007, de 27 de marzo, de la Función Pública de la Comunidad Autónoma de las Illes Balears regula", "Personal funcionario de carrera y funcionario interino.", "Personal laboral fijo y temporal.", "Personal eventual.", "Todas las anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 58, "El título IX de la la Ley 3/2007, de 27 de marzo, de la Función Pública de la Comunidad Autónoma de las Illes Balears", "Está dividido en tres capítulos: el primero regula los deberes del personal funcionario; el segundo, su régimen retributivo y de la Seguridad Social, y el tercero, el régimen de incompatibilidades.", "Está dividido en tres capítulos: el primero regula los derechos del personal funcionario; el segundo, su régimen retributivo y de la Seguridad Social, y el tercero, sus deberes y el régimen de incompatibilidades.", "Está dividido en cuatro capítulos: el primero regula los derechos del personal funcionario; el segundo, su régimen retributivo y de la Seguridad Social,  el tercero, sus deberes,  y el cuarto, el régimen de incompatibilidades.", "Está dividido en cuatro capítulos: el primero regula los derechos del personal funcionario; el segundo, su régimen retributivo, el tercero, el régimen de la Seguridad Social,  y el cuarto, sus deberes y el régimen de incompatibilidades."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 59, "La Ley 3/2007, de 27 de marzo, de la Función Pública de la Comunidad Autónoma de las Illes Balears  dispone una vacatio legis de", "Tres meses después de su publicación íntegra en el Butlletí Oficial de les Illes Balears.", "Dos meses después de su publicación íntegra en el Butlletí Oficial de les Illes Balears.", "Un mes después de su publicación íntegra en el Butlletí Oficial de les Illes Balears.", "El general para toda ley, veinte días después de su publicación íntegra en el Butlletí Oficial de les Illes Balears."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 60, "El objeto, principios y ámbito de aplicación de la Ley 3/2007, de 27 de marzo, de la Función Pública de la Comunidad Autónoma de las Illes Balears se recogen en", "El Título IV", "El Título II", "El Título I", "El Título III"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 61, "De acuerdo con lo previsto en el Estatuto Básico del Empleado Público, para poder participar en los procesos selectivos será necesario reunir los siguientes requisitos", "Poseer la titulación estudiada.", "Otros requisitos específicos que guarden relación objetiva y proporcionada con las funciones asumidas y las tareas a desempeñar. En todo caso, habrán de establecerse de manera abstracta y general.", "Tener la nacionalidad española en todo caso.", "Tener cumplidos dieciocho años y no exceder, en su caso, de la edad máxima de jubilación forzosa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 62, "La jubilación forzosa de los funcionarios se declarará", "De oficio al cumplir el funcionario los sesenta y cinco años de edad.", "A petición del interesado al cumplir la edad que prevean las normas reguladoras del régimen de Seguridad Social para el acceso a la pensión de jubilación en su modalidad contributiva.", "Por la declaración de invalidez para el ejercicio de las funciones propias de su cuerpo o escala, o por el reconocimiento de una pensión de incapacidad permanente absoluta o, incapacidad permanente total en relación con el ejercicio de las funciones de su cuerpo o escala.", "Al ser la jubilación un derecho de la persona trabajadora, ésta será siempre a instancia de parte."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 63, "En caso de extinción de la relación de servicios como consecuencia de pérdida de la nacionalidad o jubilación por incapacidad permanente para el servicio, el interesado, una vez desaparecida la causa objetiva que la motivó, podrá solicitar la rehabilitación de su condición de funcionario", "Que le será concedida si hay vacante.", "Que le será concedida en todo caso.", "Que podrá ser concedida con carácter excepcional.", "Si transcurrido el plazo para dictar la resolución, no se hubiera producido de forma expresa, se entenderá desestimada la solicitud."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 64, "Son causas de pérdida de la condición de funcionario de carrera, de acuerdo con lo previsto en el Estatuto Básico del Empleado Público.", "La denuncia a la condición de funcionario.", "La pérdida de la nacionalidad.", "La sanción disciplinaria de suspensión del servicio que tuviere carácter firme.", "La jubilación parcial del funcionario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 65, "Es requisito indispensable para adquirir la condición de funcionario", "Superar del proceso selectivo.", "Llevar más de tres años como funcionario interino.", "Toma de posesión de forma inmediata posterior al nombramiento.", "Acto voluntario de acatamiento de la Constitución y, en su caso, del Estatuto de Autonomía correspondiente y del resto del Ordenamiento Jurídico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 66, "Los sistemas selectivos de funcionarios de carrera serán", "La oposición y el concurso-oposición que deberán incluir, en todo caso, una o varias pruebas para determinar la capacidad de los aspirantes y establecer el orden de prelación.", "En determinadas plazas, con carácter general será el concurso.", "La libre designación.", "El que se establezca en cada oferta de empleo público."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 20, 67, "Los procesos selectivos que incluyan, además de las preceptivas pruebas de capacidad, la valoración de méritos de los aspirantes", "Podrán otorgar a dicha valoración una puntuación proporcionada que podrá determinar el resultado del proceso selectivo.", "Sólo podrán otorgar a dicha valoración una puntuación proporcionada que no determinará, en ningún caso, por sí misma el resultado del proceso selectivo.", "La valoración de los méritos es a efectos de establecer el orden de prelación, en ningún caso puede determinar superar el proceso selectivo.", "La valoración de méritos de los aspirantes es para el concurso de provisión de puestos de trabajo, no para el ingreso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 1, "Según el art. 60.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, se entiende por orden superior:", "La emitida por un órgano administrativo superior jerárquico del competente para la iniciación del procedimiento.", "La emitida por por cualquier órgano administrativo que no tiene competencia para iniciar el procedimiento.", "El acto por el que cualquier persona pone en conocimiento de un órgano administrativo la existencia de un determinado hecho que pudiera justificar la iniciación de oficio de un procedimiento.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 2, "Según el art. 62.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo al inicio del procedimiento por denuncia:", "Las denuncias deberán expresar la identidad de la persona o personas que las presentan.", "Las denuncias se podrán presentar anónimamente.", "Las denuncias siempre deberán identificar a los presuntos responsables.", "Las denuncias deberán calificar jurídicamente la infracción cometida."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 3, "Según el art. 63.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "No se podrán imponer sanciones por faltas graves o muy graves sin que se haya tramitado el oportuno procedimiento.", "En ningún caso se podrá imponer una sanción sin que se haya tramitado el oportuno procedimiento.", "No se podrá imponer ninguna sanción sin que se haya tramitado el procedimiento sancionador que regula el título IV de esta Ley.", "En ningún caso se podrá imponer una sanción sin que se haya tramitado el oportuno procedimiento, salvo en los casos en que la legislación específica lo autorice."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 4, "De acuerdo con el art. 64.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el acuerdo de iniciación de los procedimientos de naturaleza sancionadora:", "Debe designar siempre un secretario.", "Se notificará al inculpado únicamente cuando pueda ser interesado en el procedimiento.", "Debe contener la identificación de la persona o personas presuntamente responsables.", "Se notificará al instructor del procedimiento de acuerdo con los artículos 40 a 46 de esta Ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 5, "Según el art. 65.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿cuál es el plazo para presentar alegaciones en los procedimientos de responsabilidad patrimonial?", "Diez días, a contar desde que se dicta el acuerdo de iniciación del procedimiento.", "Quince días, a contar desde la notificación del acuerdo de iniciación del procedimiento.", "Diez días, a contar desde la notificación del acuerdo de iniciación del procedimiento.", "No hay ningún plazo específico para presentar alegaciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 6, "Según el art. 75.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, los actos de instrucción que requieran la intervención de los interesados habrán de practicarse:", "En la forma que resulte más conveniente para ellos y sea compatible, en la medida de lo posible, con sus obligaciones laborales o profesionales.", "En la forma que resulte más conveniente para la Administración y atendiendo al interés público.", "En la forma que resulte más conveniente para ellos y sea compatible, en la medida de lo posible, con el horario de atención al público.", "En la forma que resulte más conveniente para el órgano instructor."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 7, "Según el art. 77.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, se abrirá un período de prueba:", "Cuando la Administración no tenga por ciertos los hechos alegados por los interesados.", "Cuando la Administración no tenga por ciertos los hechos alegados por los interesados o la naturaleza del procedimiento lo exija.", "A petición de los interesados, cuando la naturaleza del procedimiento lo exija.", "A petición de los interesados, cuando la Administración no tenga por ciertos los hechos alegados por éstos o cuando la naturaleza del procedimiento lo exija."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 8, "Según el art. 77.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el período extraordinario de prueba se abrirá:", "Cuando el instructor lo considere necesario, a petición de los interesados, por un plazo no superior a diez días.", "Cuando el instructor lo considere necesario, a petición de los interesados, por un plazo no superior a quince días.", "Cuando el instructor lo considere necesario, por un plazo no superior a diez días.", "Cuando el instructor lo considere necesario, por un plazo no superior a treinta días ni inferior a diez."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 9, "Indique cuál de las siguientes afirmaciones es correcta de acuerdo con el art. 77.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo a los medios y el período de prueba:", "El instructor podrá decidir la apertura de un período extraordinario de prueba por un plazo no superior a quince días.", "La duración del período ordinario de prueba será inferior a treinta días.", "El instructor puede rechazar pruebas propuestas por los interesados.", "Los hechos declarados probados en actos administrativos firmes vinculan a las Administraciones Públicas respecto de los procedimientos sancionadores que substancien."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 10, "Según el art. 77.5 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, los documentos formalizados por los funcionarios a los que se reconoce la condición de autoridad y en los que, observándose los requisitos legales correspondientes se recojan los hechos constatados por aquéllos:", "Harán prueba de éstos.", "Harán prueba de éstos salvo que se acredite lo contrario.", "No harán prueba de éstos salvo que se acredite lo contrario.", "No harán prueba de éstos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 11, "Indique cuál de las siguientes afirmaciones es correcta de acuerdo con el art. 78.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo a la práctica de la prueba:", "La Administración comunicará a los interesados, con una antelación no inferior a diez días ni superior a quince, el inicio del período de prueba.", "El interesado puede nombrar técnicos para que le asistan.", "Las pruebas cuya realización implique gastos para la Administración serán pagadas por el interesado.", "Los documentos formalizados por los funcionarios a los que se reconoce la condición de autoridad siempre harán prueba de su contenido."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 12, "Según el art. 78.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿en qué casos la Administración podrá exigir el pago de los gastos de la práctica de pruebas?", "En los casos en que deban efectuarse pruebas cuya realización implique gastos que no deba soportar la Administración.", "En los casos en que, a petición del interesado, deban efectuarse pruebas cuya realización implique gastos que no deba soportar la Administración.", "En los casos en que, a petición del interesado, deban efectuarse pruebas cuya realización implique gastos que deba soportar la Administración.", "En los casos en que deban efectuarse pruebas cuya realización implique gastos que deba soportar la Administración."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 13, "Según el art. 80.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿en qué plazo serán emitidos los informes?", "En el plazo de diez días, salvo que una disposición o el cumplimiento del resto de los plazos del procedimiento permita o exija otro plazo mayor o menor.", "En un plazo no inferior a diez días ni superior a quince.", "En el plazo de quince días, salvo que una disposición o el cumplimiento del resto de los plazos del procedimiento permita o exija otro plazo mayor o menor.", "En un plazo no superior a treinta días ni inferior a diez."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 14, "Según el art. 80.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, de no emitirse el informe en el plazo señalado:", "Se podrán proseguir las actuaciones salvo cuando se trate de un informe preceptivo, en cuyo caso se deberá suspender el transcurso del plazo máximo legal para resolver.", "Se podrán proseguir las actuaciones salvo cuando se trate de un informe preceptivo, en cuyo caso se podrá suspender el transcurso del plazo máximo legal para resolver.", "Se podrán proseguir las actuaciones cuando se trate de un informe preceptivo, en cuyo caso se deberá suspender el transcurso del plazo máximo legal para resolver.", "No se podrán proseguir las actuaciones salvo cuando se trate de un informe preceptivo, en cuyo caso se deberá suspender el transcurso del plazo máximo legal para resolver."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 15, "Según el art. 80.4 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el informe emitido fuera de plazo por una administración pública distinta de la que tramita el procedimiento:", "Podrá no ser tenido en cuenta al adoptar la correspondiente resolución.", "No podrá ser tenido en cuenta al adoptar la correspondiente resolución.", "Deberá ser tenido en cuenta al adoptar la correspondiente resolución.", "No podrá ser tenido en cuenta al adoptar la correspondiente resolución, salvo lo dispuesto en la normativa sectorial específica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 16, "Según el art. 81.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo a los procedimientos de responsabilidad patrimonial, ¿qué carácter tiene el informe del servicio cuyo funcionamiento haya ocasionado la presunta lesión indemnizable?", "Preceptivo.", "Preceptivo y vinculante.", "Facultativo.", "Facultativo y no vinculante."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 17, "Según el art. 81.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, en el caso de reclamaciones en materia de responsabilidad patrimonial del Estado por el funcionamiento anormal de la Administración de Justicia, el plazo para dictar resolución:", "Podrá quedar suspendido por el tiempo que medie entre la solicitud del informe del Consejo General del Poder Judicial y su recepción, no pudiendo exceder dicho plazo de dos meses.", "Quedará suspendido por el tiempo que medie entre la solicitud del informe del Consejo General del Poder Judicial y su recepción, no pudiendo exceder dicho plazo de dos meses.", "Podrá quedar suspendido por el tiempo que medie entre la solicitud del informe del Consejo General del Poder Judicial y su recepción, no pudiendo exceder dicho plazo de un mes.", "Quedará suspendido por el tiempo que medie entre la solicitud del informe del Consejo General del Poder Judicial y su recepción, no pudiendo exceder dicho plazo de un mes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 18, "Según el art. 81.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, en el caso de reclamaciones en materia de responsabilidad patrimonial del Estado por el funcionamiento anormal de la Administración de Justicia:", "Será preceptivo el informe del Consejo General del Poder Judicial que será evacuado en el plazo máximo de dos meses.", "Será preceptivo el informe del Consejo General del Poder Judicial que será evacuado en el plazo máximo de un mes.", "Será preceptivo y vinculante el informe del Consejo General del Poder Judicial que será evacuado en el plazo máximo de dos meses.", "Será preceptivo y vinculante el informe del Consejo General del Poder Judicial que será evacuado en el plazo máximo de un mes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 19, "Según el art. 82.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el trámite de audiencia será:", "Posterior a la solicitud del informe del órgano competente para el asesoramiento jurídico.", "Anterior a la fase de prueba.", "Anterior a la solicitud del informe del órgano competente para el asesoramiento jurídico.", "Anterior a la fase de información pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 20, "Según el art. 82.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, si antes del vencimiento del plazo de audiencia los interesados manifiestan su decisión de no efectuar alegaciones ni aportar nuevos documentos o justificaciones:", "No se tendrá por realizado el trámite.", "Se entenderá que el interesado desiste del procedimiento.", "Se interrumpirá el plazo para resolver.", "Se tendrá por realizado el trámite."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 21, "Según el art. 82.4 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿cuándo se podrá prescindir del trámite de audiencia?", "Cuando la Administración no tenga por ciertos los hechos alegados por los interesados o la naturaleza del procedimiento lo exija.", "Cuando lo requiera la naturaleza del procedimiento.", "Cuando no figuren en el procedimiento ni sean tenidos en cuenta en la resolución otros hechos ni otras alegaciones y pruebas que las aducidas por el interesado.", "Cuando los interesados en el procedimiento sean desconocidos o se ignore el lugar de la notificación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 22, "Según el art. 83.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, se podrá acordar un período de información pública:", "Cuando no figuren en el procedimiento ni sean tenidos en cuenta en la resolución otros hechos ni otras alegaciones y pruebas que las aducidas por el interesado.", "Cuando la naturaleza del procedimiento lo requiera.", "Cuando la Administración no tenga por ciertos los hechos alegados por los interesados o la naturaleza del procedimiento lo exija.", "Cuando hubiera otros interesados en el procedimiento, a fin de que aleguen cuanto estimen procedente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 23, "Según el art. 83.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, la incomparecencia en el trámite de información pública:", "Impedirá a los interesados interponer los recursos procedentes contra la resolución definitiva del procedimiento.", "Implicará la pérdida de la condición de interesado.", "No impedirá a los interesados interponer los recursos procedentes contra la resolución definitiva del procedimiento.", "Implicará la renuncia del interesado a su pretensión en el procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 24, "Indique cuál de las siguientes afirmaciones es correcta según el art. 83.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo al trámite de información pública:", "La duración de este trámite no será inferior a diez días ni superior a quince.", "Quienes presenten alegaciones u observaciones en este trámite tienen derecho a obtener de la Administración una respuesta razonada.", "El plazo para presentar alegaciones será de treinta días.", "Quienes presenten alegaciones u observaciones tendrán la condición de interesados en el procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 25, "Según el art. 84.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, son formas de terminación del procedimiento:", "La resolución, el desistimiento, la prescripción, y la declaración de caducidad.", "La resolución, el desistimiento, la renuncia y la declaración de caducidad.", "La resolución, el allanamiento, la renuncia y la declaración de caducidad.", "La resolución, el desistimiento, el allanamiento, la renuncia y la declaración de caducidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 26, "Según el art. 85.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, las reducciones en el importe de la sanción por reconocimiento de la responsabilidad y por pago voluntario anterior a la resolución:", "Serán de al menos el 20 %, siendo éstos acumulables entre sí.", "Serán como máximo del 20%, siendo éstos acumulables entre sí.", "Serán de al menos el 20 %, no siendo éstos acumulables entre sí.", "Serán como máximo del 20%, no siendo éstos acumulables entre sí."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 27, "El porcentaje de reducción de la sanción previsto en el art. 85.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Solamente podrá ser incrementado mediante una ley sectorial específica.", "No podrá ser incrementado.", "Podrá ser incrementado reglamentariamente.", "No podrá ser incrementado reglamentariamente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 28, "Según el art. 86.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, los pactos y los acuerdos que suscriban las Administraciones Públicas:", "Deberán establecer las partes intervinientes, el ámbito personal, funcional y territorial, y el plazo de vigencia.", "Deberán publicarse en el boletín oficial que corresponda.", "Requerirán la aprobación del Consejo de Gobierno cuando supongan una alteración de las competencias atribuidas a otras Administraciones Públicas.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 29, "Según el art. 87 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿en qué plazo deben practicarse las actuaciones complementarias?", "En un plazo no inferior a diez días ni superior a quince.", "En un plazo no superior a diez días.", "En un plazo no inferior a quince días.", "En un plazo no superior a quince días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 30, "Indique cuál de las siguientes afirmaciones es correcta según el art. 87 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo a la práctica de actuaciones complementarias:", "Los informes que preceden inmediatamente a la resolución final tendrán la consideración de actuaciones complementarias.", "Se concederá un plazo no inferior a siete días para formular alegaciones.", "Las actuaciones complementarias deberán practicarse en un plazo de siete días.", "El plazo para resolver el procedimiento quedará suspendido hasta la terminación de las actuaciones complementarias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 31, "Según el art. 87 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, las actuaciones complementarias serán acordadas:", "Por el órgano competente para resolver.", "Por el instructor del procedimiento.", "Por el órgano competente para dictar la resolución de inicio.", "Por el órgano instructor o el órgano competente para resolver."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 32, "Según el art. 88.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, cuando haya cuestiones conexas que no hubieran sido planteadas por los interesados:", "El órgano competente podrá pronunciarse sobre estas cuestiones, poniéndolo antes de manifiesto a los interesados por un plazo no superior a quince días.", "El órgano competente podrá pronunciarse sobre estas cuestiones, y debe conceder un plazo de siete días a los interesados para formular las alegaciones que tengan por pertinentes.", "El órgano competente podrá pronunciarse sobre estas cuestiones, poniéndolo antes de manifiesto a los interesados por un plazo no inferior a quince días.", "El órgano instructor podrá pronunciarse sobre estas cuestiones, poniéndolo antes de manifiesto a los interesados por un plazo no superior a diez días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 33, "Según el art. 88.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, las resoluciones:", "Contendrán la decisión, que será motivada en los casos a que se refiere el artículo 35.", "Contendrán la decisión, que podrá ser motivada en los casos a que se refiere el artículo 37.", "Podrán contener la decisión, que será motivada en los casos a que se refiere el artículo 35.", "Podrán contener la decisión, que podrá ser motivada en los casos a que se refiere el artículo 37."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 34, "Según el art. 89.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿en cuál de los siguientes supuestos el órgano instructor debe resolver la finalización del procedimiento sancionador con el archivo de las actuaciones?", "Cuando los hechos constituyan una infracción manifiesta.", "Cuando se concluya que ha caducado la infracción.", "Cuando los hechos no resulten acreditados.", "Cuando  el instructor no tenga por ciertos los hechos alegados por los interesados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 35, "Según el art. 89.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿qué órgano debe formular la propuesta de resolución en los procedimientos de carácter sancionador?", "El órgano competente para dictar la resolución de inicio.", "El órgano instructor.", "El órgano competente para resolver.", "El órgano competente para resolver a propuesta del instructor."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 36, "Según el art. 90.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, cuando el órgano competente para resolver considere que la infracción o la sanción revisten mayor gravedad que la determinada en la propuesta de resolución, se notificará al inculpado para que aporte cuantas alegaciones estime convenientes:", "En un plazo no inferior a quince días.", "En un plazo no superior a diez días.", "En el plazo de quince días.", "En un plazo no inferior a diez días ni superior a quince."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 37, "Según el art. 90.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, cuando la resolución que ponga fin a los procedimientos de carácter sancionador sea ejecutiva:", "Se podrá suspender cautelarmente, si el interesado manifiesta a la Administración su intención de interponer recurso contencioso-administrativo contra la resolución firme en vía administrativa.", "Se suspenderá cautelarmente, si el interesado manifiesta a la Administración su intención de interponer recurso ordinario en vía administrativa.", "Se suspenderá cautelarmente, si el interesado manifiesta a la Administración su intención de interponer recurso contencioso-administrativo contra la resolución definitiva en vía administrativa.", "Se podrá suspender cautelarmente, si el interesado manifiesta a la Administración su intención de interponer recurso ordinario en vía administrativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 38, "Según el art. 90.4 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, cuando las conductas sancionadas hubieran causado daños o perjuicios a las Administraciones y la cuantía destinada a indemnizar estos daños no hubiera quedado determinada en el expediente:", "Se fijará mediante un nuevo procedimiento contradictorio, cuya resolución no será firme en vía administrativa.", "Se retrotraerá el procedimiento a la fase de instrucción a fin de que el órgano instructor cuantifique los daños o perjuicios.", "Se podrá fijar mediante un procedimiento complementario, cuya resolución será firme en vía administrativa.", "Se fijará mediante un procedimiento complementario, cuya resolución será inmediatamente ejecutiva."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 39, "Según el art. 91.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el procedimiento de responsabilidad patrimonial podrá finalizar:", "Por resolución administrativa.", "Por resolución administrativa o mediante acuerdo entre la Administración y el interesado.", "Por resolución administrativa o por silencio positivo.", "Por resolución administrativa, por silencio positivo, o mediante acuerdo entre la Administración y el interesado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 40, "Según el art. 91.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, cuando la Administración no cumpla la obligación de resolver y notificar el procedimiento de responsabilidad patrimonial en el plazo de seis meses:", "Se producirá la caducidad del procedimiento.", "Podrá entenderse que la resolución es contraria a la indemnización del particular.", "La solicitud podrá entenderse estimada por silencio administrativo.", "La indemnización se fijará mediante un procedimiento complementario, cuya resolución será firme en vía administrativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 41, "Indique cuál de las siguientes afirmaciones es correcta según el art. 94.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "En los procedimientos iniciados a instancia de parte, la Administración podrá desistir motivadamente.", "En los procedimientos iniciados de oficio, los interesados podrán desistir y renunciar a sus derechos.", "En los procedimientos iniciados a instancia de parte, los interesados podrán desistir de su solicitud.", "En los procedimientos iniciados de oficio y a instancia de parte, la Administración podrá desistir motivadamente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 42, "Según el art. 94.4 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿de qué plazo disponen los terceros interesados para instar la continuación del procedimiento en caso de desistimiento o renuncia?", "Siete días.", "Diez días.", "Quince días.", "Un plazo no inferior a quince días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 43, "Según el art. 94.5 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, si la cuestión suscitada por la incoación del procedimiento entrañase interés general o fuera conveniente sustanciarla para su definición y esclarecimiento:", "La Administración podrá limitar los efectos del desistimiento o la renuncia al interesado y seguirá el procedimiento.", "La Administración podrá limitar los efectos del desistimiento al interesado y seguirá el procedimiento.", "La Administración no podrá limitar los efectos del desistimiento o la renuncia.", "La Administración deberá limitar los efectos de la renuncia al interesado y seguirá el procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 44, "Según el art. 95.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, contra la resolución que declare la caducidad:", "Procederán los recursos pertinentes.", "No se podrá interponer ningún recurso, si bien podrá notificarse a los interesados a los meros efectos informativos.", "Se podrán presentar alegaciones en un plazo no inferior a diez días ni superior a quince.", "Los interesados podrán manifestar su oposición cuando la resolución sea firme en vía administrativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 45, "Según el art. 95.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, en los procedimientos iniciados a solicitud del interesado, cuando se produzca su paralización por causa imputable al mismo:", "La Administración le podrá advertir que, transcurridos tres meses, se producirá la caducidad del procedimiento.", "La Administración le advertirá que, transcurridos seis meses, se producirá la caducidad del procedimiento.", "La Administración le podrá advertir que, transcurridos seis meses, se producirá la caducidad del procedimiento.", "La Administración le advertirá que, transcurridos tres meses, se producirá la caducidad del procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 46, "Según el art. 95.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "La prescripción no producirá por sí sola la caducidad de las acciones del particular o de la Administración.", "La caducidad producirá la prescripción de las acciones del particular o de la Administración.", "La prescripción producirá la caducidad de las acciones del particular o de la Administración.", "La caducidad no producirá por sí sola la prescripción de las acciones del particular o de la Administración."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 47, "Según el art. 96.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, cuando se haya iniciado la tramitación simplificada del procedimiento, el órgano competente podrá continuar con arreglo a la tramitación ordinaria en cualquier momento del procedimiento:", "Anterior a su resolución.", "Anterior al trámite de audiencia.", "Anterior al trámite de información pública.", "Anterior al período de prueba."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 48, "Según el art. 96.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, la Administración deberá seguir la tramitación ordinaria:", "Cuando alguno de los interesados manifieste su conformidad a la tramitación simplificada.", "Cuando la mayoría de los interesados manifieste su oposición expresa a la tramitación simplificada.", "Cuando alguno de los interesados manifieste su oposición expresa a la tramitación simplificada.", "Cuando todos los interesados manifiesten su oposición expresa a la tramitación simplificada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 49, "Según el art. 96.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, cuando los interesados soliciten la tramitación simplificada del procedimiento, el órgano competente:", "Podrá desestimar dicha solicitud, en el plazo de cinco días desde su presentación, sin que exista posibilidad de recurso por parte del interesado.", "Deberá estimar dicha solicitud en el plazo de cinco días desde su presentación.", "Podrá desestimar dicha solicitud, en el plazo de cinco días desde su presentación, mediante resolución motivada, que será susceptible de recurso.", "Deberá desestimar dicha solicitud, en el plazo de diez días desde su presentación, sin que exista posibilidad de recurso por parte del interesado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 50, "Según el art. 96.5 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, cuando el órgano competente considere que hay elementos de juicio suficientes para calificar una infracción como leve:", "Podrá adoptar la tramitación simplificada del procedimiento, sin que quepa oposición expresa por parte del interesado.", "Deberá adoptar la tramitación simplificada del procedimiento, sin que quepa oposición expresa por parte del interesado.", "Podrá adoptar la tramitación simplificada del procedimiento, salvo que alguno de los interesados manifieste su oposición expresa.", "Deberá adoptar la tramitación simplificada del procedimiento, salvo que alguno de los interesados manifieste su oposición expresa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 51, "Según el art. 96.6 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, en los procedimientos de tramitación simplificada el dictamen del Consejo de Estado:", "Deberá ser emitido en el plazo de diez días.", "Deberá ser emitido en el plazo de quince días.", "Deberá ser emitido en el plazo de un mes.", "Podrá ser emitido en el plazo de quince días si así lo solicita el órgano competente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 52, "Según el art. 98.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, los actos de las Administraciones Públicas sujetos al Derecho Administrativo serán inmediatamente ejecutivos:", "Salvo que se trate de un procedimiento de responsabilidad patrimonial.", "Aunque se trate de un procedimiento de tramitación simplificada.", "Salvo que se produzca la suspensión de la ejecución del acto.", "Aunque se produzca la suspensión de la ejecución del acto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 53, "Según el art. 99 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, las Administraciones Públicas pueden proceder a la ejecución forzosa de los actos administrativos:", "A través de sus órganos competentes, salvo que la Constitución o la Ley exijan la intervención de un órgano judicial.", "A través de sus órganos, con la autorización previa del órgano judicial competente.", "A través del órgano judicial competente, con la autorización previa del Consejo de Ministros o del órgano equivalente de las comunidades autónomas.", "A través del órgano judicial competente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 54, "Según el art. 100.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, las Administraciones Públicas pueden entrar en el domicilio del afectado sin autorización judicial:", "Con el consentimiento del afectado.", "Cuando así lo disponga una resolución administrativa.", "Con el informe previo y vinculante del Consejo de Estado o del órgano consultivo autonómico.", "Cuando el afectado manifieste su consentimiento en un proceso judicial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 55, "Según el art. 101.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, se seguirá el procedimiento de apremio:", "Cuando en virtud de acto administrativo hubiera de satisfacerse cantidad líquida.", "Cuando los actos administrativos impongan una obligación personalísima de no hacer o soportar.", "Cuando se trate de actos que por no ser personalísimos puedan ser realizados por sujeto distinto del obligado.", "Cuando en virtud de acto administrativo hubiera de satisfacerse cantidad líquida y se cuente con la oportuna autorización judicial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 56, "Según el art. 101.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "No podrá imponerse a los administrados una obligación pecuniaria sin autorización judicial.", "No podrá imponerse a los administrados una obligación pecuniaria que no estuviese establecida con arreglo a una norma de rango legal.", "Se podrá imponer a los administrados una obligación pecuniaria que no esté prohibida mediante una norma de rango legal.", "Se podrá imponer a los administrados una obligación pecuniaria que esté establecida mediante una norma de rango legal o reglamentario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 57, "Según el art. 102.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, habrá lugar a la ejecución subsidiaria:", "Cuando los actos administrativos impongan una obligación personalísima de no hacer o soportar.", "Cuando se trate de actos que por no ser personalísimos puedan ser realizados por sujeto distinto del obligado.", "Cuando en virtud de acto administrativo hubiera de satisfacerse cantidad líquida.", "Cuando se trate de actos que por no ser personalísimos puedan ser realizados por sujeto distinto del obligado y se disponga de la correspondiente autorización judicial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 58, "¿En cuál de los supuestos siguientes puede imponerse la multa coercitiva según el art. 103.1, letra b), de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas?", "Cuando el acto carezca de los requisitos formales indispensables para alcanzar su fin o dé lugar a la indefensión de los interesados", "En los actos que impongan una obligación personalísima de no hacer o soportar.", "Cuando las indemnizaciones reclamadas sean de cuantía igual o superior a 50.000 euros.", "En los actos en que, procediendo la compulsión, la Administración no la estimara conveniente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 59, "Según el art. 104.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, cuando se imponga una obligación personalísima de hacer y el obligado no realice la prestación:", "El obligado deberá resarcir los daños y perjuicios, a cuya liquidación y cobro se procederá en vía administrativa.", "Habrá lugar a la ejecución subsidiaria del acto en vía administrativa.", "Se liquidarán los daños y perjuicios de forma provisional, a reserva de la liquidación definitiva.", "Se aplicarán los medios de ejecución forzosa respetando el principio de proporcionalidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 60, "Según el art. 47 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la Administración de la Comunidad Autónoma de las Illes Balears, el cómputo del plazo establecido para resolver y notificar empezará a computarse:", "Desde la fecha de la solicitud.", "Desde la fecha de presentación de la solicitud en el registro.", "Desde la fecha de entrada en el registro del órgano competente para su tramitación.", "Desde la fecha de nombramiento del instructor."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 61, "Según el art. 50.2 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la Administración de la Comunidad Autónoma de las Illes Balears, cuando las normas reguladoras de los procedimientos no fijen el plazo máximo para dictar y notificar la resolución expresa, éste será de:", "Tres meses.", "Seis meses.", "Un año.", "Un mes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 62, "Según el art. 50.3.a) de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la Administración de la Comunidad Autónoma de las Illes Balears, el plazo máximo para dictar y notificar la resolución expresa en los procedimientos sancionadores ordinarios respecto de los cuales la Comunidad Autónoma dispone de competencia normativa, es:", "De un año.", "De seis meses.", "De tres meses.", "De un mes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 63, "Según el art. 50.3 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la Administración de la Comunidad Autónoma de las Illes Balears, el plazo máximo para dictar y notificar la resolución expresa en los procedimientos sancionadores abreviados respecto de los cuales la comunidad autónoma dispone de competencia normativa, es:", "De un año.", "De un año, salvo que la normativa procedimental de carácter específico fije un plazo superior.", "De seis meses.", "De seis meses, salvo que la normativa procedimental de carácter específico fije un plazo superior."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 64, "Indique cuál de las siguientes afirmaciones es incorrecta según el art. 50 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la Administración de la Comunidad Autónoma de las Illes Balears:", "El plazo máximo para dictar y notificar la resolución expresa en los procedimientos de competencia de la Comunidad Autónoma es el que fije la norma reguladora del procedimiento correspondiente, y en su defecto el plazo será de seis meses.", "El plazo máximo para dictar y notificar la resolución expresa en todos los procedimientos de competencia de la Comunidad Autónoma es de seis meses.", "El plazo máximo para dictar y notificar la resolución expresa en los procedimientos sancionadores ordinarios es de un año, salvo que la normativa procedimental de carácter específico establezca un plazo superior.", "El plazo máximo para dictar y notificar la resolución expresa en los procedimientos sancionadores abreviados es de seis meses, salvo que la normativa procedimental de carácter específico establezca un plazo superior."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 65, "Según el art. 51, letra b), de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la Administración de la Comunidad Autónoma de las Illes Balears, en los procedimientos iniciados a instancia de parte se puede establecer el silencio negativo:", "Mediante una norma de derecho comunitario.", "Mediante una norma con rango de ley por razones imperiosas de interés general.", "Mediante una norma con rango de ley por razones imperiosas de interés general o mediante una norma de derecho comunitario.", "Mediante una norma con rango reglamentario o de ley por razones imperiosas de interés general o mediante una norma de derecho comunitario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 66, "Según el art. 51 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la Administración de la Comunidad Autónoma de las Illes Balears, en los procedimientos para la concesión de ayudas y de subvenciones públicas, ¿qué efectos tiene el silencio administrativo?", "La solicitud se entiende desestimada.", "La solicitud se entiende estimada.", "Se produce la caducidad del procedimiento.", "Se produce la prescripción del derecho."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 14, 67, "Según el art. 52 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la Administración de la Comunidad Autónoma de las Illes Balears, las medidas de ejecución previstas en los acuerdos y las resoluciones:", "Deberán ser ordenadas por el superior jerárquico del órgano que las hubiera dictado.", "Deberán ser ordenadas por el mismo órgano que las hubiera dictado.", "Podrán ser ordenadas por el mismo órgano que las hubiera dictado.", "Podrán ser ordenadas por el mismo órgano que las hubiera dictado o por el órgano superior jerárquico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 1, "Los cargos públicos del Sistema judicial que no pueden, de acuerdo con el artículo 127 de la Constitución española, ejercer otros cargos públicos ni pertenecer a partidos políticos o a sindicatos mientras sigan en activo son:", "Solo los jueces.", "Los magistrados y los fiscales.", "Los jueces y los magistrados.", "Los jueces, los magistrados y también los fiscales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 2, "Según el artículo 62 de la Constitución española, ¿a quién corresponde convocar y disolver las Cortes Generales y convocar elecciones?", "Al presidente del Gobierno.", "Al presidente del Congreso de los Diputados.", "Al rey.", "Al Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 3, "Según el artículo 62 de la Constitución española, ¿a quién corresponde sancionar y promulgar las leyes?", "Al rey.", "Al  Congreso de los Diputados.", "Al Senado.", "Al Gobierno"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 4, "Según el artículo 63 de la Constitución española, ¿a quién corresponde acreditar a los embajadores y otros representantes diplomáticos?", "Al ministro competente en materia de relaciones exteriores.", "Al presidente del Congreso de los Diputados.", "Al presidente del Gobierno.", "Al rey."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 5, "Según el artículo 66 de la Constitución española, las Cortes Generales ejercen la potestad legislativa del Estado:", "Y aprueban los presupuestos y controlan la acción del Gobierno.", "Y elaboran los presupuestos y controlan la acción de los gobiernos autonómicos.", "Y elaboran los presupuestos y controlan la acción del Gobierno.", "Y aprueban los presupuestos y controlan la acción de los gobiernos autonómicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 6, "Según el artículo 117 de la Constitución española, ¿qué tipo de tribunales judiciales quedan prohibidos expresamente?", "Los tribunales de honor.", "Los tribunales militares.", "Los tribunales de excepción.", "Los jurados populares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 7, "Según el artículo 117 de la Constitución española, ¿cuál es la base de la organización y del funcionamiento de los tribunales judiciales?", "El principio de independencia.", "El principio de unidad jurisdiccional.", "El principio de objetividad.", "El principio de libertad jurisdiccional."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 8, "Según el artículo 119 de la Constitución española, ¿es gratuita la justicia?", "Sí, siempre.", "Cuando lo disponga la ley.", "Sí, para aquellos que acrediten insuficiencia de recursos para litigar.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 9, "Según el artículo 120 de la Constitución española, los procedimientos judiciales serán predominantemente orales, ¿en qué materia especialmente?", "Criminal.", "Penal.", "Mercantil.", "Civil."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 10, "Según el artículo 121 de la Constitución española, los daños causados por error judicial y los que sean como consecuencia del funcionamiento anormal de la Administración de justicia, ¿a qué darán derecho?", "A la repetición del proceso judicial.", "A una indemnización a cargo del Estado.", "A interponer un nuevo recurso judicial.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 11, "Según el artículo 136 de la Constitución española, el Tribunal de Cuentas dependerá directamente:", "Del Consejo de Ministros.", "Del ministro competente en materia de Hacienda.", "Del ministerio Fiscal.", "De las Cortes Generales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 12, "Según el artículo 136 de la Constitución española, la composición, la organización y las funciones del Tribunal de Cuentas las regulará:", "Una ley ordinaria.", "Un real decreto.", "Una ley orgánica.", "El reglamento del Tribunal de Cuentas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 13, "Según el artículo 136 de la Constitución española, ¿cuál  es el órgano fiscalizador supremo de las cuentas y de la gestión económica del Estado?", "El ministerio competente en materia de Hacienda.", "El Tribunal de Cuentas.", "El ministerio  fiscal.", "El Consejo Económico y Social."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 14, "Según el artículo 136 de la Constitución española, ¿ qué tipo de informe remitirá el Tribunal de Cuentas a las Cortes Generales?", "Un informe anual.", "Un informe semestral.", "Un informe trimestral.", "Un informe bimensual."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 15, "Según el artículo 120 de la Constitución española, ¿cómo seran las sentencias judiciales?", "Motivadas siempre y pronunciadas en audiencia privada.", "Motivadas siempre en materia penal y pronunciadas en audiencia pública.", "Motivadas siempre y pronunciadas en audiencia pública.", "Motivadas en algunos casos tasados y pronunciadas en audiencia privada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 16, "Según el artículo 62 de la Constitución española, corresponde al rey:", "Aprobar y sancionar las leyes.", "Nombrar a los embajadores y el resto de representantes del Gobierno ante los demás Gobiernos extranjeros.", "Nombrar y separar a los miembros del Gobierno, a propuesta de su presidente.", "Ejercer el derecho de gracia y conceder indultos generales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 17, "De acuerdo con el artículo 122 de la Constitución española, ¿cuál es el órgano de gobierno de la Administración de Justicia?", "El ministerio fiscal.", "El ministerio competente en materia de justicia.", "El Consejo General del Poder Judicial.", "El Consejo de Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 18, "De acuerdo con el artículo 122 de la Constitución española, ¿quién preside el Consejo General del Poder Judicial?", "El ministro competente en materia de justicia.", "El presidente del Tribunal Constitucional.", "El presidente de la Audiencia Provincial.", "El presidente del Tribunal Supremo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 19, "De acuerdo con el artículo 122 de la Constitución española, ¿cuántos miembros forman parte del Consejo General del Poder Judicial?", "Veinte miembros.", "Quince miembros", "Doce miembros.", "Dieciocho miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 20, "De acuerdo con el artículo 122 de la Constitución española, ¿cuántos miembros del Consejo General del Poder Judicial son propuestos por las Cortes Generales?", "Dos miembros cada cámara.", "Tres miembros cada cámara.", "Cuatro miembros cada cámara.", "Cinco miembros cada cámara."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 21, "De acuerdo con el artículo 124 de la Constitución española, ¿qué órgano tiene la misión de promover la acción de la justicia en defensa de la legalidad?", "El ministerio fiscal.", "El Consejo General del Poder Judicial.", "El ministerio competente en materia de justicia.", "El Tribunal Supremo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 22, "De acuerdo con el artículo 124 de la Constitución española, ¿quién propone el nombramiento del fiscal general del Estado?", "El rey.", "Las Cortes Generales.", "El Gobierno.", "El ministerio fiscal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 23, "De acuerdo con el artículo 122 de la Constitución española, los miembros del Consejo General del Poder Judicial serán nombrados por un período de:", "De tres años.", "De cinco años.", "De siete años.", "De nueve años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 24, "Según el artículo 125 de la Constitución española, ¿los ciudadanos pueden ejercer la acción popular y participar en la Administración de justicia?", "No, únicamente pueden hacerlo  los Tribunales.", "Sí, mediante la institución del Jurado.", "Sí, en los tribunales consuetudinarios y tradicionales.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 25, "Según el artículo 126 de la Constitución española, ¿de quién depende la policía judicial?", "Del ministerio fiscal y del fiscal general del Estado.", "De los jueces, de los tribunales y del ministerio fiscal.", "De los jueces y de los tribunales.", "Del Tribunal Supremo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 26, "Según el artículo 127 de la Constitución española, los jueces, magistrados y fiscales mientras se hallen en activo podrán:", "Desempeñar otros cargos públicos.", "Pertenecer a partidos políticos.", "Asociarse profesionalmente según la ley.", "Pertenecer a sindicatos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 27, "Según el artículo 117 de la Constitución española, los jueces y magistrados que integran el poder judicial son:", "Independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley.", "Independientes, imparciales, responsables y sometidos únicamente al imperio de la ley.", "Independientes, inamovibles, objetivos y sometidos únicamente al imperio de la ley.", "Independientes, inamovibles, imparciales y sometidos únicamente al imperio de la Constitución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 28, "El principio de independencia de los Jueces consiste:", "En juzgar y hacer ejecutar lo juzgado.", "En la potestad jurisdiccional.", "En dictar sentencia.", "En aplicar las leyes sin la intervención de otro poder."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 29, "Según el artículo 54 de la Constitución española, ¿quién es el alto comisionado de les Cortes Generales que tiene como misión defensar los derechos comprendidos en el título I?", "El fiscal general del estado.", "El Defensor del Pueblo.", "El ministro competente en materia de justicia.", "El presidente del Consejo General del Poder Judicial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 30, "Según el artículo 62 de la Constitución española, la potestad de convocar a Referéndum, en los casos previstos en la Constitución, corresponde:", "Al presidente del Gobierno.", "Al Consejo de Ministros.", "Al Rey.", "A las Cortes Generales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 31, "Según el artículo 162 de la Constitución española, el Defensor del Pueblo podrá interponer:", "Recursos de amparo.", "Recursos de inconstitucionalidad.", "Cuestiones de inconstitucionalidad.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 32, "Según el artículo 54 de la Constitución española, ¿qué tipo de norma regulará la institución del Defensor del Pueblo?", "Una ley orgánica.", "Un real decreto.", "Una ley ordinaria.", "Un reglamento de las Cortes Generales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 33, "Según el artículo 66 de la Constitución española, las Cortes Generales representan:", "La soberanía nacional.", "La soberanía popular.", "Al pueblo español.", "Al Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 34, "Según el artículo 66 de la Constitución española, ¿qué institución representa al pueblo español?", "El Gobierno del Estado.", "Las Cortes Generales.", "El Defensor del Pueblo.", "El Congreso de los Diputados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 35, "Según el artículo 66 de la Constitución española, las Cortes Generales tienen como función:", "Ejercer la potestad legislativa.", "Elaborar los Presupuestos Generales del Estado.", "Dirigir la acción del Gobierno.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 36, "De acuerdo con el artículo 56 de la Constitución española, la persona del rey es inviolable:", "Y es el responsable último del Estado y su buen desarrollo.", "Y es el responsable de la imagen exterior de España.", "Y es responsable del orden y consistencia del Estado Mayor y el ejército.", "Y no está sujeta a responsabilidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 37, "De acuerdo con el artículo 57 de la Constitución española, el príncipe heredero tendrá la dignidad:", "De príncipe de España.", "De otros títulos nobiliarios vinculados al sucesor de la Corona.", "De príncipe de Asturias y los otros títulos vinculados al sucesor de la Corona.", "De príncipe de Asturias y Aragón y los otros títulos vinculados al sucesor de la Corona."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 38, "Según el artículo 57 de la Constitución española, habiéndose extinguido todas las líneas llamadas en derecho:", "El Gobierno convocará un referéndum.", "Las Cortes Generales propondrán un heredero alternativo y se someterá a referéndum.", "El Congreso proveerá a la sucesión a la Corona en la forma que más convenga al interés general.", "Las Cortes Generales proveerán a la sucesión a la Corona en la forma que más convenga a los intereses de España."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 39, "Según el artículo 59 de la Constitución española, si no hubiese ninguna persona a quien le correspondiese la Regencia, en caso de inhabilidad o minoría de edad del Rey, ésta será nombrada por las Cortes Generales, y se compondrá:", "De una, tres o cinco personas.", "De una, dos o cuatro personas.", "De hasta un máximo de siete personas.", "De una, tres o seis personas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 40, "De acuerdo con el artículo 57 de la Constitución española, las abdicaciones y las renuncias y cualquier duda de hecho o de derecho que ocurra en el orden de sucesión a la Corona se resolverán:", "Con la votación por mayoría absoluta de las Cortes Generales.", "Con un referéndum.", "Con un Real decreto.", "Con una ley orgánica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 41, "De acuerdo con el artículo 62 de la Constitución española, ¿cuál de las siguientes funciones NO corresponde al rey?", "El mando supremo de las Fuerzas Armadas.", "Sancionar y promulgar las leyes.", "Nombrar y remover los miembros del Congreso a proposición del presidente del Gobierno.", "El Alto Patronaje de las reales academias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 42, "De acuerdo con el artículo 63 de la Constitución española, ¿a quién corresponde manifestar el consentimiento del Estado para obligarse internacionalmente mediante tratados?", "Al Congreso.", "A las Cortes Generales.", "Al presidente del Gobierno.", "Al rey."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 43, "De acuerdo con el artículo 65 de la Constitución española, el rey percibe de los presupuestos del Estado:", "El rey no percibe nada de los presupuestos del Estado.", "El rey percibe de los presupuestos una cantidad mínima para el sostenimiento de la Corona y sus funciones esenciales.", "El rey percibe de los presupuestos una cantidad global para el sostenimiento de su Familia y Casa, y la distribuye libremente.", "El rey percibe de los presupuestos una cantidad global para el sostenimiento de su Familia y Casa, pero la distribuye según las indicaciones de las Cortes Generales y lo establecido en la Constitución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 44, "¿ En qué título de la Constitución española se regula lo relativo a las Cortes Generales?", "En el título IV.", "En el título II.", "En el título III.", "En el título IX."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 45, "De acuerdo con el artículo 66 de la Constitución española, las Cortes Generales representan al pueblo español y están formadas:", "Por el Congreso de los Diputados.", "Por el Senado.", "Por los diputados y el presidente.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 46, "De acuerdo con el artículo 68 de la Constitución española, el Congreso se compone:", "De un mínimo de 300 y un máximo de 400 diputados.", "De un mínimo de 200 y un máximo de 300 diputados.", "De un mínimo de 200 y un máximo de 400 diputados.", "De un mínimo de 350 y un máximo de 400 diputados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 47, "Según el artículo 68 de la Constitució española, el Congreso es elegido por un mandato:", "De tres años.", "De dos años.", "De cuatro años.", "De cinco años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 48, "De acuerdo con el artículo 69 de la Constitución española, el Senado es la cámara:", "De representación nacional.", "De representación estatal.", "De representación constitucional.", "De representación territorial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 49, "Según el artículo 69 de la Constitución española, los votantes de cada provincia, mediante sufragio universal, libre, igual, directo y secreto, elegirán:", "Tres senadores.", "Cuatro senadores.", "Dos senadores.", "Cinco senadores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 50, "De acuerdo con el artículo 69 de la Constitución española, el Senado es elegido por un mandato:", "De cinco años.", "De tres años.", "De cuatro años.", "De seis años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 51, "De acuerdo con el artículo 71 de la Constitución española, durante el período de su mandato, los diputados y los senadores gozarán de inmunidad :", "Y no podrán ser inculpados ni procesados en ningún caso.", "Y no podrán ser detenidos sin la autorización previa del presidente del Congreso.", "Y serán jurídicamente inviolables en todos los casos.", "Y solo podrán ser detenidos en caso de flagrante delito. Además, no podrán ser inculpados o procesados sin la autorización previa de la cámara respectiva."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 52, "Según el artículo 71 de la Constitución española, en las causas contra diputados y senadores será competente:", "La Sala Penal del Tribunal Supremo.", "La Sala Penal del Tribunal Superior de Justicia.", "La Sala Penal del Tribunal Constitucional.", "La Sala Penal de la Audiencia Provincial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 53, "De acuerdo con el artículo 73 de la Constitución española, el Congreso y el Senado se reunirán anualmente:", "En cuatro periodos ordinarios de sesiones al año.", "En dos períodos ordinarios de sesiones durante seis meses del año.", "En dos períodos ordinarios de sesiones: de setiembre a diciembre y de febrero a junio.", "En tres períodos ordinarios de sesiones: de septiembre a diciembre, de febrero a abril y de mayo a julio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 54, "De acuerdo con el artículo 77 de la Constitución española, las cámaras de  las Cortes Generales pueden recibir peticiones:", "Individuales y por escrito.", "Colectivas, de cualquier forma.", "Individuales y colectivas por via directa, incluida la manifestación ciudadana.", "Individuales y colectivas, pero siempre por escrito. Queda prohibida la presentación directa por medio de manifestaciones ciudadanas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 55, "Según el artículo 78 de la Constitución española, en cada cámara de las Cortes Generales habrá una Diputación Permanente compuesta por un mínimo:", "De veinte miembros.", "De veintitrés miembros.", "De veintiún miembros.", "De veintidós miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 56, "De acuerdo con el artículo 79 de la Constitución española, el voto de los senadores y los diputados es:", "Personal y delegable.", "Colectivo y delegable.", "Representativo e indelegable.", "Personal e indelegable."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 57, "De acuerdo con el artículo 80 de la Constitución española, las sesiones plenarias de las cámaras de las Cortes Generales serán:", "Siempre públicas.", "Siempre privadas.", "Públicas, salvo el acuerdo en contra de cada cámara.", "Privadas, salvo el cuerdo en contra de cada cámara."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 58, "De acuerdo con el artículo 81 de la Constitución española, son leyes orgánicas las relativas al desarrollo:", "De los derechos fundamentales.", "De las libertades públicas.", "De los derechos humanos y políticos.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 59, "Según el artículo 81 de la Constitución española, la aprobación, la modificación o la derogación de las leyes orgánicas exige:", "La mayoría simple del Congreso en una votación final sobre el conjunto del proyecto.", "La mayoría absoluta del Congreso en una votación final sobre el conjunto del proyecto.", "La mayoría cualificada del Congreso en una votación final sobre la ley en cuestión.", "La mayoría absoluta del Congreso y del Senado en una votación global sobre la ley en cuestión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 60, "De acuerdo con el artículo 82 de la Constitución española, ¿a quién podrán delegar las Cortes Generales la potestad de dictar normas con rango de ley?", "Al rey.", "A los gobiernos autonómicos.", "Al Gobierno del Estado.", "A los parlamentos autonómicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 61, "Según el artículo 82 de la Constitución española, la delegación legislativa de las Cortes Generales habrá de otorgarse mediante:", "Mediante una ley orgánica.", "Mediante una ley de bases.", "Mediante un real decreto.", "Mediante una ley marco."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 62, "De acuerdo con el artículo 85 de la Constitución española, las disposiciones del Gobierno que contengan legislación delegada recibirán el título:", "De decretos obligatorios.", "De reales decretos.", "De decretos legislativos.", "De decretos de delegación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 63, "Según el artículo 86 de la Constitución española, ¿qué materia no pueden regular los decretos ley dictados por el gobierno?", "Los derechos, los deberes y las libertades de los ciudadanos regulados en el título I.", "El derecho electoral general.", "El régimen de las comunidades autónomas.", "Las respuestas a), b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 64, "Según el artículo 87 de la Constitución española, de acuerdo con la Constitución y los Reglamentos de las Cámaras de las Cortes Generales, la iniciativa legislativa corresponde:", "Al Gobierno.", "Al Congreso de los Diputados y el Gobierno.", "Al Gobierno y el Senado.", "Al Gobierno, el Congreso y el Senado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 65, "De acuerdo con el artículo 87 de la Constitución española, una ley orgánica regulará las formas de ejercicio y  requisitos de la iniciativa popular para la presentación de proposiciones de ley, para las cuales en cualquier caso se requerirá:", "No menos de 50.000 firmas acreditadas.", "No menos de 100.000 firmas acreditadas.", "No menos de 500.000 firmas acreditadas.", "No menos de 300.000 firmas acreditadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 66, "De acuerdo con el artículo 88 de la Constitución española, los proyectos de ley serán aprobados:", "Por el Congreso, el cual los someterá al Consejo de Ministros.", "Por el Consejo de Ministros, el cual los someterá al Congreso.", "Por el Congreso, el cual los someterá al Senado.", "Por el Senado, el cual los someterá al rey."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 2, 67, "De acuerdo con el artículo 91 de la Constitución española, el rey sancionará las leyes aprobadas por las Cortes Generales dentro del plazo:", "De quince días.", "De diez días.", "De treinta días.", "De veinte días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 1, "¿Cuáles son, según la doctrina clásica, las formas de acción administrativa?", "La actividad de fomento, la de policía, la de contratación y la de servicio público.", "La actividad de fomento y la de servicio público.", "La actividad de fomento, la de policía y la de servicio público.", "La actividad contractual, la de policía y la de servicio público."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 2, "Indica cuál de las siguientes son características de los servicios públicos:", "Tienen por objeto la satisfacción de un interés general y una necesidad de la colectividad.", "Su régimen jurídico es de derecho privado.", "Se rigen, entre otros, por los principios de continuidad, igualdad, neutralidad, variabilidad y generalidad.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 3, "Señala la respuesta incorrecta. Para que una actividad se considere de servicio público, es necesario:", "Que la preste directamente la Administración.", "Que se trate de una actividad empresarial.", "Que contenga una prestación positiva en beneficio de los particulares.", "Todas las respuestas anteriores son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 4, "En el ordenamiento jurídico español, el servicio público se ha definido en función:", "De la persona jurídica que presta el servicio: los servicios públicos son gestionados directamente por la Administración.", "De la titularidad del servicio: la titularidad del servicio público corresponde a la Administración.", "De su inserción en el mercado: la actividad de servicio público se ejerce en régimen de libre competencia.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 5, "Señala la respuesta correcta en relación con los servicios públicos y la Constitución española:", "La Constitución define los servicios públicos como los servicios que presta la Administración y que responden al interés general de los ciudadanos.", "La Constitución prevé la posibilidad de reservar servicios esenciales mediante una ley,  especialmente en caso de monopolio.", "La Constitución prevé la posibilidad de establecer una asignación a las Comunidades Autónomas para garantizar un nivel mínimo en la prestación de los servicios públicos fundamentales, en todo el territorio español.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 6, "En el ámbito de la Unión Europea, el concepto de servicio público se utiliza a menudo de manera ambigua; por eso, en general no se utiliza este término sino que se usa una terminología distinta. ¿Cuál es esta terminología?", "Servicios de interés público.", "Servicios de interés general.", "Servicios de interés general comunitario.", "Servicios públicos europeos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 7, "De acuerdo con la Comunicación de la Comisión al Parlamento europeo, al Consejo, al Comité Económico y Social Europeo y al Comité de las Regiones de 2011 denominada Un marco de calidad para los servicios de interés general en Europa, cuáles son las categorías de servicios de interés general:", "Servicios de interés económico general, servicios no económicos y servicios sociales de interés general.", "Servicios de interés económico general y servicios sociales de interés general.", "El concepto de servicio de interés general es único.", "Servicios de interés económico general y servicios no económicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 8, "Los servicios de interés económico general:", "Son servicios básicos que se prestan a cambio de una remuneración.", "Pueden ser prestados por empresarios.", "Están sujetos a las normas europeas de competencia y mercado interior.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 9, "De acuerdo con la clasificación de los servicios de interés general efectuada por la Unión Europea, la educación y el sistema nacional de salud:", "Son servicios sociales de interés general.", "Son servicios de interés general no económicos.", "No son servicios de interés general.", "Pueden ser prestados por la Administración."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 10, "Los servicios que atienden las necesidades de los ciudadanos más vulnerables y que se basan en los principios de solidaridad e igualdad de acceso:", "Son servicios sociales de interés general.", "Son servicios de interés general no económicos.", "No son servicios de interés general.", "Se gestionan directamente por los poderes públicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 11, "Indica la respuesta incorrecta en relación con los servicios a los que se imponen obligaciones de servicio universal:", "El servicio de telecomunicaciones tiene obligaciones de servicio universal.", "El servicio universal se presta en condiciones de neutralidad tecnológica, con una calidad determinada y a un precio razonable.", "Los servicios que tienen obligaciones de servicio universal son servicios cuya prestación se garantiza para todos los consumidores con independencia condicionada a su localización geográfica.", "El servicio universal se presta en condiciones de neutralidad tecnológica, con una calidad determinada y a un precio asequible."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 12, "La Ley 11/2022, de 28 de junio, general de telecomunicaciones dispone:", "Que las telecomunicaciones son servicios de interés general que se prestan en régimen de libre competencia.", "Que el secreto de las comunicaciones es una obligación de servicio público.", "Que las telecomunicaciones son servicios de interés general que se prestan en régimen de monopolio.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 13, "La limpieza viaria y el alcantarillado son servicios públicos:", "Competencia de los ayuntamientos, que han de prestarse mediante gestión directa.", "Que los ayuntamientos pueden prestar mediante un contrato de concesión de servicios.", "Que han de prestarse en régimen de monopolio.", "Que los ayuntamientos pueden gestionar de forma directa o de forma indirecta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 14, "De acuerdo con la Ley 7/1985, de 2 de abril, reguladora de las bases del régimen local, señala cuál de los siguientes son servicios públicos que deben prestar los municipios con población superior a 5.000 habitantes:", "Cementerio, protección civil y extinción de incendios.", "Cementerio y transporte colectivo urbano de viajeros.", "Cementerio y atención a personas en situación o riesgo de exclusión social.", "Cementerio, abastecimiento domiciliario de agua potable, pavimentación de las vías públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 15, "¿Es posible que una Comunidad Autónoma delegue en un municipio servicios públicos de su competencia?", "No, la competencia en cuanto a los servicios públicos es indelegable.", "Sólo se pueden delegar servicios públicos en casos de urgente necesidad y para evitar duplicidades administrativas.", "Sí, al objeto de evitar duplicidades administrativas, mejorar la transparencia de los servicios públicos y el servicio a la ciudadanía y, en general, contribuir a los procesos de racionalización administrativa, generando un ahorro limpio de recursos.", "Sí, al objeto de evitar duplicidades administrativas, mejorar la transparencia de los servicios públicos y el servicio a la ciudadanía y, en general, contribuir a los procesos de racionalización administrativa a pesar de que no genere un ahorro limpio de recursos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 16, "Los servicios públicos de gestión pública son:", "Aquellos que no pueden ser objeto de prestación por particulares porque responden a la noción de función pública que ejerce la Administración pública institucional.", "Aquellos que pueden ser objeto de prestación por particulares mediante alguna de las fórmulas previstas legalmente en materia de contratación.", "Aquellos que pueden ser prestados al público en general a través del sector privado, aunque la prestación está sometida a una estricta reglamentación por parte de la Administración.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 17, "¿Es posible que la Administración del Estado delegue en un municipio servicios públicos de su competencia?", "Sí, al objeto de evitar duplicidades administrativas, mejorar la transparencia de los servicios públicos y el servicio a la ciudadanía y, en general, contribuir a los procesos de racionalización administrativa, generando un ahorro limpio de recursos.", "No, la competencia en cuanto a los servicios públicos es indelegable.", "Sí, al objeto de evitar duplicidades administrativas, mejorar la transparencia de los servicios públicos y el servicio a la ciudadanía y, en general, contribuir a los procesos de racionalización administrativa a pesar de que no genere un ahorro limpio de recursos.", "Sólo se pueden delegar servicios públicos en casos de urgente necesidad y para evitar duplicidades administrativas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 18, "Señala el servicio público que no puede ser delegado por la Administración del Estado en los municipios:", "Prestación de los servicios sociales.", "Servicios postales.", "Creación, mantenimiento y gestión de escuelas infantiles.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 19, "Para crear servicios públicos, las entidades locales de las Illes Balears:", "Deben acordar de manera expresa la creación del servicio público local.", "Debe aprobarse un reglamento por el que se regule el servicio, si bien puede aprobarse con posterioridad al inicio de la prestación.", "No es necesario que se acuerde expresamente su creación.", "La aprobación de un reglamento que regule el servicio público sólo es exigible a los municipios de más de 50.000 habitantes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 20, "De acuerdo con el Real decreto legislativo 781/1986, de 18 de abril, por el que se aprueba el texto refundido de las disposiciones legales vigentes en materia de régimen local, los servicios públicos locales han de gestionarse:", "Directamente.", "Indirectamente.", "Indirectamente, excepto los servicios que impliquen ejercicio de autoridad.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 21, "De acuerdo con la Ley 20/2006, de 15 de diciembre, municipal y de régimen local de las Illes Balears, las formas de gestión de los servicios públicos locales son:", "Gestión indirecta y gestión mixta.", "Gestión directa y gestión mixta.", "Gestión directa y gestión concertada.", "Gestión directa y gestión indirecta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 22, "La Ley 20/2006, de 15 de diciembre, municipal y de régimen local de las Illes Balears, dispone que los servicios públicos que impliquen ejercicio de autoridad:", "No pueden prestarse por gestión indirecta, excepto que se preste mediante sociedad mercantil de capital mixto.", "No pueden prestarse por gestión indirecta ni mediante sociedad mercantil de capital social exclusivamente local.", "Se pueden prestar indirectamente mediante sociedad mercantil de capital social exclusivamente local.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 23, "En cuanto a la utilización de servicios públicos, ¿puede el Ayuntamiento de Palma establecer ventajas económicas en beneficio de los grupos sociales de menor capacidad económica, en cuanto a la utilización de servicios públicos?", "No es posible, porque resulta contrario al principio constitucional de igualdad.", "Sí; así lo prevé el artículo 21 del Estatuto de Autonomía de las Illes Balears.", "Sí, porque lo permite la Ley 20/2006, de 15 de diciembre, municipal y de régimen local de las Illes Balears.", "No, está prohibido expresamente por la normativa comunitaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 24, "Indica cuál de las siguientes no es una forma de gestión directa de los servicios públicos:", "Gestión por la propia Administración pública.", "Gestión a través de un organismo autónomo.", "Gestión mediante una entidad pública empresarial.", "Gestión mediante una sociedad mercantil de titularidad privada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 25, "De acuerdo con la Ley 20/2006, de 15 de diciembre, municipal y de régimen local de las Illes Balears, si un servicio público local se presta en régimen de monopolio, significa:", "Que se trata de un servicio público esencial reservado mediante una ley a los entes locales.", "Que un servicio público lo presta un único empresario.", "Que se trata de un servicio público en el que no es posible la libre concurrencia.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 26, "De acuerdo con la Ley 20/2006, de 15 de diciembre, municipal y de régimen local de las Illes Balears, para que un servicio público se preste en régimen de monopolio, se requiere:", "El acuerdo del pleno por mayoría absoluta del número de miembros de la corporación presentes a la sesión, y la aprobación del consejo, que ha de otorgarse si concurren las circunstancias de interés público legitimadoras de la exclusión de la iniciativa privada o lo aconsejen razones de seguridad, salubridad u orden público.", "El acuerdo del pleno por mayoría absoluta del número legal de miembros de la corporación y la aprobación del consejo, que ha de otorgarse si concurren las circunstancias de interés público legitimadoras de la exclusión de la iniciativa privada o lo aconsejen  razones de seguridad, salubridad u orden público.", "El acuerdo del pleno por mayoría absoluta del número legal de miembros de la corporación y la aprobación del consejo, que ha de otorgarse sólo si concurren las circunstancias de interés público legitimadoras de la exclusión de la iniciativa privada.", "El acuerdo del pleno por mayoría absoluta del número legal de miembros de la corporación y la aprobación del consejo, que ha de otorgarse sólo si lo aconsejan razones de seguridad, salubridad u orden público."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 27, "La gestión directa de un servicio público por parte de la Administración puede llevarse a cabo:", "Mediante medios propios no personificados.", "Mediante un organismo autónomo o una entidad pública empresarial.", "Mediante medios propios personificados.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 28, "En el caso de gestión directa de un servicio público con medios propios no personificados, ¿puede contar la Administración con medios privados?", "Sí, siempre que la Administración ejecute la parte esencial del servicio y el empresario lo que resulte complementario.", "Sí, en todo caso; el artículo 30 de la Ley de Contratos del Sector Público reconoce la ejecución directa de prestaciones por parte de la Administración pública con la colaboración de empresarios particulares.", "No, si la colaboración es para atender a los usuarios de forma directa.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 29, "Señala la respuesta incorrecta. Son formas de gestión directa de la Administración:", "El encargo a medios propios personificados.", "La ejecución por una entidad pública empresarial.", "La ejecución por un organismo autónomo dependiente.", "La concesión de autorización o licencia a una entidad sin ánimo de lucro."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 30, "Para que un organismo autónomo ejecute un servicio público, se requiere:", "Que la ley de creación así lo disponga.", "Que subscriba un contrato con la Administración de la cual depende.", "Que se le otorgue autorización o licencia para ejecutarlo.", "Los organismos autónomos no pueden gestionar servicios públicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 31, "Los servicios públicos que implican ejercicio de autoridad han de ejercerse:", "En régimen de libre concurrencia.", "En régimen de monopolio.", "En régimen de gestión directa.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 32, "Indica cuál o cuáles de las siguientes no es un forma de gestionar indirectamente un servicio público:", "El contrato de servicios a las personas.", "La concesión.", "El contrato de gestión de servicios públicos.", "El concierto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 33, "La gestión indirecta de servicios públicos puede llevarse a cabo:", "Mediante un contrato de concesión de servicios.", "Mediante un contrato de servicios que comporte prestaciones directas a la ciudadanía.", "Mediante concierto, gestión delegada u otras modalidades reguladas a la legislación autonómica.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 34, "Señala la respuesta incorrecta. El artículo 86 de la Ley 7/1985, de 2 de abril, reguladora de las bases de régimen local, declara la reserva a favor de las entidades locales de algunas actividades o servicios esenciales:", "Recogida, tratamiento y aprovechamiento de residuos.", "Transporte público de viajeros.", "Alumbrado público.", "Abastecimiento y depuración de aguas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 35, "La prestación por entidades privadas de servicios públicos destinados a satisfacer necesidades de carácter social, ¿está sometida a la normativa de contratación?", "Sí; se trata de una relación contractual entre la Administración y un empresario, por lo cual está sujeta a la Directiva 24/2004/UE del Parlamento Europeo y del Consejo, de 26 de febrero de 2014, sobre contratación pública, y a la Ley 9/2017, de 30 de noviembre, de contratos del sector público.", "No; la Directiva 2014/24 reconoce a los poderes públicos la libertad para prestar por sí mismos los servicios a las personas, y para organizarlos de forma que no sea necesario subscribir contratos públicos.", "No; estos servicios quedan excluidos de la Ley de contratos del sector público de acuerdo con el artículo 11 y la disposición adicional cuadragésimo novena de esta Ley.", "La satisfacción de necesidades de carácter social puede prestarse mediante un contrato de concesión de servicios o un contrato de servicios, o bien mediante otras fórmulas no contractuales, como el concierto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 36, "¿La prestación de servicios sociales por entidades privadas está excluida de la Ley de contratos del sector público?", "Sí, siempre que se lleve a cabo sin necesidad de subscribir contratos públicos, a través de la simple financiación de estos servicios a todas las entidades que cumplan las condiciones previamente fijadas por el poder adjudicador, sin límites ni cuotas, y que el sistema mencionado se ajuste a los principios de transparencia y no discriminación.", "No, la Ley de contratos del sector público regula dos tipos de contratos mediante los cuales se prestan servicios sociales o a las personas: el contrato de servicios y el de concesión de servicios.", "Sí, siempre que se lleve a cabo a través de concesión de licencias o autorizaciones a todas las entidades que cumplan las condiciones previamente fijadas por la Ley sin límites ni cuantías.", "Sí, siempre que se lleve a cabo sin necesidad de subscribir contratos públicos, a través, entre otros medios, de la simple financiación de estos servicios o la concesión de licencias o autorizaciones a todas las entidades que cumplan las condiciones que el poder adjudicador haya fijado previamente, sin límites ni cuotas, y que el sistema mencionado garantice una publicidad suficiente y se ajuste a los principios de transparencia y no-discriminación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 37, "En el ámbito de la Comunidad Autónoma de las Illes Balears, ¿qué ley  regula la acción concertada de servicios sociales a las personas?", "La Ley 3/2018, de 29 de mayo, del tercer sector de acción social.", "La Ley 12/2018, de 15 de noviembre, de servicios sociales a la comunidad autónoma de las Illes Balears.", "La Ley 3/2018, de 29 de mayo, del tercer sector de acción social de las Illes Balears.", "La Ley 12/2018, de 15 de noviembre, de servicios a las personas en el ámbito social a la comunidad autónoma de las Illes Balears."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 38, "El régimen de acción concertada se define, en la Ley 12/2018, de 15 de noviembre, de servicios a las personas en el ámbito social en la comunidad autónoma de las Illes Balears, cómo:", "La prestación por terceros de servicios sociales incluidos en la cartera de servicios sociales recogidos en la cartera común del Sistema Nacional de Ocupación, en los que la financiación, el acceso y el control administrativo son públicos.", "La prestación por terceros de servicios sociales incluidos en la cartera de servicios sociales y el servicio de orientación profesional recogido en la cartera común del Sistema Nacional de Ocupación, en los cuales la financiación y el control administrativo son públicos.", "La prestación por terceros de servicios sociales incluidos en la cartera de servicios sociales y del servicio de orientación profesional recogido en la cartera común del Sistema Nacional de Ocupación, la financiación, el acceso y el control administrativo de los cuales son públicos.", "La prestación por terceros de servicios sociales incluidos en la cartera de servicios sociales y el servicio de orientación profesional recogido en la cartera común del Sistema Nacional de Ocupación, y en los cuales el acceso y el control administrativo son públicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 39, "La acción concertada con terceros para la prestación a las personas de servicios sociales se ajustará a los principios siguientes:", "Solidaridad, transparencia, eficiencia presupuestaria, subsidiariedad, participación, publicidad, calidad asistencial y no discriminación.", "Subsidiariedad, igualdad, eficiencia presupuestaria, transparencia, intencionalidad social y ambiental, calidad asistencial y libre elección de las personas usuarias.", "Subsidiariedad, solidaridad, eficiencia presupuestaria, transparencia, intencionalidad social y ambiental, calidad asistencial y libre elección de las personas usuarias.", "Subsidiariedad, igualdad, eficiencia presupuestaria, solidaridad, no discriminación, transparencia, publicidad, intencionalidad social y ambiental, participación, calidad asistencial y libre elección y arraigo de las personas usuarias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 40, "¿Cuál o cuáles de los servicios siguientes pueden ser objeto de concierto,  de acuerdo con la Ley 1272018, de 15 de noviembre, de servicios a las personas en el ámbito social en la comunidad autónoma de las Illes Balears?", "Los servicios administrativos de administración general.", "Los servicios de inserción laboral.", "Los servicios de ayuda a domicilio para personas en situación de dependencia.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 41, "¿Quién puede subscribir acuerdos de acción concertada de servicios a las personas en el ámbito social en las Illes Balears?", "Las personas físicas o jurídicas de carácter privado, con o sin ánimo de lucro, sea cual sea la forma jurídica que adopten, que presten los servicios objeto del concierto y lo soliciten expresamente en los plazos y la forma que se determine.", "Todas las entidades del tercer sector de acción social que presten los servicios objeto del concierto.", "Las personas físicas o jurídicas a las cuales hace referencia la opción a), sólo en los servicios declarados de interés económico general.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 42, "Indica cuál o cuáles de los siguientes servicios pueden ser objeto de acción concertada, de acuerdo con la Ley 12/2018, de 15 de noviembre, de servicios a las personas en el ámbito social en la comunidad autónoma de las Illes Balears:", "Servicio de acompañamiento para personas con discapacidad.", "Servicios de tutela para personas con discapacidad.", "Servicio de búsqueda de trabajo para personas con discapacidad.", "Todos los servicios anteriores pueden ser objeto de acción concertada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 43, "¿Cuál es la duración máxima que pueden tener los acuerdos de acción concertada en el ámbito social en las Illes Balears?", "Cinco años.", "Diez años.", "Tres años.", "Doce años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 44, "¿Puede gestionarse un servicio público mediante un contrato de servicios de los regulados en la Ley de contratos del sector público?", "En ningún caso.", "Sólo puede gestionarse un servicio público mediante un contrato de concesión de servicios.", "Sí, mediante un contrato de servicios que comporten prestaciones directas a favor de la ciudadanía.", "No, los contratos de servicios son aquellos que se prestan directamente a la Administración contratante."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 45, "De acuerdo con la Ley de contratos del sector público, la duración de un contrato de servicios a las personas puede ser:", "En todo caso, de cinco años como máximo.", "Más de cinco años cuando sea necesario para la continuidad de aquellos tratamientos a los usuarios en que el cambio del prestador pueda repercutir negativamente.", "Más de tres años cuando sea necesario para la continuidad de aquellos tratamientos a los usuarios en que el cambio del prestador pueda repercutir negativamente.", "Diez años, como máximo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 46, "En los contratos de servicios sociales dirigidos a las personas que se lleven a cabo en la comunidad autónoma de las Illes Balears, la Ley 12/2018, de 15 de noviembre, de servicios a las personas en el ámbito social en la comunidad autónoma de las Illes Balears, establece una solvencia económica y financiera referida al volumen de negocios en el ámbito de las actividades correspondientes al objeto del contrato en relación, como máximo, con los tres últimos ejercicios disponibles, que nunca ha de ser inferior:", "Al 50 % del presupuesto base de licitación.", "Al 50 % del valor estimado del contrato.", "Al 75 % del presupuesto base de licitación.", "Al 75 % del valor estimado del contrato."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 47, "El plazo máximo de duración de los contratos de servicios sociales a personas en la comunidad autónoma de las Illes Balears establecido en la Ley 12/2018, de 15 de noviembre, de servicios a las personas en el ámbito social en la comunidad autónoma de las Illes Balears, es:", "De cinco años.", "De diez años.", "De seis años, salvo que sea necesario un plazo mayor por circunstancias debidamente justificadas.", "De tres años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 48, "De acuerdo con la Ley de contratos del sector público, ¿qué prescripciones han de cumplirse para contratar un servicio que comporte prestaciones directas a favor de la ciudadanía?", "Debe haberse establecido el régimen jurídico, que determine el alcance de las prestaciones en favor de los administrados y regule los aspectos de carácter jurídico, económico y administrativo relativos a la prestación del servicio.", "Debe haberse establecido el régimen jurídico, que declare expresamente que la actividad de que se trata queda asumida por la Administración como propia, y regule los aspectos de carácter jurídico, económico y administrativo relativos a la prestación del servicio.", "Debe haberse establecido el régimen jurídico, que declare expresamente que la actividad de que se trata queda asumida por la Administración respectiva como propia de aquella, que determine el alcance de las prestaciones a favor de los administrados y que regule los aspectos de carácter jurídico, económico y administrativo relativos a la prestación del servicio.", "Debe haberse establecido el régimen jurídico, que declare expresamente que la actividad de que se trata queda asumida por la Administración respectiva como propia de aquella, determine el alcance de las prestaciones en favor de los administrados y regule los aspectos de carácter jurídico y económico relativos a la prestación del servicio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 49, "¿En qué casos la Administración puede acordar el secuestro o la intervención del servicio público gestionado por un contratista de un servicio de prestaciones directas a favor de la ciudadanía?", "Cuando por causas ajenas al contratista se derive una perturbación grave y no reparable por otros medios en el servicio.", "Cuando a causa del incumplimiento por parte del contratista se derive una perturbación grave y no reparable por otros medios en el servicio y la Administración no decide resolver el contrato.", "Cuando por causas ajenas al concesionario se derive una perturbación muy grave y no reparable por otros medios en el servicio y la Administración no decide resolver el contrato.", "El secuestro es aplicable a las concesiones, no al contrato de servicios que comporten prestaciones directas a favor de la ciudadanía."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 50, "¿Es posible que una administración que ha de licitar un contrato para la prestación de determinados servicios sociales reserve la participación en la licitación a ciertas organizaciones?", "No, esto supondría una vulneración del principio de libre concurrencia establecido en la Ley de contratos del sector público y las directivas comunitarias sobre contratación.", "Sí, la Ley de contratos del sector público lo permite.", "No, porque lo prohíbe la Directiva 2014/23/UE del Parlamento Europeo y del Consejo, de 26 de febrero de 2014, relativa a la adjudicación de contratos de concesión.", "No, porque lo prohíbe la Directiva 2014/24/UE del Parlamento Europeo y del Consejo, de 26 de febrero de 2014, sobre contratación pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 51, "La Ley de contratos del sector público permite que los órganos de contratación de los poderes adjudicadores puedan reservar a determinadas organizaciones el derecho a participar en los procedimientos de licitación de ciertos contratos de carácter social. Indica cuál de los siguientes son requisitos que han de concurrir en estas organizaciones para poder participar en las licitaciones:", "Que el objetivo de la organización sea la realización de una misión de servicio público vinculada a la prestación de los servicios que se han de contratar.", "Que las estructuras de dirección o propiedad de la organización que ejecute el contrato se basen en la propiedad de los empleados o en principios de participación, o exijan la participación activa de los empleados, los usuarios o las partes interesadas.", "Que las estructuras de dirección o propiedad de la organización que ejecute el contrato se basen en la propiedad de los empleados o de los accionistas o en principios de participación, o exijan la participación activa de los usuarios o las partes interesadas.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 52, "De acuerdo con la Ley de contratos del sector público, ¿cuál es la duración máxima de un contrato para la prestación de servicios sociales que se haya reservado a determinadas organizaciones?", "Cinco años.", "Diez años.", "Tres años.", "Dos años, prorrogables por dos años más."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 53, "De acuerdo con el artículo 284 de la Ley 9/2017, de 8 de noviembre, de contratos del sector público:", "La Administración puede gestionar directamente, mediante contrato de concesión de servicios, los servicios de su titularidad o competencia siempre que sean susceptibles de explotación económica por particulares.", "La Administración puede gestionar indirectamente, mediante contrato de concesión de servicios, los servicios de su titularidad o competencia a pesar de que no sean susceptibles de explotación económica por particulares.", "La Administración puede gestionar directamente, mediante contrato de concesión de servicios, los servicios de su titularidad o competencia a pesar de que no sean susceptibles de explotación económica por particulares.", "La Administración puede gestionar indirectamente, mediante contrato de concesión de servicios, los servicios de su titularidad o competencia siempre que sean susceptibles de explotación económica por particulares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 54, "Señala la respuesta correcta en cuanto a la posibilidad de gestionar un servicio público mediante un contrato de concesión de servicios:", "La Ley de contratos del sector público permite la gestión indirecta de un servicio público mediante un contrato de concesión de servicios incluso si el servicio implica ejercicio de la autoridad inherente a los poderes públicos.", "Los servicios públicos no pueden ser objeto de concesión.", "Puede gestionarse un servicio público mediante concesión siempre que el servicio sea susceptible de explotación económica por parte de particulares.", "Puede gestionarse el servicio público mediante concesión, siempre que no implique la construcción de una obra, caso en que se tiene que calificar de concesión de obra."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 55, "¿En qué caso puede adjudicarse directamente un contrato de concesión de un servicio público?:", "La Ley de contratos del sector público no permite la adjudicación directa de un contrato de concesión.", "En el supuesto de que el adjudicatario sea una sociedad de economía mixta en la que concurra capital público mayoritariamente con capital privado.", "La Ley de contratos del sector público permite la adjudicación directa de un contrato de concesión a una sociedad de economía mixta, siempre que no se trate de la concesión de un servicio público.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 56, "De acuerdo con la Ley 9/2017, de 8 de noviembre, de contratos del sector público, ¿cuáles son los requisitos que han de cumplirse previamente a la contratación de la concesión de un servicio público?", "Debe establecerse el régimen jurídico, determinar el alcance de las prestaciones en favor de los administrados y regular los aspectos de carácter jurídico, económico y administrativo relativos a la prestación del servicio.", "Debe establecerse el régimen jurídico, declarar expresamente que la actividad de que se trata queda asumida por la Administración como propia, y regular los aspectos de carácter jurídico, económico y administrativo relativos a la prestación del servicio.", "Debe establecerse el régimen jurídico, declarar expresamente que la actividad de que se trata queda asumida por la Administración como propia, determinar el alcance de las prestaciones en favor de los administrados y regular los aspectos de carácter jurídico, económico y administrativo relativos a la prestación del servicio.", "Debe establecerse el régimen jurídico, declarar expresamente que la actividad de que se trata queda asumida por la Administración como propia, determinar el alcance de las prestaciones en favor de los administrados y regular los aspectos de carácter jurídico y económico relativos a la prestación del servicio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 57, "La asunción del riesgo operacional como elemento distintivo del contrato de concesión de servicios, supone:", "Que no está garantizado que, en condiciones normales de funcionamiento, el contratista recupere las inversiones realizadas.", "Que no está garantizado que, en condiciones anormales de funcionamiento, el contratista recupere las inversiones realizadas.", "Que no está garantizado que, en condiciones normales de funcionamiento, el contratista cubra los costes en qué haya incurrido como consecuencia de la explotación del servicio que sea objeto de concesión, a pesar de que tenga derecho a ser indemnizado por la Administración en el caso de pérdidas.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 58, "El contrato de concesión de servicios:", "Supone la gestión directa de un servicio público por parte de la Administración mediante un empresario intermediario.", "Puede suponer la gestión indirecta de un servicio público.", "Supone siempre la gestión indirecta de un servicio público.", "No puede gestionar en ningún caso un servicio que implique ejercicio de la autoridad inherente a los poderes públicos, salvo que lo autorice una ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 59, "¿Cuál puede ser la duración máxima de un contrato de concesión de servicios cuando el objeto es la gestión de un servicio público?", "Cuarenta años, si comprende la ejecución de obras y la explotación de servicio.", "Veinticinco años, en el supuesto de que comprenda la explotación de un servicio no relacionado con la prestación de servicios sanitarios.", "Diez años, si comprende la explotación de un servicio cuyo objeto consista en la prestación de servicios sanitarios siempre que no incluya la ejecución de obras.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 60, "Cuando el contrato de concesión de servicios recae sobre un servicio público:", "La Administración conserva los poderes de policía necesarios para asegurar la buena marcha de los servicios de que se trate.", "El concesionario tiene la facultad de oponerse a las instrucciones de la Administración, dado que asume el riesgo operacional.", "Las instalaciones fijas necesarias para la prestación del servicio no pueden ser objeto de hipoteca.", "El contrato no se puede modificar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 61, "¿Cuál es la diferencia más significativa entre un contrato de concesión de servicios y un contrato de servicios que comporte prestaciones directas a favor de la ciudadanía, cuando se gestiona en ambos casos un servicio público?", "No hay ninguna diferencia entre uno y otro contrato.", "La diferencia más significativa es la duración del contrato.", "La diferencia más significativa es la traslación del riesgo operacional al concesionario en el contrato de concesión.", "La diferencia más significativa recae en el objeto del contrato."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 62, "Indica cuál de las siguientes opciones no es una obligación del concesionario de servicios:", "Indemnizar los daños que se causen a terceros como consecuencia de las operaciones que requiera el desarrollo del servicio, incluso cuando el daño se produzca por causas imputables a la Administración.", "Prestar el servicio con la continuidad convenida y garantizar a los particulares el derecho a utilizarlo en las condiciones que se hayan establecido.", "Continuar con la prestación del servicio a la finalización del contrato hasta que se formalice uno nuevo.", "Cuidar del buen orden del servicio, para lo cual podrá dictar las instrucciones oportunas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 63, "¿Cuál de las siguientes son causas de resolución de una concesión de servicios?", "La intervención de la concesión por un plazo superior a dos años sin que el concesionario haya garantizado la asunción completa de sus obligaciones.", "El rescate.", "La demora superior a tres meses por parte de la Administración en la entrega al concesionario de los medios auxiliares a que se obligó según el contrato.", "La demora en el cumplimiento de los plazos por parte del contratista."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 64, "¿Qué significa la reversión en el contrato de concesión de un servicio público?", "Que los bienes afectos a la concesión que tengan que revertir a la Administración pueden ser objeto de embargo.", "Que el servicio pasa a manos de la Administración una vez finalizado el plazo de la concesión.", "La resolución del contrato.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 66, "¿En qué casos la Administración puede acordar el secuestro o la intervención del servicio público gestionado por un concesionario?", "Cuando por causas ajenas al concesionario se derive una perturbación grave y no reparable por otros medios en el servicio.", "Cuando a causa del incumplimiento por parte del concesionario se derive una perturbación grave y no reparable por otros medios en el servicio.", "Cuando por causas ajenas al concesionario se derive una perturbación muy grave y no reparable por otros medios en el servicio.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 19, 67, "En los expedientes de los contratos de concesión de servicios, ¿cuál es el documento que fija las tarifas que, en su caso, han de abonar los usuarios de un servicio público?", "El pliego de prescripciones técnicas particulares.", "En las concesiones de servicio público los usuarios no abonan tarifas.", "El estudio de viabilidad.", "El pliego de cláusulas administrativas particulares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 1, "Indique la respuesta correcta en relación con los convenios. Según el artículo 47.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público:", "No pueden ser formalizados con sujetos de derecho privado.", "No pueden tener efectos jurídicos frente a terceros.", "Pueden tener prestaciones propias de los contratos.", "No pueden tener prestaciones propias de los contratos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 2, "Los convenios suscritos entre organismos públicos y entidades de derecho público vinculados o dependientes de una misma administración pública son:", "Convenios interadministrativos.", "Convenios que pueden ser firmados además con un sujeto de derecho privado.", "Convenios intraadministrativos.", "Convenios entre la Administración de la Comunidad Autónoma y la Administración local."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 3, "Según el artículo 48 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, la suscripción de convenios, entre otros:", "Debe mejorar la eficiencia de la gestión económica.", "Debe mejorar la eficiencia de la gestión pública, facilitar la utilización conjunta de medios y servicios públicos, y contribuir a la realización de actividades de utilidad pública.", "Debe facilitar la utilización individual de medios y servicios públicos.", "Debe contribuir a la realización de actividades de interés público."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 4, "Señale la opción correcta. Las administraciones públicas deben respetar, en su actuación y relaciones los siguientes principios:", "Servicio efectivo a los interesados.", "Participación, subjetividad y transparencia de la actuación administrativa.", "Responsabilidad por la gestión pública.", "In dubio pro reo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 5, "Señale la opción correcta en relación con los requisitos que se requieren para la creación de un órgano administrativo:", "Determinación de su forma de integración en la sociedad.", "Determinación de la independencia jerárquica.", "Delimitación de algunas funciones y competencias y la dotación de las partidas presupuestarias necesarias para su puesta en marcha.", "Determinación de su forma de integración en la Administración pública, determinación de su dependencia jerárquica y deslimitación de sus funciones, competencias y la dotación de los créditos necesarios para su puesta en marcha y funcionamiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 6, "En relación con la competencia de los órganos administrativos que la tienen atribuida como propia, es cierto:", "Que la desconcentración no supone alteración alguna del ejercicio ni la titularidad.", "Que la encomienda de gestión no puede tener por objeto prestaciones propias de los contratos ni de los convenios de colaboración.", "Que la delegación de competencias, la delegación de firma y la suplencia no supongan alteración de la titularidad de la competencia.", "Que la competencia es irrenunciable y la ejercen los órganos administrativos que la tienen atribuida por delegación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 7, "En relación con la avocación regulada en la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, es cierto:", "Que contra el acuerdo motivado de avocación no se puede interponer recurso.", "Que la avocación sólo se da entre órganos jerárquicamente dependientes.", "Que la avocación es lo mismo que la delegación de competencias.", "Que entre órganos no dependientes jerárquicamente la avocación puede realizarla, entre otros, el órgano delegante."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 8, "Señale la respuesta incorrecta en relación con los órganos colegiados. De acuerdo con el artículo 17 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público:", "Se pueden constituir, convocar y celebrar las sesiones tanto de forma presencial como a distancia.", "Deben adoptar acuerdos y remitir las actas de forma presencial.", "En las sesiones que se celebren a distancia, sus miembros pueden encontrarse en diferentes lugares.", "Para la válida constitución del órgano, se requiere la asistencia, presencial o a distancia, del presidente y el secretario, o de quienes les suplan y al menos de la mitad de sus miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 9, "¿Qué asuntos son objeto de deliberación y acuerdo de los órganos colegiados?", "Sólo los asuntos que figuran en el orden del día.", "Los asuntos que desee incluir el presidente o el secretario unilateralmente por su carácter urgente.", "Los asuntos incluidos en el orden del día, salvo que asistan todos los miembros del órgano colegiado y sea declarada la urgencia de algún otro asunto por el voto favorable de la mayoría.", "Los asuntos que decidan todos los miembros del órgano colegiado con el voto favorable de un tercio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 10, "Según lo dispuesto en el artículo 18 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, es cierto:", "Que cuando los miembros del órgano voten en contra o se abstienen, quedan exentos de la responsabilidad que, en su caso, pueda derivarse de los acuerdos.", "Que no se pueden grabar las sesiones que celebre el órgano colegiado.", "Que de cada sesión que celebre el órgano colegiado el secretario debe extender un acta.", "Que el acta de cada sesión debe aprobarse en la misma reunión o en la siguiente inmediata."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 11, "Los órganos colegiados de la Administración General del Estado y de sus organismos públicos, por su composición, se clasifican:", "En órganos colegiados ministeriales, si sus miembros proceden de distintos departamentos de cada ministerio.", "En órganos colegiados intraestatales.", "En órganos colegiados interministeriales, si sus miembros proceden de distintos ministerios.", "En órganos colegiados colectivos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 12, "¿Cómo pueden dirigir las actividades de sus órganos jerárquicamente dependientes los órganos administrativos, según el artículo 6 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público?", "Mediante órdenes de servicio únicamente.", "Mediante instrucciones y resoluciones únicamente.", "Mediante comunicaciones, notas internas e instrucciones.", "Mediante instrucciones y órdenes de servicio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 13, "De acuerdo con el artículo 6 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el incumplimiento de las instrucciones u órdenes de servicio:", "No afecta por sí solo a la validez de los actos dictados por los órganos administrativos.", "Afecta por sí solo a la validez de los actos dictados por los órganos administrativos.", "Afecta por sí solo a la validez de los actos dictados por los órganos directivos.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 14, "Si una disposición atribuye la competencia a una administración, sin especificar el órgano que deba ejercerla, se entiende que la facultad de instruir y resolver los expedientes corresponde a los siguientes órganos:", "A los inferiores por razón de la materia o territorio.", "A los superiores competentes por razón de la materia y del territorio.", "A los que establezca el órgano superior competente por razón de la materia y del territorio.", "A los inferiores competentes por razón de la materia y del territorio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 15, "De acuerdo con el artículo 55.2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, la Administración General del Estado comprende:", "La organización central, compuesta por los ministerios y servicios independientes.", "La organización central que integra los ministerios y servicios comunes, la organización territorial y la Administración General del Estado en el exterior.", "La organización territorial e insular.", "La Administración General del Estado en las comunidades autónomas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 16, "¿Dónde se determinan los respectivos órganos directivos de los organismos públicos?", "En los estatutos de autonomía.", "En la respectiva orden de creación.", "En los estatutos de los organismos.", "En los reglamentos de desarrollo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 17, "Como norma general, ¿dónde tienen su sede las delegaciones de Gobierno?", "Donde especifiquen los estatutos de autonomía de cada comunidad autónoma.", "Donde decida el Consejo de Ministros.", "En la localidad donde radique la asamblea legislativa de la comunidad autónoma.", "En la localidad donde radique el Consejo de Gobierno de la comunidad autónoma."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 18, "Las administraciones públicas que establezcan medidas que limiten el ejercicio de derechos individuales o colectivos o exijan el cumplimiento de requisitos para el desarrollo de una actividad, deben aplicar el principio:", "De proporcionalidad y elegir la medida menos restrictiva.", "De reciprocidad y elegir la medida menos limitativa.", "De racionalidad y elegir la medida que asegure su cumplimiento.", "De la medida proporcionada, racional y menos restrictiva."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 19, "Los miembros del órgano colegiado deben recibir la convocatoria contenida en el orden del día de las reuniones con una antelación mínima:", "De cuatro días. La información sobre los temas que figuren en el orden del día estará a disposición de los miembros en un plazo superior.", "De tres días. La información sobre los temas que figuren en el orden del día estará a disposición de los miembros en un plazo inferior.", "De dos días. La información sobre los temas que figuren en el orden del día estará a disposición de los miembros en el mismo plazo.", "De setenta y dos horas. La información sobre los temas que figuren en el orden del día estará a disposición de los miembros en el mismo plazo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 20, "No pueden abstenerse en las votaciones quienes, por su calidad de autoridades o personal al servicio de las administraciones públicas, tienen la condición:", "De miembros de distintos órganos colegiados.", "De altos cargos de órganos colegiados.", "De secretario del órgano colegiado.", "De miembros natos de órganos colegiados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 21, "En el acta de la sesión del órgano colegiado, a solicitud de los respectivos miembros del órgano, no figurará:", "El voto contrario al acuerdo adoptado.", "Su abstención y los motivos que la justifiquen.", "El sentido del voto favorable.", "La responsabilidad asumida por la abstención."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 22, "Las diferentes administraciones públicas actúan y se relacionan con otras administraciones y entidades u organismos vinculados o dependientes de éstas de acuerdo con el principio:", "De colaboración y coresponsabilidad.", "De lealtad instrumental.", "De interoperabilidad.", "De lealtad institucional, cooperación y colaboración."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 23, "Según el artículo 16 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿cuáles son las funciones del secretario de un órgano colegiado?", "Únicamente garantizar que las reglas de constitución de los órganos se cumplen adecuadamente.", "Velar por la legalidad formal y material de las actuaciones del órgano colegiado, certificar sus actuaciones y garantizar que los procedimientos y reglas de constitución y adopción de acuerdos son respetadas.", "Establecer los procedimientos que deben seguirse para adoptar acuerdos.", "Sólo puede asistir a las sesiones de los órganos colegiados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 24, "¿Quién puede solicitar al secretario de un órgano colegiado la expedición de la certificación de sus acuerdos?", "Quienes acrediten la titularidad de un interés legítimo.", "Cualquier persona.", "Nadie.", "Sólo los miembros del órgano."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 25, "Según lo dispuesto en el artículo 18 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el acta de la sesión de un órgano colegiado debe incluir:", "Sólo los asistentes y el contenido de los acuerdos adoptados.", "Los asistentes, el orden del día de la reunión, las circunstancias del lugar y tiempo en que se ha celebrado, los principales puntos de las deliberaciones, así como el contenido de los acuerdos adoptados.", "Únicamente el orden del día y el contenido de los acuerdos adoptados.", "Sólo los asistentes y circunstancias del lugar y tiempo en que se ha celebrado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 26, "Señale la respuesta correcta en relación con el momento en que debe aprobarse el acta de cada sesión:", "Se tendrá que aprobar en la misma reunión.", "Sólo se puede aprobar en la siguiente reunión.", "Podrá aprobarse en la misma reunión o en la siguiente inmediata", "Se tendrá que aprobar en la última reunión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 27, "¿Cuál de las siguientes funciones no corresponde al presidente de los órganos colegiados de la Administración General del Estado y de las entidades de derecho público vinculadas o que dependen de las mismas?", "Visar las actas y certificaciones de los acuerdos del órgano.", "Asegurar el cumplimiento de las leyes.", "Acordar la convocatoria de las sesiones ordinarias y extraordinarias y la fijación del orden del día, teniendo en cuenta, en su caso, las peticiones de los demás miembros, siempre que hayan sido formuladas con la suficiente antelación.", "Expedir certificaciones de las consultas, dictámenes y acuerdos aprobados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 28, "Cuál de las siguientes funciones no corresponde al secretario de los órganos colegiados de la Administración General del Estado y de entidades de derecho público vinculadas o dependientes?", "Ejercer la representación del órgano.", "Expedir certificaciones de las consultas, dictámenes y acuerdos aprobados.", "Preparar el despacho de los asuntos, redactar y autorizar las actas de las sesiones.", "Recibir los actos de comunicación de los miembros con el órgano, sean notificaciones, peticiones de datos, rectificaciones o cualquier otra clase de escritos de los que deba tener conocimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 29, "Señale la respuesta incorrecta. Según el artículo 19 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, los miembros de los órganos colegiados de la Administración General del Estado y de las entidades de derecho público vinculadas o que dependen:", "Tienen que recibir, con una antelación mínima de dos días, la convocatoria que contenga el orden del día de las reuniones.", "Deben obtener la información necesaria para cumplir las funciones asignadas.", "Deben participar en los debates de las sesiones.", "Tienen que recibir, con una antelación mínima de una semana, la convocatoria que contenga el orden del día de las reuniones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 30, "¿En qué casos los miembros titulares del órgano colegiado de la Administración General del Estado y de las entidades de derecho público vinculadas o dependientes son sustituidos por sus suplentes, si los hubiere?", "En casos de ausencia o enfermedad.", "Siempre que lo soliciten.", "Cuando lo soliciten las organizaciones representativas.", "En general, aunque no exista causa justificada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 32, "¿En quiénes pueden delegar los órganos de las diferentes administraciones públicas el ejercicio de las competencias que tienen atribuidas?", "En otros órganos de la misma administración, aunque no sean jerárquicamente dependientes, o a los organismos públicos o entidades de derecho público vinculados o dependientes de estas administraciones públicas.", "En otros órganos de la propia administración, siempre que sean jerárquicamente dependientes.", "Siempre deben delegar en órganos de otra administración.", "Sólo en los organismos públicos o entidades de derecho público vinculados o dependientes de estas administraciones públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 33, "¿Dónde debe publicarse la delegación de competencias y su revocación?", "Únicamente en el Boletín Oficial del Estado.", "Únicamente en el boletín de la comunidad autónoma o en el de la provincia.", "En el Boletín Oficial del Estado, en el de la comunidad autónoma o en el de la provincia, según la Administración a la que pertenezca el órgano delegante, y el ámbito territorial de competencia del mismo.", "No es necesario publicarla."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 34, "Señale la respuesta incorrecta en relación con la delegación de competencias:", "Las resoluciones administrativas que se adopten por delegación deben indicar expresamente esta circunstancia y se considerarán dictadas por el órgano delegante.", "Salvo autorización expresa de una ley, no podrán delegarse las competencias que se ejerzan por delegación.", "La delegación no será revocable en ningún caso por el órgano que la haya conferido.", "El acuerdo de delegación de aquellas competencias atribuidas a órganos colegiados, para cuyo ejercicio se requiera un quórum o mayoría especial, se adoptará observando, en todo caso, ese quórum o mayoría."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 35, "¿En qué casos la realización de actividades de carácter material o técnico de la competencia de los órganos administrativos o de las entidades de derecho público puede ser encargada a otros órganos o entidades de derecho público de la misma o de diferente administración?", "Siempre que entre sus competencias se encuentren estas actividades, por razones de eficacia o cuando no se posean los medios técnicos idóneos para su ejercicio.", "Siempre que entre sus competencias se encuentren estas actividades, por razones de eficacia, aunque se posean los medios técnicos idóneos para ejercerlas.", "Por razones técnicas y siempre que no se posean los medios para su ejercicio.", "Siempre por razones de eficiencia y eficacia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 36, "¿Dónde debe publicarse el encargo de gestión entre órganos y entidades de derecho público de diferentes administraciones?", "Únicamente en el Boletín Oficial del Estado.", "Únicamente en el boletín de la comunidad autónoma o en el de la provincia.", "En el Boletín Oficial del Estado, en el de la comunidad autónoma o en el de la provincia, según la Administración a la que pertenezca el órgano que efectúa el encargo, salvo en el supuesto de la gestión ordinaria de los servicios de las comunidades autónomas por las diputaciones provinciales o en su caso cabildos o consejos insulares, que se rige por la legislación de régimen local.", "No es necesario publicarla."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 37, "Señale la respuesta incorrecta en relación con la suplencia prevista en el artículo 13 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público:", "Si no se designa suplente, la competencia del órgano administrativo será ejercida por quien designe el órgano administrativo inmediato superior de quien dependa.", "La suplencia no implica alteración de la competencia.", "Los titulares de los órganos administrativos pueden ser suplidos temporalmente en los supuestos de vacante, ausencia o enfermedad, así como en los casos en que haya sido declarada su abstención o recusación.", "Para su validez es necesaria la publicación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 38, "¿Qué debe hacer el órgano administrativo que se considere incompetente para la resolución de un asunto?", "Remitir directamente las actuaciones al órgano que considere competente y notificar esta circunstancia a los interesados.", "Remitir a través de un jerárquico superior las actuaciones al órgano que considere competente.", "Remitir directamente las actuaciones al órgano que considere competente, sin necesidad de notificar esta circunstancia a los interesados.", "Dictar una resolución en la que se declare incompetente y notificarla a los interesados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 39, "Señale la afirmación correcta:", "Los interesados, tanto si son parte en el procedimiento como si no, pueden dirigirse al órgano que esté conociendo de un asunto para que decline su competencia y remita las actuaciones al órgano competente.", "Los conflictos de atribuciones sólo podrán suscitarse entre órganos de una misma administración no relacionados jerárquicamente, y en lo que se refiere a asuntos sobre los que no haya finalizado el procedimiento administrativo.", "Los interesados no pueden dirigirse al órgano que consideren competente para que requiera de inhibición a lo que esté conociendo del asunto.", "Los conflictos de atribuciones sólo podrán suscitarse entre órganos de una misma Administración que estén relacionados jerárquicamente, y en lo que se refiere a asuntos sobre los que haya finalizado el procedimiento administrativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 40, "Según el artículo 47.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, no tienen la consideración de convenios:", "Los acuerdos con efectos jurídicos interadministrativos.", "Los acuerdos con efectos jurídicos intraadministrativos.", "Los acuerdos con efectos jurídicos firmados entre administraciones públicas y entes de un sujeto de derecho internacional.", "Los protocolos generales de actuación o instrumentos similares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 41, "Señale la respuesta incorrecta. Los convenios suscritos por las administraciones públicas, sus organismos públicos y entidades de derecho público vinculados o dependientes y las universidades públicas deben incluir:", "El régimen de recursos.", "Los sujetos que suscriben el convenio y la capacidad jurídica con la que actúa cada una de las partes.", "El régimen de modificación del convenio.", "El objeto del convenio y las actuaciones que debe llevar a cabo cada sujeto para su cumplimiento, indicando, en su caso, la titularidad de los resultados obtenidos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 42, "Señale la respuesta correcta en relación con el plazo de vigencia de un convenio:", "No puede ser superior a cuatro años, salvo que normativamente se prevea un plazo superior.", "En ningún caso podrá ser superior a cuatro años.", "No podrá ser superior a cinco años, salvo que se prevea normativamente un plazo superior.", "No podrá ser superior a tres años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 43, "¿Cuál de las siguientes causas no prevé el artículo 51 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público como causa de resolución de un convenio?", "El transcurso del plazo de vigencia del convenio sin haberse acordado la prórroga del convenio.", "El acuerdo unánime de todos los firmantes.", "El incumplimiento de las obligaciones y compromisos asumidos por parte de alguno de los firmantes.", "La renuncia verbal por parte de alguno de los firmantes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 44, "En el ámbito de la Administración General del Estado, la designación de suplente podrá efectuarse:", "En los reales decretos de estructura orgánica básica de los departamentos ministeriales o en los estatutos de sus organismos públicos y entidades vinculados o dependientes según corresponda.", "Únicamente en los estatutos de sus organismos públicos y entidades vinculados o dependientes según corresponda.", "En las resoluciones del Gobierno.", "Mediante ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 45, "Según señala el artículo 31 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, en relación con la concurrencia de sanciones, ¿qué ocurre si un órgano de la Unión Europea impone una sanción por unos mismos hechos?", "Que salvo que no concurra la identidad de sujeto y fundamento, el órgano competente para resolver la tendrá en cuenta a efectos de graduar la sanción que, en su caso, deba imponerse, y no la puede aminorar, sin perjuicio de declarar la comisión de la infracción.", "Que siempre que no concurra la identidad de sujeto y fundamento, el órgano competente para resolver lo tendrá en cuenta a efectos de graduar la sanción que, en su caso, deba imponerse, y no la puede minorar, en el momento de declarar la comisión de la infracción.", "Que siempre que no concurra la identidad de sujeto y fundamento, el órgano competente para resolver debe tenerlo en cuenta a efectos de graduar la sanción que, en su caso, deba imponerse, y la puede minorar, sin perjuicio de declarar la comisión de la infracción.", "Que siempre que concurra la identidad de sujeto y fundamento, el órgano competente para resolver la tendrá en cuenta a efectos de graduar la sanción que, en su caso, deba imponerse, pudiendo minorarla , sin perjuicio de declarar la comisión de la infracción."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 46, "¿Cómo define el artículo 39 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el portal de Internet?", "Como aquella dirección electrónica, disponible para los ciudadanos a través de redes de telecomunicaciones, cuya titularidad corresponde a una administración pública, o bien a uno o varios organismos públicos o entidades de derecho público en el ejercicio de sus competencias.", "Como aquella sede que permite realizar cualquier acto o actuación de forma íntegra a través de medios electrónicos en el marco de un procedimiento administrativo.", "Como aquel punto de acceso electrónico cuya titularidad corresponde a una administración pública, organismo público o entidades de derecho público que permite acceder a través de internet a la información publicada y, en su caso, a la correspondiente sede electrónica.", "Como aquella sede virtual cuya titularidad corresponde a una AP organismo público o entidades de derecho público que permite acceder a través de internet a la información publicada y, en su caso, a la dirección electrónica correspondiente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 47, "Según la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, las conferencias sectoriales se reúnen:", "Dos veces al año.", "Al menos una vez al año.", "Al menos una vez cada semestre.", "Una vez cada dos años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 48, "En los convenios debe indicarse su plazo de vigencia y en la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, se señalan una serie de reglas, ¿cuál de las siguientes es una?", "Que en cualquier momento anterior a la finalización del plazo previsto en el apartado h) del artículo 49, los firmantes del convenio pueden acordar unánimemente su prórroga por un período de hasta un año adicional o su extinción.", "Que en cualquier momento antes de la finalización del plazo previsto en el apartado h) del artículo 49, los firmantes del convenio pueden acordar unánimemente su prórroga por un período de hasta dos años adicionales o su extinción.", "Que en cualquier momento anterior a la finalización del plazo previsto en el apartado h) del artículo 49, los firmantes del convenio pueden acordar unánimemente su prórroga por un período de hasta cuatro años adicionales o su extinción.", "Que en cualquier momento antes de la finalización del plazo previsto en el apartado h) del artículo 49, los firmantes del convenio pueden acordar unánimemente su prórroga por un período de hasta cinco años adicionales o su extinción."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 49, "¿A qué consecuencia da lugar la resolución de un convenio según el artículo 52 la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público?", "A la comunicación a los órganos de control externo y fiscalización a efectos de determinar las obligaciones de las partes y los compromisos de cada una de las partes.", "A su liquidación a fin de determinar las obligaciones y compromisos de cada una de las partes.", "A la satisfacción de ambas partes con arreglo a las reglas contenidas en el convenio.", "A la comunicación al Tribunal de Cuentas a fin de determinar, con carácter previo a su liquidación, las obligaciones y compromisos que puedan corresponder a cada una de las partes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 50, "Señale la opción incorrecta. Según la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, la creación de un órgano administrativo exige, al menos, el cumplimiento de los siguientes requisitos:", "La determinación de las unidades administrativas que lo integran.", "La dotación de los créditos necesarios para su puesta en marcha y funcionamiento.", "La delimitación de sus funciones y competencias.", "La determinación de su forma de integración en la Administración pública de que se trate."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 52, "Señale la opción correcta. Según lo dispuesto en el artículo 17.2 de la Ley 40/2015 , de 1 de octubre, de régimen jurídico del sector público, para la válida constitución de un órgano colegiado, a efectos de la celebración de sesiones, deliberaciones y toma de acuerdos, ¿de qué miembros se requiere la asistencia, presencial o a distancia?", "Del presidente y secretario o, en su caso, de quienes les suplan, y, al menos, de la mitad más uno de sus miembros.", "Del presidente y secretario o, en su caso, de quienes les suplan, y la del número de miembros que determine la norma de funcionamiento de cada órgano colegiado.", "Del presidente y secretario o, en su caso, de quienes les suplan, y la de un tercio, al menos, de sus miembros.", "Del presidente y secretario o, en su caso, de quienes les suplan, y la de la mitad, al menos, de sus miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 53, "Señale la opción incorrecta respecto de la avocación de acuerdo con la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público:", "Los órganos superiores pueden avocar para sí el conocimiento de uno o varios asuntos cuya resolución corresponda ordinariamente o por delegación a sus órganos administrativos dependientes, cuando circunstancias de índole técnica, económica, social, jurídica o territorial lo hagan conveniente.", "En los supuestos de delegación de competencias en órganos no dependientes jerárquicamente, el conocimiento de un asunto lo puede avocar únicamente por el órgano delegante.", "En todo caso, la avocación se llevará a cabo mediante acuerdo motivado, que será notificado a los interesados en el procedimiento, si lo hubiere, con posterioridad a la resolución final que se dicte.", "Contra el acuerdo de avocación no se puede interponer recurso, aunque puede impugnarse en el recurso que, en su caso, se interponga contra la resolución del procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 54, "Indique la respuesta correcta en relación con lo dispuesto en el artículo 32.7 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público:", "La responsabilidad patrimonial del Estado por el funcionamiento de la Administración de Justicia se rige por el Real decreto 429/1993, de 26 de marzo, por el que se aprueba el Reglamento de los procedimientos de las administraciones públicas en materia de responsabilidad patrimonial.", "La responsabilidad patrimonial del Estado por el funcionamiento de la Administración de Justicia se rige por la Ley orgánica 6/1985, de 1 de julio, del poder judicial.", "La responsabilidad patrimonial del estado por el funcionamiento de la Administración de Justicia se rige por la Ley 40/2015 de 1 de octubre de régimen jurídico del sector público.", "La responsabilidad patrimonial del Estado por el funcionamiento de la Administración de Justicia se rige por la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 55, "Para la válida constitución de los órganos colegiados, el artículo 17 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, exige:", "La asistencia, presencial o a distancia, del presidente y secretario o, en su caso, de quienes les suplan, y la mitad, al menos de sus miembros, a efectos de la celebración de sesiones, deliberaciones y toma de acuerdos.", "La asistencia presencial del presidente y secretario o, en su caso, de quienes les suplan, y de todos sus miembros, a efectos de la celebración de sesiones, deliberaciones y toma de acuerdos.", "La asistencia presencial del presidente y secretario o, en su caso, de quienes les suplan, y de la mitad al menos de sus miembros, a efectos de la celebración de sesiones y deliberaciones, y la de todos sus miembros, para la toma de acuerdos.", "La asistencia, presencial oa distancia, de al menos la mitad de sus miembros, a efectos de la celebración de sesiones y deliberaciones; sólo será necesaria la asistencia del presidente y el secretario, para la toma de acuerdos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 56, "Según el artículo 47 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, son convenios:", "Los acuerdos con efectos jurídicos adoptados por las administraciones públicas, los organismos públicos y las entidades de derecho público vinculados o dependientes o las universidades públicas entre sí o con sujetos de derecho privado para una finalidad común.", "Los que se formalicen para actuar con un objetivo común, aunque no supongan la formalización de compromisos jurídicos.", "Los que tienen por objeto una delegación de competencias entre órganos.", "Los acuerdos por los que se formalicen prestaciones propias de los contratos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 57, "De acuerdo con el artículo 53 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿qué convenios deben enviarse al Tribunal de Cuentas o al órgano de externo de fiscalización de la comunidad autónoma en los tres meses siguientes a la suscripción?", "Cualquier convenio cuyos compromisos económicos asumidos superen los 500.000 euros.", "Cualquier convenio cuyos compromisos económicos asumidos superen los 600.000 euros.", "Todos los convenios.", "Los convenios interadministrativos suscritos entre dos o más administraciones públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 58, "Señale la afirmación correcta. De conformidad con lo que dispone el artículo 81 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, que regula los principios generales de actuación del sector público institucional:", "Las entidades que integran el sector público institucional están sometidas en su actuación a los principios de legalidad, eficiencia, estabilidad presupuestaria y sostenibilidad financiera, así como al principio de transparencia en su gestión.", "Las entidades que integran el sector público institucional no se sujetarán en materia de personal, incluido el laboral, a las limitaciones previstas en materia presupuestaria.", "Las administraciones autonómicas y locales pueden establecer un sistema de supervisión continua de sus entidades dependientes, a fin de comprobar la subsistencia de los motivos que justificaron su creación.", "Los organismos y entidades vinculados o dependientes de la Administración autonómica y local se rigen por las disposiciones propias considerando que la Ley 40/2015 se aplica exclusivamente al sector público de la Administración General del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 59, "Señale la opción incorrecta. De acuerdo con el artículo 5 de la Ley 40/2015, de 1 de octubre, del Régimen Jurídico del Sector Público, la creación de cualquier órgano administrativo exige, al menos, el cumplimiento de los siguientes requisitos:", "Determinación de su forma de integración en la Administración pública de que se trate y su dependencia jerárquica.", "Delimitación de sus funciones y competencias.", "Dotación de los créditos necesarios para su puesta en marcha y funcionamiento.", "Ubicación geográfica de sus dependencias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 60, "Señale la opción incorrecta en relación con los convenios administrativos:", "Tienen como finalidad mejorar la eficiencia de la gestión pública.", "Tienen como finalidad contribuir a la realización de actividades de utilidad privada.", "Deben facilitar la utilización conjunta de medios y servicios públicos.", "Deben cumplir la legislación de estabilidad presupuestaria y sostenibilidad financiera."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 61, "Las diferentes administraciones públicas actúan y se relacionan entre ellas y con las entidades u organismos vinculados a ellas de acuerdo con el principio:", "De cooperación.", "De colaboración.", "De lealtad institucional.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 62, "La resolución de los convenios da lugar a su liquidación con el objeto de determinar:", "Los derechos de cada una de las partes.", "Los derechos y obligaciones de una de las partes.", "Las obligaciones y compromisos de cada una de las partes.", "Las expectativas y compromisos de cada una de las partes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 63, "Los consorcios se rigen por lo que se establece:", "En la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público.", "En la normativa autonómica de desarrollo, en su caso.", "En sus estatutos.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 64, "Señale la opción correcta. En relación con el funcionamiento de los órganos colegiados, la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, permite la deliberación y acuerdo de los asuntos que no figuren incluidos en el orden del día de la sesión que se remitió junto con la convocatoria, siempre que:", "Asistan todos los miembros del órgano colegiado y se declare la urgencia del asunto por mayoría absoluta.", "Asistan la mayoría absoluta de los miembros del órgano colegiado y se declare la urgencia del asunto por el voto favorable de la mayoría.", "Asistan los miembros del órgano colegiado y se declare la urgencia del asunto por unanimidad.", "Asistan todos los miembros del órgano colegiado y se declare la urgencia del asunto por el voto favorable de la mayoría."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 65, "De conformidad con la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, los organismos públicos vinculados o dependientes de la Administración General del Estado se clasifican:", "En organismos autónomos y entidades públicas empresariales.", "En organismos autónomos y agencias estatales.", "En organismos autónomos, consorcios y agencias estatales.", "En organismos autónomos, entidades públicas empresariales y agencias estatales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 66, "Señale la opción correcta. En relación con la delegación de competencias relativas a la resolución de recursos ante los órganos administrativos que hayan dictado los actos recurridos, la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, establece:", "Que la delegación debe ser expresa.", "La delegación deberá publicarse en el boletín oficial correspondiente.", "Que la delegación sólo puede realizarse en órganos que estén bajo la dependencia jerárquica del órgano que delega.", "Que en ningún caso pueden ser objeto de delegación las competencias relativas a esta materia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 12, 67, "Señale la respuesta correcta. Según el artículo 6 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, en relación con las órdenes de servicio y las instrucciones:", "Pueden dirigir las actividades de sus órganos jerárquicamente dependientes.", "Sólo las instrucciones pueden dirigir las actividades de sus órganos jerárquicamente dependientes.", "Sólo las órdenes de servicio pueden dirigir las actividades de sus órganos jerárquicamente dependientes.", "Deben publicarse en el diario oficial para su entrada en vigor."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 1, "El Parlamento Europeo estará compuesto por representantes de los ciudadanos de la Unión Europea. Su número no excede:", "De 649 diputados, más el presidente.", "De 750 diputados más el presidente.", "De 705 diputados, incluido el presidente.", "De representantes en una proporción decreciente por Estado miembro."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 2, "Un país que cumpla los criterios de Copenhague y quiera pertenecer a la Unión Europea debe presentar una solicitud de adhesión:", "En el Parlamento Europeo.", "En el Consejo Europeo.", "En la Comisión Europea y en el Consejo.", "En el Consejo de la Unión Europea."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 3, "En el marco del proceso de ampliación de la Unión Europea, en 2004 se incorporó uno de los siguientes estados de la Unión Europea:", "Malta.", "Croacia.", "Dinamarca.", "Finlandia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 4, "Según el Tratado de la Unión Europea, el presidente del Consejo Europeo es elegido:", "Por el Parlamento Europeo, por mayoría simple, para un mandato de dos años, que no podrá renovarse.", "Por el Consejo Europeo, por mayoría simple, para un mandato de dos años, que no podrá renovarse.", "Por el Consejo Europeo, por mayoría cualificada, para un mandato de dos años y medio, que podrá renovarse una sola vez.", "Por el Parlamento Europeo, por mayoría cualificada, para un mandato de dos años y medio, que podrá renovarse una sola vez."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 5, "De acuerdo con el artículo 282.2 del Tratado de funcionamiento de la Unión Europea, el principal objetivo del Sistema Europeo de Bancos Centrales es:", "Mantener la estabilidad de precios.", "Asegurar el crédito de los Estados miembros.", "Mantener la estabilidad de precios y apoyar las políticas económicas generales de la Unión.", "Garantizar los tipos de cambio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 6, "De acuerdo con el artículo 4 del Tratado de funcionamiento de la Unión Europea, qué competencia de las siguientes seguirá siendo exclusiva de cada estado miembro de la Unión:", "La protección civil.", "La protección civil y de los consumidores.", "La seguridad nacional.", "La seguridad nacional, la protección de los consumidores y la protección civil."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 7, "De acuerdo con el artículo 17.2 del Tratado de la Unión Europea, los actos legislativos de la Unión:", "Se adoptan por mayoría calificada del Parlamento Europeo.", "Sólo pueden adoptarse a propuesta de la Comisión, salvo cuando los tratados dispongan otra cosa.", "Únicamente podrán adoptarse a propuesta de la Comisión, salvo cuando los tratados o norma europea dispongan otra cosa.", "Se adoptan a propuesta del Consejo por mayoría calificada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 8, "En cuanto al Parlamento Europeo:", "Tiene su sede en Bruselas, donde celebra sus períodos de sesiones ordinarias, y la Secretaría General se encuentra en Luxemburgo.", "Tiene su sede en Luxemburgo, donde celebra sus períodos de sesiones ordinarias, y la secretaría general se centra en Bruselas.", "Tiene su sede en Estrasburgo, donde celebra sus períodos de sesiones ordinarias, y la Secretaría General se encuentra en Luxemburgo.", "Tiene su sede en Estrasburgo, donde celebra sus períodos de sesiones ordinarias, y la Secretaría General se encuentra en Bruselas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 9, "De conformidad con el artículo 288 del Tratado de funcionamiento de la Unión Europea, indique cuál de los siguientes actos jurídicos de la Unión no son vinculantes:", "Los reglamentos.", "Los dictámenes y recomendaciones.", "Las decisiones.", "Las directivas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 10, "De acuerdo con lo que establece el artículo 48.2 del Tratado de la Unión Europea, pueden presentar al Consejo proyectos de revisión de los tratados:", "El presidente de cualquier Estado miembro, el Parlamento de un Estado miembro o la Comisión Bilateral.", "El gobierno de cualquier estado miembro o sus ministros.", "El parlamento de cualquier Estado miembro, o el Tribunal de Justicia Europeo.", "El gobierno de cualquier Estado miembro, el Parlamento Europeo o la Comisión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 11, "El Tribunal de Justicia de la Unión Europea se compone, de acuerdo con el artículo 19.2 del Tratado de la Unión Europea:", "Dos jueces por cada Estado miembro, asistidos por un abogado general.", "Un Juez por Estado miembro, asistido por abogados generales.", "Un juez por cada Estado miembro que componen el Tribunal General.", "27 abogados generales de los Estados miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 12, "El Parlamento Europeo:", "El Parlamento Europeo ejerce la función legislativa y reglamentaria.", "Ejerce funciones de control político y normativo.", "Ejerce conjuntamente con el Consejo la función legislativa y la función presupuestaria.", "Elige al presidente del Consejo de la Unión Europea."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 13, "De conformidad con lo previsto en el Tratado de la Unión Europea, respecto de las sesiones o reuniones del Consejo:", "No son públicas, con excepción de las reuniones del Consejo de Asuntos Generales.", "Son públicas, salvo las reuniones del Consejo de Asuntos Exteriores y del de Asuntos Económicos y Financieros.", "Son públicas cuando delibere y vote sobre un proyecto de acto legislativo.", "No son públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 14, "De conformidad con lo establecido en el Tratado de funcionamiento de la Unión Europea (TFUE), la Comisión publicará un informe general sobre las actividades de la Unión, con carácter:", "Semestral.", "Anual.", "Trianual.", "Bianual."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 15, "Entre otras funciones, corresponde al Parlamento Europeo:", "No impulsar el desarrollo de la Unión Europea y definir sus orientaciones y prioridades políticas generales.", "Velar por la coherencia de la acción exterior de la Unión Europea.", "Adoptar las iniciativas de la programación anual y plurianual de la Unión Europea para alcanzar acuerdos institucionales.", "Ejercer funciones de control político y consultivo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 16, "Señala la afirmación correcta. Teniendo en cuenta las disposiciones del Tratado de la Unión Europea sobre cooperaciones reforzadas en el artículo 20:", "Las cooperaciones reforzadas, una vez acordadas, están abiertas durante el plazo de diez años a todos los Estados miembros de la Unión.", "Las cooperaciones reforzadas serán adoptadas por el Consejo, en el marco de las competencias exclusivas de la Unión, cuando éste haya llegado a la conclusión de que los objetivos perseguidos por esta cooperación no pueden ser alcanzados en un plazo razonable por la Unión en su conjunto.", "Todos los miembros del Consejo pueden participar en la deliberación y votación de los asuntos de la cooperación reforzada.", "Los actos adoptados en el marco de una cooperación reforzada no se considerarán caudal que deban aceptar los Estados candidatos de la adhesión a la Unión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 17, "El Fondo de la Unión Europea por el que se presta ayuda financiera en caso de que se produzca una catástrofe grave en el territorio de un Estado miembro o de un Estado cuya adhesión a la Unión Europea esté en proceso de negociación, se llama:", "Fondo de Contingencia territorial.", "Fondo de Asistencia Financiera.", "Fondo de Asociación.", "Fondo de Solidaridad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 18, "De acuerdo con el artículo 254 del Tratado de Funcionamiento de la Unión Europea, la duración del mandato del presidente del Tribunal General del Tribunal de Justicia de la Unión Europea es:", "De tres años, no renovable.", "De tres años, renovable.", "De dos años, renovable.", "De dos años, no renovable."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 19, "Según el artículo 4 del Tratado de la Unión Europea, toda competencia no atribuida a la Unión en los Tratados corresponde:", "A los Estados miembros que la soliciten.", "No las gestiona ningún Estado miembro.", "Las reparte el Parlamento Europeo en función de la representatividad.", "En los Estados miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 20, "¿A qué institución corresponde promover el interés general de la Unión Europea según el artículo 17.1 del Tratado de la Unión Europea?", "Al Consejo de la Unión Europea.", "Al Tribunal de Justicia de la Unión Europea.", "A la Comisión Europea.", "Al Consejo Europeo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 21, "El voto de aprobación del Parlamento Europeo al presidente, el alto representante y los demás miembros de la Comisión exige:", "Mayoría absoluta del Parlamento.", "La mayoría de los votos emitidos.", "El voto unánime de los diputados.", "Mayoría de dos tercios de los diputados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 22, "De los siguientes tratados, indique que Tratado la Unión Europea sustituyó a la Comunidad Europea:", "El Tratado de Ámsterdam de 1992.", "El Tratado de Roma.", "El Acta Única Europea de 1986.", "El Tratado de Lisboa de 2007."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 23, "Según el artículo 14.3 Tratado la Unión Europea, ¿cuál es la duración del mandato de un diputado en el Parlamento Europeo?", "Cuatro años.", "Seis años.", "Cinco años.", "Tres años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 24, "Mediante qué mecanismo el Parlamento Europeo establece el estatuto y las condiciones generales de ejercicio de las funciones de sus miembros, previo dictamen de la Comisión y con la aprobación del Consejo?", "Mediante reglamentos adoptados por propia iniciativa, de acuerdo con un procedimiento legislativo especial.", "Mediante una ley.", "Mediante circulares.", "Mediante reglamentos adoptados por iniciativa de un tercio de sus miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 25, "Señale la respuesta correcta. El Parlamento Europeo puede solicitar a la Comisión que presente las propuestas oportunas sobre cualquier asunto que a juicio del Parlamento requiera la elaboración de un acto de la Unión para la aplicación de los tratados:", "Por decisión de una quinta parte de los miembros que lo componen.", "Por decisión de la mayoría de los miembros que lo componen.", "Por decisión de la mitad de los miembros que lo componen.", "Por decisión de una tercera parte de los miembros que lo componen."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 26, "En qué casos el Parlamento Europeo puede constituir una comisión temporal de investigación para examinar, sin perjuicio de las competencias que los tratados confieren a otras instituciones u órganos, alegaciones de infracción o de mala administración en la aplicación del derecho de la Unión, salvo que un órgano jurisdiccional conozca de los hechos alegados, ¿hasta que no se cierre el procedimiento jurisdiccional?", "Únicamente cuando lo soliciten una tercera parte de los miembros que lo componen.", "A petición de la mayoría de los miembros que lo componen.", "En cumplimiento de sus cometidos ya petición de la cuarta parte de los miembros que lo componen.", "Siempre que lo soliciten una quinta parte de los miembros que lo componen."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 27, "¿Quién tiene derecho a presentar en el Parlamento Europeo, individualmente o asociado con otros ciudadanos o personas, una petición sobre un asunto propio de los ámbitos de actuación de la Unión que le afecte directamente?", "Sólo personas físicas.", "Sólo personas jurídicas.", "Cualquier persona física o jurídica aunque no resida o tenga su domicilio social en un Estado miembro.", "Cualquier ciudadano de la Unión, así como cualquier persona física o jurídica que resida o tenga su domicilio social en un Estado miembro."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 28, "¿Quién elige a un defensor del pueblo europeo, que está facultado para recibir las reclamaciones de cualquier ciudadano de la Unión o de cualquier persona física o jurídica que resida o tenga su domicilio social en un Estado miembro?", "La Comisión Europea.", "El Parlamento Europeo.", "El Tribunal de Justicia de la Unión Europea.", "El Consejo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 29, "¿Cada cuánto tiempo celebra el Parlamento Europeo un período de sesiones?", "Cada año.", "Cada medio año.", "Cada dos años.", "Cada tres años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 30, "El Parlamento Europeo puede reunirse en período parcial de sesiones extraordinario:", "A petición de una quinta parte de los miembros que lo componen.", "A petición de la mitad de los miembros que lo componen, del Consejo o de la Comisión.", "A petición de la mayoría de los miembros que lo componen, del Consejo o de la Comisión.", "a petición de una tercera parte de los miembros que lo componen."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 31, "El Parlamento Europeo, en caso de que se le someta una moción de censura sobre la gestión de la Comisión:", "Sólo podrá pronunciarse sobre esta moción transcurridos tres días como mínimo desde la fecha de la presentación y en votación pública.", "Sólo podrá pronunciarse sobre esta moción transcurridos cinco días como mínimo desde la fecha de la presentación y en votación pública.", "Sólo podrá pronunciarse sobre esta moción transcurridos tres días como máximo desde la fecha de la presentación y en votación pública.", "Sólo podrá pronunciarse sobre esta moción transcurridos diez días como mínimo desde la fecha de su presentación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 32, "Señale la respuesta correcta:", "El Consejo ejerce conjuntamente con la Comisión la función legislativa.", "El Consejo ejerce únicamente funciones legislativas.", "El Consejo ejerce conjuntamente con el Parlamento Europeo la función reglamentaria.", "El Consejo ejerce conjuntamente con el Parlamento Europeo la función legislativa y presupuestaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 33, "¿En qué casos se reúne el Consejo?", "Por convocatoria de su presidente, a iniciativa de éste, de uno de sus miembros o de la Comisión.", "Por convocatoria de sus consejeros, a iniciativa de éste.", "Por convocatoria de su presidente, cuando lo solicite una tercera parte de sus miembros.", "Por convocatoria de su presidente, cuando lo solicite la mitad de sus miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 34, "¿Quién se encarga de preparar los trabajos del Consejo y de realizar las tareas que éste le confía?", "Los miembros de la Secretaría General.", "Un comité compuesto por Representantes Permanentes de los Gobiernos de los Estados miembros.", "Los propios miembros del Consejo.", "El Defensor del Pueblo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 35, "Señale la respuesta correcta. El Consejo fija los sueldos, dietas y pensiones:", "De los jefes de Estado.", "Del presidente del Banco Central Europeo y de sus miembros.", "De los presidentes, de los miembros y de los secretarios de cada estado miembro.", "Del presidente del Consejo Europeo; del presidente de la Comisión: del alto representante de la Unión para Asuntos Exteriores y Política de Seguridad; de los miembros de la Comisión; de los presidentes, miembros y secretarios del Tribunal de Justicia de la Unión Europea y del Secretario General del Consejo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 36, "¿Cuál de las siguientes no es una función del presidente de la Comisión?", "Definir las orientaciones de acuerdo con las que la Comisión desempeña sus funciones.", "Presidir el Consejo de Asuntos Exteriores.", "Determinar la organización interna de la Comisión y velar por la coherencia, eficacia y colegialidad de su actuación.", "Nombrar a vicepresidentes, distintos del alto representante de la Unión para Asuntos Exteriores y Política de Seguridad, entre los miembros de la Comisión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 37, "¿Cuándo publica la Comisión un informe general sobre las actividades de la Unión?", "Cada año al menos un mes antes de la apertura del período de sesiones del Parlamento Europeo.", "Cada año al menos dos meses antes de la apertura del período de sesiones del Parlamento Europeo.", "Cada año con una antelación de un mes y medio antes de la apertura del período de sesiones del Parlamento Europeo.", "Cada año al menos tres meses antes de la apertura del período de sesiones del Parlamento Europeo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 38, "El Tribunal General dispondrá:", "Al menos de un juez por estado miembro.", "Al menos de dos jueces por estado miembro.", "Por tres jueces por estado miembro.", "Por cuatro jueces por estado miembro."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 39, "Señale la respuesta incorrecta. El Tribunal de Justicia de la Unión Europea se pronuncia, de conformidad con los tratados:", "Con carácter prejudicial, a petición de los órganos jurisdiccionales nacionales, sobre la interpretación del derecho de la Unión o sobre la validez de los actos adoptados por las instituciones.", "Sobre los recursos interpuestos por un Estado miembro, por una institución o por personas físicas o jurídicas.", "En los demás casos previstos por los tratados.", "Sobre los conflictos de competencias entre los Estados miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 40, "¿Por qué período son nombrados los jueces y abogados generales del Tribunal de Justicia y los jueces del Tribunal General?", "4 años.", "3 años.", "6 años.", "5 años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 41, "¿Qué año se firmó el Estatuto del Consejo de Europa ?", "1944", "1919.", "1959.", "1949."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 42, "¿Qué países se adhirieron en 2004 a la Unión Europea?", "Dinamarca, Irlanda y Reino Unido.", "La República Checa, Chipre, Eslovaquia, Eslovenia, Estonia, Hungría, Letonia, Lituania, Malta y Polonia.", "Austria, Finlandia, Suecia, España y Portugal.", "Bulgaria, Rumanía y Grecia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 43, "Según el Tratado de Lisboa, el Consejo de la Unión Europea está integrado:", "Por un representante de cada Estado miembro, de rango ministerial, facultado para comprometer al Gobierno del Estado miembro que represente y para ejercer el derecho de voto.", "Por dos representantes de cada Estado miembro, de rango ministerial, facultades para comprometer al Gobierno del Estado miembro que representen.", "Por un representante de cada Estado miembro de rango ministerial, facultado para comprometer al Gobierno del Estado miembro que represente, aunque no pueda ejercer el derecho de voto.", "Por tres representantes de cada Estado miembro de rango ministerial, facultades para comprometer al Gobierno del Estado miembro que representen y para ejercer el derecho de voto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 44, "En relación con los tratados de la Unión Europea:", "Forman parte del derecho derivado de la Unión Europea.", "Sólo forman parte del derecho originario los tratados constitutivos.", "Entre los tratados se encuentra el Tratado de Madrid de 1991, que forma parte del derecho de la Unión Europea.", "Forman parte del derecho originario de la Unión Europea."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 45, "Las directivas comunitarias:", "No se aplican directamente a los estados.", "No son vinculantes.", "Habitualmente se dictan sobre materias que son competencias exclusivas de la Unión d) Europea.", "Tienen alcance general."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 46, "El Consejo de la Unión Europea:", "Está asistido por dos secretarías generales.", "Está asistido por una Secretaría General, dirigida por un secretario general.", "Está asistido por un alto representante de Política Interior y Exterior.", "Está asistido por el Consejo de Europa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 47, "¿Cuántos estados eran miembros de la Unión Europea al entrar en vigor la Acta Única Europea?", "10 estados.", "12 estados.", "13 estados.", "8 estados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 48, "¿Cuándo entró en vigor el Tratado de Lisboa?:", "El 2 de octubre de 1992.", "El 1 de julio de 2008.", "El 1 de diciembre de 2009.", "El 3 de marzo de 1997."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 49, "¿Cuándo puede durar el mandato del presidente del Consejo Europeo?", "Cinco años.", "Cuatro años.", "Tres años.", "Seis años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 50, "¿Qué órgano es el legitimado para interponer recursos ante el Tribunal de Justicia de la Unión Europea por violación de los principios de subsidiariedad y proporcionalidad?", "El Presidente del Parlamento Europeo.", "La Comisión Europea.", "El Parlamento Europeo.", "El Comité de Regiones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 51, "¿En qué Tratado se prevé explícitamente y por primera vez la posibilidad de que un Estado miembro se retire de la Unión?", "El Tratado de Lisboa.", "El Tratado de Niza.", "El Tratado de Ámsterdam.", "El Tratado de Maastricht."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 52, "La Unión Europea se fundamenta en los siguientes tratados:", "Tratado de la Unión Europea y Tratado de la Comunidad Europea de la Energía Atómica.", "Tratado de la Unión Europea, Tratado de Funcionamiento de la Unión Europea y carta de derechos fundamentales de la Unión Europea.", "Tratado de la Comunidad Europea del Carbón y del Acero, Tratado de la Comunidad Europea de la Energía Atómica y Tratado de la Comunidad Europea.", "Tratado de la Unión Europea y Tratado de funcionamiento de la Unión Europea."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 53, "Según el artículo 5 del Tratado de la Unión Europea, la delimitación de las competencias en la Unión se rige por el siguiente principio:", "El principio de cooperación leal.", "El principio de subsidiariedad.", "El principio de atribución.", "El principio de proporcionalidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 54, "La Unión Europea sucede en la Comunidad Europea con el siguiente tratado:", "El Tratado de Ámsterdam.", "El Tratado de Lisboa.", "El Tratado de Niza.", "El Tratado de Maastricht."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 55, "El presidente del Tribunal de Justicia tiene un mandato:", "De un año.", "De cuatro años.", "De dos años.", "De tres años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 56, "¿Cuál es la duración del mandato de los Diputados del Parlamento Europeo:", "Cinco años, que comienzan desde la proclamación del diputado electo.", "Cinco años, que comienzan con la apertura del primer período de sesiones después de cada elección.", "Cinco años, que comienzan desde la proclamación del diputado electo.", "Cuatro años, que comienzan con la apertura del primer período de sesiones después de cada elección."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 57, "Los gastos del presupuesto de la Unión Europea pueden ser:", "Ordinarias y extraordinarias.", "Finalistas y no finalistas.", "Obligatorias y no obligatorias.", "De funcionamiento y de intervención."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 58, "La Gran sala del Tribunal de Justicia está compuesta:", "Por quince jueces.", "Por doce jueces.", "Por cinco jueces.", "Por siete jueces."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 59, "Tras la entrada en vigor del Tratado de Lisboa, las instituciones son:", "El Parlamento Europeo, el Consejo Europeo, el Consejo, la Comisión Europea, el Tribunal de Justicia de la Unión Europea, el Tribunal de Cuentas y el Banco Central Europeo y el Banco Europeo de Inversiones.", "El Parlamento Europeo, el Consejo Europeo, el Consejo, la Comisión Europea, el Tribunal de Justicia de la Unión Europea y el Defensor del Pueblo.", "El Parlamento Europeo, el Consejo Europeo, el Consejo, la Comisión Europea, el Tribunal de Justicia de la Unión Europea y el Defensor del Pueblo.", "El Parlamento Europeo, el Consejo Europeo, el Consejo, la Comisión Europea, el Tribunal de Justicia de la Unión Europea, el Tribunal de Cuentas y el Banco Central Europeo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 60, "¿Cuál es la forma de adopción de decisión, como norma general, del Consejo de la Unión Europea?", "Mayoría calificada.", "Unanimidad.", "Mayoría absoluta.", "Mayoría simple."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 61, "¿Indica qué órgano nombra a los miembros del Tribunal de Cuentas?", "El Parlamento Europeo.", "El Consejo de la Unión Europea.", "El Consejo Europeo.", "Los gobiernos de los Estados miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 62, "Indique la opción correcta en relación con la presidencia del Consejo Europeo:", "Es permanente y recae en una persona elegida por mayoría calificada. Su mandato es de dos años y medio.", "Es rotatoria y por seis meses.", "Su mandato será de dos años y será elegido por mayoría calificada.", "Su mandato será de cuatro años y será elegido por mayoría simple."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 63, "Los Reglamentos entran en vigor:", "El día de su publicación en el diario que corresponda.", "A los treinta días de su publicación en el Diario Oficial de la Unión Europea.", "A los veinte días de su publicación en el Diario Oficial de la Unión Europea.", "En la fecha que se indique o, en su defecto, a los veinte días de su publicación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 64, "¿Qué actos son los reglamentos de funcionamiento interno de las instituciones?", "Actos complementarios.", "Actos constitutivos.", "Actos legislativos.", "Actos atípicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 65, "¿En qué tratado se creó la figura del Defensor del Pueblo Europeo?", "En el Tratado de Roma.", "En el Tratado de Maastricht.", "En el Tratado de Ámsterdam.", "En el Tratado de La Haya."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 66, "¿Cuántos abogados generales integran el Tribunal de Justicia Europeo?", "6 abogados generales.", "11 abogados generales.", "Un abogado general por cada estado miembro.", "12 abogados generales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 5, 67, "Según el Tratado de Lisboa, ¿cuál de las siguientes es competencia exclusiva de la Unión Europea?", "Política monetaria de los Estados miembros con moneda euro.", "Medio ambiente.", "Redes transeuropeas.", "Cohesión económica, social y territorial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 1, "Según el art. 35.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, los actos serán motivados:", "Con sucinta referencia de hechos y fundamentos de derecho.", "Con extensa referencia a los hechos.", "Con sucinta referencia a los fundamentos de derecho.", "Con extensa referencia de hechos y fundamentos de derecho."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 2, "Según el art. 35.1.f) de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, deben ser motivados:", "Los actos que rechacen pruebas propuestas por los interesados.", "Los actos que se dicten en ejercicio de potestades regladas.", "Los actos que reconozcan derechos subjetivos o intereses legítimos.", "Los actos sigan el dictamen de órganos consultivos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 3, "El art. 36.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, establece que:", "Los actos administrativos se producirán por escrito a través de medios electrónicos.", "Los actos administrativos se producirán por escrito o verbalmente, a menos que su naturaleza exija otra forma más adecuada de expresión y constancia.", "Los actos administrativos se producirán por escrito a través de medios electrónicos, a menos que su naturaleza exija otra forma más adecuada de expresión y constancia.", "Los actos administrativos se producirán por escrito o verbalmente, siempre por medios electrónicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 4, "El art. 36.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, establece que en los casos en que los órganos administrativos ejerzan su competencia de forma verbal:", "La constancia del acto se efectuará a través de medios de grabación y difusión.", "La constancia escrita del acto, cuando sea necesaria, se efectuará y firmará por el titular del órgano superior o funcionario que la reciba oralmente, expresando en la comunicación del mismo la autoridad de la que procede.", "La constancia escrita del acto se efectuará y firmará por la autoridad que emita el acto.", "La constancia escrita del acto, cuando sea necesaria, se efectuará y firmará por el titular del órgano inferior o funcionario que la reciba oralmente, expresando en la comunicación del mismo la autoridad de la que procede."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 5, "Según el art. 36.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, cuando deba dictarse una serie de actos administrativos de la misma naturaleza, tales como nombramientos, concesiones o licencias:", "Se refundirán en un único acto, acordado por el órgano competente.", "Podrán refundirse en un único acto, certificado por el funcionario competente.", "Podrán refundirse en un único acto, acordado por el órgano competente.", "Se dictarán actos separados, acordados por el órgano competente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 6, "De acuerdo con el art. 37.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Las resoluciones administrativas de carácter particular podrán vulnerar lo establecido en una disposición de carácter general si proceden de un órgano de superior jerarquía al que dictó la disposición general.", "Las resoluciones administrativas de carácter particular podrán inaplicar la regulación establecida en una disposición reglamentaria de un órgano inferior.", "Son nulas las resoluciones administrativas que vulneren lo establecido en una disposición reglamentaria, así como aquellas que incurran en alguna de las causas recogidas en el artículo 47.", "Son anulables la resoluciones administrativas que vulneren lo establecido en una disposición reglamentaria, así como aquellas que incurran en alguna de las causas recogidas en el artículo 47."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 7, "En virtud del principio de inderogabilidad singular consagrado en el art. 37 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Las resoluciones dictadas por los consejeros pueden vulnerar los decretos aprobados por el Consejo de Gobierno.", "Los actos administrativos del Consejo de Gobierno pueden vulnerar lo establecido en un decreto del propio Consejo de Gobierno.", "Las resoluciones dictadas por los consejeros deben aplicar los decretos aprobados por el Consejo de Gobierno.", "Las resoluciones dictadas por los consejeros únicamente deben aplicar los decretos emanados por los órganos de igual o superior jerarquía."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 8, "Según el art. 39.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, los actos de las Administraciones Públicas sujetos al derecho administrativo, se presumirán válidos y producirán efectos:", "Desde la fecha en que se dicten, salvo que en ellos se disponga otra cosa.", "Desde la fecha en que se notifiquen, salvo que en ellos se disponga otra cosa.", "Desde la fecha en que se dicten, cuando se indique expresamente.", "Desde la fecha en que se notifiquen, cuando se indique expresamente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 9, "De acuerdo con el art. 39.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, excepcionalmente podrá otorgarse eficacia retroactiva a los actos:", "Cuando se dicten en sustitución de actos anulados, así como cuando produzcan efectos favorables al interesado.", "Cuando se dicten en sustitución de actos nulos o anulables, así como cuando produzcan efectos favorables al interesado.", "Cuando se dicten en sustitución de actos anulados, así como cuando produzcan efectos desfavorables al interesado.", "Cuando se dicten en sustitución de actos nulos o anulables, así como cuando produzcan efectos desfavorables al interesado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 10, "Indique cuál de las siguientes afirmaciones es correcta según el art. 39.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Los actos dictados por los órganos de las Administraciones Públicas en el ejercicio de su propia competencia únicamente vinculan a los órganos de la misma administración.", "Los actos de las Administraciones Públicas sujetos al Derecho Administrativo se presumirán válidos y producirán efectos desde la fecha de la notificación, salvo que en ellos se disponga otra cosa", "La eficacia quedará demorada cuando lo soliciten los interesados o esté supeditada a su notificación, publicación o aprobación superior.", "Podrá otorgarse eficacia retroactiva a los actos cuando se dicten en sustitución de actos anulados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 11, "Según el art. 39.5 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, cuando una Administración Pública tenga que dictar, en el ámbito de sus competencias, un acto que necesariamente tenga por base otro dictado por una Administración Pública distinta y aquélla entienda que es ilegal:", "No debe aplicar el acto administrativo y simultáneamente debe interponer un recurso contencioso administrativo.", "Podrá requerir a ésta previamente para que anule o revise el acto de acuerdo con lo dispuesto en el artículo 44 de la Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso- Administrativa, y, de rechazar el requerimiento, podrá interponer recurso contencioso-administrativo.", "Podrá requerir a ésta previamente para que anule o revise el acto y, de rechazar el requerimiento, suspenderá la aplicación del acto.", "Podrá suspender la aplicación del acto administrativo y simultáneamente debe interponer un recurso contencioso administrativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 12, "Según el art. 40.4 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, a los solos efectos de entender cumplida la obligación de notificar dentro del plazo máximo de duración de los procedimientos, será suficiente la notificación que contenga, cuando menos:", "El texto íntegro de la resolución, con indicación de si pone fin o no a la vía administrativa, la expresión de los recursos que procedan, en su caso, en vía administrativa y judicial.", "Un extracto de la resolución, con indicación de si pone fin o no a la vía administrativa, la expresión de los recursos que procedan, en su caso, en vía administrativa y judicial.", "El texto íntegro de la resolución, así como el intento de notificación debidamente acreditado.", "El texto íntegro de la resolución, con indicación de si pone fin o no a la vía administrativa, la expresión de los recursos que procedan, así como el intento de notificación debidamente acreditado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 13, "Según el art. 41.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿qué notificaciones no deben efectuarse por medios electrónicos?", "Aquellas en las que el acto a notificar vaya acompañado de elementos que no sean susceptibles de conversión en formato electrónico.", "Las que reconozcan derechos a favor de los interesados.", "Aquellas que contengan el texto íntegro de la resolución, con indicación de si pone fin o no a la vía administrativa.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 14, "Según el art. 41.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿cuál de las siguientes notificaciones no debe practicarse por medios electrónicos?", "Una notificación que contenga un medio de pago a favor del obligado.", "Una notificación que vaya acompañada de elementos susceptibles de conversión en formato electrónico.", "Una notificación que contenga una multa.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 15, "Según el art. 41.5 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, si el interesado rechaza la notificación de una actuación administrativa:", "Se hará constar esta circunstancia en el expediente, junto con el día y la hora en que se intentó la notificación, intento que se repetirá por una sola vez y en una hora distinta dentro de los tres días siguientes.", "La notificación se hará por medio de un anuncio publicado en el Boletín Oficial del Estado.", "Se hará constar en el expediente, especificándose las circunstancias del intento de notificación y el medio, dando por efectuado el trámite y siguiéndose el procedimiento.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 16, "Según el art. 41.6 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, si la Administración incumple la obligación de enviar un aviso al interesado informándole de la puesta a disposición de una notificación en la sede electrónica de la Administración:", "La notificación será considerada plenamente válida.", "La notificación incurrirá en un vicio de nulidad de pleno derecho.", "La notificación incurrirá en un vicio de anulabilidad.", "La notificación deberá repetirse."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 17, "De acuerdo con el art. 41.7 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, si el interesado ha sido notificado por distintos cauces, se tomará como fecha de notificación:", "La que resulte más favorable para el interesado.", "La que se haya producido en último lugar.", "La que determine el interesado.", "La que se haya producido en primer lugar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 18, "Según el art. 42.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, cuando una notificación se practique en papel:", "No deberá ser puesta a disposición del interesado en la sede electrónica de la Administración.", "Deberá ser puesta a disposición del interesado en la sede electrónica de la Administración para que pueda acceder al contenido de la misma de forma voluntaria.", "El interesado deberá acceder a su contenido a través de la sede electrónica de la Administración.", "Deberá publicarse en la sede electrónica de la Administración para que el interesado pueda consultar su contenido."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 19, "Según el art. 42.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo a la práctica de notificaciones en papel:", "Cuando el interesado accediera al contenido de la notificación en sede electrónica, el resto de notificaciones se practicarán través de medios electrónicos.", "Las notificaciones que se practiquen en papel podrán ser puestas a disposición del interesado en la sede electrónica.", "Cuando el interesado accediera al contenido de la notificación en sede electrónica, se le ofrecerá la posibilidad de que el resto de notificaciones se puedan realizar a través de medios electrónicos.", "Las notificaciones que se practiquen en papel no serán puestas a disposición del interesado en la sede electrónica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 20, "Según el art. 43.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, la notificación se entenderá rechazada cuando hayan transcurrido diez días naturales desde la puesta a disposición de la notificación sin que se acceda a su contenido:", "Cuando la notificación por medios electrónicos sea de carácter obligatorio.", "Cuando la notificación por medios electrónicos sea de carácter obligatorio, o haya sido expresamente elegida por el interesado.", "Cuando la notificación por medios electrónicos haya sido expresamente elegida por el interesado.", "Cuando la notificación por medios electrónicos sea de carácter voluntario, o haya sido expresamente elegida por el interesado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 21, "Según el art. 43.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, se entenderá cumplida la obligación a la que se refiere el artículo 40.4:", "Con la puesta a disposición de la notificación en la sede electrónica o en la dirección electrónica habilitada única.", "Cuando hayan transcurrido diez días naturales desde la puesta a disposición de la notificación en la sede electrónica o en la dirección electrónica habilitada única.", "Cuando hayan transcurrido diez días hábiles desde la puesta a disposición de la notificación en la sede electrónica o en la dirección electrónica habilitada única.", "Cuando hayan transcurrido quince días hábiles desde la puesta a disposición de la notificación en la sede electrónica o en la dirección electrónica habilitada única."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 22, "Según el art. 43 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo a la práctica de las notificaciones a través de medios electrónicos:", "Los interesados podrán acceder a las notificaciones desde el Punto de Acceso General electrónico de la Administración, que funcionará como un portal de acceso.", "Se entiende por comparecencia en la sede electrónica, el acceso por el interesado o su representante debidamente identificado al contenido de la notificación.", "Las notificaciones se entenderán practicadas en el momento de la puesta a disposición de la notificación en la sede electrónica de la Administración.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 23, "Según el art. 44 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿en qué supuestos debe practicarse la notificación mediante anuncios?", "Cuando los interesados en un procedimiento sean desconocidos o bien se ignore el lugar de la notificación.", "Cuando los interesados en un procedimiento sean desconocidos o bien se ignore el lugar de la notificación, y cuando los interesados hayan rechazado la notificación.", "Cuando los interesados en un procedimiento sean desconocidos, se ignore el lugar de la notificación o bien, intentada ésta, no se hubiese podido practicar.", "Cuando los interesados en un procedimiento sean desconocidos o hayan rechazado la notificación, cuando se ignore el lugar de la notificación o bien, intentada ésta, no se hubiese podido practicar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 24, "Según el art. 44 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo a la notificación infructuosa:", "Las Administraciones Públicas establecerán otras formas de notificación complementarias a través de los restantes medios de difusión, que no excluirán la obligación de publicar el correspondiente anuncio en el «Boletín Oficial del Estado».", "Las Administraciones Públicas podrán establecer otras formas de notificación complementarias a través de los restantes medios de difusión, que no excluirán la obligación de publicar el correspondiente anuncio en el «Boletín Oficial del Estado».", "Las Administraciones Públicas podrán establecer otras formas de notificación complementarias a través de los restantes medios de difusión, que excluirán la obligación de publicar el correspondiente anuncio en el «Boletín Oficial del Estado».", "Las Administraciones Públicas establecerán otras formas de notificación complementarias a través de los restantes medios de difusión, que excluirán la obligación de publicar el correspondiente anuncio en el «Boletín Oficial del Estado»."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 25, "Según el art. 44 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, la publicación de un anuncio en el boletín oficial de la Comunidad Autónoma o de la Provincia en los casos de notificación infructuosa:", "Es obligatoria y se hará previamente a la publicación del anuncio en el «Boletín Oficial del Estado».", "Es facultativa y se hará previamente a la publicación del anuncio en el «Boletín Oficial del Estado».", "Es obligatoria y se hará después de la publicación del anuncio en el «Boletín Oficial del Estado».", "Es facultativa y se hará después de la publicación del anuncio en el «Boletín Oficial del Estado»."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 26, "Indique cuál de las siguientes afirmaciones es correcta según el art. 45.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo a la publicación de actos administrativos:", "Los actos administrativos serán objeto de publicación cuando así lo establezcan las normas reguladoras de cada procedimiento o cuando lo aconsejen razones de interés público apreciadas por el órgano competente.", "La publicación de los actos se realizará siempre en el «Boletín Oficial del Estado», con independencia de cual sea la Administración de la que proceda el acto a notificar.", "Todos los actos integrantes de un procedimiento selectivo o de concurrencia competitiva se publicarán obligatoriamente en el diario oficial que corresponda.", "Todos los actos que afecten a una pluralidad de personas se publicarán obligatoriamente en el diario oficial que corresponda."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 27, "Según el art. 45.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿cuál de los siguientes actos administrativos deberá ser publicado?", "Un acto que tenga por destinatario a una pluralidad indeterminada de personas.", "Un acto que tenga por destinatarias a más de diez personas.", "Un acto que tenga por destinatario a una persona que ha rechazado la notificación.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 28, "Según el art. 46 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, si el órgano competente aprecia que la notificación por medio de anuncios o la publicación de un acto lesiona derechos o intereses legítimos:", "Se limitará a publicar en el Diario oficial que corresponda una somera indicación del contenido del acto y del lugar donde los interesados podrán comparecer.", "Se limitará a publicar en el «Boletín Oficial del Estado» una somera indicación del contenido del acto y del lugar donde los interesados podrán comparecer.", "Se limitará a publicar en el Diario oficial que corresponda una somera indicación del contenido del acto y del lugar donde todos los ciudadanos podrán comparecer.", "Se limitará a publicar en el «Boletín Oficial del Estado» el texto íntegro del acto y el lugar donde los interesados podrán comparecer."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 29, "Según el art. 47.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿cuál de los siguientes actos es nulo de pleno derecho?", "El que se dicte por un órgano manifiestamente incompetente por razón del territorio.", "El que contenga un defecto de forma.", "El que restrinja derechos de los ciudadanos.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 30, "Según el art. 47.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, son nulas de pleno derecho las disposiciones administrativas:", "Que vulneren la Constitución, las leyes, las disposiciones y los actos administrativos de rango superior, las que regulen materias reservadas a la Ley, y las que establezcan la retroactividad de disposiciones sancionadoras no favorables o restrictivas de derechos individuales.", "Que vulneren la Constitución, las leyes u otras disposiciones administrativas de rango superior, las que regulen materias reservadas a la Ley, y las que establezcan la irretroactividad de disposiciones sancionadoras no favorables o restrictivas de derechos individuales.", "Que vulneren la Constitución, las leyes u otras disposiciones administrativas de rango superior, las que regulen materias reservadas a la Ley, y las que establezcan la retroactividad de disposiciones sancionadoras no favorables o restrictivas de derechos individuales.", "Que vulneren la Constitución, las leyes, las disposiciones y los actos administrativos de rango superior, las que regulen materias reservadas a la Ley, y las que establezcan la irretroactividad de disposiciones sancionadoras no favorables o restrictivas de derechos individuales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 31, "Indique cuál de las siguientes afirmaciones es incorrecta según el art. 48.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Son anulables los actos de la Administración que incurran en cualquier infracción del ordenamiento jurídico, incluso la desviación de poder.", "El defecto de forma sólo determinará la anulabilidad cuando el acto carezca de los requisitos formales indispensables para alcanzar su fin o dé lugar a la indefensión de los interesados.", "La Administración podrá convalidar los actos anulables, subsanando los vicios de que adolezcan.", "La realización de actuaciones administrativas fuera del tiempo establecido para ellas implicará la nulidad del acto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 32, "Indique cuál de las siguientes afirmaciones es correcta según el art. 49.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "La nulidad o anulabilidad en parte del acto administrativo no implicará la de las partes del mismo independientes de aquélla, siempre que la parte viciada sea de tal importancia que sin ella el acto administrativo no hubiera sido dictado.", "La nulidad o anulabilidad de un acto implicará la de los sucesivos en el procedimiento que sean independientes del primero.", "La nulidad de una parte del acto administrativo siempre determina la nulidad del resto de partes del acto.", "La nulidad o anulabilidad de un acto no implicará la de los sucesivos en el procedimiento que sean independientes del primero."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 33, "El art. 50 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo a la conversión de actos viciados, establece que:", "Los actos nulos que, sin embargo, contengan los elementos constitutivos de otro distinto no producirán efectos jurídicos.", "Los actos nulos o anulables que, sin embargo, contengan los elementos constitutivos de otro distinto no producirán efectos jurídicos.", "Los actos anulables que, sin embargo, contengan los elementos constitutivos de otro distinto producirán los efectos de éste.", "Los actos nulos o anulables que, sin embargo, contengan los elementos constitutivos de otro distinto producirán los efectos de éste."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 34, "Según el art. 52.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el acto de convalidación producirá efecto:", "Desde su fecha, salvo lo dispuesto en el artículo 39.3 para la retroactividad de los actos administrativos.", "Siempre desde que se dictó el acto convalidado, además de lo dispuesto en el artículo 39.3 para la retroactividad de los actos administrativos.", "Desde la notificación, salvo lo dispuesto en el artículo 39.3 para la retroactividad de los actos administrativos.", "Desde la notificación o publicación, salvo lo dispuesto en el artículo 39.3 para la retroactividad de los actos administrativos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 35, "Indique cuál de las siguientes afirmaciones es correcta según el art. 52.4 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo a la convalidación de actos administrativos:", "La Administración podrá convalidar los actos nulos o anulables, subsanando los vicios de que adolezcan.", "El acto de convalidación producirá efecto desde la notificación.", "Si el vicio consistiese en la falta de alguna autorización, podrá ser convalidado el acto mediante el otorgamiento de la misma por el órgano competente.", "Si el vicio consiste en incompetencia determinante de nulidad, la convalidación podrá realizarse por el órgano competente cuando sea superior jerárquico del que dictó el acto viciado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 36, "Según el art. 112.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, los recursos de alzada y de reposición deben fundarse:", "En cualquier infracción del ordenamiento jurídico.", "En cualquiera de los motivos de nulidad o anulabilidad previstos en los artículos 47 y 48 de esta Ley.", "En cualquiera de los motivos de nulidad, anulabilidad o error material previstos en los artículos 47 y 48 de esta Ley.", "En cualquiera de los motivos de nulidad previstos en los artículos 47 y 48 de esta Ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 37, "Según el art. 112.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿contra qué actos de trámite se puede interponer un recurso administrativo?", "Contra los que deciden indirectamente el fondo del asunto, determinan la imposibilidad de continuar el procedimiento, o producen perjuicio a derechos e intereses legítimos.", "Contra los que deciden directa o indirectamente el fondo del asunto, determinan la imposibilidad de continuar el procedimiento, o producen perjuicio irreparable a derechos e intereses legítimos.", "Contra los que deciden directa o indirectamente el fondo del asunto, determinan la imposibilidad de continuar el procedimiento, producen indefensión o perjuicio irreparable a derechos e intereses legítimos.", "Contra los que deciden directa o indirectamente el fondo del asunto, determinan la imposibilidad de continuar el procedimiento, producen indefensión o perjuicio irreparable o lesionan expectativas e intereses intereses legítimos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 38, "Indique cuál de las siguientes afirmaciones es correcta según el art. 112.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Contra las disposiciones administrativas de carácter general cabrá recurso en vía administrativa.", "Los reglamentos podrán sustituir el recurso de alzada por otros procedimientos de impugnación, reclamación, conciliación, mediación y arbitraje.", "Los recursos contra un acto administrativo que se funden únicamente en la nulidad de alguna disposición administrativa de carácter general podrán interponerse directamente ante el órgano que dictó dicha disposición.", "Se puede interponer recurso de alzada o de reposición contra todos los actos de trámite."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 39, "Según el art. 114.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿cuál de los actos siguientes pone fin a la vía administrativa?", "Las resoluciones de los órganos administrativos que tengan superior jerárquico.", "La resolución administrativa de los procedimientos de responsabilidad patrimonial, cualquiera que fuese el tipo de relación, pública o privada, de que derive.", "Los acuerdos que inicien la negociación de pactos, convenios o contratos.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 40, "De acuerdo con el art. 115.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, en la interposición de un recurso no hay obligación de expresar:", "El acto que se recurre y la razón de su impugnación.", "Los plazos de resolución del recurso.", "El órgano, centro o unidad administrativa al que se dirige y su correspondiente código de identificación.", "El lugar, fecha y firma del recurrente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 41, "Indique cuál de las siguientes afirmaciones es correcta según el art. 115.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Los recursos administrativos pueden presentarse de forma anónima.", "El transcurso del plazo para la interposición del recurso no es una causa de inadmisión.", "El error o la ausencia de la calificación del recurso por parte del recurrente no será obstáculo para su tramitación, siempre que se deduzca su verdadero carácter.", "Los vicios y defectos que hagan anulable un acto podrán ser alegados por quienes los hubieren causado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 42, "Según el art. 116 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿cómo debe actuar un órgano administrativo cuando considere que la competencia para resolver un recurso corresponde a otra Administración Pública?", "Remitirá directamente el recurso al órgano que considere competente, debiendo notificar esta circunstancia a los interesados.", "Deberá desestimar el recurso, debiendo notificar esta circunstancia a los interesados.", "Deberá requerir al interesado para que subsane el recurso.", "Remitirá el recurso al órgano superior jerárquico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 43, "Según el art. 117.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿en qué circunstancias puede suspenderse la ejecución del acto impugnado?", "Cuando la ejecución pudiera causar perjuicios de imposible o difícil reparación.", "Cuando la impugnación se fundamente en alguna de las causas de nulidad de pleno derecho previstas en el artículo 47.1 de esta Ley.", "Cuando la ejecución pudiera causar perjuicios de imposible o difícil reparación o cuando la impugnación se fundamente en alguna de las causas de nulidad de pleno derecho previstas en el artículo 47.1 de esta Ley.", "Cuando la ejecución pudiera causar perjuicios de imposible o difícil reparación o cuando la impugnación se fundamente en alguna de las causas de nulidad o de anulabilidad previstas en los artículos 47 y 48 de esta Ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 44, "Según el art. 117.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, la ejecución del acto impugnado se entenderá suspendida:", "Si transcurrido un mes desde que la solicitud de suspensión haya tenido entrada en cualquier registro electrónico, el órgano a quien competa resolver el recurso no ha dictado y notificado resolución expresa al respecto.", "Transcurrido un mes desde que la solicitud de suspensión haya tenido entrada en el registro electrónico de la Administración u Organismo competente para decidir sobre la misma.", "Si transcurrido un mes desde que la solicitud de suspensión haya tenido entrada en el registro electrónico de la Administración u Organismo competente para decidir sobre la misma, el órgano a quien competa resolver el recurso no ha dictado y notificado resolución expresa al respecto.", "Transcurrido un mes desde que la solicitud de suspensión haya tenido entrada en cualquier registro electrónico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 45, "Indique cuál de las siguientes afirmaciones es correcta según el art. 117.4 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo a la suspensión de la ejecución de los actos:", "La ejecución se deberá suspender cuando la impugnación se fundamente en alguna de las causas de nulidad de pleno derecho previstas en el artículo 47.1 de esta Ley.", "La suspensión se prolongará después de agotada la vía administrativa cuando, habiéndolo solicitado previamente el interesado, exista medida cautelar y los efectos de ésta se extiendan a la vía contencioso-administrativa.", "Al dictar el acuerdo de suspensión se deberán adoptar medidas cautelares para asegurar la eficacia de la resolución.", "Si el interesado interpone un recurso contencioso-administrativo decaerá automáticamente la suspensión de la ejecución del acto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 46, "Según el art. 118.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo al trámite de audiencia a los interesados en un recurso administrativo:", "No podrá solicitarse la práctica de pruebas cuando su falta de realización en el procedimiento en el que se dictó la resolución recurrida fuera imputable al interesado.", "Podrá solicitarse la práctica de todas las pruebas que no se hayan realizado durante el procedimiento.", "No podrá solicitarse la práctica de pruebas que no se hayan realizado durante el procedimiento.", "Podrá solicitarse la práctica de todas las pruebas que sean relevantes para la decisión del procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 47, "Indique cuál de las siguientes afirmaciones es correcta según el art. 118.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo al trámite de audiencia a los interesados en un recurso administrativo:", "El recurso, los informes y las propuestas tienen el carácter de documentos nuevos a los efectos de este artículo.", "No se tendrán en cuenta en la resolución de los recursos, hechos, documentos o alegaciones del recurrente, cuando habiendo podido aportarlos en el trámite de alegaciones no lo haya hecho.", "Si hubiera otros interesados se les dará, en todo caso, traslado del recurso para que en el plazo de quince días aleguen cuanto estimen procedente.", "Tienen carácter de documentos nuevos los que los interesados hayan aportado al expediente antes de recaer la resolución impugnada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 48, "Según el art. 119.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, cuando el órgano competente considere que existe un vicio de forma en un acto recurrido:", "Debe acordar la convalidación de actuaciones de acuerdo con lo dispuesto en el artículo 52.", "No debe acordar la convalidación de actuaciones de acuerdo con lo dispuesto en el artículo 52.", "Puede acordar la convalidación de actuaciones de acuerdo con lo dispuesto en el artículo 52.", "Puede retrotraer el procedimiento y debe acordar la convalidación de actuaciones de acuerdo con lo dispuesto en el artículo 52."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 49, "Según el art. 119.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el órgano que resuelva un recurso administrativo:", "Decidirá cuantas cuestiones, tanto de forma como de fondo, plantee el procedimiento, siempre que hayan sido alegadas por los interesados.", "Podrá decidir sobre las cuestiones de forma y fondo que plantee el procedimiento que hayan sido alegadas por los interesados.", "Decidirá cuantas cuestiones, tanto de forma como de fondo, plantee el procedimiento, hayan sido o no alegadas por los interesados.", "Solo podrá decidir sobre las cuestiones fondo que plantee el procedimiento aunque no hayan sido alegadas por los interesados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 50, "Según el art. 120.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, cuando deban resolverse una pluralidad de recursos administrativos que traigan causa de un mismo acto administrativo y se hubiera interpuesto un recurso judicial contra una resolución administrativa:", "El órgano administrativo podrá acordar la suspensión del plazo para resolver hasta que recaiga pronunciamiento judicial, a petición de los interesados.", "El órgano administrativo debe acordar la suspensión del plazo para resolver hasta que recaiga sentencia firme.", "El órgano administrativo debe acordar la suspensión del plazo para resolver hasta que recaiga pronunciamiento judicial.", "El órgano administrativo podrá acordar la suspensión del plazo para resolver hasta que recaiga pronunciamiento judicial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 51, "Indique cuál de las siguientes afirmaciones es correcta según el art. 121.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Los actos administrativos que pongan fin a la vía administrativa deberán ser recurridos en alzada como requisito previo para impugnarlos ante la jurisdicción contenciosa administrativa.", "Contra los actos firmes en vía administrativa se podrá interponer un recurso de alzada ante el superior jerárquico del órgano que dictó el acto.", "El recurso de alzada podrá interponerse ante el órgano que dictó el acto que se impugna o ante el competente para resolverlo.", "Contra la resolución de un recurso de alzada se podrá interponer un recurso de reposición."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 52, "Indique cuál de las siguientes afirmaciones es correcta según el art. 122 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "El plazo para interponer un recurso de reposición contra los actos expresos es de un mes y el plazo para resolver el recurso es de tres meses.", "El plazo para interponer un recurso de alzada contra los actos expresos es de un mes y el plazo para resolver el recurso es de un mes.", "El plazo para interponer un recurso de reposición contra los actos expresos es de tres meses y el plazo para resolver el recurso es de un mes.", "El plazo para interponer un recurso de alzada contra los actos expresos es de un mes y el plazo para resolver el recurso es de tres meses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 53, "Según el art. 122.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el plazo para la interposición del recurso de alzada:", "Será de un mes, si el acto fuera expreso. Transcurrido dicho plazo sin haberse interpuesto el recurso, la resolución será firme a todos los efectos.", "Será de tres meses, si el acto fuera expreso. Transcurrido dicho plazo sin haberse interpuesto el recurso, la resolución será firme a todos los efectos.", "Será de un mes, si el acto fuera expreso. Transcurrido dicho plazo sin haberse interpuesto el recurso, la resolución agotará la vía administrativa a todos los efectos.", "Será de tres meses, si el acto fuera expreso. Transcurrido dicho plazo sin haberse interpuesto el recurso, la resolución agotará la vía administrativa a todos los efectos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 54, "Según el art. 122.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el recurso de alzada:", "Debe interponerse en el plazo de tres meses, si el acto fuera expreso.", "Puede interponerse contra las resoluciones y actos a que se refiere el artículo 112.1, cuando pongan fin a la vía administrativa.", "Debe resolverse en el plazo de un mes, si el acto fuera expreso, y de tres meses, si el acto fuera tácito.", "Debe resolverse y notificarse en el plazo de tres meses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 55, "Indique cuál de las siguientes afirmaciones es correcta según el art. 123.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Los actos administrativos que pongan fin a la vía administrativa deben ser recurridos en reposición ante el mismo órgano que los haya dictado.", "Los actos firmes pueden ser impugnados directamente ante el orden jurisdiccional contencioso-administrativo.", "El plazo máximo para dictar y notificar la resolución del recurso de reposición será de tres meses.", "No se podrá interponer recurso contencioso-administrativo hasta que sea resuelto expresamente o se haya producido la desestimación presunta del recurso de reposición interpuesto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 56, "Según el art. 124.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, si el acto no fuera expreso, el solicitante y otros posibles interesados podrán interponer recurso de reposición:", "En cualquier momento a partir del día siguiente a aquel en que, de acuerdo con su normativa específica, se produzca el acto presunto.", "En el plazo de seis meses a partir del día siguiente a aquel en que, de acuerdo con su normativa específica, se produzca el acto presunto.", "En cualquier momento a partir del día siguiente a aquel en que hayan transcurrido tres meses desde que se inició el procedimiento.", "En el plazo de un mes a partir del día siguiente a aquel en que, de acuerdo con su normativa específica, se produzca el acto presunto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 57, "Indique cuál de las siguientes afirmaciones es correcta según el art. 124.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Si el acto no fuera expreso, el interesado podrá interponer un recurso de reposición en el plazo de seis meses.", "El plazo máximo para dictar la resolución del recurso de reposición será de tres meses.", "El plazo para la interposición del recurso de reposición será de un mes, si el acto fuera expreso.", "Si el acto no fuera expreso, el interesado deberá interponer recurso de reposición para agotar la vía administrativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 58, "Indique cuál de las siguientes afirmaciones es correcta según el art. 124.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "El plazo para la interposición del recurso de reposición será de un mes, si el acto fuera expreso, y de tres meses, si fuera presunto.", "Contra la desestimación presunta de un recurso de reposición se podrá interponer un nuevo recurso de reposición en el plazo de tres meses.", "El recurso de reposición podrá interponerse ante el órgano que dictó el acto que se impugna o ante la jurisdicción contencioso administrativa.", "El plazo máximo para dictar y notificar la resolución del recurso de reposición será de un mes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 59, "Según el art. 125.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el recurso extraordinario de revisión:", "Puede interponerse ante el órgano administrativo que dictó el acto, que también será el competente para su resolución.", "Puede interponerse ante el órgano que dictó el acto o ante su superior jerárquico, que será el competente para su resolución.", "Puede interponerse ante el superior jerárquico del órgano que dictó el acto, que será el competente para su resolución.", "Debe interponerse ante el órgano administrativo que dictó el acto, que lo remitirá al superior jerárquico junto con un informe."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 60, "Indique cuál de las siguientes afirmaciones es correcta según el art. 126.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "El plazo para la interposición del recurso extraordinario de revisión será de tres meses, si el acto fuera expreso.", "Cuando la resolución se hubiese dictado como consecuencia de prevaricación, cohecho, violencia, maquinación fraudulenta u otra conducta punible, el plazo para la interposición del recurso extraordinario de revisión será de tres meses a contar desde la notificación de la sentencia.", "Transcurrido el plazo de tres meses desde la interposición del recurso extraordinario de revisión sin haberse dictado y notificado la resolución, se entenderá desestimado.", "Cuando aparezcan documentos de valor esencial para la resolución del asunto que, aunque sean posteriores, evidencien el error de la resolución recurrida, el plazo para la interposición del recurso extraordinario de revisión será de cuatro años a contar desde la notificación de la resolución impugnada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 61, "De acuerdo con el art. 42 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, adoptan la forma de acuerdo:", "Los actos dictados por los órganos colegiados, por el Gobierno y por las comisiones delegadas.", "Los actos dictados por el presidente, por los órganos colegiados, por el Gobierno y por las comisiones delegadas.", "Los actos dictados por el presidente y por los órganos colegiados.", "Los actos dictados por el presidente, por el vicepresidente, por el Gobierno y por las comisiones delegadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 62, "Según el art. 53.1 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, agotan la vía administrativa:", "Los acuerdos de las comisiones delegadas del Gobierno y las resoluciones de los consejeros, salvo que una ley establezca lo contrario.", "Los actos dictados por el presidente, por el Consejo de Gobierno y por los órganos directivos de las Consejerías.", "Los acuerdos de las comisiones delegadas del Gobierno y las resoluciones dictadas por los órganos directivos de las Consejerías.", "Los acuerdos de las comisiones delegadas del Gobierno y del Consejo de Gobierno, y las resoluciones dictadas por el presidente, los consejeros y los órganos directivos de las Consejerías."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 63, "Según el art. 53.2 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, en los entes que integran la administración instrumental agotan la vía administrativa:", "Los actos emanados de los órganos de dirección unipersonales o colegiados.", "Los actos emanados de los órganos de dirección unipersonales o colegiados, si así lo prevén sus estatutos o la norma de creación.", "Los actos emanados de los órganos de dirección unipersonales o colegiados y del personal directivo profesional.", "Los actos emanados de los órganos de dirección unipersonales o colegiados y del personal directivo profesional, si así lo prevén sus estatutos o la norma de creación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 64, "Según el art. 58.1 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, son susceptibles de recurso de alzada:", "Los actos de los órganos de la Administración de la comunidad autónoma que no agoten la vía administrativa.", "Los actos de los órganos de la Administración de la comunidad autónoma que no agoten la vía administrativa, así como los actos de trámite en los casos previstos en la normativa básica de procedimiento administrativo.", "Los actos de los órganos de la Administración de la comunidad autónoma que agoten la vía administrativa.", "Los actos de los órganos de la Administración de la comunidad autónoma que agoten la vía administrativa, así como los actos de trámite en los casos previstos en la normativa básica de procedimiento administrativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 65, "Según el art. 58.2 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, se entiende que el consejero es el órgano superior jerárquico:", "De los órganos unipersonales adscritos a la consejería.", "De los órganos directivos adscritos a la consejería.", "De los órganos y unidades administrativos que no dispongan de otro superior jerárquico.", "De los órganos directivos y de los órganos de dirección de los entes del sector público instrumental adscritos a la consejería."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 66, "Según el art. 58.3 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, se podrá interponer recurso de alzada ante el Consejo de Gobierno en relación a los actos dictados por:", "Las comisiones delegadas o por los consejeros.", "Las comisiones delegadas o por los consejeros, cuando una ley prevea que estos actos no agotan la vía administrativa.", "El presidente, las comisiones delegadas o por los consejeros.", "El presidente, las comisiones delegadas o por los consejeros, cuando una ley prevea que estos actos no agotan la vía administrativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 13, 67, "Según el art. 58.4 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, los actos y las resoluciones de los órganos superiores de dirección de los entes que integran la administración instrumental de la comunidad autónoma, serán objeto de recurso de alzada:", "Ante el consejero titular de la consejería a la cual se hallen adscritos, siempre y cuando agoten la vía administrativa.", "Ante el consejero titular de la consejería a la cual se hallen adscritos, siempre y cuando no agoten la vía administrativa.", "Ante el Consejo de Dirección del ente, siempre y cuando agoten la vía administrativa.", "Ante el Consejo de Dirección del ente, siempre y cuando no agoten la vía administrativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 1, "De acuerdo con el art. 10 de la Constitución española, las normas relativas a los derechos fundamentales y a las libertades que la Constitución reconoce se interpretarán en conformidad :", "Con la Declaración Universal de los Derechos Humanos.", "Con la normativa europea.", "Con los tratados y los acuerdos internacionales sobre estas materias ratificados por España.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 2, "De acuerdo con el artículo 11 de la Constitución española, la nacionalidad española se adquiere, se conserva y se pierde:", "De acuerdo con los tratados internacionales sobre nacionalidades y migración.", "De acuerdo con lo que la Ley establece.", "De acuerdo con la normativa civil.", "De acuerdo con las conexiones sociales o vínculos familiares que el individuo tenga con otros españoles nativos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 3, "Según el artículo 168 de la Constitución española, ¿cuándo se requiere la disolución inmediata de las Cortes Generales después de la aprobación de una reforma constitucional?", "Cuando la reforma afecta al título preliminar.", "Cuando la reforma afecta al título III.", "Cuando la reforma afecta al título VIII.", "Cuando la reforma afecta al título X."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 4, "¿En qué título de la Constitución española se establece la mayoría de edad  de lo españoles?", "En el título preliminar.", "En el título I.", "En el título III.", "En el título IV."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 5, "Según el artículo 14 de la Constitución española, los españoles son iguales ante la ley, sin que pueda prevalecer discriminación alguna:", "Por razón de nacimiento, raza, religión, sexo o cualquier otra condición o circunstancia personal.", "Por razón de nacimiento, sexo, raza, opinión, religión o cualquier otra condición o circunstancia personal o social.", "Por razón de nacimiento, sexo, opinión o cualquier otra condición o circunstancia social.", "Por razón de religión, raza, nacimiento o cualquier otra condición personal y social."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 6, "Según el artículo 168 de la Constitución española, aprobada una reforma total de la Constitución por las Cortes Generales, ¿qué se requiere para su ratificación?", "La sanción y promulgación del rey.", "La publicación en el Boletín Oficial del Estado.", "Un referéndum.", "Las respuestas a) i b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 7, "Según el artículo 16 de la Constitución española, en cuanto a la obligación a declarar sobre la propia ideología, religión o creencias:", "Será obligatorio cuando el Estado mayor lo considere necesario.", "Será obligatorio declarar cuando aquella información se considere de vital importancia ante un peligro para el Estado.", "Nadie podrá ser obligado a declarar en cuanto a su ideología, religión o creencias.", "Sólo los extranjeros podrán ser obligados a declarar en tiempo den guerra."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 8, "Según el artículo 16 de la Constitución española, la confesión oficial del Estado español es:", "La religión católica.", "La religión cristiana.", "Aquella confesión que sea mayoritaria entre las creencias de la sociedad española.", "Ninguna confesión tendrá carácter estatal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 9, "Según el artículo 17 de la Constitución española, toda persona detenida tiene derecho:", "A ser informada inmediatamente de sus derechos y de las razones de la detención.", "A no ser obligada a declarar", "A la asistencia de abogado.", "Las respuestas a) b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 10, "Según el artículo 18 de la Constitución española, se garantiza el derecho:", "Al honor.", "A la propiedad privada.", "A la intimidad personal y familiar y a la propia imagen.", "=Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 11, "Según el artículo 18 de la Constitución española, el domicilio es inviolable. No se podrá entrar ni hacer ningún registro sin el consentimiento del titular o:", "O sin resolución judicial, salvo en caso de flagrante delito.", "O sin resolución policial, salvo en el caso de flagrante delito.", "Sin una orden de registro, salvo en el caso de posesión de armas.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 12, "Según el artículo 18 de la Constitución española, se garantiza el secreto de las comunicaciones y, especialmente, de las postales, telegráficas y telefónicas, excepto en caso de:", "En caso de declaración del estado de excepción.", "En caso de resolución militar en tiempo de guerra.", "En caso de resolución judicial.", "En caso de interés general del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 13, "Según el artículo 18 de la Constitución española, la ley limitará el uso de la informática por tal de garantizar:", "El honor de los ciudadanos españoles.", "El honor y la intimidad personal de los ciudadanos y el respeto de sus libertades.", "La intimidad personal de los ciudadanos y sus derechos fundamentales.", "El honor y la intimidad personal y familiar de los ciudadanos y el pleno ejercicio de sus derechos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 14, "Según el artículo 19 de la Constitución española, los españoles tienen derecho a entrar y salir libremente de España en la forma que la ley establezca. Este derecho no podrá ser limitado por motivos:", "Económicos o políticos.", "Militares, políticos o sociales.", "Políticos o ideológicos.", "Políticos o militares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 15, "¿Cuál de los siguientes derechos NO se reconoce y protege en el artículo 20 de la Constitución española?", "A expresar y difundir libremente los pensamientos, las ideas y las opiniones mediante la palabra, la escritura o cualquier otro medio de reproducción.", "A la producción y a la creación literaria, artística, científica y técnica.", "A la libertad de cátedra.", "A la libertad de enseñanza de la lengua oficial propia de las comunidades autónomas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 16, "Según el artículo 20 de la Constitución española, la ley regulará la organización y el control parlamentario de los medios de comunicación social que dependan del Estado o de cualquier entidad pública y garantizará el acceso a estos medios de los grupos sociales y políticos significativos, respetando:", "El pluralismo político y de las diferentes lenguas de España.", "El pluralismo de la sociedad y de las diferentes lenguas de España.", "El pluralismo ideológico, racial y de las diferentes confesiones religiosas de España.", "El pluralismo social, de las diferentes ideologías políticas y creencias religiosas de España."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 17, "De acuerdo al artículo 20 de la Constitución española, sólo podrá acordarse el secuestro de publicaciones, grabaciones y otros medios de información:", "En virtud de resolución judicial.", "En virtud de resolución policial.", "En virtud de sentencia por flagrante delito.", "En virtud del interés general."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 18, "Según el artículo 21 de la Constitución española, ¿se reconoce el derecho de reunión pacífica y sin armas?", "Sí, pero para su ejercicio hará falta autorización previa.", "No, la posesión de armas no se nombra en el artículo.", "Sí, y para su ejercicio no hará falta autorización previa.", "No, el derecho de reunión pacífica no se nombra en este artículo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 19, "De acuerdo con el artículo 21 de la Constitución española, en los casos de reuniones en lugares de tránsito público y de manifestaciones, hará falta comunicarlo previamente a la autoridad, la cual sólo podrá prohibirlas cuando:", "En ningún caso se puede prohibir una manifestación porque es un derecho fundamental.", "Se considere un peligro para el orden público, por impacto social o político.", "No respeten los valores o principios fundamentales superiores constitucionales.", "Haya motivos fundamentados de alteración del orden público, con peligro para personas o bienes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 20, "De acuerdo con el artículo 22 de la Constitución española, se reconoce el derecho de asociación. Las actividades de las asociaciones sólo podrán ser disueltas o suspendidas:", "En virtud de una resolución policial.", "En virtud de una resolución judicial motivada.", "En virtud de una sentencia del Tribunal Supremo.", "En virtud de una sentencia del Tribunal Superior de Justicia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 21, "Según el artículo 22 de la Constitución española, se prohíben las asociaciones:", "Secretas y las de carácter paramilitar.", "De carácter político pero antidemocráticas.", "Secretas y las de carácter fascista.", "Secretas, antidemocráticas y las de carácter sectario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 22, "Según el artículo 23 de la Constitución española, los ciudadanos tienen el derecho a participar en los asuntos públicos:", "Mediante votación asamblearia local o electoral a nivel nacional.", "Directamente.", "Por medio de representantes libremente elegidos en elecciones periódicas por sufragio universal.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 23, "De acuerdo con el artículo 23 de la Constitución española, los ciudadanos tienen el derecho de acceder a las funciones y a los cargos públicos:", "Según se indique en una ley orgánica.", "En condiciones de igualdad y con los requisitos que las leyes señalen.", "De acuerdo con la normativa sobre incompatibilidad.", "Siempre y cuando cumplan con los requisitos que indica la ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 24, "Según el artículo 24 de la Constitución española, todo el mundo tiene derecho a obtener la tutela efectiva de los jueces y de los tribunales en el ejercicio de sus derechos e intereses legítimos:", "Sin que el individuo haya de pagar por ningún servicio jurídico.", "Sin que el individuo haya de defenderse sin ninguna ayuda.", "Sin que pueda haber indefensión.", "Sin que esto influya en el tratamiento de los jueces hacia el individuo o en la decisión final de los tribunales en un juicio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 25, "De acuerdo con el artículo 25 de la Constitución española, las penas privativas de libertad y las medidas de seguridad están orientadas:", "A la reeducación.", "Al castigo.", "A la reinserción social.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 26, "Según el artículo 26 de la Constitución española, se prohíben los tribunales de honor en el ámbito de:", "En el ámbito de la Administración civil.", "En el ámbito de la Administración pública y las organizaciones privadas.", "En el ámbito de las organizaciones profesionales.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 27, "De acuerdo con el artículo 30 de la Constitución española , para los españoles la defensa de España:", "Solo es un deber.", "No es obligatoria.", "Es un derecho y un deber.", "Solo es un derecho."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 28, "Según el artículo 28 de  la Constitución española, la huelga forma parte:", "Del derecho a la libertad de expresión y manifestación.", "Del derecho del trabajo.", "De los derechos fundamentales y de las libertades públicas.", "Del derecho a la libertad sindical."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 29, "Según el artículo 27 de la Constitución española, la educación tendrá como objeto el pleno desarrollo de la personalidad humana en el respeto:", "A los principios democráticos de convivencia y a los derechos y a las libertades fundamentales.", "A los principios democráticos y a los derechos humanos.", "A los derechos fundamentales de la Constitución y a los derechos humanos y de la infancia reconocidos en los tratados internacionales.", "A los principios constitucionales de convivencia y a los derechos fundamentales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 30, "Según el artículo 28 de la Constitución española, la obligatoriedad de afiliación a un Sindicato de los trabajadores es posible:", "Cuando lo acuerda la mayoría de los trabajadores.", "En ningún caso.", "Cuando así venga dispuesto por razón del trabajo que se realice.", "Cuando así se imponga en el convenio laboral."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 31, "De acuerdo con el artículo 27 de la Constitución española, los poderes garantizan el derecho que asiste a los padres por tal de que los hijos reciban:", "Una formación basada en el respeto a los principios democráticos y a la libertad religiosa.", "La formación religiosa i moral que concuerde con la confesión estatal.", "Una educación en concordancia con la orientación ideológica y religiosa de los padres.", "La formación religiosa y moral que vaya de acuerdo con sus convicciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 32, "Según el artículo 27 de la Constitución española, dentro del respeto a los principios constitucionales, se reconoce la libertad de creación de centros docentes:", "A las personas civiles.", "A los ciudadanos con los requisitos indicados por la ley.", "A Las personas jurídicas.", "A las personas físicas y jurídicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 33, "Según el artículo 28 de la Constitución española, dentro de la libertad sindical los sindicatos tienen derecho:", "A formar confederaciones.", "A fundar organizaciones sindicales internacionales.", "A afiliarse en organizaciones sindicales internacionales.", "Las respuestas a) b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 34, "Según el artículo 27 de la Constitución española, los poderes públicos inspeccionarán y homologarán el sistema educativo por tal de garantizar:", "El cumplimiento y respeto de los derechos de los estudiantes.", "La obtención de buenos resultados en el nivel cultural general de los estudiantes.", "El cumplimiento de las leyes.", "El cumplimiento de la normativa del ministerio competente en materia de Educación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 35, "De acuerdo con el artículo 27 de la Constitución española, en materia de Educación, la enseñanza básica es:", "Gratuita.", "Obligatoria.", "Voluntaria y gratuita.", "Obligatoria y gratuita."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 36, "Según el artículo 27 de la Constitución española, se reconoce la autonomía de las universidades:", "En la forma que la ley establezca.", "En la forma que los estatutos de autonomía establezcan.", "En la forma que los tratados internacionales de educación europea establezcan.", "En la forma que la Constitución establezca."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 37, "Según el artículo 28 de la Constitución española, todo el mundo tiene derecho a sindicarse. Pero la ley podrá limitar o exceptuar el ejercicio de este derecho a:", "A la policía.", "A las fuerzas armadas.", "A las fuerzas o los institutos armados o a los otros cuerpos sometidos a disciplina militar.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 38, "Según el artículo 28 de la Constitución española, se reconoce a los trabajadores el derecho a la huelga para la defensa de sus intereses. La ley que regule el ejercicio de este derecho establecerá las garantías que hagan falta:", "Por tal de asegurar el mantenimiento de los puestos de trabajo de aquellos que ejerzan este derecho.", "Por tal de asegurar el mantenimiento de los servicios esenciales de la comunidad.", "Por tal de asegurar la escucha activa de las demandas de la huelga por parte del Gobierno.", "Por tal de asegurar la protección de los trabajadores que ejerzan este derecho."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 39, "Según el artículo 29 de la Constitución española, los miembros de las fuerzas o institutos armados o de los cuerpos sometidos a disciplina militar podrán ejercer el derecho de petición:", "Sólo colectivamente.", "Colectivamente y de acuerdo con aquello que dispone su legislación específica.", "Colectiva o individualmente.", "Sólo individualmente y de acuerdo con aquello que dispone su legislación específica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 40, "De acuerdo con el artículo 32 de la Constitución española, ¿cuál de los siguientes elementos sobre el matrimonio NO se especifica que regulará la ley?", "La edad y la capacidad para contraerlo.", "Los derechos y deberes de los cónyuges.", "La separación de bienes.", "Las causas de separación y disolución y sus efectos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 41, "Según el artículo 33 de la Constitución española, nadie podrá ser privado de sus bienes ni de sus derechos sino:", "Por razón de Estado.", "Por causa declarada de interés general.", "Por causa motivada en tiempo de guerra.", "Por causa justificada de utilidad pública o de interés social."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 42, "De acuerdo con el artículo 34 de la Constitución española, se reconoce el derecho de fundación para finalidades de:", "De interés general.", "De interés social.", "De utilidad pública.", "De interés privado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 43, "Según el artículo 35 de la Constitución española sobre el deber y el derecho a trabajar, ¿qué tipo de discriminación no puede ocurrir en ningún caso a la hora de obtener una remuneración suficiente para satisfacer las necesidades del trabajador y su familia?", "Por razón de género.", "Por razón de edad.", "Por razón de sexo.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 44, "Según el artículo 36 de la Constitución española, la estructura interna y funcionamiento de los colegios profesionales habrán de ser:", "Piramidales.", "Meritocráticos.", "Democráticos.", "Jerárquicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 45, "De acuerdo con el artículo 159 de la Constitución española, ¿cuántos miembros propone el Consejo General del Poder Judicial para formar el Tribunal Constitucional?", "Dos", "Tres", "Cuatro", "Cinco"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 46, "De acuerdo con el artículo 38 de la Constitución española, se reconoce la libertad de empresa:", "Dentro del marco de la economía general.", "Dentro del marco de la economía de mercado.", "Dentro del marco de la economía pública.", "Dentro del marco de la economía privada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 47, "De acuerdo con el artículo 159 de la Constitución española, ¿cuántos miembros propone el Senado para formar el Tribunal Constitucional?", "Dos", "Tres", "Cuatro", "Cinco"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 48, "¿Cuáles son los valores superiores de nuestro Ordenamiento Jurídico conforme al artículo 1 de la  Constitución española?", "La libertad, la justicia, la igualdad y el pluralismo político.", "La libertad, la justicia y la igualdad.", "La democracia y el pluralismo político.", "El principio de legalidad y la independencia judicial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 49, "Según el artículo 39 de la Constitución española, los padres han de prestar asistencia completa a los hijos:", "Tenidos dentro del matrimonio y durante la minoría de edad.", "Tenidos dentro o fuera del matrimonio y en los otros casos en que los tribunales les obliguen.", "Tenidos dentro o fuera del matrimonio, durante la minoría de edad y en los otros casos en que la ley les obligue.", "Durante la minoría y mayoría de edad, siempre que sean dependientes económica y jurídicamente y en los otros casos en que la ley les obligue."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 50, "Según el artículo 53 de la Constitución española, ¿ qué tipo de recurso ante el Tribunal Constitucional pueden interponer los ciudadanos para la tutela de todos los derechos y libertades reconocidos en la sección 1ª del capítulo II del título I?", "Recurso de amparo.", "Recurso de apelación.", "Recurso de inconstitucionalidad.", "Recurso contencioso-Administrativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 51, "De acuerdo con el artículo 54 de la Constitución española, ¿qué institución es la encargada de defender los derechos comprendidos en el título I?", "Los Tribunales de Justicia.", "El Defensor del Pueblo.", "El Ministerio Fiscal.", "El Fiscal General del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 52, "De acuerdo con el artículo 40 de la Constitución española, los poderes públicos velarán por la seguridad y la higiene en el trabajo y garantizarán el descanso necesario:", "Mediante períodos de vacaciones mínimos.", "Mediante jornadas laborales limitadas y la promoción de centros adecuados.", "Mediante la buena distribución del volumen de trabajo y vacaciones periódicas.", "Mediante la limitación de la jornada laboral, las vacaciones periódicas retribuidas y la promoción de centros adecuados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 53, "De conformidad con el artículo 1 de la Constitución de 1978, España se constituye:", "En una soberanía constitucional.", "En una soberanía nacional.", "En un estado liberal de derecho.", "En un estado social y democrático de derecho."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 54, "Según el artículo 169 de la Constitución española , podrá iniciarse una reforma constitucional:", "En cualquier momento sin limitación alguna.", "Salvo en tiempo de guerra.", "Salvo vigencia de los estados de alarma, de excepción y de sitio.", "Salvo en tiempo de guerra y de vigencia de los estados de alarma, de excepción y de sitio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 55, "De acuerdo con el artículo 159 de la Constitución española, ¿cuántos miembros propone el Congreso de los Diputados para formar el Tribunal Constitucional?", "Dos", "Tres", "Cuatro", "Cinco"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 56, "Según el artículo 41 de la Constitución española, los poderes públicos mantendrán un régimen público de Seguridad Social para todos los ciudadanos que garantice la asistencia y las prestaciones sociales suficientes en las situaciones de necesidad, especialmente:", "En caso de problemas de salud infantil.", "En caso de accidentes laborales.", "En caso de falta de trabajo.", "En caso de dependencia por discapacidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 57, "Según el artículo 159 de la Constitución española, los miembros del el Tribunal Constitucional tendrán que ser nombrados:", "Entre juristas de prestigio.", "Entre juristas de competencia reconocida con más de quince años de ejercicio profesional.", "Entre juristas de competencia reconocida con más de diez años de ejercicio profesional.", "Entre juristas de competencia y experiencia reconocida en Tribunales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 58, "Según el artículo 159 de la Constitución española, el Tribunal Constitucional se compone:", "De diez miembros nombrados por el Congreso.", "De doce miembros nombrados por el rey.", "De ocho miembros nombrados por las Cortes Generales.", "De nueve miembros nombrados por el Senado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 59, "De acuerdo con el título I de la Constitución española, los derechos y deberes fundamentales:", "Son absolutos i irrenunciables.", "Pueden ser limitados solo por ley orgánica.", "Tienen su límite en el derecho de los demás y en otros bienes y derechos constitucionalmente protegidos.", "Son personales e intransferibles."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 60, "Según el artículo 159 de la Constitución española, el período de designación de los miembros del Tribunal Constitucional tendrá una duración:", "De diez años.", "De ocho años.", "De doce años.", "De nueve años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 61, "Según el artículo 10 de la Constitución española, la dignidad de la persona, los derechos inviolables que le son inherentes, el libre desarrollo de la personalidad, el respeto a la ley y a los derechos de los demás son fundamento:", "Del orden político.", "De la paz social.", "De la estabilidad nacional y la comunión social.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 62, "Según el artículo 11 de la Constitución española, el Estado podrá concertar tratados de doble nacionalidad con:", "Con los países iberoamericanos.", "Con aquellos países que hayan tenido o tengan una vinculación particular con España.", "Con aquellos países que hayan tenido una vinculación histórica o económica con España.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 63, "Según el artículo 13 de la Constitución española, los extranjeros disfrutarán en España de las libertades públicas que garantiza el título I en los términos:", "Que establezca la ley.", "Que establezcan los tratados internacionales.", "Que disponga el Gobierno español.", "Que establezcan los tratados y la ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 64, "De acuerdo con el artículo 11 de la Constitución española, un español de origen podrá ser privado de su nacionalidad en caso de:", "En caso de cometer un delito flagrante.", "En caso de terrorismo.", "En caso de ser desterrado por traición a la nación española.", "En ningún caso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 65, "Según el artículo 15 de la Constitución española, todo el mundo tiene derecho a la vida y, por lo tanto, la pena de muerte:", "Queda abolida en todos los casos.", "Está reservada sólo para los crímenes más graves según estipule el código penal.", "Queda abolida, salvo aquello que dispongan las leyes penales militares para tiempos de guerra.", "Ha de ser aprobada por el Tribunal Supremo, únicamente para tiempos de guerra."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 66, "De acuerdo con el artículo 16 de la Constitución española, se garantiza la libertad ideológica, religiosa y de culto de los individuos y de las comunidades sin ninguna más limitación, cuando sean manifestados:", "Que la necesaria para el mantenimiento del orden público protegido por la ley.", "Que la que sea indicada por la ley.", "Que la prohibición de predicación pública con el fin del proselitismo religioso.", "Ninguna limitación en ningún caso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 1, 67, "Según el artículo 17, la detención preventiva no podrá durar más tiempo del que sea estrictamente necesario para hacer las indagaciones para aclarar los hechos y, en cualquier caso el detenido tendrá que ser puesto en libertad o a disposición de la autoridad judicial dentro del plazo máximo:", "De setenta horas.", "De setenta y dos horas.", "De setenta y ocho horas.", "De setenta y cinco horas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 1, "Los reglamentos son disposiciones normativas:", "De carácter general.", "De rango inferior a la ley.", "Que emanan del poder ejecutivo en virtud de su potestad reglamentaria.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 2, "¿Qué característica comparten las leyes y los reglamentos?", "Que ambas son normas jurídicas.", "Que ambas emanan de la voluntad popular.", "Que ambas emanan del ejecutivo.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 3, "Señala la respuesta correcta en relación con el reglamento:", "Los decretos legislativos son reglamentos.", "El reglamento es controlable por el poder judicial.", "El reglamento puede dejar sin efecto una ley o contradecirla.", "El reglamento puede suplir a la ley en los casos recogidos en la Constitución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 4, "Indica cuál de las siguientes respuestas es la incorrecta en relación con los reglamentos:", "El control de las normas reglamentarias dictadas por la Administración de la Comunidad Autónoma de las Illes Balears corresponde a la jurisdicción contenciosa administrativa.", "La entrada en vigor de los reglamentos aprobados por el Gobierno de la Nación requiere su publicación íntegra en el Boletín Oficial del Estado.", "De acuerdo con la Ley 1/2019, de 31 de enero, de Gobierno de las Illes Balears, en casos de urgencia y de forma excepcional, la entrada en vigor de determinados reglamentos aprobados por el Consejo de Gobierno requiere únicamente su publicación en extracto en el Boletín Oficial de las Illes Balears.", "Los reglamentos dictados por las entidades locales han de publicarse en el boletín oficial que corresponda."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 5, "Señala la respuesta incorrecta. Tradicionalmente, los reglamentos se clasifican:", "Por el sujeto del cual proceden: estatales, autonómicos y locales.", "Por sus efectos: jurídicos y normativos.", "Por su relación con la ley: ejecutivos, independientes y de necesidad.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 6, "Los reglamentos pueden definirse:", "Como cualquier disposición jurídica de carácter singular dictada por la Administración pública y subordinada a la ley.", "Como cualquier disposición jurídica dictada por el Gobierno y la Administración en virtud de la delegación normativa efectuada a su favor por las Cortes Generales.", "Como cualquier disposición jurídica de carácter general dictada por el Gobierno y la Administración pública, subordinada a la ley.", "Como cualquier disposición administrativa dictada en el seno de un procedimiento, con efectos erga omnes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 7, "Los reglamentos independientes se caracterizan por ser:", "Los que regulan materias sobre las que la Constitución ha previsto expresamente una reserva reglamentaria.", "Los que regulan materias en las que no se ha producido una previa regulación por ley y que no están protegidas por reserva material de ley.", "Los que regulan materias sobre las que la Constitución ha previsto expresamente una reserva reglamentaria, así como aquellos que regulan materias en las que no se ha producido una previa regulación por ley y que no están protegidas por reserva material de ley.", "En España no puede haber reglamentos independientes, dado que la Constitución no ha previsto expresamente una reserva reglamentaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 8, "Los reglamentos ejecutivos son:", "Los que regulan materias en las que no se ha producido una previa regulación por ley y que no están protegidas por reserva material de ley.", "Los que desarrollan y complementan una ley.", "Los que dicta la Administración para hacer frente a riesgos extraordinarios, suspendiendo la vigencia de las leyes a las cuales contradicen mientras dure la situación de emergencia.", "Los que regulan materias sobre las que la Constitución española ha previsto una reserva reglamentaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 9, "De acuerdo con las clasificaciones doctrinales clásicas de los reglamentos, ¿cómo se denomina el reglamento que se dicta sin una habilitación o remisión específica de una ley?", "Reglamento ejecutivo.", "Reglamento independiente.", "Reglamento de necesidad.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 10, "Señala la respuesta incorrecta en relación con el reglamento de necesidad:", "El reglamento de necesidad implica la suspensión de la legalidad establecida.", "El reglamento de necesidad tiene carácter transitorio en el ordenamiento jurídico.", "El reglamento de necesidad sólo se puede dictar por razón de la concurrencia de circunstancias extraordinarias.", "El reglamento de necesidad tiene carácter de permanencia en el ordenamiento jurídico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 11, "Señala la respuesta correcta:", "El reglamento independiente no puede abordar ni entrar a regular ningún ámbito normativo externo a la Administración.", "El reglamento de necesidad tiene una extensión temporal ilimitada y precisa de una norma posterior que lo derogue.", "El reglamento independiente necesita de habilitación normativa.", "El reglamento ejecutivo se denomina también reglamento praeter legem."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 12, "Las órdenes de funciones de los puestos de trabajo dictadas por los consejeros y consejeras son reglamentos:", "De necesidad.", "Independientes.", "Ejecutivos.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 13, "El Reglamento del Parlamento de las Illes Balears:", "No está subordinado a la ley, sino que está al mismo nivel de la ley.", "No es susceptible de recurso contencioso administrativo.", "A pesar de su denominación, no tiene naturaleza de disposición reglamentaria.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 14, "Se entiende por potestad reglamentaria:", "La facultad del Gobierno y de la Administración de crear normas jurídicas, incluidas las de carácter singular.", "La facultad del Gobierno y de la Administración de dictar disposiciones administrativas.", "La facultad del Gobierno y de la Administración de crear de normas jurídicas de carácter general, sometidas a la Constitución y a la ley.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 15, "De acuerdo con el artículo 97 de la Constitución Española:", "El Gobierno ejerce la potestad reglamentaria de acuerdo con la Constitución y los estatutos de autonomía.", "El Gobierno ejerce la potestad reglamentaria de acuerdo con la Constitución, los estatutos de autonomía y el resto de leyes.", "El Gobierno ejerce la potestad reglamentaria de acuerdo con la Constitución y las leyes.", "El Gobierno ejerce la potestad reglamentaria con carácter exclusivo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 16, "A quien corresponde el ejercicio de la potestad reglamentaria de acuerdo con lo dispuesto en el artículo 128 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas?", "Al Gobierno de la nación y a los órganos de gobierno de las comunidades autónomas.", "Al Gobierno de la nación, a los órganos de gobierno de las comunidades autónomas y a los órganos de gobierno locales.", "Al Gobierno de la nación.", "Al Gobierno de la nación, a los órganos de gobierno de las comunidades autónomas, a los órganos de gobierno locales y a las entidades del sector público institucional."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 17, "El Estatuto de autonomía de las Illes Balears atribuye potestad reglamentaria:", "Al Gobierno de la Comunidad Autónoma, de acuerdo con el artículo 57.", "A los consejeros.", "A los Consejos Insulares, de acuerdo con el artículo 58.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 18, "En cuanto a la potestad reglamentaria de las entidades locales:", "La Constitución no prevé ninguna referencia a la potestad reglamentaria de la Administración local, a pesar de que se entiende implícita en el artículo 122, al reconocerle autonomía para la gestión de sus intereses.", "La potestad reglamentaria de los entes locales en el ámbito de la comunidad autónoma de las Illes Balears está recogida en el artículo 106 de la Ley 20/2006, de 15 de diciembre, municipal y de régimen local de las Illes Balears.", "La Ley 7/1985, de 2 de abril, reguladora de las bases del régimen local, atribuye a los municipios la potestad reglamentaria y de autoorganización.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 19, "¿A qué se refiere el Tribunal Supremo en su sentencia de 17 de febrero de 1998, cuando dice que la ley, por sí misma, es insuficiente para regular la convivencia de la sociedad y la gestión de los intereses de la comunidad?", "Al fundamento de la función ejecutiva.", "Al fundamento de la potestad reglamentaria.", "Al fundamento de la Administración pública.", "Al fundamento de la función organizativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 20, "¿Qué se entiende por inderogabilidad singular de los reglamentos?", "Que las resoluciones administrativas de carácter particular pueden vulnerar los reglamentos cuando procedan de un órgano de igual o superior jerarquía al que dictó la disposición general.", "Que las resoluciones administrativas de carácter particular pueden vulnerar los reglamentos únicamente cuando procedan del Gobierno en casos de extraordinaria y urgente necesidad.", "Que las resoluciones administrativas de carácter particular no pueden vulnerar las disposiciones reglamentarias a pesar de que aquéllas procedan de un órgano de igual o superior jerarquía al que dictó la disposición general.", "Que la vulneración de una disposición de alcance general por una de carácter particular requiere acuerdo del Consejo de Ministros o del Consejo de Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 21, "¿Cuál de estas afirmaciones es la incorrecta?", "Existen materias que no pueden ser reguladas por normas reglamentarias.", "Un reglamento puede derogar una ley, siempre que no sea orgánica.", "Toda norma con rango de ley tiene fuerza derogatoria sobre cualquier reglamento.", "El reglamento es una norma general y abstracta, sin que se pueda referir a un sujeto concreto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 22, "Al hablar de los límites formales de los reglamentos, se puede afirmar:", "Que el reglamento sólo está sujeto a la Constitución y a las leyes orgánicas por el principio de jerarquía.", "Que las relaciones entre la ley y el reglamento son de competencia y no de jerarquía.", "Que el reglamento está jerárquicamente subordinado a la Constitución y a la ley, de acuerdo con el artículo 97 de la Constitución y el artículo 128 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas.", "Que no hay jerarquía normativa entre reglamentos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 23, "Señala la respuesta correcta relativa al principio de jerarquía:", "El principio de jerarquía sirve para establecer reglas de resolución de conflictos entre leyes y reglamentos de un mismo subordenamiento jurídico.", "El principio de jerarquía sirve para establecer reglas de resolución de conflictos entre reglamentos de un mismo subordenamiento jurídico.", "Sólo la Constitución se impone jerárquicamente a cualquier norma, del rango que sea y de cualquier subordenamiento al que pertenezca.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 24, "¿En qué artículo de la Ley 1/2019, de 31 de enero, de Gobierno de las Illes Balears, se recoge el orden jerárquico entre los reglamentos?", "En el artículo 30.", "En el artículo 40.", "En el artículo 48.", "En el artículo 50."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 25, "¿Los principios generales del derecho operan como límite material de los reglamentos?", "Solamente los principios recogidos en el artículo 103 de la Constitución.", "Sí.", "No; los límites materiales de los reglamentos son la Constitución, los estatutos de autonomía y las normas con rango de ley.", "Sólo opera como límite el principio de no arbitrariedad de los poderes públicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 26, "Indica cuál de las siguientes materias puede regularse o establecerse mediante reglamento:", "Prestaciones patrimoniales de carácter público.", "Exacciones parafiscales.", "Infracciones administrativas.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 27, "Un reglamento que vulnere otro reglamento de rango superior:", "Puede ser convalidado.", "Es anulable.", "Es nulo de pleno derecho.", "Es nulo de pleno derecho; no obstante, el plazo para declarar la nulidad o impugnarlo es de un año, de acuerdo con lo que prevé la Ley 39/2017, de 30 de octubre, del procedimiento administrativo común de las administraciones públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 28, "Indica cuál de las respuestas es la correcta:", "El reglamento que infringe la ley se considera en todo caso anulable.", "El reglamento que infringe la ley se considera en todo caso nulo de pleno derecho.", "El reglamento que infringe la ley se considera en todo caso validable.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 29, "La aplicación del régimen de nulidad absoluta o de pleno derecho como única causa de invalidez de los reglamentos implica:", "Que se puede declarar en cualquier momento, a instancia de parte o incluso de oficio por la propia Administración o por parte de los tribunales.", "Que requiere de la petición de las personas inmediatamente afectadas por la norma reglamentaria.", "Que el consentimiento de los afectados es intrascendente.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 30, "¿Qué deben hacer jueces y magistrados ante un reglamento ilegal?", "Aplicarlo hasta que el Tribunal Constitucional declare su nulidad.", "No aplicarlo, ateniéndose a la obligación establecida en la Ley Orgánica del Poder Judicial de no aplicar los reglamentos o cualquiera otra disposición contrarios a la Constitución, a la ley o al principio de jerarquía normativa.", "Puede no aplicarlo, dada la independencia del poder judicial.", "No aplicarlo siempre que lo haya alegado la parte recurrente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 31, "¿Qué debe hacer un funcionario ante un reglamento ilegal?", "Aplicarlo hasta que el Tribunal Constitucional declare su nulidad.", "No aplicarlo, dado que los funcionarios están sujetos a la Constitución y a la ley.", "Aplicarlo si así lo impone una instrucción o una orden de servicio.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 32, "Las instrucciones dictadas por los órganos de la Administración:", "Han de ser publicadas.", "Vinculan directamente a los particulares.", "Su naturaleza jurídica es de acto administrativo.", "Pueden interpretar las leyes o los reglamentos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 33, "¿Es posible que un reglamento congele una materia, de tal manera que no pueda ser regulada posteriormente por una ley?", "Sí, en el caso de una materia reservada al reglamento.", "Si, cuando una norma con fuerza de ley así lo permita.", "No, porque los reglamentos sólo pueden desarrollar y complementar aquello que establecen las leyes.", "No, porque en nuestro derecho no existe el principio de reserva reglamentaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 34, "De acuerdo con el artículo 131 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, los reglamentos:", "Deben publicarse en el diario oficial que corresponda para que entren en vigor y produzcan efectos jurídicos.", "Sin perjuicio de que entren en vigor y produzcan efectos jurídicos desde el momento de su aprobación, pueden publicarse en el diario oficial que corresponda cuando se estime conveniente por razón de los destinatarios o de los efectos que puedan producirse.", "Únicamente pueden publicarse en el diario oficial correspondiente cuando una disposición específica así lo establezca.", "Sólo deben publicarse si se dictan en desarrollo de una ley y ésta así lo haya previsto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 35, "¿Se puede exceptuar mediante una resolución administrativa, a un contribuyente X concreto, de la aplicación de determinados preceptos del Real decreto 1624/1992, de 29 de diciembre, por el cual se aprueba el Reglamento del impuesto sobre el valor añadido (IVA), para fomentar la inversión extranjera?", "Sí, por razones de interés general.", "No, porque lo impide el principio de inderogabilidad singular de los reglamentos, establecido en el artículo 37 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común.", "Si, porque el reglamento del IVA y la resolución de carácter particular tienen el mismo rango jerárquico.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 36, "En relación con el procedimiento de elaboración de los reglamentos, la Constitución dispone:", "Que la ley regula la audiencia de los ciudadanos, exclusivamente de manera indirecta a través de las organizaciones y asociaciones reconocidas por la ley, en el procedimiento de elaboración de las disposiciones administrativas que los afecten.", "Que la ley regula la audiencia de los ciudadanos, necesariamente de forma directa, y nunca a través de las organizaciones y asociaciones reconocidas por la ley, en el procedimiento de elaboración de las disposiciones administrativas que los afecten.", "La Constitución no contiene ninguna previsión en relación con la audiencia a los ciudadanos en el procedimiento de elaboración de las disposiciones administrativas.", "Que la Ley regula la audiencia de los ciudadanos, directamente o a través de las organizaciones y asociaciones reconocidas por la ley en el procedimiento de elaboración de las disposiciones administrativas que los afecten."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 37, "¿En qué casos la Administración puede revisar de oficio las disposiciones administrativas nulas?", "En los supuestos previstos en las letras a, c, y f  del artículo 47.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas.", "En los supuestos previstos en el artículo 47.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas.", "Sólo en el supuesto de que declaren la irretroactividad de disposiciones sancionadoras no favorables.", "La Administración sólo puede revisar de oficio los actos nulos de pleno derecho, no los reglamentos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 38, "Ante un reglamento ilegal, la Administración:", "Puede derogarlo, mediante la aprobación de un nuevo reglamento.", "Puede revisarlo de oficio, previo dictamen del Consejo Consultivo.", "Puede revisarlo de oficio, con audiencia previa e información pública.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 39, "La declaración de nulidad de un reglamento mediante revisión de oficio produce efectos:", "Ex tunc, sólo para los ciudadanos que hayan denunciado la ilegalidad del reglamento.", "Ex nunc.", "Ex tunc.", "Ex nunc, sólo para los ciudadanos que hayan denunciado la ilegalidad del reglamento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 40, "¿Qué norma es la que permite a los juzgados y tribunales del orden contencioso administrativo controlar la legalidad de las disposiciones generales de rango inferior a la ley?", "La Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las Administraciones públicas.", "Para cada comunidad autónoma, el estatuto de autonomía respectivo.", "La Ley 29/1998, de 13 de julio, reguladora de la jurisdicción contenciosa administrativa.", "La Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 41, "¿Qué plazo establece la Ley 29/1998, de 13 de julio, reguladora de la jurisdicción contenciosa administrativa para la interposición de un recurso directo contra una disposición general?", "Tres meses computables desde el día siguiente al de la publicación de la disposición impugnada.", "Dos meses computables desde el día siguiente al de la publicación de la disposición impugnada.", "Los ciudadanos no pueden interponer un recurso directo contra un reglamento.", "Un mes computable desde el día siguiente al de la publicación de la disposición impugnada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 42, "Si ha transcurrido el plazo para impugnar un reglamento que consideras contrario a derecho, ¿qué puedes hacer?", "Nada, porque el reglamento ya es firme, por lo que sólo puede anularlo el Tribunal Constitucional.", "Puede impugnarse a través de un recurso indirecto contra un acto administrativo que aplique este reglamento ilegal.", "Sólo puede interponer una querella penal contra la autoridad que lo aprobó.", "Puede instarse a un órgano administrativo que interponga un recurso directo, porque un particular no puede ir contra una norma reglamentaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 43, "De acuerdo con la Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción contenciosa administrativa, ¿puede un recurso indirecto contra un reglamento ilegal dar lugar a su anulación?", "No, sólo a su inaplicación.", "Sí, lo anulará el órgano judicial que conozca del recurso indirecto si es competente también para conocer del recurso directo contra el reglamento; si no lo es, tendrá que plantear la cuestión de ilegalidad.", "Sí, lo anulará el órgano judicial que conozca del recurso indirecto sea o no competente también para conocer del recurso directo contra el reglamento.", "Sí, pero el órgano judicial que conozca del recurso indirecto nunca puede anularlo, sino que habrá necesariamente de plantear la cuestión de ilegalidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 44, "De acuerdo con la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, los reglamentos pueden establecer infracciones administrativas?", "Sí, en todo caso.", "Sí, siempre que se traten de faltas leves.", "Sí, siempre que se traten de faltas leves y las sanciones no superen los 100  de multa.", "No, sin perjuicio de su función de desarrollo o colaboración respecto de la ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 45, "¿Cuáles son los motivos para que la Gobierno del Estado impugne un reglamento de una comunidad autónoma ante el Tribunal Constitucional?", "Los reglamentos no pueden impugnarse ante el Tribunal Constitucional, sólo ante la jurisdicción contenciosa administrativa.", "Pueden impugnarse tanto por infracciones de índole competencial como también sustantivas o de contenido material.", "Sólo por infracciones de derechos constitucionales.", "Sólo puede hacerlo con autorización previa de las Cortes Generales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 46, "Los reales decretos son:", "Una manifestación de la potestad reglamentaria del Gobierno.", "Una norma con rango de ley del Gobierno que requiere autorización de las Cortes Generales.", "Una norma con rango de ley del Gobierno que se dicta en supuestos de urgente necesidad.", "Una disposición administrativa de carácter general emanada de un ministerio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 47, "De acuerdo con la Ley 1/2019, de 31 de enero, del Gobierno de las Illes Balears, ¿en qué casos los consejeros pueden dictar disposiciones reglamentarias?:", "Los consejeros no pueden dictar disposiciones reglamentarias.", "Sólo en las materias propias de sus departamentos.", "Sólo en las materias propias de sus departamentos cuando las disposiciones tengan por objeto regular la organización y el funcionamiento de los servicios de la consejería o cuando lo autorice una ley o un decreto del Gobierno, y de acuerdo con la legislación básica.", "Sólo en las materias propias de sus departamentos cuando las disposiciones tengan por objeto regular la organización y el funcionamiento de los servicios de la consejería o cuando lo autorice una ley o un decreto del Gobierno, y de acuerdo con la legislación ordinaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 48, "¿En cuál de los siguientes casos el presidente de la Comunidad Autónoma de las Illes Balears puede dictar disposiciones reglamentarias?", "El presidente no puede dictar disposiciones reglamentarias.", "Sólo para crear consejerías.", "Sólo para modificar la denominación de las consejerías.", "Para determinar el régimen de suplencias de los consejeros y de la Secretaría del Consejo de Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 49, "En cuanto a la forma de las disposiciones reglamentarias, la Ley 1/2019, de 31 de enero, del Gobierno de las Illes Balears, establece:", "Que las disposiciones reglamentarias adoptan la forma de decreto si son aprobadas por el Consejo de Gobierno; de acuerdo si las aprueba el presidente y de orden, en el supuesto de que sea el consejero quién las apruebe.", "Que las disposiciones reglamentarias adoptan la forma de decreto si son aprobadas por el Gobierno o por el presidente, y de resolución si las aprueba el consejero.", "Que las disposiciones reglamentarias adoptan la forma de decreto si son aprobadas por el Gobierno o por los consejeros y de orden si las aprueba la presidenta.", "Que las disposiciones reglamentarias adoptan la forma de decreto si son aprobadas por el Gobierno o por el presidente, y de orden si son aprobadas por los consejeros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 50, "Las disposiciones reglamentarias se encabezan:", "Con una exposición de motivos, que exprese la finalidad de las medidas adoptadas en la regulación y el marco normativo en que se inserta.", "Con un preámbulo, que exprese la finalidad de las medidas adoptadas en la regulación y el marco normativo en que se inserta.", "Con una exposición motivada, que exprese la finalidad de las medidas adoptadas en la regulación y el marco normativo en que se inserta.", "Con unos antecedentes, que expresen la finalidad de las medidas adoptadas en la regulación y el marco normativo en que se inserta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 51, "De acuerdo con la Ley 1/2019, de 31 de enero, del Gobierno de las Illes Balears, señala el orden jerárquico correcto:", "Primero los decretos aprobados por el Consejo de Gobierno y segundo las órdenes de los consejeros.", "Primero los decretos de los consejeros y segundo las resoluciones de los consejeros.", "Primero los decretos aprobados por el Consejo de Gobierno o por el presidente y segundo las órdenes de los consejeros.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 52, "¿Cuáles han de ser los principios de actuación del Gobierno de las Illes Balears cuando ejerce la potestad reglamentaria?", "Necesidad, eficacia, proporcionalidad, seguridad jurídica, transparencia, calidad y simplificación.", "Necesidad, eficacia, proporcionalidad, seguridad jurídica, transparencia, eficiencia, y simplificación.", "Necesidad, eficacia, proporcionalidad, seguridad jurídica, transparencia, eficiencia, calidad y simplificación.", "Necesidad, eficacia, proporcionalidad, seguridad jurídica, transparencia, eficiencia y simplificación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 53, "La Ley 1/2019, de 31 de enero, del Gobierno de las Illes Balears, dispone que los expedientes de elaboración de reglamentos organizativos han de incluir la resolución de inicio, los informes preceptivos previstos legalmente y, en su caso, el informe relativo al gasto que genere:", "Sólo en el caso de las dictadas por el Gobierno.", "Sólo en el caso de las dictadas por el Gobierno o por los consejeros.", "En todos los casos.", "Sólo en el caso de las dictadas por el presidente o por los consejeros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 54, "¿Quién firma las órdenes que afectan a más de una consejería?", "El consejero competente en la materia que tiene preponderancia.", "Los consejeros competentes en la materia.", "El presidente de Gobierno de las Illes Balears", "El consejero encargado de la Secretaría del Consejo de Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 55, "¿Cuáles son los procedimientos que la Ley 1/2019, de 31 de enero, del Gobierno de las Illes Balears, establece para la elaboración normativa de los reglamentos?", "Procedimiento ordinario y procedimiento simplificado.", "Procedimiento ordinario y procedimiento de urgencia.", "Procedimiento ordinario, procedimiento de urgencia y procedimiento abreviado.", "Procedimiento ordinario, procedimiento de urgencia y procedimiento simplificado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 56, "De acuerdo con la Ley 1/2019, de 31 de enero, del Gobierno de las Illes Balears, el procedimiento simplificado para la elaboración normativa de los reglamentos sólo se aplica:", "En casos de urgente necesidad.", "Para la elaboración de textos consolidados de reglamentos.", "Para la elaboración de textos consolidados siempre que no incluyan la armonización, la aclaración o la regulación de los reglamentos que se consolidan.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 57, "Indica la respuesta incorrecta. De acuerdo con la Ley 1/2019, de 31 de enero, del Gobierno de las Illes Balears, con carácter previo a la elaboración de un proyecto de reglamento, ha de sustanciarse una consulta pública a través del sitio web con el fin  de que la ciudadanía tenga la posibilidad de emitir su opinión. No obstante, la Ley indica algunos supuestos en que la consulta previa no es necesaria:", "No es necesaria la consulta pública cuando se trata de la aprobación de normas reglamentarias de carácter presupuestario.", "No es necesaria la consulta pública cuando concurran razones graves de interés público que lo justifiquen.", "No es necesaria la consulta pública en casos de tramitación urgente del procedimiento normativo.", "No es necesaria la consulta pública cuando las normas tengan incidencia jurídica relevante."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 58, "¿Indica en cuál de los siguientes casos es preceptivo el dictamen del Consejo Consultivo en la tramitación de un proyecto de disposición reglamentaria?", "Siempre.", "En el caso de un reglamento de carácter organizativo.", "En el caso de una orden de un consejero por la que se aprueban las bases reguladoras de subvenciones.", "En el caso de un decreto que afecte a los derechos de los ciudadanos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 59, "Señala la respuesta incorrecta. De acuerdo con la Ley 1/2019, de 31 de enero, del Gobierno de las Illes Balears, en la tramitación de un proyecto de disposición reglamentaria hay que elaborar un estudio sobre las cargas administrativas que comporta la propuesta:", "Sólo ha de elaborarse en los procedimientos que se tramitan de forma ordinaria.", "El estudio ha de incluirse en la memoria de impacto normativo.", "Ha de elaborarse previamente a la resolución del consejero por la que se inicia el procedimiento.", "Sólo se elabora si se trata de reglamentos que se dicten en materia presupuestaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 60, "¿Es posible que en la resolución iniciadora de un procedimiento para la elaboración de disposiciones reglamentarias se encomiende la adopción de medidas provisionales?", "No, las medidas excepcionales sólo pueden establecerse en el seno del procedimiento administrativo común que regula la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común.", "No, las medidas excepcionales sólo pueden establecerse en el seno del procedimiento administrativo común que regula la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común, iniciado a instancia del interesado.", "Si, excepcionalmente puede encomendarse al órgano competente por razón de la materia que adopte motivadamente las medidas provisionales que considere adecuadas y necesarias para asegurar la eficacia de la regulación que prevé establecerse.", "Si, excepcionalmente puede encomendarse al órgano competente por razón de la materia que adopte motivadamente las medidas provisionales que considere adecuadas y necesarias para asegurar la eficacia de la regulación que se prevé establecer, sin que sea necesario dar audiencia previa a las personas directamente afectadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 61, "En la tramitación de un proyecto de disposición reglamentaria ha de elaborarse una memoria de análisis de impacto normativo. ¿Cuál de las siguientes características que establece la Ley 1/2019, de 31 de enero, de Gobierno de las Illes Balears, es la correcta?", "Es un documento que se redacta una vez completados los trámites que establecen los apartados 1 y 2 del artículo 59 de la Ley 1/2019, de 31 de enero, del Gobierno de las Illes Balears.", "Es un documento dinámico, que ha de ir actualizándose con la incorporación de los aspectos relevantes resultantes de las diferentes fases de la tramitación.", "Es un documento que ha de incorporar los contenidos siguientes: oportunidad de la propuesta normativa; análisis del impacto económico; análisis y valoración resumida de las alegaciones presentadas en el trámite de audiencia pública y evaluación del cumplimiento de los principios de buena regulación.", "Es un documento que ha de incorporar los contenidos siguientes: oportunidad de la propuesta normativa, análisis del impacto económico y presupuestario, análisis y valoración resumida de las alegaciones presentadas en el trámite de audiencia pública y evaluación del cumplimiento de los principios de buena regulación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 62, "Indica la respuesta incorrecta referida al trámite de audiencia en la elaboración de disposiciones reglamentarias:", "La necesidad del trámite de audiencia deriva del artículo 105 de la Constitución.", "El trámite de audiencia es necesario siempre que la disposición que se pretende aprobar afecte los derechos e intereses legítimos de los ciudadanos.", "El trámite de audiencia puede practicarse por medio de las entidades reconocidas por la ley que agrupen o representen a los interesados.", "El trámite de audiencia sólo está abierto a los ciudadanos que tienen la condición de interesados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 63, "Indica cuál de los siguientes informes tiene carácter preceptivo en la elaboración de una disposición reglamentaria:", "El dictamen del Consejo Económico y Social cuando el anteproyecto de decreto regule de forma directa y estructural materias socioeconómicas, laborales y de ocupación.", "En caso de regular un supuesto en que los efectos del silencio administrativo sean desestimatorios, un informe que motive las razones de interés general que lo justifiquen.", "En caso de que se establezcan limitaciones para el acceso a actividades económicas y servicios, un informe que motive que concurren razones de interés general y que se respetan los principios de necesidad y proporcionalidad, en el marco de lo dispuesto en la legislación autonómica en materia de libre acceso a las actividades de servicios.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 64, "Cuál debe ser el contenido mínimo del informe de evaluación de impacto de género en el procedimiento de elaboración de las disposiciones generales establecido en la Ley 1/2019, de 31 de enero, de Gobierno de las Illes Balears?", "La estimación del impacto potencial del proyecto normativo en la situación de las mujeres y de los hombres como colectivo.", "La estimación del impacto potencial del proyecto normativo en la situación de las mujeres y de los hombres como colectivo y el análisis de las repercusiones positivas o adversas, en materia de igualdad, de la actividad proyectada.", "El análisis de las repercusiones positivas o adversas, en materia de igualdad, de la actividad proyectada.", "La estimación del impacto potencial del proyecto normativo en la situación de las mujeres y de los hombres como colectivo; también el análisis de las repercusiones positivas o adversas, en materia de igualdad, de la actividad proyectada, y las medidas propuestas para eliminar las adversas, en su caso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 65, "Con carácter general, el informe del Consejo Consultivo en la elaboración de disposiciones reglamentarias:", "Es preceptivo y vinculante.", "Es preceptivo y no vinculante.", "Es no preceptivo y vinculante.", "Es no preceptivo y no vinculante."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 66, "Señala la respuesta correcta respecto de la tramitación urgente del procedimiento de elaboración de anteproyectos de disposiciones reglamentarias:", "Puede acordarse cuando sea necesario para que la norma entre en vigor en el plazo exigido para la transposición de directivas comunitarias.", "Puede acordarse cuando sea necesario para que la norma entre en vigor en el plazo exigido por una ley de carácter básico.", "Los plazos de las audiencias y de la información pública se reducen a ocho días.", "La memoria de impacto normativo es potestativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 11, 67, "De acuerdo con el artículo 62 de la Ley 1/2019, de 31 de enero, del Gobierno de las Illes Balears, el procedimiento simplificado de elaboración de textos consolidados de reglamentos debe someterse a los trámites e informes siguientes:", "Informe de la Secretaría General de la consejería correspondiente referido a la adecuación del procedimiento seguido e informe de impacto de género en todo caso.", "Informe de la Secretaría General de la consejería correspondiente referido a la adecuación del procedimiento seguido e informe de impacto de género, en los casos en que de las normas objeto de consolidación no se hubiera emitido este informe en el momento en que se tramitaron.", "Informe de la Secretaría General de la consejería correspondiente referido a la adecuación del procedimiento seguido, informe de impacto de género en el supuesto previsto en el artículo 62 de la Ley 1/2019 y audiencia a las consejerías afectadas, en su caso.", "Informe de la Secretaría General de la consejería correspondiente referido a la adecuación del procedimiento seguido, informe de impacto de género en el supuesto previsto en el artículo 62 de la Ley 1/2019 y memoria del análisis de impacto normativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 1, "Según el art. 165,3 del texto refundido haciendas locales, los derechos liquidados y las obligaciones reconocidas se aplicarán a los presupuestos por su importe:", "Integro", "Correcto", "Exclusivo", "Total"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 2, "Por lo establecido en el art. 165,1 del texto refundido haciendas locales, el presupuesto general de cada entidad local atenderá al cumplimiento del principio de:", "Proporcionalidad", "Estabilidad", "Competitividad", "Universalidad"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 3, "Señala la proposición incorrecta:", "Todo incremento de los créditos presupuestarios o decremento en las previsiones de ingresos deberá ser compensado en el mismo acto en que se acuerda.", "El principio de equilibrio presupuestario o de nivelación significa que los presupuestos deben aprobarse sin déficit inicial.", "La autorización de los gastos se da de una manera global", "El ejercicio presupuestario coincidirá con el año natural."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 4, "¿Las sociedades mercantiles deben presentar la previsión de gastos e ingresos?", "Antes del 15 de octubre de cada año", "Antes del 1 de octubre de cada año", "Antes del 25 de septiembre de cada año", "Antes del 15 de septiembre de cada año"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 5, "¿A que especialidad nos referimos cuando señalamos que no se puede gastar en cuantía superior a la consignación presupuestaria?", "Cualitativa", "Cuantitativa", "Cualificada", "Absoluta"); 
