insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 7, "El presupuesto de cada organismo autónomo será remitido a la entidad local antes del:", "15 de septiembre de cada año", "15 de octubre de cada año", "31 de diciembre de cada año", "15 de noviembre de cada año"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 8, "Según el art. 165,3 del texto refundido haciendas locales, queda prohibido atender obligaciones mediante minoración de los derechos a liquidar o ya ingresados. No obstante se exceptúa de la anterior prohibición:", "Las devoluciones de ingresos que se declaren indebidos por tribunal o autoridad competente", "Las devoluciones de ingresos que se declaren debidos por tribunal o autoridad competente.", "Las devoluciones de ingresos con carácter general", "No hay excepciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 9, "Señala la proposición correcta:", "Las bases de ejecución contendrán las adaptaciones de las disposiciones generales en materia presupuestaria a la organización y circunstancias de la propia entidad", "Las bases de ejecución no tienen que incluirse en todos los presupuestos de las entidades locales.", "Los presupuestos locales constituyen la expresión cifrada, conjunta y sistemática de las obligaciones que, como mínimo puede reconocer la entidad.", "Los presupuestos locales constituyen la expresión cifrada, conjunta y sistemática de las obligaciones que, como máximo puedan reconocer las sociedades mercantiles íntegramente locales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 10, "Cual de las siguientes expresiones es incorrecta en relación a las bases de ejecución del presupuesto:", "Incluirán la relación de créditos que se declaren ampliables.", "En ellas se establecerán las normas que regulen el procedimiento de ejecución del presupuesto.", "En ellas se establecerán los niveles de vinculación jurídica de créditos.", "La bases de cada ejercicio no podrán remitirse a reglamentos o normas de carácter general dictadas por el pleno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 11, "El presupuesto general de cada entidad local contendrá para cada uno de los presupuestos que en él se integran:", "Los estados de gastos y los estados de ingresos.", "Los estados de gastos, los estados de ingresos y las bases de ejecución.", "Los estados de gastos e ingresos y gastos de las sociedades pertenecientes a la entidad local.", "Los estados de gastos e ingresos y gastos de los organismos autonomos pertenecientes a la entidad local."); 
