insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 13, "Según el art. 169,1 del texto refundido haciendas locales, aprobado inicialmente el presupuesto general, se expondrá al público previo anuncio en:", "El BOP o en su caso en el boletín de la comunidad autónoma uniprovincial durante 15 días.", "En el boletín oficial de la comunidad autónoma a la que pertenezca durante 15 días.", "En el BOP y en el boletín oficial de la comunidad autónoma a la que pertenezca durante 15 días.", "Exclusivamente en el boletín de la corporación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 14, "Al presupuesto de la entidad local, según el art 168 del texto refundido haciendas locales, habrá de unirse la siguiente documentación:", "Anexo de personal de la Entidad Local.", "Liquidación del presupuesto del ejercicio anterior y avance de la del corriente, referida, al menos, a nueve meses del mismo.", "Liquidación del presupuesto del ejercicio anterior y avance de la del corriente, referida, al menos, a cinco meses del mismo.", "Liquidación del presupuesto del ejercicio anterior y avance de la del corriente, referida, al menos, a tres meses del mismo"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 15, "En el presupuesto general debe integrarse:", "El presupuesto de la propia Entidad.", "El presupuesto de la propia entidad, los de los organismos autonomos y los de las sociedades mercantiles.", "Es cierta la segunda respuesta, siendo necesario que las sociedades mercantiles, su capital social pertenezca íntegramente a la Entidad Local.", "Es cierta la segunda respuesta, siendo necesario que las sociedades mercantiles, su capital social pertenezca mayoritariamente a la Entidad Local."); 
