insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 17, "Los organismos autónomos de las entidades locales se clasifican a efectos de su régimen presupuestario y contable en:", "Organismos autónomos de carácter administrativo y de carácter comercial, industrial, financiero o análogo.", "Organismos autónomos de carácter administrativo.", "Organismos autónomos de carácter administrativo y entidades  publicas empresariales de carácter comercial, industrial, financiero o análogo.", "Organismos autónomos de carácter comercial, industrial, financiero o análogo."); 
