insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 19, "El presupuesto de la Entidad Local será formado por:", "El Presidente de la corporación.", "El concejal de hacienda.", "El Interventor.", "El Director de los Servicios Económicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 20, "En relación al presupuesto general, definitivamente aprobado, cual de estas frases no es correcta:", "Será insertado en el Boletín oficial de la corporación si lo tuviere", "Será insertado en el Boletín oficial de la Provincia.", "Será insertado, en su caso, en el Boletín oficial de la comunidad autónoma uniprovincial", "Del presupuesto general definitivamente aprobado se remitirá exclusivamente copia a la Administración del Estado."); 
