insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 58, "Las partidas presupuestarias desarrollan, dentro de la clasificación económica de los gastos:", "Las subfunciones.", "Los subconceptos.", "Los programas.", "Los subprogramas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 59, "La gestión del sector público esta sometida al régimen de presupuesto:", "Concreto", "Anual.", "Permanente", "Equilibrado"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 60, "Cuando haya de realizarse algún gasto que no pueda demorarse hasta el ejercicio siguiente y no exista en el presupuesto de la corporación crédito o sea insuficiente, el presidente ordenará la incoación del expediente:", "De concesión de crédito extraordinario.", "De suplemento de crédito.", "De incorporación de remanente.", "De concesión de crédito extraordinario en el primer caso y de suplemento en el segundo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 61, "Señale la respuesta correcta en relación a las transferencias de créditos:", "Incrementarán créditos que como consecuencia e otras transferencias hayan sido objeto de minoración, salvo cuando afecte a créditos de personal.", "No afectarán a los créditos ordinarios concedidos durante el ejercicio.", "No podrán minorarse los créditos que hayan sido incrementados con suplementos o transferencias, salvo cuando afecten a créditos de personal.", "Todas las transferencias serán aprobadas por el presidente.."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 62, "El principio de universalidad aplicado al presupuesto local significa:", "Es un presupuesto general.", "Solo existe un presupuesto.", "Todos los ingresos y gastos han de figurar en el presupuesto.", "Todo lo anterior es correcto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 63, "El presidente rendirá los estados y cuentas de la entidad para la formación de la cuenta general:", "Antes del 1 de mayo.", "Antes del 1 de junio.", "Antes del 15 de mayo.", "Antes del 30 de mayo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 64, "En el supuesto de que un crédito presupuestario fuera insuficiente para atender determinada obligación, la entidad local precisará destinar:", "Un crédito extraordinario.", "Un suplemento de crédito.", "Una incorporación de créditos.", "Cualquiera de los anteriores al prudente arbitrio del presidente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 65, "No suponen una excepción a las limitaciones de las partidas presupuestarias:", "Los suplementos de crédito.", "Los créditos ordinarios.", "Los créditos ampliables.", "Los créditos extraordinarios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 66, "El plazo de exposición al público del presupuesto local, una vez aprobado  inicialmente, será de:", "45 días.", "30 días", "15 días.", "1 mes"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 67, "Unas vez aprobado definitivamente el presupuesto general, debe existir una copia a disposición del público:", "Durante 2 meses.", "Durante 15 días.", "Durante todo el ejercicio.", "Hasta la finalización del ejercicio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 68, "El presupuesto general contendrá para cada uno de los presupuestos que en el se integren:", "Los estados de gastos.", "Los estados de ingresos.", "Son ciertas a y b.", "Los estados de gastos, de ingresos y los excedentes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 69, "El presupuesto de cada uno de los organismos autónomos integrantes del general, será remitido a la entidad local de la que dependan:", "Antes del 15 de julio de cada año.", "Antes del 15 de agosto de cada año.", "Antes del 15 de septiembre de cada año.", "Antes del 15 de octubre de cada año."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 70, "La aprobación de los presupuestos que integran el presupuesto general de una entidad con déficit inicial:", "Obliga a una inmediata compensación.", "Se permite cuando, a lo largo del ejercicio al que se refieran, pueda producirse dicha compensación.", "Está absolutamente prohibida.", "Se admite excepcionalmente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 71, "¿A quien corresponde formar el presupuesto general de la entidad local?", "A pleno de la corporación local.", "Al presidente de la corporación local.", "Al depositario.", "A la junta de gobierno local."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 72, "Una vez emitido el informe del presupuesto por el interventor, el presidente de la entidad local lo remitirá al pleno de la corporación:", "Antes del 15 de septiembre para su aprobación enmienda o devolución.", "Antes del 30 de octubre para su aprobación enmienda o devolución.", "Antes del 15 de noviembre para su aprobación enmienda o devolución.", "Antes del 15 de octubre para su aprobación enmienda o devolución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 73, "La aprobación definitiva del presupuesto general por el pleno de la corporacion, deberá realizarse antes del:", "31 de octubre del año anterior al del ejercicio en que deba aplicarse.", "31 de diciembre del año anterior al del ejercicio en que deba aplicarse.", "30 de diciembre del año anterior al del ejercicio en que deba aplicarse.", "30 de septiembre del año anterior al del ejercicio en que deba aplicarse."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 74, "La modificación del presupuesto de gastos mediante la que, sin alterar la cuantía total del mismo, se imputa el importe total o parcial de un crédito a otras partidas presupuestarias con diferente vinculación jurídica se denomina:", "Habilitación de créditos extraordinarios.", "Transferencias de créditos.", "Generación de créditos por ingresos.", "Incorporación de remanentes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 22, 75, "Las partidas del presupuesto de gastos tienen una limitación:", "Cuantitativa", "Cualitativa", "Especifica", "Cuantitativa y cualitativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 1, "De acuerdo con el artículo 140 de la Constitución española, la Constitución garantiza la autonomía de los municipios, los cuales disfrutarán:", "De personalidad jurídica total.", "De personalidad jurídica propia.", "De derechos y obligaciones establecidos en los estatutos de autonomía.", "De personalidad jurídica plena."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 2, "De acuerdo con el artículo 141 de la Constitución española, cualquier alteración de los límites provinciales habrá de ser aprobada:", "Por el Congreso de los Diputados mediante un real decreto.", "Por las Cortes Generales por medio de una ley orgánica.", "Por el Consejo de Ministros mediante una ley ordinaria.", "Por el Parlamento mediante una ley ordinaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 3, "Según el artículo 143 de la Constitución española, las provincias limítrofes que tengan características históricas, culturales y económicas comunes, los territorios insulares y las provincias de entidad regional histórica podrán acceder:", "Al autogobierno y constituirse en comunidades autónomas.", "A la garantía estatal de manutención y preservación de sus tradiciones.", "A una mancomunidad provincial.", "A un fondo de compensación interterritorial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 4, "De acuerdo con el artículo 146 de la Constitución española, el proyecto de Estatuto de Autonomía será elaborado por una asamblea compuesta:", "Por los miembros de la Diputación o el órgano interinsular de las provincias afectadas.", "Por los diputados y senadores que hayan sido elegidos.", "Por las Cortes Generales.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 5, "Indica cuál de los siguientes elementos que tienen que hacer constar los estatutos de autonomía NO se indica en el artículo 147 de la Constitución española:", "La denominación de la comunidad que mejor se ajuste a su identidad histórica.", "La delimitación del territorio.", "La denominación, la organización y la sede de las instituciones autónomas propias.", "La lengua cooficial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 6, "Según el artículo 147 de la Constitución española, la reforma de los estatutos se ajustará:", "A la normativa europea.", "Al procedimiento que ellos mismos establezcan.", "Al procedimiento establecido en la Constitución.", "A la aprobación del Parlamento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 7, "De acuerdo con el artículo 148 de la Constitución española, indica en cuál de las siguientes materias NO pueden asumir competencias las comunidades autónomas:", "Ordenación del territorio, urbanismo y vivienda.", "La agricultura y la ganadería, de acuerdo con la ordenación general de la economía.", "Hacienda general y deuda del Estado.", "Asistencia social."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 8, "De acuerdo con el artículo 145 de la Constitución española, la federación entre las Comunidades Autónomas:", "No se prevé en la Constitución.", "Requiere ley orgánica y autorización previa por las Cortes Generales.", "Solo puede existir para la prestación de servicios propios de las Comunidades.", "No se admitirá en ningún caso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 9, "Según el artículo 153 de la Constitución española, el control sobre los aspectos económicos y presupuestarios de los órganos de las comunidades autónomas lo ejerce:", "El Tribunal de Cuentas.", "El ministerio competente en materia de economía y hacienda.", "La consejería competente en materia de hacienda de la propia comunidad autónoma.", "La Intervención General del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 10, "Según el artículo 152 de la Constitución española, ¿quién elige al presidente de las comunidades autónomas?", "El Senado.", "El Consejo de Ministros.", "La asamblea legislativa correspondiente.", "El consejo de gobierno autonómico correspondiente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 11, "Indique qué título de la Constitución es el que establece los principios de la organización de las autonomías:", "El título IX.", "El título II.", "El título VIII.", "El título VII."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 12, "Según el artículo 148 de la Constitución española, ¿qué tiempo ha de transcurrir para que las Comunidades Autónomas puedan ampliar sus competencias, mediante la reforma de sus Estatutos de autonomía?", "Dos años.", "Tres años.", "Un año.", "Cinco años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 13, "De acuerdo con el artículo 149 de la Constitución española, ¿qué tipo de competencia tiene el Estado sobre la legislación laboral?", "Competencia compartida con las comunidades autónomas.", "Competencia de desarrollo legislativo.", "Competencia exclusiva.", "Competencia ejecutiva."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 14, "De acuerdo con el artículo 149 de la Constitución española, ¿qué tipo de competencia tiene el Estado sobre el fomento y la coordinación general de la investigación científica y técnica?", "Competencia compartida con las comunidades autónomas.", "Competencia de desarrollo legislativo.", "Competencia exclusiva.", "Competencia ejecutiva."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 15, "De acuerdo con el artículo 150 de la Constitución española, las Cortes Generales, en materias de competencia estatal, podrán atribuir a todas o a algunas de las comunidades autónomas la facultad:", "De modificar, para ellas mismas, normas legislativas dentro del marco de los principios, bases y directrices fijados por una ley estatal.", "De dictar, para ellas mismas, normas legislativas dentro del marco de los principios, bases y directrices fijados por una ley estatal.", "De anular, para ellas mismas, normas legislativas fijadas dentro del marco de los principios, bases y directrices por una ley orgánica.", "De dictar, para ellas mismas y todas las comunidades limítrofes y similares cultural e históricamente, normas legislativas dentro del marco de los principios, bases y directrices fijados por una ley orgánica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 16, "De acuerdo con el artículo 152 de la Constitución española, la organización institucional autonómica se basará:", "En una asamblea legislativa, un consejo de gobierno y un presidente.", "En un consejo de gobierno y su presidente.", "En una asamblea legislativa elegida por sufragio cualificado y un consejo de gobierno.", "En un consejo de gobierno, diputaciones provinciales y ayuntamientos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 17, "De acuerdo con el artículo 153 de la Constitución española, ¿cuál de los siguientes órganos NO ejerce el control de la actividad de los órganos de las comunidades autónomas?", "El Tribunal Constitucional.", "El Gobierno, previo dictamen del Consejo de Estado.", "El Consell General del Poder Judicial.", "El Tribunal de Cuentas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 18, "De acuerdo con el artículo 154 de la Constitución española, ¿quién dirigirá la Administración del Estado en el territorio de la comunidad autónoma?", "El presidente del gobierno autonómico.", "El ministro competente en materia de Interior.", "Un delegado nombrado por el rey.", "Un delegado nombrado por el Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 19, "De acuerdo con el artículo 155 de la Constitución española, en caso de que una comunidad autónoma no cumpla con las obligaciones que la Constitución u otras leyes le impongan, o de actuar de forma que atente gravemente contra el interés general de España, ¿quién podría obligarla al cumplimiento forzoso de sus obligaciones?", "El rey, previa aprobación por mayoría absoluta de las Cortes Generales.", "El Gobierno, previo requerimiento al presidente de la Comunidad autónoma y, en caso de no ser atendido, con la aprobación por mayoría absoluta del Senado.", "El Congreso, previa aprobación por mayoría absoluta.", "El Gobierno, previo único requerimiento de la aprobación por mayoría absoluta del Senado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 20, "Según el artículo 156 de la Constitución española, las comunidades autónomas gozarán de autonomía financiera:", "Para cumplir y ejercer sus competencias de forma libre y plenamente autónoma, sin ningún tipo de restricción.", "Para cumplir con sus competencias y obligaciones, de acuerdo con los principios constitucionales y las indicaciones del Tribunal de Cuentas.", "Para cumplir con sus competencias y funciones de acuerdo con los principios constitucionales y las indicaciones del ministerio competente en materia de hacienda.", "Para cumplir y ejercer sus competencias de acuerdo con los principios de coordinación con la hacienda estatal y de solidaridad entre todos los españoles."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 21, "De acuerdo con el artículo 157 de la Constitución española, ¿cuál de los siguientes elementos NO forma parte de los que constituyen los recursos de las comunidades autónomas?", "Impuestos cedidos total o parcialmente por el Estado.", "Sus propios impuestos, tasas y contribuciones especiales.", "El producto de las operaciones de crédito.", "El producto de las operaciones de débito."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 22, "Según el artículo 158 de la Constitución española, en los presupuestos generales del Estado se podrá establecer una asignación a las comunidades autónomas en función:", "Del volumen de los servicios y de las actividades estatales que hayan asumido y de la garantía de un nivel mínimo en la prestación de los servicios públicos fundamentales en todo el territorio español.", "Del volumen de los servicios que hayan asumido y de la garantía de un nivel mínimo en la prestación de los servicios públicos fundamentales en el territorio de la propia Comunidad autónoma.", "De la amplitud del territorio de la Comunidad y el volumen de actividades y servicios estatales que hayan podido asumir.", "De la amplitud territorial y ciudadana de la Comunidad, su nivel económico y el volumen de servicios estatales que haya asumido."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 23, "De acuerdo con el artículo 158 de la Constitución española, por tal de corregir desequilibrios económicos interterritoriales y hacer efectivo el principio de solidaridad, se constituirá:", "Un fondo nacional destinado a la igualdad entre regiones.", "Un fondo de compensación destinado a gastos de inversión.", "Un tributo especial destinado a la compensación intraregional.", "Un fondo de compensación destinado al bienestar general de las autonomías más pobres."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 24, "De acuerdo con el artículo 153 de la Constitución española, ¿quién ejerce el control de las normas reglamentarias dictadas por las Comunidades Autónomas?", "El Delegado del Gobierno en la Comunidad Autónoma.", "El Tribunal Constitucional.", "La jurisdicción contenciosa-administrativa.", "El parlamento autonómico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 25, "De acuerdo con el artículo 147 de la Constitución española, la delimitación territorial de cada comunidad autónoma es definida:", "En la Constitución Española.", "En una ley especial a tal efecto.", "En su estatuto de autonomía.", "No es precisa su determinación previa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 26, "Según el artículo 152 de la Constitución española, ¿qué tipo de funciones tiene el Consejo de Gobierno autonómico?", "Funciones administrativas y legislativas.", "Funciones ejecutivas y administrativas.", "Funciones legislativas y ejecutivas.", "Funciones ejecutivas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 27, "¿De qué forma se denominan los capítulos del título VIII de la Constitución española?", "De la organización territorial del estado; de la administración local; de las comunidades autónomas.", "Principios generales; de la Administración local; de las comunidades autónomas.", "De la administración; principios generales; de la administración local y de las comunidades autónomas.", "De la organización territorial del estado; de las comunidades autónomas; de la Administración local."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 28, "¿Cómo se denomina el título VIII de la Constitución española?", "De la Administración Local y de las comunidades autónomas.", "De las comunidades autónomas.", "De la organización territorial del Estado.", "De la organización administrativa del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 29, "De acuerdo con el artículo 137 de la Constitución española, ¿cómo se organiza territorialmente el Estado español?", "En entidades locales y autonómicas.", "En municipios, en provincias y en las comunidades autónomas que se constituyan.", "En municipios, mancomunidades, provincias, territorios insulares y comunidades autónomas.", "En municipios, provincias, territorios insulares y en las comunidades autónomas que se constituyan."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 30, "Según el artículo 137 de la Constitución española, ¿cuál de las siguientes entidades gozan de autonomía para la gestión de sus respectivos intereses?", "Las provincias.", "Los municipios.", "Las comunidades autónomas.", "Las respuestas a), b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 31, "De acuerdo con el artículo 138 de la Constitución española, ¿quién garantiza la realización efectiva del principio de solidaridad?", "El Gobierno.", "El Estado.", "Las Cortes Generales.", "EL Senado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 32, "Según el artliculo 138 de la Constitución española, las diferencias entre los Estatutos de las distintas Comunidades Autónomas no podrán implicar:", "Privilegios económicos o sociales, excepto los recogidos en una ley.", "Privilegios fiscales o sociales, en ningún caso.", "Privilegios de ningún tipo, en ningún caso.", "Privilegios económicos o sociales, en ningún caso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 33, "Según el artículo 139 de la Constitución española, ¿quién podrá adoptar medidas que obstaculicen la libertad de circulación y el establecimiento de las personas y la libre circulación de bienes en todo el territorio nacional?", "Las Cortes Generales, en cualquier caso.", "El Gobierno, mediante la correspondiente delegación legislativa.", "Ninguna autoridad podrá adoptar medidas que directa o indirectamente lo obstaculicen.", "Las asambleas legislativas o los órganos colegiados superiores de las distintas comunidades autónomas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 34, "Según el artículo 152 de la Constitución española, ¿qué órgano culmina la organización judicial dentro del ámbito de la comunidad autónoma?", "El Tribunal Superior de Justicia.", "La Audiencia Provincial.", "El Consejo General del Poder Judicial.", "El ministerio fiscal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 35, "Según el artículo 140 de la Constitución española, ¿a quién corresponde el gobierno y la administración de los municipios?", "A sus respectivos ayuntamientos.", "A los vecinos.", "Al alcalde.", "A los regidores de los ayuntamientos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 36, "De acuerdo con el artículo 141 de la Constitución española, ¿cuál de las siguientes entidades locales tiene personalidad jurídica propia?", "La provincia.", "El municipio.", "Las comunidades autónomas.", "Las islas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 37, "Según el artículo 141 de la Constitución española, las provincias son entidades locales determinadas por la agrupación de municipios:", "Y la división territorial para el cumplimiento de las actividades propias.", "Y la división territorial para el cumplimiento de las actividades de las comunidades autónomas en las que se encuentren integradas.", "Y sin división territorial.", "Y la división territorial para el cumplimiento de las actividades del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 38, "¿En qué título de la Constitución española se regula la organización territorial del Estado?", "En el título VI.", "En el  título V.", "En el título VIII.", "En el título VII."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 39, "Según el artículo 148 de la Constitución española, las comunidades autónomas pueden asumir competencias en la materia siguiente:", "Organización de sus instituciones de autogobierno.", "Nacionalidad.", "Relaciones internacionales.", "Legislación sobre pesos y medidas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 40, "Según el artículo 148 de la Constitución española, las comunidades autónomas pueden asumir competencias en la materia siguiente:", "Régimen aduanero y arancelario.", "Ordenación del territorio, urbanismo y vivienda.", "Comercio exterior.", "Derecho de asilo."); 
