insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 60, "Según el artículo 149 de la Constitución española, en materia de relaciones internacionales:", "Es una competencia exclusiva de la comunidad autónoma.", "Es una competencia exclusiva del Estado.", "Es una competencia de desarrollo legislativo y ejecución autonómica.", "Es una competencia compartida del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 61, "Según el artículo 149 de la Constitución española, en materia de las bases del régimen jurídico de las administraciones públicas:", "Es una competencia exclusiva del Estado.", "Es una competencia de desarrollo legislativo y ejecución autonómica.", "Es una competencia exclusiva de la comunidad autónoma.", "Es una competencia compartida del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 62, "Según el artículo 149 de la Constitución española, en materia de comercio exterior:", "Es una competencia exclusiva de la comunidad autónoma.", "Es una competencia compartida del Estado.", "Es una competencia exclusiva del Estado.", "Es una competencia de desarrollo legislativo y ejecución autonómica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 63, "Según el artículo 149 de la Constitución española, ¿a quién corresponderá la competencia sobre las materias que no hayan sido asumidas por los estatutos de autonomía?", "A la comunidad autónoma.", "Al Estado.", "A la comunidad autónoma o al Estado dependiendo de la materia.", "Al Estado, sólo en caso de conflicto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 64, "Según el artículo 157 de la Constitución española, los recursos de las comunidades autónomas serán constituidas, entre otros:", "Por impuestos cedidos parcialmente por el Estado.", "Por el producto de las operaciones de débito.", "Por el producto de las operaciones de crédito.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 65, "Según el artículo 138 de la Constitución española, El Estado garantiza, entre las diversas partes del territorio español, la realización efectiva del principio:", "De autonomía.", "De equilibrio.", "De solidaridad.", "De justicia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 4, 66, "Según el artículo 140 de la Constitución española, los regidores de los ayuntamientos son elegidos:", "Por los vecinos del municipio.", "Por los partidos políticos.", "Mediante sufragio universal, igual, libre, directo y secreto.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 1, "De acuerdo con el artículo 116 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, en el expediente de contratación se justificará adecuadamente:", "La decisión de dividir en lotes el objeto del contrato.", "En los contratos de suministros, el informe de insuficiencia de medios.", "El valor estimado del contrato con exclusión de los costes laborales.", "La clasificación que se exige a los participantes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 2, "Completado el expediente de contratación, de acuerdo con el artículo 117  de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014:", "Se dictará resolución por el órgano de contratación aprobando el mismo y disponiendo la apertura del procedimiento de adjudicación.", "Se dictará resolución por el órgano de contratación aprobando el mismo y disponiendo la apertura del procedimiento de adjudicación y la aprobación del gasto.", "Se dictará resolución motivada por el órgano de contratación aprobando el mismo y disponiendo la apertura del procedimiento de adjudicación, aunque no implicará la aprobación del gasto.", "Se dictará resolución motivada por el órgano de contratación aprobando el mismo y disponiendo la apertura del procedimiento de adjudicación y la aprobación del gasto, salvo en el supuesto excepcional de que el presupuesto no hubiera podido ser establecido previamente, o que las normas de desconcentración o el acto de delegación hubiesen establecido lo contrario, en cuyo caso deberá recabarse la aprobación del órgano competente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 3, "De acuerdo con el artículo 3.1 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014 se considera que no forman parte del sector público las siguientes entidades:", "La Administración General del Estado, las Administraciones de las Comunidades Autónomas, las Ciudades Autónomas de Ceuta y Melilla y las Entidades que integran la Administración Local.", "Las Entidades Gestoras y los Servicios Comunes de la Seguridad Social.", "Los Organismos Autónomos, las Universidades Públicas y las autoridades administrativas independientes.", "Las fundaciones privadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 4, "Serán competencia del orden jurisdiccional contencioso-administrativo las siguientes cuestiones:", "Las cuestiones que se susciten en relación con la extinción de los contratos subvencionados a que se refiere el artículo 23 de la Ley.", "Las relativas a la preparación, la adjudicación, los efectos, la modificación y la extinción de los contratos administrativos.", "Las que se susciten en relación con la preparación y la extinción de los contratos privados de las Administraciones Públicas.", "Las relativas a la preparación y la adjudicación de los contratos de entidades del sector público que tengan el carácter de poderes adjudicadores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 5, "De acuerdo con el artículo 34 de la Ley de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, solo podrán fusionarse prestaciones correspondientes a diferentes contratos en un contrato mixto:", "Cuando las prestaciones se encuentren directamente vinculadas entre sí.", "Cuando las prestaciones mantengan relaciones de complementariedad que exijan su consideración y tratamiento como una unidad funcional dirigida a la satisfacción de una determinada necesidad.", "Cuando las prestaciones mantengan relaciones de complementariedad que exijan su consideración y tratamiento como una unidad funcional dirigida a la consecución de un fin institucional propio de la entidad contratante.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 6, "Señale la respuesta incorrecta. Quedan excluidos del ámbito de aplicación de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014:", "La relación de servicio de los funcionarios públicos y los contratos regulados en la legislación laboral queda excluida del ámbito de la presente Ley.", "Las relaciones jurídicas consistentes en la prestación de un servicio público cuya utilización por los usuarios requiera el abono de una tarifa, tasa o precio público de aplicación general.", "Los contratos relativos a servicios de arbitraje y conciliación.", "En todo caso las autorizaciones y concesiones sobre bienes de dominio público y los contratos de explotación de bienes patrimoniales distintos a los definidos en el artículo 14 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 7, "De acuerdo con el artículo 8 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, no quedan excluidos de la presente Ley siempre que los beneficios pertenezcan exclusivamente al poder adjudicador para su utilización en el ejercicio de su propia actividad y que el servicio prestado sea remunerado íntegramente por el poder adjudicador,  los contratos:", "De servicios de investigación y desarrollo y servicios de consultoría conexos (código CPV 73000000-2).", "De servicios de laboratorio de investigación (código CPV 73111000-3).", "De diseño y ejecución en materia de investigación y desarrollo (código CPV 73300000-5).", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 8, "Se consideran contratos menores:", "Los de valor estimado inferior a 45.000 euros cuando se trate de obras.", "Los de valor estimado inferior a 50.000 euros cuando se trate de obras.", "Los de valor estimado inferior a 18.000 euros cuando se trate de servicios.", "Los de valor estimado inferior a 15.000 euros cuando se trate de servicios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 9, "Los contratos administrativos se califican:", "En contratos de obras, de servicios y de suministros.", "En contratos de obras, de servicios, de suministros y de concesión de obras.", "En contratos de obras, de servicios, de concesión de obras y de concesión de servicios.", "En contratos de obras, de servicios, de suministros, de concesión de obras y de concesión de servicios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 10, "El contrato de mantenimiento de un centro público educativo es un contrato:", "De obras.", "De servicios.", "De suministros.", "De gestión de servicios públicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 11, "De acuerdo con el artículo 34 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, en los contratos del sector público podrán incluirse cualesquiera pactos, cláusulas y condiciones:", "Siempre que no sean contrarios al interés público, al ordenamiento jurídico y a los principios de buena administración.", "Siempre que no sean contrarios al principio de igualdad.", "Siempre que no sean contrarios al principio de proporcionalidad.", "Siempre que no sean contrarios al principio de lealtad institucional."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 12, "De acuerdo con el artículo 19 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, no se consideran sujetos a regulación armonizada, cualquiera que sea su valor estimado, los contratos siguientes:", "Los que tengan por objeto la adquisición, el desarrollo, la producción o la coproducción de programas destinados a servicios de comunicación audiovisual o servicios de comunicación radiofónica, que sean adjudicados por proveedores del servicio de comunicación audiovisual o radiofónica, o los relativos al tiempo de radiodifusión o al suministro de programas que sean adjudicados a proveedores del servicio de comunicación audiovisual o radiofónica.", "Los incluidos dentro del ámbito definido por el artículo 346 del Tratado de Funcionamiento de la Unión Europea que se concluyan en el sector de la defensa.", "Los declarados secretos o reservados.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 13, "De acuerdo con el artículo 37.1 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, las entidades del sector público no podrán contratar verbalmente:", "Nunca.", "Salvo que el contrato tenga, conforme a lo señalado en el artículo 120.1, carácter de emergencia.", "Salvo que el contrato se tramite de forma urgente.", "Salvo que el contrato tenga consecuencias económicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 14, "El plazo para la presentación de las proposiciones en el procedimiento abierto simplificado abreviado previsto en el artículo 159.6  de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014:", "No podrá ser inferior a diez días hábiles, a contar desde el siguiente a la publicación del anuncio de licitación en el perfil de contratante. No obstante, cuando se trate de compras corrientes de bienes disponibles en el mercado el plazo será de 5 días hábiles.", "No podrá ser inferior a diez días naturales, a contar desde el siguiente a la publicación del anuncio de licitación en el perfil de contratante. No obstante, cuando se trate de compras corrientes de bienes disponibles en el mercado el plazo será de 5 días naturales.", "No podrá ser inferior a diez días naturales, a contar desde el siguiente a la publicación del anuncio de licitación en el perfil de contratante. No obstante, cuando se trate de compras corrientes de bienes disponibles en el mercado el plazo será de 5 días hábiles.", "No podrá ser inferior a quince días naturales, a contar desde el siguiente a la publicación del anuncio de licitación en el perfil de contratante. No obstante, cuando se trate de compras corrientes de bienes disponibles en el mercado el plazo será de 5 días hábiles."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 15, "Señale la respuesta incorrecta. De acuerdo con el artículo 29 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, respecto a la prórroga del contrato:", "El contrato podrá prever una o varias prórrogas siempre que sus características permanezcan inalterables durante el período de duración de estas.", "La prórroga se acordará por el órgano de contratación y será obligatoria para el empresario, siempre que su preaviso se produzca al menos con dos meses de antelación a la finalización del plazo de duración del contrato, salvo que en el pliego que rija el contrato se establezca uno mayor.", "La prórroga se acordará por el órgano de contratación y será potestativa para el empresario, siempre que su preaviso se produzca al menos con dos meses de antelación a la finalización del plazo de duración del contrato, salvo que en el pliego que rija el contrato se establezca uno mayor.", "Quedan exceptuados de la obligación de preaviso los contratos cuya duración fuera inferior a dos meses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 16, "De acuerdo con el artículo 36.1 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, los contratos que celebren los poderes adjudicadores, a excepción de los contratos menores y de los contratos basados en un acuerdo marco y los contratos específicos en el marco de un sistema dinámico de adquisición a los que se refiere el apartado 3 de este artículo, se perfeccionan:", "Con su adjudicación.", "Con su aprobación.", "Con su formalización.", "Con su publicación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 17, "Señale la respuesta correcta. Cuando al vencimiento de un contrato no se hubiera formalizado el nuevo contrato que garantice la continuidad de la prestación a realizar por el contratista como consecuencia de incidencias resultantes de acontecimientos imprevisibles para el órgano de contratación producidas en el procedimiento de adjudicación y existan razones de interés público para no interrumpir la prestación:", "Se podrá prorrogar el contrato originario hasta que comience la ejecución del nuevo contrato y en todo caso por un periodo máximo de doce meses, sin modificar las restantes condiciones del contrato, siempre que el anuncio de licitación del nuevo contrato se haya publicado con una antelación mínima de tres meses respecto de la fecha de finalización del contrato originario.", "Se podrá prorrogar el contrato originario hasta que comience la ejecución del nuevo contrato y en todo caso por un periodo máximo de doce meses, sin modificar las restantes condiciones del contrato, aunque el anuncio de licitación del nuevo contrato no se haya publicado.", "Se podrá prorrogar el contrato originario hasta que comience la ejecución del nuevo contrato y en todo caso por un periodo máximo de nueve meses, sin modificar las restantes condiciones del contrato, siempre que el anuncio de licitación del nuevo contrato se haya publicado con una antelación mínima de tres meses respecto de la fecha de finalización del contrato originario.", "Se podrá prorrogar el contrato originario hasta que comience la ejecución del nuevo contrato y en todo caso por un periodo máximo de nueve meses, sin modificar las restantes condiciones del contrato, siempre que el anuncio de licitación del nuevo contrato se haya publicado con una antelación mínima de seis meses respecto de la fecha de finalización del contrato originario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 18, "Señale la respuesta incorrecta. En relación a los encargos de los poderes adjudicadores a medios propios personificados:", "Los poderes adjudicadores podrán organizarse ejecutando de manera directa prestaciones propias de los contratos de obras, suministros, servicios, concesión de obras y concesión de servicios, a cambio de una compensación tarifaria valiéndose de otra persona jurídica distinta a ellos, ya sea de derecho público o de derecho privado, previo encargo a esta siempre y cuando la persona jurídica que utilicen merezca la calificación jurídica de medio propio personificado respecto de ellos.", "El encargo que cumpla dichos requisitos no tendrá la consideración de contrato.", "Uno de los requisitos para tener la consideración de medio propio personificado respecto de una única entidad concreta del sector público que más del 60 por ciento de las actividades del ente destinatario del encargo se lleven a cabo en el ejercicio de los cometidos que le han sido confiados por el poder adjudicador que hace el encargo y que lo controla o por otras personas jurídicas controladas del mismo modo por la entidad que hace el encargo.", "Cuando el ente destinatario del encargo sea un ente de personificación jurídico-privada, además, la totalidad de su capital o patrimonio tendrá que ser de titularidad o aportación pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 19, "De acuerdo con el artículo 39.2 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, serán nulos de pleno derecho los contratos celebrados por poderes adjudicadores en los que concurra alguna de las causas siguientes:", "El incumplimiento grave de normas de derecho de la Unión Europea en materia de contratación pública que conllevara que el contrato no hubiera debido adjudicarse al contratista, declarado por el Tribunal de Justicia de la Unión Europea (TJUE) en un procedimiento con arreglo al artículo 260 del Tratado de Funcionamiento de la Unión Europea.", "La falta de publicación del anuncio de licitación en el perfil de contratante alojado en la Plataforma de Contratación del Sector Público o en los servicios de información similares de las Comunidades Autónomas, en el «Diario Oficial de la Unión Europea» o en el medio de publicidad en que sea preceptivo, de conformidad con el artículo 135.", "La falta de capacidad de obrar o de solvencia económica, financiera, técnica o profesional; o la falta de habilitación empresarial o profesional cuando sea exigible para la realización de la actividad o prestación que constituya el objeto del contrato; o la falta de clasificación, cuando esta proceda, debidamente acreditada, del adjudicatario; o el estar este incurso en alguna de las prohibiciones para contratar señaladas en el artículo 71.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 20, "De acuerdo con el artículo 44.1. de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, serán susceptibles de recurso especial en materia de contratación, los actos y decisiones relacionados en el apartado 2 de este mismo artículo, cuando se refieran a los siguientes contratos que pretendan concertar las Administraciones Públicas o las restantes entidades que ostenten la condición de poderes adjudicadores:", "Contratos de obras cuyo valor estimado sea inferior a tres millones de euros, y de suministro y servicios, que tenga un valor estimado superior a cien mil euros.", "Acuerdos marco y sistemas dinámicos de adquisición que tengan por objeto la celebración de alguno de los contratos tipificados en la letra anterior, pero no los contratos basados en cualquiera de ellos.", "Concesiones de obras o de servicios cuyo valor estimado supere los tres millones de euros.", "Concesiones de servicios cuyo valor estimado supere los tres millones de euros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 21, "De acuerdo con el artículo 49.2 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, antes de interponer el recurso especial en materia de contratación, las personas legitimadas para ello podrán solicitar ante el órgano competente para resolver el recurso la adopción de medidas cautelares. Así, el órgano competente para resolver el recurso especial deberá adoptar decisión en forma motivada sobre las medidas cautelares:", "Dentro de los cinco días hábiles siguientes a la presentación del escrito en que se soliciten.", "Dentro de los diez días hábiles siguientes a la presentación del escrito en que se soliciten.", "Dentro de los siete días hábiles siguientes a la presentación del escrito en que se soliciten.", "Dentro de los tres días hábiles siguientes a la presentación del escrito en que se soliciten."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 22, "Señale la respuesta incorrecta:", "Con independencia de la unidad encargada del seguimiento y la ejecución ordinaria del contrato que figure en los pliegos, los órganos de contratación deberán designar un responsable del contrato al que corresponderá supervisar su ejecución y adoptar las decisiones y dictar las instrucciones necesarias con el fin de asegurar la correcta realización de la prestación pactada, dentro del ámbito de facultades que aquellos le atribuyan.", "En los contratos de obras, las facultades del responsable del contrato serán ejercidas por el director facultativo conforme con lo dispuesto en los artículos 237 a 246 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014.", "El responsable del contrato sólo podrá ser una persona física.", "En los casos de concesiones de obra pública y de concesiones de servicios, la Administración designará una persona que actúe en defensa del interés general, para obtener y para verificar el cumplimiento de las obligaciones del concesionario, especialmente en lo que se refiere a la calidad en la prestación del servicio o de la obra."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 23, "De acuerdo con el artículo 63.3 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, en el caso de la información relativa a los contratos, deberá publicarse en el perfil del contratante al menos la siguiente información:", "La memoria justificativa del contrato, el informe de insuficiencia de medios en el caso de contratos de servicios, la justificación del procedimiento utilizado para su adjudicación cuando se utilice un procedimiento distinto del abierto o del restringido, el pliego de cláusulas administrativas particulares y el de prescripciones técnicas que hayan de regir el contrato o documentos equivalentes, en su caso, y el documento de aprobación del expediente.", "El objeto detallado del contrato, su duración, el presupuesto base de licitación y el importe de adjudicación, incluido el Impuesto sobre el Valor Añadido.", "Los anuncios de información previa, de convocatoria de las licitaciones, de adjudicación y de formalización de los contratos, los anuncios de modificación y su justificación, los anuncios de concursos de proyectos y de resultados de concursos de proyectos, con las excepciones establecidas en las normas de los negociados sin publicidad.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 24, "De acuerdo con el artículo 64.2 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, el concepto de conflicto de intereses abarcará, al menos:", "Cualquier situación en la que el personal al servicio del órgano de contratación, que además participe en el desarrollo del procedimiento de licitación o pueda influir en el resultado del mismo, tenga directa o indirectamente un interés financiero, económico o personal que pudiera parecer que compromete su imparcialidad e independencia en el contexto del procedimiento de licitación.", "Cualquier situación en la que el personal al servicio del órgano de contratación o de otros órganos, que además participe en el desarrollo del procedimiento de licitación o pueda influir en el resultado del mismo, tenga indirectamente un interés financiero que pudiera parecer que compromete su imparcialidad en el contexto del procedimiento de licitación.", "Cualquier hecho en el que el personal que participe en el desarrollo del procedimiento de licitación pueda influir en el resultado del mismo y tenga directamente un interés financiero, económico o personal que pudiera parecer que compromete su imparcialidad e independencia en el contexto del procedimiento de licitación.", "Cualquier hecho en la que el personal al servicio del órgano de contratación, que además participe en el desarrollo del procedimiento de licitación o pueda influir en el resultado del mismo, tenga indirectamente cierto interés financiero, económico o personal aunque no pudiera parecer que compromete su imparcialidad e independencia en el contexto del procedimiento de licitación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 25, "De acuerdo con el artículo 65 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, solo podrán contratar con el sector público:", "Las personas naturales o jurídicas españolas, que tengan plena capacidad de obrar, no estén incursas en alguna prohibición de contratar, y acrediten su solvencia económica y financiera y técnica o profesional o, en los casos en que así lo exija esta Ley, se encuentren debidamente clasificadas.", "Las personas jurídicas, españolas o extranjeras, que tengan plena capacidad de obrar, no estén incursas en alguna prohibición de contratar, y acrediten su solvencia económica y financiera y técnica o profesional o, en los casos en que así lo exija esta Ley, se encuentren debidamente clasificadas.", "Las personas naturales o jurídicas, españolas o extranjeras, que tengan plena capacidad de obrar, no estén incursas en alguna prohibición de contratar, y acrediten su solvencia económica y financiera y técnica o profesional o, en los casos en que así lo exija esta Ley, se encuentren debidamente clasificadas.", "Las personas naturales o jurídicas, españolas o extranjeras, que no tengan plena capacidad de obrar, no estén incursas en alguna prohibición de contratar, y acrediten su solvencia económica y financiera y técnica o profesional o, en los casos en que así lo exija esta Ley, se encuentren debidamente clasificadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 26, "Podrán contratar con el sector público las uniones de empresarios que se constituyan temporalmente al efecto:", "Sin que sea necesaria la formalización de las mismas en escritura pública hasta que se haya efectuado la adjudicación del contrato a su favor.", "Sin que sea necesaria la formalización de las mismas en escritura pública hasta que se haya efectuado la formalización del contrato a su favor.", "Sin que sea necesaria la formalización de las mismas en escritura pública hasta que se haya efectuado la publicación del contrato a su favor.", "Sin que sea necesaria la formalización de las mismas en escritura pública hasta que se haya efectuado la disposición del gasto del contrato a su favor."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 27, "No podrán contratar con las entidades previstas en el artículo 3 con los efectos establecidos en el artículo 73 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, las personas en quienes concurra alguna de las siguientes circunstancias:", "Haber sido condenadas mediante sentencia firme por delitos de terrorismo, constitución o integración de una organización o grupo criminal, asociación ilícita, financiación ilegal de los partidos políticos, trata de seres humanos, corrupción en los negocios, tráfico de influencias, cohecho, fraudes, delitos contra la Hacienda Pública y la Seguridad Social, delitos contra los derechos de los trabajadores, prevaricación, malversación, negociaciones prohibidas a los funcionarios, blanqueo de capitales, delitos relativos a la ordenación del territorio y el urbanismo, la protección del patrimonio histórico y el medio ambiente, o a la pena de inhabilitación especial para el ejercicio de profesión, oficio, industria o comercio.", "Haber retirado indebidamente su proposición o candidatura en un procedimiento de adjudicación, o haber imposibilitado la adjudicación del contrato a su favor por no cumplimentar lo establecido en el apartado 2 del artículo 150 dentro del plazo señalado mediando dolo, culpa o negligencia.", "Haber dejado de formalizar el contrato, que ha sido adjudicado a su favor, en los plazos previstos en el artículo 153 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público por causa imputable al adjudicatario.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 28, "De acuerdo con el artículo 74 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, para celebrar contratos con el sector público los empresarios deberán acreditar:", "Estar en posesión de las condiciones mínimas de solvencia económica y financiera que se determinen por el órgano de contratación. Este requisito será sustituido por el de la clasificación, cuando esta sea exigible conforme a lo dispuesto en esta Ley.", "Estar en posesión de las condiciones mínimas de solvencia económica y financiera y profesional o técnica que se determinen por el órgano de contratación. Este requisito será sustituido por el de la clasificación, cuando esta sea exigible conforme a lo dispuesto en esta Ley.", "Estar en posesión de las condiciones mínimas de solvencia profesional o técnica que se determinen por el órgano de contratación. Este requisito será sustituido por el de la clasificación, cuando esta sea exigible conforme a lo dispuesto en esta Ley.", "Estar en posesión de las condiciones mínimas de solvencia económica y financiera y profesional o técnica que se determinen por el órgano de contratación. Sin que este requisito pueda ser sustituido por el de la clasificación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 29, "De acuerdo con el artículo 77.1 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, la clasificación de los empresarios como contratistas de obras de los poderes adjudicadores será exigible y surtirá efectos para la acreditación de su solvencia para contratar en los siguientes casos y términos:", "Para los contratos de obras cuyo valor estimado sea igual o superior a 500.000 euros.", "Para los contratos de obras cuyo valor estimado sea igual o superior a 1.000.000 euros.", "Para los contratos de obras cuyo presupuesto de licitación sea igual o superior a 500.000 euros.", "Para los contratos de obras cuyo presupuesto de licitación sea igual o superior a 1.000.000 euros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 30, "De acuerdo con el artículo 82.1 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, la clasificación de las empresas en tanto se mantengan por el empresario las condiciones y circunstancias en que se basó su concesión:", "Tendrá una vigencia indefinida.", "Tendrá una vigencia por diez años.", "Tendrá una vigencia por cinco años.", "Tendrá una vigencia por tres años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 31, "Cuando el órgano de contratación proceda a la división en lotes del objeto del contrato, este podrá introducir las siguientes limitaciones, justificándolas debidamente en el expediente:", "Podrá limitar el número de lotes para los que un mismo candidato o licitador puede presentar oferta.", "Podrá limitar el número de lotes que pueden adjudicarse a cada licitador.", "Podrá limitar el número de lotes para los que un mismo candidato o licitador puede presentar oferta, pero no podrá limitar el número de lotes que pueden adjudicarse a cada licitador.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 32, "Señale la respuesta incorrecta. Para el cálculo del valor estimado de los contratos de concesión de obras y de concesión de servicios se tendrán en cuenta, cuando proceda, los siguientes conceptos:", "La renta procedente del pago de tasas y multas por los usuarios de las obras o servicios, distintas de las recaudadas en nombre del poder adjudicador.", "Los pagos o ventajas financieras, cualquiera que sea su forma, concedidos al concesionario por el poder adjudicador o por cualquier otra autoridad pública, incluida la compensación por el cumplimiento de una obligación de servicio público y subvenciones a la inversión pública.", "El valor de los subsidios o ventajas financieras, cualquiera que sea su forma, procedentes de terceros a cambio de la ejecución de la concesión.", "El precio de la compra de cualquier activo que forme parte de la concesión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 33, "Los contratos del sector público tendrán siempre:", "Un precio cierto, que se abonará al contratista en función de la prestación realmente ejecutada y de acuerdo con lo pactado. En el precio no se entenderá incluido el importe a abonar en concepto de Impuesto sobre el Valor Añadido, que en todo caso se indicará como partida independiente.", "Un precio cierto, que se abonará al contratista en función de la prestación realmente ejecutada y de acuerdo con lo pactado. En el precio se entenderá incluido el importe a abonar en concepto de Impuesto sobre el Valor Añadido, que en todo caso se indicará como partida independiente.", "Un precio incierto ya que se abonará al contratista en función de la prestación realmente ejecutada y de acuerdo con lo pactado. En el precio se entenderá incluido el importe a abonar en concepto de Impuesto sobre el Valor Añadido, que en todo caso se indicará como partida independiente.", "Un precio indeterminado, que se abonará al contratista en función de la prestación realmente ejecutada y de acuerdo con lo pactado. En el precio no se entenderá incluido el importe a abonar en concepto de Impuesto sobre el Valor Añadido, que en todo caso se indicará como partida independiente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 34, "Señale la respuesta incorrecta. Respecto a la revisión de precios en los contratos de las entidades del Sector Público, previa justificación en el expediente y de conformidad con lo previsto en el Real Decreto al que se refieren los artículos 4 y 5 de la Ley 2/2015, de 30 de marzo, de desindexación de la economía española, la revisión periódica y predeterminada de precios solo se podrá llevar a cabo:", "En los contratos de obra.", "En los contratos de suministros de fabricación de armamento y equipamiento de las Administraciones Públicas.", "En los contratos de suministro de energía.", "En aquellos contratos en los que el período de recuperación de la inversión sea igual o superior a diez años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 35, "En los casos en que el órgano de contratación haya acordado la exigencia de garantía provisional, en los pliegos de cláusulas administrativas particulares se determinará el importe de la misma:", "Que no podrá ser superior a un 3 por 100 del presupuesto base de licitación del contrato, excluido el Impuesto sobre el Valor Añadido.", "Que no podrá ser superior a un 3 por 100 del presupuesto base de licitación del contrato, incluido el Impuesto sobre el Valor Añadido.", "Que no podrá ser superior a un 5 por 100 del presupuesto base de licitación del contrato, incluido el Impuesto sobre el Valor Añadido.", "Que no podrá ser superior a un 5 por 100 del presupuesto base de licitación del contrato, excluido el Impuesto sobre el Valor Añadido."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 36, "Señale la respuesta incorrecta. El órgano de contratación podrá eximir al adjudicatario de la obligación de constituir garantía definitiva, justificándolo adecuadamente en el pliego de cláusulas administrativas particulares:", "Especialmente en el caso de suministros de bienes consumibles cuya entrega y recepción deba efectuarse antes del pago del precio.", "En los contratos que tengan por objeto la prestación de servicios sociales o la inclusión social o laboral de personas pertenecientes a colectivos en riesgo de exclusión social.", "En los contratos privados de la Administración a los que se refieren los puntos 1.º y 2.º de la letra a) del apartado 1 del artículo 25 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público.", "En el caso de contratos de obras y concesión de obras."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 37, "Cuando el precio del contrato se formule en función de precios unitarios, el importe de la garantía definitiva a constituir se fijará atendiendo:", "Al presupuesto base de licitación, IVA excluido.", "Al presupuesto base de licitación, IVA incluido.", "Al importe de adjudicación, IVA excluido.", "Al importe de adjudicación, IVA incluido."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 38, "Señale la respuesta incorrecta. Las garantías definitivas exigidas en los contratos celebrados con las Administraciones Públicas podrán prestarse en alguna o algunas de las siguientes formas:", "En efectivo o en valores, que en todo caso serán de Deuda Pública.", "Mediante aval.", "Mediante contrato de seguro de caución.", "Mediante retención en el precio aunque no se haya previsto en los pliegos de cláusulas administrativas particulares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 39, "Señale la respuesta incorrecta. En relación a las consultas preliminares del mercado:", "El órgano de contratación hará constar en un informe motivado las actuaciones realizadas. En el informe se relacionarán los estudios realizados y sus autores, las entidades consultadas, las cuestiones que se les han formulado y las respuestas a las mismas. Este informe formará parte del expediente de contratación, y estará sujeto a las mismas obligaciones de publicidad que los pliegos de condiciones, publicándose en todo caso en el perfil del contratante del órgano de contratación.", "En ningún caso durante el proceso de consultas, el órgano de contratación podrá revelar a los participantes en el mismo las soluciones propuestas por los otros participantes, siendo las mismas solo conocidas íntegramente por aquel.", "Con carácter general, el órgano de contratación al elaborar los pliegos deberá tener en cuenta los resultados de las consultas realizadas; de no ser así deberá dejar constancia de los motivos en el informe de las actuaciones realizadas.", "La participación en la consulta impide la posterior intervención en el procedimiento de contratación que en su caso se tramite."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 40, "De acuerdo con el artículo 119 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, en el expediente de contratación calificado de urgente:", "El plazo de inicio de la ejecución del contrato no podrá exceder de quince días, contados desde la formalización.", "El plazo de inicio de la ejecución del contrato no podrá exceder de un mes, contado desde la adjudicación.", "El plazo de inicio de la ejecución del contrato no podrá exceder de un mes, contado desde la formalización.", "El plazo de inicio de la ejecución del contrato no podrá exceder de quince días, contados desde la adjudicación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 41, "Los pliegos de cláusulas administrativas particulares y de prescripciones técnicas particulares:", "Deberán aprobarse con posterioridad a la autorización del gasto o conjuntamente con ella, y siempre con posterioridad a la licitación del contrato.", "Deberán aprobarse previamente a la autorización del gasto o conjuntamente con ella, y siempre antes de la licitación del contrato, o de no existir esta, antes de su adjudicación.", "Deberán aprobarse con posterioridad a la autorización del gasto y siempre antes de la licitación del contrato, o de no existir esta, antes de su adjudicación.", "Deberán aprobarse previamente a la autorización del gasto o conjuntamente con ella, y siempre con posterioridad a la licitación del contrato."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 42, "El contratista deberá respetar el carácter confidencial de aquella información a la que tenga acceso con ocasión de la ejecución del contrato a la que se le hubiese dado el referido carácter en los pliegos o en el contrato, o que por su propia naturaleza deba ser tratada como tal. Este deber se mantendrá durante un plazo:", "De tres años desde el conocimiento de esa información, salvo que los pliegos o el contrato establezcan un plazo mayor que, en todo caso, deberá ser definido y limitado en el tiempo.", "De cuatro años desde el conocimiento de esa información, salvo que los pliegos o el contrato establezcan un plazo mayor que, en todo caso, deberá ser definido y limitado en el tiempo.", "De cinco años desde el conocimiento de esa información, salvo que los pliegos o el contrato establezcan un plazo menor que, en todo caso, deberá ser definido y limitado en el tiempo.", "De cinco años desde el conocimiento de esa información, salvo que los pliegos o el contrato establezcan un plazo mayor que, en todo caso, deberá ser definido y limitado en el tiempo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 43, "De acuerdo con el artículo 134 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, los órganos de contratación podrán publicar un anuncio de información previa:", "Con el fin de dar a conocer aquellos contratos de obras, suministros o servicios que, estando sujetos a regulación armonizada, tengan proyectado adjudicar.", "Con el fin de dar a conocer aquellos contratos de obras que, estando sujetos a regulación armonizada, tengan proyectado adjudicar.", "Con el fin de dar a conocer aquellos contratos de obras, suministros o servicios que, sin estar sujetos a regulación armonizada, tengan proyectado adjudicar.", "Con el fin de dar a conocer aquellos contratos de obras y suministros que, sin estar sujetos a regulación armonizada, tengan proyectado adjudicar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 44, "Los órganos de contratación que decidan recurrir a una subasta electrónica deberán indicarlo en el anuncio de licitación e incluir en el pliego de condiciones, como mínimo, la siguiente información:", "Los elementos objetivos a cuyos valores se refiera la subasta electrónica y en su caso, los límites de los valores que podrán presentarse, tal como resulten de las especificaciones relativas al objeto del contrato.", "La información que se pondrá a disposición de los licitadores durante la subasta electrónica y, cuando proceda, el momento en que se facilitará.", "La forma en que se desarrollará la subasta y el dispositivo electrónico utilizado y las modalidades y especificaciones técnicas de conexión.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 45, "De acuerdo con el artículo 145.3 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, la aplicación de más de un criterio de adjudicación procederá, en todo caso, en la adjudicación de los siguientes contratos:", "Aquellos contratos cuyos proyectos o presupuestos hayan podido ser establecidos previamente y deban ser presentados por los candidatos o licitadores.", "Cuando el órgano de contratación considere que la prestación es indefinible.", "Aquellos contratos para cuya ejecución facilite el órgano, organismo o entidad contratante materiales o medios auxiliares cuya buena utilización exija garantías especiales por parte de los contratistas.", "Aquellos contratos que no requieran el empleo de tecnología especialmente avanzada o cuya ejecución no sea particularmente compleja."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 46, "De acuerdo con el artículo 150.2 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, una vez aceptada la propuesta de la mesa por el órgano de contratación, los servicios correspondientes requerirán al licitador que haya presentado la mejor oferta:", "Para que, dentro del plazo de diez días hábiles, a contar desde el siguiente a aquel en que hubiera recibido el requerimiento, presente la documentación justificativa de las circunstancias a las que se refieren las letras a) a c) del apartado 1 del artículo 140 si no se hubiera aportado con anterioridad, tanto del licitador como de aquellas otras empresas a cuyas capacidades se recurra.", "Para que, dentro del plazo de diez días hábiles, a contar desde el siguiente a aquel en que hubiera recibido el requerimiento, presente la documentación justificativa de disponer efectivamente de los medios que se hubiese comprometido a dedicar o adscribir a la ejecución del contrato  y de haber constituido la garantía definitiva que sea procedente.", "Para que, dentro del plazo de diez días hábiles, a contar desde el siguiente a aquel en que hubiera recibido el requerimiento, presente la documentación justificativa de haber constituido la garantía definitiva que sea procedente.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 47, "La notificación y la publicación en la Plataforma de Contratos del Sector Público de la resolución de adjudicación deberán contener la información necesaria que permita a los interesados en el procedimiento de adjudicación interponer recurso suficientemente fundado contra la decisión de adjudicación, y entre esta información, en todo caso, deberá figurar:", "En relación con los candidatos descartados, no será necesario exponer las razones por las que se haya desestimado su candidatura.", "Con respecto a los licitadores excluidos del procedimiento de adjudicación, los motivos por los que no se haya admitido su oferta.", "El nombre del adjudicatario sin ninguna otra información de acuerdo con la normativa reguladora de la protección de datos.", "No será necesario indicar el plazo en que debe procederse a la formalización del contrato."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 48, "De acuerdo con el artículo 152 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, en el caso en que el órgano de contratación desista del procedimiento de adjudicación:", "El desistimiento deberá estar fundado en una infracción no subsanable de las normas de preparación del contrato o de las reguladoras del procedimiento de adjudicación, debiendo justificarse en el expediente la concurrencia de la causa.", "El desistimiento impedirá la iniciación inmediata de un procedimiento de licitación.", "El desistimiento no impedirá la iniciación inmediata de un procedimiento de licitación.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 49, "Señale la respuesta incorrecta:", "La formalización de los contratos deberá publicarse, junto con el correspondiente contrato, en un plazo no superior a quince días tras el perfeccionamiento del contrato en el perfil de contratante del órgano de contratación.", "Cuando el contrato esté sujeto a regulación armonizada, el anuncio de formalización deberá publicarse, además, en el «Diario Oficial de la Unión Europea».", "El órgano de contratación publicará trimestralmente dentro de los 30 días siguientes al fin de cada trimestre la adjudicación de los contratos basados en un acuerdo marco o de los contratos específicos en el marco de un sistema dinámico de adquisición, ya perfeccionados en virtud de lo establecido en el artículo 36.3 de la Ley 9/2017, de 8 de noviembre, de contratos del sector público.", "Los contratos menores no serán objeto de publicación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 50, "De acuerdo con el artículo 156.2 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, en los procedimientos abiertos de adjudicación de contratos sujetos a regulación armonizada, el plazo general de presentación de proposiciones:", "No será inferior a treinta y cinco días, para los contratos de obras, suministros y servicios, y a treinta días para las concesiones de obras y servicios, contados desde la fecha de envío del anuncio de licitación a la Oficina de Publicaciones de la Unión Europea.", "No será inferior a cuarenta días, para los contratos de obras, suministros y servicios, y a veinticinco días para las concesiones de obras y servicios, contados desde la fecha de envío del anuncio de licitación a la Oficina de Publicaciones de la Unión Europea.", "No será inferior a treinta días, para los contratos de obras, suministros y servicios, y a veinte días para las concesiones de obras y servicios, contados desde la fecha de envío del anuncio de licitación a la Oficina de Publicaciones de la Unión Europea.", "No será inferior a treinta y cinco días, para los contratos de obras, suministros y servicios, y a treinta días para las concesiones de obras y servicios, contados desde la fecha de recepción del anuncio de licitación en la Oficina de Publicaciones de la Unión Europea."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 51, "Cuando el valor estimado de un contrato de obras sea igual a 2.000.000 y entre los criterios de adjudicación previstos en el pliego no haya ninguno evaluable mediante juicio de valor, se podrá aplicar el procedimiento:", "Restringido.", "Negociado.", "Derivado.", "Abierto simplificado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 52, "De acuerdo con el artículo 160.4 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, el procedimiento de contratación restringido es especialmente adecuado cuando se trata:", "De servicios de limpieza.", "De servicios de consultoría, de arquitectura o de ingeniería.", "De obras.", "De suministros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 53, "De acuerdo con el artículo 167 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, los órganos de contratación podrán adjudicar contratos utilizando el procedimiento de licitación con negociación en los contratos de obras, suministros, servicios, concesión de obras y concesión de servicios cuando se dé alguna de las siguientes situaciones :", "Las respuestas b) y c) son correctas.", "Cuando la prestación objeto del contrato incluya un proyecto o soluciones innovadoras.", "Cuando el contrato no pueda adjudicarse sin negociaciones previas debido a circunstancias específicas vinculadas a la naturaleza, la complejidad o la configuración jurídica o financiera de la prestación que constituya su objeto, o por los riesgos inherentes a la misma.", "Cuando en los procedimientos abiertos o restringidos seguidos previamente solo se hubieren presentado ofertas anormalmente bajas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 54, "De acuerdo con el artículo 168 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, los órganos de contratación podrán adjudicar contratos utilizando el procedimiento negociado sin la previa publicación de un anuncio de licitación únicamente en los siguientes casos:", "En los contratos de obras, suministros, servicios, concesión de obras y concesión de servicios, en los casos en que no se haya presentado ninguna oferta; ninguna oferta adecuada; ninguna solicitud de participación; o ninguna solicitud de participación adecuada en respuesta a un procedimiento abierto o a un procedimiento restringido, siempre que las condiciones iniciales del contrato se modifiquen sustancialmente, pudiéndose incrementar el presupuesto base de licitación.", "En los contratos de obras, suministros, servicios, concesión de obras y concesión de servicios, en los casos en que no se haya presentado ninguna oferta; ninguna oferta adecuada; ninguna solicitud de participación; o ninguna solicitud de participación adecuada en respuesta a un procedimiento abierto o a un procedimiento restringido, siempre que las condiciones iniciales del contrato no se modifiquen sustancialmente, sin que en ningún caso se pueda incrementar el presupuesto base de licitación ni modificar el sistema de retribución, y que se envíe un informe a la Comisión Europea cuando esta así lo solicite.", "En los contratos de obras, suministros y servicios, en casos de emergencia.", "En los contratos de suministro, siempre y cuando los productos no sean para fines de investigación, experimentación, estudio o desarrollo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 55, "De acuerdo con el artículo 175 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, la mesa especial del diálogo competitivo desarrollará con los candidatos seleccionados un diálogo cuyo fin será determinar y definir los medios adecuados para satisfacer sus necesidades. En el transcurso de este diálogo, podrán debatirse:", "Únicamente los aspectos económicos del contrato con los candidatos seleccionados.", "Únicamente las cuestiones técnicas del contrato con los candidatos seleccionados.", "Todos los aspectos del contrato con los candidatos seleccionados.", "Únicamente los criterios de adjudicación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 56, "De acuerdo con el artículo 183 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, son concursos de proyectos:", "Los procedimientos encaminados a la obtención de planos o proyectos, principalmente en los campos de la arquitectura, el urbanismo, la ingeniería y el procesamiento de datos, a través de una selección que, tras la correspondiente licitación, se encomienda a un jurado.", "Los procedimientos encaminados a la obtención de pliegos, principalmente en los campos de la arquitectura, el urbanismo, la ingeniería y el procesamiento de datos, a través de una selección que, tras la correspondiente licitación, se encomienda a un jurado.", "Los procedimientos encaminados a la obtención de planos o proyectos, principalmente en los campos de la arquitectura, el urbanismo, la ingeniería y el procesamiento de datos, a través de una selección que, tras la correspondiente licitación, se encomienda a un comité de expertos.", "Los procedimientos encaminados a la obtención de pliegos, principalmente en los campos de la arquitectura, el urbanismo, la ingeniería y el procesamiento de datos, a través de una selección que, tras la correspondiente licitación, se encomienda a un jurado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 57, "De acuerdo con el artículo 192 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, respecto a las penalidades que puedan prever los pliegos:", "Deberán ser proporcionales a la gravedad del incumplimiento y las cuantías de cada una de ellas no podrán ser superiores al 5 por ciento del precio del contrato, IVA incluido, ni el total de las mismas superar el 30 por cien del precio del contrato.", "Deberán ser proporcionales a la gravedad del incumplimiento y las cuantías de cada una de ellas no podrán ser superiores al 10 por ciento del precio del contrato, IVA excluido, ni el total de las mismas superar el 50 por cien del precio del contrato.", "Deberán ser proporcionales a la gravedad del incumplimiento y las cuantías de cada una de ellas no podrán ser superiores al 10 por ciento del precio del contrato, IVA incluido, ni el total de las mismas superar el 40 por cien del precio del contrato.", "Deberán ser proporcionales a la gravedad del incumplimiento y las cuantías de cada una de ellas no podrán ser superiores al 5 por ciento del precio del contrato, IVA excluido, ni el total de las mismas superar el 40 por cien del precio del contrato."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 58, "De acuerdo con el artículo 202 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, los órganos de contratación podrán establecer condiciones especiales en relación con la ejecución del contrato:", "Siempre que no estén vinculadas al objeto del contrato.", "Siempre que no sean directa o indirectamente discriminatorias.", "Siempre que no sean incompatibles con el Derecho de la Unión Europea.", "Siempre que se indiquen en la resolución de aprobación del contrato."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 59, "De acuerdo con el artículo 206 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, en los supuestos de modificación del contrato por causas no previstas en el pliego de cláusulas administrativas particulares, las modificaciones acordadas por el órgano de contratación serán:", "Optativas para los contratistas cuando impliquen, aislada o conjuntamente, una alteración en su cuantía que no exceda del 20 por ciento del precio inicial del contrato, IVA incluido.", "Obligatorias para los contratistas cuando impliquen, aislada o conjuntamente, una alteración en su cuantía que no exceda del 30 por ciento del precio inicial del contrato, IVA excluido.", "Obligatorias para los contratistas cuando impliquen, aislada o conjuntamente, una alteración en su cuantía que no exceda del 20 por ciento del precio inicial del contrato, IVA excluido.", "Optativas para los contratistas cuando impliquen, aislada o conjuntamente, una alteración en su cuantía que no exceda del 30 por ciento del precio inicial del contrato, IVA incluido."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 60, "Cuando el contrato se resuelva por incumplimiento culpable del contratista:", "Le será incautada la garantía.", "Deberá, además, indemnizar a la Administración los daños y perjuicios ocasionados en lo que excedan del importe de la garantía incautada.", "El expediente de resolución contractual deberá ser instruido y resuelto en el plazo máximo de ocho meses.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 61, "La duración de un acuerdo marco:", "No podrá exceder de cuatro años.", "No podrá exceder de cinco años.", "No podrá exceder de tres años.", "No podrá exceder de dos años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 62, "Señale la respuesta incorrecta. Aprobado el proyecto y previamente a la aprobación del expediente de contratación de la obra, se procederá a efectuar:", "En la tramitación de los expedientes de contratación referentes a obras de infraestructuras hidráulicas, de transporte y de carreteras, en ningún caso se dispensará del requisito previo de disponibilidad de los terrenos.", "El replanteo del proyecto.", "Una vez realizado el replanteo se incorporará el proyecto al expediente de contratación.", "El replanteo consistirá en comprobar la realidad geométrica de la obra y la disponibilidad de los terrenos precisos para su normal ejecución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 63, "Con carácter previo a la decisión de construir y explotar en régimen de concesión unas obras, el órgano que corresponda de la Administración concedente acordará la realización de un estudio de viabilidad de las mismas que deberá contener, al menos, los datos, análisis, informes o estudios que procedan sobre los puntos siguientes:", "Finalidad y justificación de las obras, así como definición de sus características esenciales.", "Previsiones sobre la demanda de uso e incidencia económica y social de las obras en su área de influencia y sobre la rentabilidad de la concesión.", "Estudio de impacto ambiental cuando este sea preceptivo de acuerdo con la legislación vigente. En los restantes casos, un análisis ambiental de las alternativas y las correspondientes medidas correctoras y protectoras necesarias.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 64, "Señale la respuesta incorrecta en relación a la mesa de contratación (órgano de asistencia técnica especializada):", "Los miembros de la mesa serán nombrados por el órgano de contratación.", "La composición de la mesa se publica en el perfil del contratante del órgano de contratación correspondiente.", "La mesa lleva a cabo la  adjudicación del contrato a favor del licitador que haya presentado la mejor oferta.", "La mesa propone sobre la calificación de una oferta como anormalmente baja, previa tramitación del procedimiento a que se refiere el artículo 149 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 65, "La  Oficina Independiente de Regulación y Supervisión de la Contratación:", "Es un órgano unipersonal.", "Vela por la correcta interpretación de los pliegos de prescripciones técnicas.", "Actúa en el desarrollo de su actividad y el cumplimiento de sus fines con plena independencia orgánica y funcional.", "Actúa en el desarrollo de su actividad y el cumplimiento de sus fines dependiendo del Ministerio de Hacienda y Función Pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 66, "De acuerdo con la disposición adicional duodécima de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014:", "Los plazos establecidos por días en esta Ley se entenderán referidos a días hábiles. Si el último día del plazo fuera inhábil, este se entenderá prorrogado al primer día hábil siguiente.", "Los plazos establecidos por días en esta Ley se entenderán referidos a días naturales, salvo que en la misma se indique expresamente que solo deben computarse los días hábiles. No obstante, si el último día del plazo fuera inhábil, este se entenderá prorrogado al primer día hábil siguiente.", "Los plazos establecidos por días en esta Ley se entenderán referidos a días naturales, salvo que en la misma se indique expresamente que solo deben computarse los días hábiles. No obstante, si el último día del plazo fuera inhábil, este se entenderá prorrogado al primer día natural siguiente.", "Los plazos establecidos por días en esta Ley se entenderán referidos a días hábiles, salvo que en la misma se indique expresamente que se computarán los días naturales. No obstante, si el último día del plazo fuera inhábil, este se entenderá prorrogado al primer día hábil siguiente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 17, 67, "Salvo en los casos en los que el órgano de contratación, por motivos excepcionales, lo considere necesario y así lo justifique motivadamente en el expediente no procederá la exigencia de la garantía definitiva:", "En los contratos de servicios.", "En los contratos de suministros.", "En los contratos de arrendamiento.", "En los procedimientos de contratación en los que se aplique la reserva que establece la disposición adicional cuarta de la LCSP."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 1, "Para el acceso a los cuerpos o escalas del grupo B se exigirá estar en posesión del:", "Título de Técnico Superior.", "Título de Bachiller.", "Título de Técnico.", "Título Universitario de Grado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 2, "¿A qué dos principios ha de atender la designación de personal directivo profesional de las Administraciones Públicas?", "Publicidad y concurrencia.", "Legalidad e igualdad.", "Capacidad y mérito.", "Idoneidad y transparencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 3, "Cuando sea declarado en situación de servicios especiales el personal interino:", "Tendrá reserva del puesto de trabajo mientras dure la situación de servicios especiales.", "No tendrá reserva de puesto de trabajo en ningún caso.", "Tendrá reserva del puesto de trabajo únicamente hasta que se lleve a cabo la provisión del puesto ocupado.", "Tendrá reserva del puesto de trabajo en cualquier caso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 4, "El personal funcionario que ejercite el derecho de huelga, por el tiempo que haya permanecido en la misma, devengará y percibirá:", "Sólo las retribuciones básicas prorrateadas.", "Las retribuciones básicas y los trienios.", "Todas las retribuciones que le correspondieran si no hubiera ejercido ese derecho.", "No devengará ni percibirá retribución alguna."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 5, "El personal funcionario de carrera podrá ser declarado en situación de excedencia voluntaria por interés particular cuando haya prestado servicios en cualquiera de las Administraciones Públicas durante un periodo mínimo de:", "Diez años inmediatamente anteriores.", "Dos años inmediatamente anteriores.", "Cinco años inmediatamente anteriores.", "Tres años inmediatamente anteriores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 6, "¿En qué situación administrativa se encontraran los funcionarios de carrera cuando sean designados para formar parte del Consejo General del Poder Judicial?", "Servicio activo.", "Servicios especiales.", "Servicio en otras Administraciones Públicas.", "Excedencia voluntaria por interés particular."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 7, "¿Cuál es la duración máxima de la sanción de suspensión de funciones por faltas muy graves?", "Cinco años.", "Tres años.", "Dos años.", "Seis años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 8, "Cuando el personal funcionario sea declarado en situación de suspensión, dicha situación determinará la pérdida del puesto de trabajo cuando la suspensión exceda de:", "Seis meses.", "Tres meses.", "Cinco meses.", "Dos meses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 9, "El personal funcionario suspendido provisionalmente percibe en esta situación", "Todas sus retribuciones.", "Las retribuciones básicas y, en su caso , las prestaciones familiares por hijo a cargo.", "Las retribuciones complementarias y, en su caso, las prestaciones familiares por hijo a cargo.", "Solo las retribuciones básicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 10, "En caso de excedencia por cuidado de hijos se tiene derecho a la reserva del puesto de trabajo, al menos, durante:", "El tiempo que dure la excedencia que, en cualquier caso no podrá ser superior a tres años.", "No se tendrá reserva de puesto de trabajo.", "Los dos primeros años.", "Los tres primeros años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 11, "La rehabilitación en la condición de funcionario no es posible para quienes la perdieron", "Por pérdida de la nacionalidad.", "Por jubilación por incapacidad permanente para el servicio.", "Por renuncia.", "No es posible la rehabilitación en ningún caso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 12, "La jornada ordinaria de trabajo de los funcionarios:", "Es la misma para todos los funcionarios independientemente de la Administración para la que trabajen.", "Cada Administración puede aprobar jornadas de trabajo propias, siempre que hayan cumplido los objetivos de estabilidad presupuestaria, deuda pública y regla de gasto.", "Cada Administración puede aprobar jornadas de trabajo propias, sin ningún tipo de condición, pues es una manifestación de su autonomía organizativa.", "Es diferente según se trate de funcionarios de carrera o de funcionarios interinos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 13, "¿Cuál de las siguientes modalidades de jubilación no está prevista en la actualidad en el Real Decreto Legislativo 5/2015, de 30 de octubre, por el que se aprueba el texto refundido de la Ley del Estatuto Básico del Empleado Público?", "La jubilación voluntaria.", "La jubilación parcial.", "La jubilación forzosa.", "La jubilación por incapacidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 14, "¿Cuál de las siguientes no es una situación administrativa en la que se pueda encontrar un funcionario de carrera?", "La excedencia.", "La suspensión de funciones.", "La incapacidad temporal.", "El servicio activo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 15, "Según el Estatuto Básico del Empleado Público, el ejercicio de funciones que supongan la participación en la salvaguarda de los intereses generales de una Administración", "Corresponde exclusivamente a los funcionarios de carrera cuando dicha participación es directa y a los funcionarios interinos cuando la misma es indirecta.", "Corresponde exclusivamente a los funcionarios de carrera cuando dicha participación es indirecta, y a los funcionarios interinos cuando la misma es directa", "Corresponde exclusivamente a los funcionarios públicos, sea directa o indirecta dicha participación.", "Corresponde exclusivamente a los empleados públicos"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 16, "Las retribuciones de los funcionarios públicos:", "Se dividen en básicas, complementarias y discrecionales", "Se dividen en básicas y complementarias", "Son las mismas para todo el personal funcionario de todas las Administraciones.", "Son las mismas para todos el personal funcionario de una misma Administración"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 17, "La incoación de un procedimiento disciplinario:", "Conlleva necesariamente la suspensión provisional del personal funcionario.", "No conlleva necesariamente la suspensión provisional del personal funcionario.", "Conlleva automáticamente la suspensión provisional del personal funcionario cuando se le imputa una falta muy grave, siendo discrecional el establecimiento de dicha suspensión en caso de faltas graves o simplemente leves.", "Nunca conlleva la suspensión provisional del personal funcionario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 18, "Indique cual de los siguientes no es uno de los derechos de carácter individual de los empleados públicos ejercidos colectivamente:", "La libertad sindical.", "La huelga.", "La formación continua y la actualización permanente de sus conocimientos y capacidades profesionales.", "La negociación colectiva y la participación en la determinación de las condiciones de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 19, "En el año 2022 el permiso de paternidad por el nacimiento, guarda con fines de adopción, acogimiento o adopción de un hijo/a  tendrá una duración de:", "Ocho semanas.", "Catorce semanas.", "Dieciséis semanas.", "Doce semanas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 20, "El incumplimiento de la obligación de atender los servicios esenciales en caso de huelga es constitutivo de:", "Falta grave", "Falta muy grave", "No constituye falta", "Falta Leve"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 21, "Quienes se encuentren en situación de excedencia por interés particular:", "Les será computable el tiempo que permanezcan en tal situación a efectos de ascensos.", "Les será  computable el tiempo que permanezcan en tal situación a efectos de trienios.", "No devengarán retribuciones.", "Les será computable el tiempo que permanezcan en tal situación a efectos de Seguridad Social."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 22, "Señale la respuesta correcta respecto del personal funcionario en situación de servicios especiales:", "No se le computará el tiempo que permanezca en esta situación a efectos de ascensos, trienios o derechos pasivos.", "Tendrá derecho a la reserva de plaza.", "Tendrá preferencia para el reingreso en el servicio activo", "Tendrá derecho a la reserva de puesto de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 23, "El personal funcionario que sea adscrito al servicio del defensor del Pueblo quedará en su puesto de procedencia en la situación de:", "Servicio activo.", "Servicios especiales.", "Servicio en otra Administración Pública.", "Excedencia especial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 24, "En las pagas extraordinarias se perciben:", "El sueldo y el complemento de destino solamente.", "Todas las retribuciones.", "Las retribuciones básicas en exclusiva.", "El sueldo el complemento de destinación y el complemento específico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 25, "El reconocimiento de compatibilidad al personal funcionario para ejercer un trabajo fuera de la Administración", "Es previo a dicho trabajo.", "Sólo se da para actividades privadas.", "Se tiene que solicitar cada vez que hay un cambio de puesto de trabajo dentro de la Administración.", "Se puede ejercer en tanto no sea denegado por la Administración."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 26, "El personal funcionario que, por un procedimiento de provisión de puestos, obtenga destino definitivo en una administración Pública distinta es declarado en.", "Servicio activo.", "Servicio en otras Administraciones Públicas.", "Excedencia voluntaria.", "Excedencia voluntaria por prestación de servicios en el sector público."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 27, "La separación del servicio en un municipio de gran población se acuerda por", "Presidente/a de la Corporación.", "Pleno de la Corporación.", "Junta de Gobierno Local.", "La Junta de Personal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 28, "En el caso de separación del servicio del personal funcionario interino", "Podrá ser rehabilitado en el futuro.", "Permanece en activo hasta que se cubra su vacante.", "Se revoca su nombramiento.", "No es necesario seguir procedimiento disciplinario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 29, "Según el artículo 1.3 del texto refundido de la Ley del Estatuto Básico del Empleado Público, uno de los fundamentos de actuación reflejados en el EBEP es", "La igualdad de trato entre mujeres y hombres.", "La prevención de riesgos laborales.", "La protección de datos de carácter personal.", "La equiparación salarial entre Administraciones Públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 30, "Según el artículo 1.3 del texto refundido de la Ley del Estatuto Básico del Empleado Público, con la inamovilidad en la condición de funcionario de carrera se garantiza (Señale la respuesta incorrecta.)", "Objetividad.", "Disponibilidad.", "Profesionalidad.", "Imparcialidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 31, "Según el artículo 1.3 del texto refundido de la Ley del Estatuto Básico del Empleado Público, uno de los fundamentos de actuación reflejados por el EBEP es el servicio a los ciudadanos y", "A los intereses generales.", "Al ordenamiento jurídico.", "Al bienestar general.", "A la Administración pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 32, "Para poder participar en los concursos de provisión de puestos de trabajo, los funcionarios deberán permanecer en cada puesto de trabajo obtenido por concurso un mínimo de", "Cinco años.", "Tres años.", "Dos años.", "Un año."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 33, "La titulación exigible para ser funcionario del grupo B según el Real decreto Legislativo 5/2015, de 30 de octubre, por el que se aprueba el texto refundido de la Ley del Estatuto Básico del Empleado Público, es:", "Título de Bachiller o técnico.", "Título de Graduado en Educación Secundaria.", "Título de Técnico Superior.", "Título de ESO."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 34, "Los sistemas de provisión de puestos de trabajo de funcionarios son", "Oposición.", "Concurso de méritos.", "Libre designación.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 35, "La constitución del Registro de Personal:", "Se efectúa a nivel estatal.", "Es facultativa para las Corporaciones locales.", "Es obligatoria para las Corporaciones locales.", "Se supedita a la voluntad de la correspondiente Comunidad Autónoma."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 36, "Qué complemento está destinado a retribuir el interés e iniciativa con que el funcionario desempeña su puesto de trabajo?", "Complemento de productividad.", "Complemento específico.", "Complemento de carrera profesional.", "Complemento de dedicación especial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 37, "La utilización del concurso como sistema de selección del personal funcionario de carrera", "Exige que se trate de acceso a cuerpos o escalas cuyas funciones no sean susceptibles de medición a través de pruebas de oposición.", "Exige que una norma con rango de Ley lo haya permitido.", "Exige que una norma con rango de ley o con rango de reglamento lo haya permitido.", "No se puede utilizar para el acceso a la función pública por el sistema de concurso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 38, "Señale la afirmación correcta:", "Todos los empleados públicos son funcionarios públicos", "Todos los funcionarios públicos son empleados públicos.", "Sólo los funcionarios de carrera e interinos son empleados públicos", "Los funcionarios públicos no son empleados públicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 39, "En relación con las plantillas, ¿Cuál de las siguientes afirmaciones es incorrecta?:", "Deberán responder a los principios de racionalidad, economía y eficiencia y establecerse de acuerdo con la ordenación general de la economía, sin que los gastos de personal puedan rebasar los límites que se fijen con carácter general.", "Deberán comprender todos los puestos de trabajo debidamente clasificados y reservados a personal funcionario y personal laboral.", "Se aprobarán cada dos años con ocasión de la aprobación del presupuesto.", "Podrán ser ampliadas cuando el incremento de las dotaciones sea consecuencia del establecimiento o ampliación de servicios de carácter obligatorio que resulten impuestos por disposiciones legales ."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 40, "En relación con la provisión de puestos por concurso de traslados:", "La periodicidad de su convocatoria será como mínimo anual.", "Es el sistema de provisión de puestos genéricos y singularizados, en todo caso.", "La valoración total de los méritos en el concurso específico supondrá como máximo, el 55% de la puntuación máxima alcanzable.", "El personal funcionario que haya obtenido un puesto de trabajo mediante un sistema de provisión ordinario, deberá permanecer en él un mínimo de dos años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 41, "¿Cuál de las siguientes categorías de personal no se encuentra dentro de la clasificación de empleados públicos del Real decreto Legislativo 5/2015, de 30 de octubre, por el que se aprueba el texto refundido de la Ley del Estatuto Básico del Empleado Público?", "Personal funcionario interino.", "Personal eventual.", "Personal laboral indefinido o temporal.", "Todos ellos son empleados públicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 42, "La provisión de puestos de trabajo destinada a personal funcionario de carrera puede efectuarse mediante:", "Concurso de méritos y, excepcionalmente, el sistema de libre designación.", "Concurso-oposición cuando por la naturaleza de las funciones sea más adecuado elegir este sistema para valorar, además de la aptitud de los aspirantes, determinadas condiciones de formación o experiencia.", "Concurso cuando se trata de acceso a puestos de trabajo que, por sus características especiales, deban cubrirse por personas con méritos excepcionales.", "Sólo el sistema de concurso de méritos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 43, "Los principios de igualdad y de mérito y capacidad:", "Sólo se aplican en el momento del ingreso en la Función Pública.", "Sólo se aplican en los procedimientos de provisión de puestos de trabajo entre quienes ya son funcionario.", "Se aplican en los procedimientos de selección y en los procedimientos de provisión.", "No son principios constitucionales sino legales al no estar recogidos en la Constitución sino en el Estatuto Básico del Empleado Público"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 44, "En los procedimientos de selección para el ingreso en la Función Pública:", "La Administración elabora las bases de la oposición y el Tribunal de selección valora la capacidad y el mérito de las personas aspirantes.", "El Tribunal de selección elabora las bases de la oposición y la Administración valora la capacidad y el mérito de los candidatos.", "El Tribunal de selección elabora las bases y valora la capacidad y el mérito de las personas aspirantes.", "La Administración elabora las bases y valora la capacidad y el mérito de las personas aspirantes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 45, "El personal funcionario interino:", "Sólo pueden ser nombrados para sustituir a funcionarios de carrera.", "Sólo pueden ser nombrados para ocupar vacantes.", "Pueden ser nombrados exclusivamente para sustituir a funcionarios de carrera o para para ocupar vacantes.", "Son una clase de empleado público cuyo régimen jurídico es el de los funcionarios de carrera, con las adaptaciones necesarias según la naturaleza de su condición interina."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 46, "Conforme al Real Decreto Legislativo 5/2015, de 30 de octubre, por el que se aprueba el texto refundido de la Ley del Estatuto Básico del Empleado Público, la ejecución de la oferta de empleo público deberá desarrollarse dentro del plazo improrrogable de:", "5 años.", "3 años.", "1 año.", "La ejecución de la oferta de empleo público no se encuentra sujeta a un plazo determinado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 47, "Las funciones que impliquen la participación directa o indirecta en el ejercicio de las potestades públicas quedan reservadas:", "Al personal funcionario de carrera.", "Al personal funcionario de carrera e interino.", "Al personal funcionario de carrera e interino, y al personal eventual.", "A todos los empleados públicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 48, "El cese de los funcionarios interinos se producirá:", "Exclusivamente cuando finalice la causa que dio lugar a su nombramiento.", "Cuando finalice la causa que dio lugar a su nombramiento o cuando concurra alguna de las causas generales de extinción de la relación de servicio de los funcionarios de carrera.", "Exclusivamente cuando concurra alguna de las causas generales de extinción de la relación de servicio de los funcionarios de carrera.", "Cuando finalice la causa que dio lugar a su nombramiento, siempre que concurra además alguna de las causas generales de extinción de la relación de servicio de los funcionarios de carrera."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 49, "El Ayuntamiento de la localidad en que reside desea saber las disponibilidades de personal que tiene y, en su caso, si necesita más personal y con qué perfiles para afrontar la ejecución de los Fondos europeos. ¿Qué instrumento de ordenación del empleo público deberá elaborar?", "Una relación de puestos de trabajo", "Un plan de ordenación de recursos humanos", "Una reasignación de efectivos", "Una oferta de empleo público"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 50, "En relación al acceso a la función pública, la experiencia, formación y perfeccionamiento recibidos, publicaciones efectuadas y similares son elementos que tienen que ver con el principio constitucional de:", "Igualdad", "Publicidad", "Capacidad", "Mérito"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 51, "La renuncia voluntaria de la condición de funcionario:", "Puede ser denegada por la Administración si las necesidades del servicio la desaconsejan.", "Debe ser denegada por la Administración si las necesidades del servicio la desaconsejan.", "Inhabilita al personal funcionario para volver a ingresar en la Función Pública.", "No puede concederse si la persona está sujeta a un expediente disciplinario o a un proceso penal por la comisión de un delito."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 52, "¿ De cuánto tiempo disfrutarán los empleados públicos por traslado de domicilio sin cambio de residencia?", "De dos días", "De un día", "De dos horas", "De un máximo de seis horas"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 53, "¿Qué retribución complementaria está destinada a retribuir las condiciones particulares de algunos puestos de trabajo en atención a su especial dificultad técnica, dedicación, incompatibilidad, responsabilidad, peligrosidad o penosidad?", "El complemento de carrera profesional", "El complemento específico", "El complemento de productividad", "El complemento de destino"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 54, "En relación con la excedencia voluntaria por interés particular, señale la respuesta incorrecta:", "El funcionario que la solicite debe haber prestado servicios efectivos en cualquiera de las Administraciones públicas durante los dos años inmediatamente anteriores.", "Quien se encuentre en esta situación no devengará retribuciones, ni le será computable el tiempo que permanezca en tal situación a efectos de ascensos, trienios y derechos en el régimen de la Seguridad social.", "No podrá concederse mientras esté en trámite un procedimiento disciplinario o esté pendiente del cumplimiento de una sanción disciplinaria.", "Se declarará dicha situación cuando, finalizada la causa que determinó el pase a una situación distinta a la de servicio activo, se incumpla la obligación de solicitar el reingreso al servicio activo en el plazo en que se determine reglamentariamente"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 55, "El acoso laboral se tipifica como:", "Falta muy grave", "Falta grave", "No está tipificado como falta", "Falta leve"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 56, "En la corrección de una falta leve, un trámite inexcusable es:", "La previa audiencia al interesado.", "La incoación de diligencias preliminares.", "La incoación de expediente informativo.", "La incoación de expediente disciplinario ordinario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 57, "En caso de excedencia por cuidado de hijos, se tiene derecho a la reserva del puesto de trabajo desempeñado, al menos, durante:", "El tiempo que dure la excedencia.", "Ningún momento.", "Un periodo no superior a dos años.", "Un periodo no superior a tres años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 58, "Cuándo  estará sometido a la relación laboral de carácter especial de alta dirección el personal directivo, según el art. 13.4.c del Real Decreto Legislativo 5/2015, de 30 de octubre?", "Cuando reúna la condición de personal laboral.", "Cuando reúna la condición de funcionario interino.", "Cuando reúna la condición de funcionario de carrera.", "Cuando así lo acuerde el órgano competente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 59, "Los empleados públicos tienen los siguientes derechos de carácter individual en correspondencia con la naturaleza jurídica de su relación de servicio:", "A la movilidad en la condición de funcionario de carrera.", "A la progresión en la carrera profesional y promoción interna según principios constitucionales de igualdad, mérito y capacidad mediante la implantación de sistemas objetivos y transparentes de evaluación.", "A la defensa jurídica y protección de la Administración Pública en los procedimientos que se sigan ante cualquier orden jurisdiccional como consecuencia del ejercicio legítimo o ilegítimo de sus funciones o cargos públicos.", "A la formación continua y a la actualización permanente de sus conocimientos y capacidades profesionales, siempre que se realicen en horario laboral."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 21, 60, "La Oferta de empleo Público en n municipio de gran población debe aprobarse por:", "Pleno.", "Junta de Personal.", "Presidente/a.", "Junta de Gobierno Local."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 1, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, cuál de las siguientes respuestas no está incluida en el ámbito de aplicación de esta ley?", "Las entidades gestoras y los servicios comunes de la Seguridad Social.", "La Casa de su Majestad el Rey.", "El Senado.", "Las fundaciones cuya actividad se realiza en territorio español."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 2, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, el derecho de acceso a la información pública se ejercerá:", "Sin límite dado que es un derecho constitucionalmente garantizado.", "Tiene el límite derivado de los secretos políticos.", "Tiene el límite derivado de la protección de datos de carácter personal.", "Tiene el límite temporal de diez años desde que se resuelve el expediente al cual se pretende acceder."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 3, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, toda la información estará a disposición de las personas con discapacidad en una modalidad suministrada por medios o en formatos adecuados:", "De manera que resulten accesibles y comprensibles, conforme al principio de accesibilidad universal y diseño para todos.", "De manera que resulten accesibles y comprensibles, siempre que la tecnología lo permita.", "De manera que resulten accesibles y comprensibles, en el plazo de dos años desde la publicación de esta ley.", "De manera que resulten accesibles y comprensibles, conforme al principio de accesibilidad para la mayoría."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 4, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿qué entidades privadas están obligadas a publicar de forma periódica y actualizada la información, cuyo conocimiento sea relevante para garantizar la transparencia de su actividad?", "Las que perciban durante el período de un año ayudas o subvenciones públicas en una cuantía superior a 100.000 euros.", "Las que perciban durante el período de un año ayudas o subvenciones públicas en una cuantía superior a 10.000 euros.", "Las que perciban durante el período de tres años ayudas o subvenciones públicas en una cuantía superior a 100.000 euros.", "Las que perciban durante el período de tres años ayudas o subvenciones públicas en una cuantía superior a 10.000 euros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 5, "La Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿cómo denomina a los dos tipos de transparencia que regula?", "Publicidad activa y derecho de solicitud de la información pública.", "Publicidad informativa y derecho de acceso a la información pública.", "Publicidad informativa y derecho de solicitud de la información pública.", "Publicidad activa y derecho de acceso a la información pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 6, "De acuerdo con la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, en aplicación del principio de transparencia entre los principios de buena regulación, las administraciones públicas:", "Posibilitarán el acceso a la normativa en vigor y los documentos propios de su proceso de elaboración, pero no se prevé que los potenciales destinatarios puedan tener una participación activa en la elaboración de las normas.", "Posibilitarán el acceso exclusivamente a los procesos de elaboración de las leyes, ya que el acceso a la normativa en vigor se obliga por el principio de seguridad jurídica.", "Posibilitarán el acceso a la normativa en vigor a través de sus paginas web pero no están obligadas a hacerlo en los procesos de elaboración de las leyes.", "Posibilitarán el acceso a la normativa en vigor y los documentos propios de su proceso de elaboración y posibilitaran que los potenciales destinatarios tengan una participación activa en la elaboración de las normas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 7, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, señala qué información pública se corresponde a información institucional, organizativa y de planificación que deben publicar las administraciones públicas:", "información relativa a su estructura organizativa.", "Las directrices, instrucciones, acuerdos o circulares que tengan efectos jurídicos.", "Los proyectos de Reglamentos cuya iniciativa les corresponda.", "La información estadística necesaria para valorar el grado de cumplimiento y calidad de los servicios públicos que sean de su competencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 8, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿que se entiende por información pública?", "Los contenidos, pero no los documentos, que obren en poder de alguno de los sujetos incluidos en el ámbito de aplicación de esta ley, elaborados o adquiridos en el ejercicio de sus funciones.", "Los contenidos, pero no los documentos, que obren en poder de alguno de los sujetos incluidos en el ámbito de aplicación de esta ley, siempre que hayan sido elaborados por estos sujetos.", "Los contenidos o documentos que obren en poder de alguno de los sujetos incluidos en el ámbito de aplicación de esta ley, siempre que hayan sido elaborados por estos sujetos.", "Los contenidos o documentos que obren en poder de alguno de los sujetos incluidos en el ámbito de aplicación de esta ley, elaborados o adquiridos en el ejercicio de sus funciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 9, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, el derecho de acceso podrá ser limitado cuando acceder a la información suponga un perjuicio para:", "Las relaciones interiores.", "La igualdad de las partes en los procesos judiciales y la tutela judicial efectiva.", "La seguridad internacional.", "La geopolítica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 10, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, la aplicación de los límites al derecho de acceso:", "Atenderá a las circunstancias del caso concreto, especialmente a la concurrencia de un interés público o privado.", "Atenderá a las circunstancias del caso concreto, especialmente a la concurrencia de interéses exclusivamente públicos.", "Atenderá a las circunstancias del caso concreto, especialmente a la concurrencia de interéses exclusivamente privados.", "Atenderá a las circunstancias del caso concreto, sin atender a otros posibles intereses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 11, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, señala qué información pública se corresponde a información de relevancia jurídica que deben publicar las administraciones públicas:", "Los presupuestos.", "Las directrices, instrucciones, acuerdos o circulares en la medida en que supongan una interpretación del Derecho o tengan efectos jurídicos.", "La relación de los convenios suscritos.", "Información relativa a su estructura organizativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 12, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, si la información solicitada contuviera datos personales que revelen la ideología, afiliación sindical, religión o creencias:", "El acceso únicamente se podrá autorizar en caso de tener el consentimiento expreso y por escrito del afectado, aun cuando dicho afectado hubiese hecho manifiestamente públicos los datos con anterioridad.", "El acceso únicamente se podrá autorizar en caso de que dicho afectado hubiese hecho manifiestamente públicos los datos con anterioridad, aun cuando éste lo autorice expresamente.", "El acceso únicamente se podrá autorizar en caso de tener el consentimiento expreso y por escrito del afectado, o que dicho afectado hubiese hecho manifiestamente públicos los datos con anterioridad.", "No se podrá acceder a esta información bajo ningún concepto, con el fin de salvaguardar la intimidad de las personas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 13, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, cuando la información solicitada contenga datos personales pero estos datos no se encuentren especialmente protegidos, el órgano al que se dirija la solicitud:", "Concederá el acceso de inmediato sin posibilidad de recurso administrativo por parte de los afectados.", "Concederá el acceso previa ponderación razonada de los intereses contrapuestos.", "Concederá el acceso de inmediato con posibilidad de recurso administrativo por parte de los afectados.", "No concederá el acceso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 14, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, la solicitud de acceso a la información deberá permitir tener constancia en todo caso de la siguiente información:", "La identidad del solicitante e información que se solicita.", "La identidad del solicitante, información que se solicita y una dirección de contacto.", "La identidad del solicitante, información que se solicita, motivación de la consulta y una dirección de contacto.", "La identidad del solicitante, información que se solicita, afectados por la revelación de estos datos y una dirección de contacto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 15, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿Cual de las siguientes solicitudes de información se inadmitirán a trámite?", "Las que contengan datos personales que hagan referencia a la vida sexual.", "Las referidas a información que tenga carácter auxiliar o de apoyo contenida en informes internos.", "Las dirigidas a un órgano en cuyo poder no obre la información cuando no se desconozca el competente.", "Datos personales relativos a la comisión de infracciones penales o administrativas que no conllevasen la amonestación pública al infractor."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 16, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, señala qué información pública se corresponde a información de relevancia jurídica que deben publicar las administraciones públicas:", "Las cuentas anuales que deban rendirse.", "Información relativa a las funciones que desarrollan.", "Los presupuestos.", "Las memorias e informes que conformen los expedientes de elaboración de los textos normativos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 17, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, si la información solicitada incluyese datos personales que hagan referencia a la salud o a la vida sexual:", "El acceso solo se podrá autorizar en caso de que estuviera amparado por una norma con rango de ley.", "El acceso solo se podrá autorizar en caso de que se cuente con el consentimiento expreso, por escrito o por comparecencia apud acta del afectado.", "El acceso únicamente se podrá autorizar en caso de tener el consentimiento expreso y por escrito del afectado, o que dicho afectado hubiese hecho manifiestamente públicos los datos con anterioridad.", "El acceso solo se podrá autorizar en caso de que se cuente con el consentimiento expreso del afectado o si aquel estuviera amparado por una norma con rango de ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 18, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, si la solicitud de información no identifica de forma suficiente la información solicitada:", "Se inadmitirá la solicitud.", "Se pedirá al solicitante que la concrete en un plazo de quince días.", "Se pedirá al solicitante que la concrete en un plazo de treinta días.", "Se pedirá al solicitante que la concrete en un plazo de diez días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 19, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, si la información solicitada pudiera afectar a derechos o intereses de terceros, debidamente identificados, y se les ha concedido un plazo para presentar alegaciones:", "Se suspende el plazo para dictar resolución hasta que se hayan recibido las alegaciones o haya transcurrido el plazo de diez días para su presentación.", "Se suspende el plazo para dictar resolución hasta que se hayan recibido las alegaciones o haya transcurrido el plazo de quince días para su presentación.", "No es obligatorio suspender el plazo para dictar resolución hasta que se hayan recibido las alegaciones o haya transcurrido el plazo de diez días para su presentación.", "No es obligatorio suspender el plazo para dictar resolución hasta que se hayan recibido las alegaciones o haya transcurrido el plazo de quince días para su presentación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 20, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿A quien se debe notificar la ampliación del plazo máximo para notificar la resolución en la que se conceda o deniegue el acceso a la información pública?", "No es necesario notificar dicha ampliación.", "Al solicitante de la información pública.", "A los terceros afectados por la información solicitada", "Al solicitante de la información pública y a los terceros afectados por dicha información."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 21, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, las resoluciones dictadas en materia de acceso a la información pública:", "No son recurribles directamente ante la jurisdicción contencioso-administrativa.", "Debe agotarse la vía administrativa primero, mediante el correspondiente recurso de alzada o potestativo de reposición.", "Solo son recurribles ante la Jurisdicción Contencioso-administrativa después de que se haya resuelto el recurso ante el Consejo de Transparencia y Buen Gobierno.", "Son recurribles directamente ante la Jurisdicción Contencioso-administrativa, dado que el recurso ante el Consejo de Transparencia y Buen Gobierno es potestativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 22, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, a los efectos de la aplicación a sus responsables del régimen disciplinario, el incumplimiento de la obligación de resolver en plazo las resoluciones dictadas en materia de acceso a la información pública:", "Tendrá en todo caso la consideración de infracción grave.", "Tendrá en todo caso la consideración de infracción leve.", "Tendrá la consideración de infracción leve pero si el incumplimiento es reiterado tendrá la consideración de infracción grave.", "Solo el incumplimiento reiterado se establece como infracción, que tendrá la consideración de grave."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 23, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿cual de los siguientes datos personales se podrían revelar sin autorización del afectado si una norma con rango de ley lo amparara?", "Datos personales que hagan referencia al origen racial.", "Datos personales que revelen la ideología.", "Datos personales que revelen la afiliación sindical.", "Datos personales que revelen la religión o creencias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 24, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, indique cual de las siguientes respuestas no supondrá una limitación para ejercer el derecho de acceso.", "La prevención, investigación y sanción de los ilícitos penales, administrativos o disciplinarios.", "Los intereses económicos y comerciales.", "Las funciones militares de vigilancia, inspección y control.", "La seguridad pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 25, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, si la solicitud de acceso se refiere a información que no obre en poder del sujeto al que se dirige:", "Éste la remitirá al competente, si lo conociera, e informará de esta circunstancia al solicitante.", "Éste inadmitirá a trámite la solicitud e informará de esta circunstancia al solicitante.", "Éste la remitirá al competente, si lo conociera, y el órgano competente informará al solicitante de haber recibido la solicitud.", "Éste inadmitirá a trámite la solicitud, indicando que órgano es el competente a su parecer."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 26, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿Cual de las siguientes resoluciones en las que se conceda o deniegue el acceso a la información pública no necesitan motivarse?", "Las que permitan el acceso cuando no haya habido oposición de un tercero.", "Las que denieguen el acceso.", "Las que concedan el acceso parcial.", "Las que concedan el acceso a través de una modalidad distinta a la solicitada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 27, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, la reclamación ante el Consejo de Transparencia y Buen Gobierno:", "Tendrá la consideración de sustitutiva del recurso de reposición.", "Tendrá la consideración de sustitutiva del recurso contencioso-administrativo.", "Tendrá la consideración de sustitutiva del recurso de alzada.", "Tendrá la consideración de sustitutiva del recurso extraordinario de revisión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 28, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, la reclamación ante el Consejo de Transparencia y Buen Gobierno se interpondrá:", "en el plazo de un mes a contar desde el día siguiente al de la notificación del acto impugnado o desde el día siguiente a aquel en que se produzcan los efectos del silencio administrativo.", "en el plazo de dos meses a contar desde el día siguiente al de la notificación del acto impugnado o desde el día siguiente a aquel en que se produzcan los efectos del silencio administrativo.", "en el plazo de tres meses a contar desde el día siguiente al de la notificación del acto impugnado o desde el día siguiente a aquel en que se produzcan los efectos del silencio administrativo.", "en el plazo de un mes a contar desde el día siguiente al de la notificación del acto impugnado o de dos meses desde el día siguiente a aquel en que se produzcan los efectos del silencio administrativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 29, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, las resoluciones del Consejo de Transparencia y Buen Gobierno se publicarán:", "Por medios electrónicos y a la vez que se notifique a los interesados.", "Por medios electrónicos y una vez se hayan notificado a los interesados.", "En el diario oficial correspondiente y a la vez que se notifique a los interesados.", "En el diario oficial correspondiente y una vez se hayan notificado a los interesados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 30, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, el presidente del Consejo de Transparencia y Buen Gobierno tiene que comunicar las resoluciones de las reclamaciones que dicte:", "Al Defensor del Pueblo.", "Al Gobierno.", "Al Presidente del Gobierno.", "Al Congreso de los Diputados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 31, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, indique cual es la normativa que regula el acceso por parte de quienes tengan la condición de interesados, en un procedimiento administrativo en curso, a los documentos que se integren en el mismo.", "La Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno.", "La normativa reguladora del correspondiente procedimiento administrativo.", "La ley 1/2019, de 31 de enero, del Gobierno de las Illes Balears", "La ley 4/2011, de 31 de marzo, de la buena administración y del buen gobierno de las Illes Balears"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 32, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, señala qué información pública se corresponde a información económica, presupuestaria y estadística que deben publicar las administraciones públicas:", "Información relativa a las funciones que desarrollan.", "Las memorias e informes que conformen los expedientes de elaboración de los textos normativos.", "Los anteproyectos de Ley y los proyectos de decretos legislativos cuya iniciativa les corresponda.", "Las retribuciones percibidas anualmente por los altos cargos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 33, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, la formalización del acceso a la información pública:", "Cuando no pueda darse el acceso en el momento de la notificación de la resolución deberá otorgarse, en cualquier caso, en un plazo no superior a diez días.", "Cuando no pueda darse el acceso en el momento de la notificación de la resolución deberá otorgarse, en cualquier caso, en un plazo no superior a quince días.", "Cuando no pueda darse el acceso en el momento de la notificación de la resolución deberá otorgarse, en cualquier caso, en un plazo no superior a un mes.", "Cuando no pueda darse el acceso en el momento de la notificación de la resolución deberá otorgarse, preferentemente, en un plazo no superior a quince días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 34, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, el plazo máximo para resolver y notificar la resolución de la reclamación ante el Consejo de Transparencia y Buen Gobierno:", "Será de un mes, transcurrido el cual, la reclamación se entenderá estimada.", "Será de un mes, transcurrido el cual, la reclamación se entenderá desestimada.", "Será de tres meses, transcurrido el cual, la reclamación se entenderá estimada.", "Será de tres meses, transcurrido el cual, la reclamación se entenderá desestimada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 35, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, para el cumplimiento de las obligaciones previstas en relación a la transparencia de la actividad pública:", "Las corporaciones de Derecho Público deberán establecer sus propios procedimientos.", "Las corporaciones de Derecho Público no están obligadas a cumplirlas.", "Las corporaciones de Derecho Público podrán celebrar convenios de colaboración con la Administración Pública correspondiente.", "Las corporaciones de Derecho Público delegarán dichas obligaciones a la Administración Pública correspondiente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 36, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno,¿cuándo podrá ser limitado el derecho de acceso a la información pública relacionada con la política económica y monetaria?", "Cuando acceder a la información suponga un perjuicio para la propia política económica y monetaria.", "En ningún caso, prevaleciendo el derecho a la información.", "Cuando así lo establezca el Banco de España.", "En todo caso, dada la importancia de la política económica y monetaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 37, "Cuando se solicita el acceso a la información pública la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno establece una serie de garantías para la protección de determinados datos personales, estas garantías:", "Se aplicarán en todo caso.", "No se aplicarán si así lo considera el órgano encargado de resolver la solicitud de información.", "No se aplicarán si el acceso se efectúa previa disociación de los datos de carácter personal de modo que se impida la identificación de las personas afectadas.", "Se aplicarán según consideración del órgano que posee la información."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 38, "Señale la respuesta falsa respecto a la solicitud de acceso a la información pública según la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno:", "La resolución en la que se conceda o deniegue el acceso deberá notificarse al solicitante y a los terceros afectados que así lo hayan solicitado en el plazo máximo de 15 días desde la recepción de la solicitud por el órgano competente para resolver.", "Transcurrido el plazo máximo para resolver sin que se haya dictado y notificado resolución expresa se entenderá que la solicitud ha sido desestimada.", "Las resoluciones dictadas en materia de acceso a la información pública son recurribles directamente ante la Jurisdicción Contencioso-administrativa, sin perjuicio de la posibilidad de interposición de la reclamación potestativa prevista en el artículo 24.", "El incumplimiento reiterado de la obligación de resolver en plazo tendrá la consideración de infracción grave a los efectos de la aplicación a sus responsables del régimen disciplinario previsto en la correspondiente normativa reguladora."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 39, "Según la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno de transparencia, ¿cual de las siguientes opciones no es un miembro de la Comisión de Transparencia y Buen Gobierno:", "Un representante de la Autoridad Independiente de Responsabilidad Fiscal.", "Un representante de la Agencia Española de Protección de Datos.", "Un representante de la Federación Española de Municipios y Provincias.", "Un Senador."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 40, "El Consejo de Transparencia y Buen Gobierno, se configura como:", "Comisión interministerial presidida por el titular del Ministerio competente en Función Pública.", "Consejo interterritorial en el que están representados el Estado y las Comunidades Autónomas.", "Organismo público adscrito al actual Ministerio de Hacienda  y Función Pública.", "Organismo comisionado por las Cortes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 41, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿Cual de las siguientes respuestas No es una finalidad del Consejo de Transparencia y Buen Gobierno?", "Salvaguardar el ejercicio de derecho de acceso a la información pública", "Garantizar la observancia de las disposiciones de buen gobierno", "Promover la transparencia de la actividad pública", "Garantizar la publicidad de las reuniones del Consejo de Ministros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 42, "De acuerdo con la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, entre los principios de buena regulación se encuentran:", "El de transparencia y publicidad.", "El de publicidad pero no el de transparencia.", "El de transparencia pero no el de publicidad.", "Ninguno de los dos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 43, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, indique cual de las siguientes respuestas no supondrá una limitación para ejercer el derecho de acceso.", "Las funciones administrativas de vigilancia, inspección y control.", "El secreto político.", "La protección del medio ambiente.", "El secreto profesional y la propiedad intelectual e industrial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 44, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, si la información solicitada incluyese datos personales que hagan referencia al origen racial:", "El acceso solo se podrá autorizar en caso de que se cuente con el consentimiento expreso y por escrito del afectado.", "El acceso solo se podrá autorizar en caso de que se cuente con el consentimiento expreso, por escrito o por comparecencia apud acta del afectado.", "El acceso solo se podrá autorizar en caso de que se cuente con el consentimiento expreso del afectado o si aquel estuviera amparado por una norma con rango de ley.", "El acceso solo se podrá autorizar en caso de que estuviera amparado por una norma con rango de ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 45, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, la reclamación ante el Consejo de Transparencia y Buen Gobierno:", "Podrá interponerse con carácter obligatorio y previo a su impugnación en vía contencioso-administrativa.", "Podrá interponerse con carácter obligatorio y substitutivo del recurso  contencioso-administrativo.", "Podrá interponerse con carácter potestativo y substitutivo del recurso  contencioso-administrativo.", "Podrá interponerse con carácter potestativo y previo a su impugnación en vía contencioso-administrativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 46, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, las resoluciones del Consejo de Transparencia y Buen Gobierno se publicarán:", "Con su texto íntegro, por medios electrónicos.", "Con su texto íntegro, en el diario oficial correspondiente.", "Previa disociación de los datos de carácter personal que contuvieran, por medios electrónicos.", "Previa disociación de los datos de carácter personal que contuvieran, en el diario oficial correspondiente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 47, "¿Cuál de los siguientes no es un principio técnico de los mencionados en la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno al que debe atenerse la información publicada en el Portal de Transparencia de la Administración General del Estado?", "Compatibilidad", "Interoperabilidad", "Reutilización.", "Accesibilidad"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 48, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, el procedimiento para el ejercicio del derecho de acceso se iniciará con la presentación de la correspondiente solicitud, que deberá dirigirse:", "Al Portal de Transparencia de cada administración.", "Al Portal de Transparencia del Estado.", "Al Consejo de Transparencia y Buen Gobierno.", "Al titular del órgano administrativo o entidad que posea la información."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 49, "En relación al derecho de acceso a la información pública, y de acuerdo con lo que prevé la disposición adicional cuarta de la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿Que órgano resuelve actualmente las reclamaciones previstas en el artículo 24 de esta ley?", "La Comisión para las Reclamaciones de Acceso a la Información Pública.", "El Consejo de Transparencia y Buen Gobierno, en aplicación del convenio firmado con este ente el 9 de diciembre de 2021.", "El Consejo de Transparencia y Buen Gobierno, en aplicación del contrato firmado con este ente el 9 de diciembre de 2021.", "El Consejo de Transparencia y Buen Gobierno, en aplicación de la encomienda de gestión firmada con este ente el 9 de diciembre de 2021."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 50, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, el Consejo de Transparencia y Buen Gobierno:", "Actúa con autonomía y plena independencia en el cumplimiento de sus fines.", "El Ministro competente en Hacienda puede establecer directrices para el correcto cumplimiento de sus fines.", "No actúa con autonomía al no tener personalidad jurídica.", "No tiene personalidad jurídica propia pero sí independencia funcional."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 51, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, si la solicitud de información no identifica de forma suficiente la información solicitada:", "Se pedirá al solicitante que la concrete en un plazo de quince días, con indicación de que, en caso de no hacerlo, se entenderá que renuncia al derecho de solicitud de dicha información.", "Se pedirá al solicitante que la concrete en un plazo de diez días, con indicación de que, en caso de no hacerlo, se entenderá que renuncia al derecho de solicitud de dicha información.", "Se pedirá al solicitante que la concrete en un plazo de quince días, con indicación de que, en caso de no hacerlo, se le tendrá por desistido.", "Se pedirá al solicitante que la concrete en un plazo de diez días, con indicación de que, en caso de no hacerlo, se le tendrá por desistido."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 52, "La Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, de transparencia, acceso a la información pública y buen gobierno, indique que en la composición de la Comisión de Transparencia y Buen Gobierno se incluye:", "Un representante de la Secretaría de Estado de Igualdad.", "Un representante de la Abogacía del Estado.", "Un representante de la Secretaría de Estado de Políticas Públicas.", "Un representante de la Autoridad Independiente de Responsabilidad Fiscal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 53, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno de transparencia, indique la respuesta falsa:", "La publicidad activa y el derecho de acceso fomentan la transparencia y la participación en la actividad pública.", "En la publicidad activa la Administración pone los datos a disposición de la ciudadanía, en portales y páginas web, sin esperar a que los ciudadanos los demanden, proactivamente.", "En el derecho de acceso a la información pública la Administración responde a las demandas de información por parte de los ciudadanos.", "En el derecho de acceso a la información pública los ciudadanos acceden a la información pública puesta a disposición por la Administración en portales y páginas web."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 54, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, las comunidades autónomas para la resolución de la reclamación prevista en relación al derecho de acceso a la información pública:", "Deberán crear un órgano propio para su resolución.", "Tendrán que firmar un convenio con el Consejo de Transparencia y Buen Gobierno.", "Atribuirán esta competencia al Consejo de Transparencia y Buen Gobierno.", "Podrán atribuir esta competencia al Consejo de Transparencia y Buen Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 55, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, cuando la información objeto de la solicitud, aun obrando en poder del sujeto al que se dirige, haya sido elaborada o generada en su integridad o parte principal por otro órgano:", "Se le remitirá la solicitud a éste, informandole de forma motivada sobre la conveniencia o no de facilitar el acceso.", "Se inadmitirá la solicitud.", "Se le remitirá la solicitud a éste para que decida sobre el acceso.", "Se resolverá sobre el acceso, informando posteriormente al órgano que ha elaborado o generado la información."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 56, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿cual de los siguientes datos personales se podrían revelar si el afectado los hubiese hecho manifiestamente públicos los datos con anterioridad?", "Datos personales que hagan referencia a la salud.", "Datos personales que incluyesen datos genéticos o biométricos.", "Datos personales que hagan referencia a la vida sexual.", "Datos personales que revelen la afiliación sindical."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 57, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, indique cual de las siguientes respuestas no supondrá una limitación para ejercer el derecho de acceso.", "La seguridad internacional.", "La defensa.", "Las relaciones exteriores.", "La seguridad pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 58, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, señala que información pública se corresponde a información económica, presupuestaria y estadística que deben publicar las administraciones públicas:", "Las memorias e informes que conformen los expedientes de elaboración de los textos normativos.", "Los proyectos de Reglamentos cuya iniciativa les corresponda.", "La información estadística necesaria para valorar el grado de cumplimiento y calidad de los servicios públicos que sean de su competencia.", "Los Anteproyectos de Ley y los proyectos de Decretos Legislativos cuya iniciativa les corresponda."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 24, 59, "De acuerdo con la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, entre los derechos de las personas, en sus relaciones con las Administraciones Públicas, se encuentra:", "El acceso a la información pública, archivos y registros.", "El acceso a la información pública, expedientes y registros.", "El acceso a la información pública, expedientes y circulares.", "El acceso a la información pública, archivos y circulares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 1, "De acuerdo con el artículo 135 de la Constitución española:", "Una ley orgánica tiene que fijar el déficit estructural máximo permitido al Estado, a las comunidades autónomas y a las entidades locales.", "Las entidades locales tienen que presentar equilibrio presupuestario.", "El Estado, las comunidades autónomas y las entidades locales tienen que estar autorizados por ley para emitir deuda pública o contraer crédito.", "Los límites de déficit estructural y de volumen de deuda pública sólo se pueden rebasar en casos de catástrofes naturales, recesión económica o situaciones de emergencia extraordinaria, valorados por la mayoría absoluta de los miembros del Congreso y del Senado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 2, "De acuerdo con el artículo 137 de la Constitución española:", "El Estado se organiza territorialmente en municipios y en comunidades autónomas.", "El Estado se organiza territorialmente en municipios y en las comunidades autónomas que se constituyan.", "El Estado se organiza territorialmente en municipios, en provincias y en las comunidades autónomas que se constituyan.", "El Estado se organiza territorialmente en municipios, en provincias, en islas y en las comunidades autónomas que se constituyan."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 3, "De acuerdo con los artículos 137, 140 y 141 de la Constitución española:", "Los municipios y las provincias tienen autonomía para la gestión de sus respectivos intereses.", "Las islas tienen que tener una administración propia en forma de cabildos o consejos.", "Las respuestas a) y b) son correctas.", "Ninguna de las respuestas anteriores es correcta"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 4, "El artículo 142 de la Constitución española garantiza:", "El principio de suficiencia financiera de las haciendas locales.", "El principio de autonomía financiera de las haciendas locales.", "Las respuestas a) y b) son correctas.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 5, "El artículo 141 de la Constitución española garantiza:", "La posibilidad de crear federaciones de municipios distintas de la provincia.", "La posibilidad de crear agrupaciones de municipios distintas de la provincia.", "La posibilidad de crear federaciones de municipios distintas de la comunidad autónoma.", "La posibilidad de crear agrupaciones de municipios distintas de la comunidad autónoma."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 6, "De acuerdo con el artículo 142 de la Constitución española, las haciendas locales se tienen que sostener fundamentalmente por<A[por|para]> los ingresos siguientes:", "Tributos propios.", "Participación en tributos del Estado.", "Participación en tributos de la respectiva comunidad autónoma.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 7, "De acuerdo con los artículos 148 y 149 de la Constitución española y con los artículos 30 a 32 del Estatuto de autonomía de las Illes Balears, la competencia de la Comunidad Autónoma de las Illes Balears en materia de régimen local:", "Es una competencia exclusiva que incluye toda la función legislativa y la función ejecutiva.", "Es una competencia no exclusiva que incluye el despliegue de la legislación básica estatal.", "Es una competencia no exclusiva que incluye la función ejecutiva.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 8, "De acuerdo con los artículos 70 y 71 del Estatuto de Autonomía de las Illes Balears, la competencia de los consejos insulares en materia de régimen local:", "Es una competencia propia de los consejos insulares.", "Es una competencia susceptible de ser transferida a los consejos insulares.", "Es una competencia susceptible de ser delegada a los consejos insulares.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 9, "De acuerdo con el artículo 72 del Estatuto de Autonomía de las Illes Balears, los consejos insulares ejercen la potestad reglamentaria:", "En las competencias transferidas.", "En las competencias transferidas y en las delegadas.", "En las competencias propias.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 10, "De acuerdo con el artículo 73 del Estatuto de autonomía de las Illes Balears, los consejos insulares ejercen la actividad de fomento:", "En las competencias transferidas.", "En las competencias propias.", "En las competencias delegadas.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 11, "Los artículos 74 y 75 del Estatuto de Autonomía de las Illes Balears no prevén expresamente:", "Una conferencia de presidentes de los consejos insulares, integrada por los presidentes de cada uno de los consejos insulares.", "El derecho de los municipios a asociarse y a cooperar entre sí por medio de la constitución de mancomunidades, consorcios y asociaciones.", "Que el Parlamento de las Illes Balears apruebe una ley de capitalidad especial para el municipio de Palma.", "Que el Parlamento de las Illes Balears apruebe una ley de capitalidad especial para el municipio de Ibiza."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 12, "El artículo 75 del Estatuto de autonomía de las Illes Balears no prevé expresamente:", "Que el Parlamento de las Illes Balears apruebe una ley de régimen local para las Illes Balears.", "Que los municipios puedan ejercer competencias transferidas por el Estado o por la Administración de la Comunidad Autónoma de las Illes Balears.", "Que los municipios puedan ejercer competencias delegadas por el Estado, por la Administración de la Comunidad Autónoma de las Illes Balears o por los consejos insulares.", "Que los municipios puedan ejercer competencias transferidas por los consejos insulares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 13, "De acuerdo con el artículo 75 del Estatuto de autonomía de las Illes Balears y con los artículos 27, 47 y 123 de la Ley reguladora de las bases de régimen local:", "La delegación de competencias del Estado, de la Administración de la Comunidad Autónoma de las Illes Balears o de un consejo insular a favor de los municipios requiere la aceptación del municipio correspondiente.", "La transferencia de competencias de los consejos insulares a los ayuntamientos requiere la aceptación del municipio correspondiente.", "Las respuestas a) y b) son correctas.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 14, "De acuerdo con el artículo 75 del Estatuto de autonomía de las Illes Balears y con los artículos 27, 47 y 123 de la Ley reguladora de las bases del régimen local, la aceptación por parte de un municipio de competencias delegadas por el Estado, una comunidad autónoma o un consejo insular:", "Requiere acuerdo del Pleno del ayuntamiento correspondiente, por mayoría absoluta del número legal de miembros de la Corporación.", "Requiere acuerdo del Pleno del ayuntamiento correspondiente, por mayoría absoluta de los asistentes.", "Requiere acuerdo del Pleno del ayuntamiento correspondiente, por mayoría simple de los asistentes.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 15, "De acuerdo con los artículos 75, 81 y 82 del Estatuto de Autonomía de las Illes Balears, los municipios, en el ejercicio de las competencias de estos, están sujetos:", "Al control de constitucionalidad y de legalidad.", "Al control jurisdiccional.", "A la fiscalización externa de la Sindicatura de Cuentas.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 16, "Los actos de las entidades locales que atenten gravemente el interés general de España pueden ser suspendidos, previo requerimiento de anulación al presidente de la entidad, con la adopción de las medidas adecuadas para la protección del interés general mencionado:", "Por el delegado del Gobierno de España en el ámbito de la comunidad autónoma correspondiente.", "Por el presidente de la comunidad autónoma correspondiente, en nombre del rey.", "Por el Tribunal Constitucional.", "Por el Senado, por mayoría absoluta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 17, "Los actos de las entidades locales que atenten gravemente el interés general de las Illes Balears pueden ser suspendidos, previo requerimiento de anulación al presidente de la entidad, con la adopción de las medidas adecuadas para la protección del interés general mencionado:", "Por el Parlamento de las Illes Balears, por mayoría absoluta.", "Por el presidente de las Illes Balears.", "Por el presidente del consejo insular correspondiente.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 18, "La vulneración de la autonomía local constitucionalmente garantizada por leyes estatales o autonómicas:", "Sólo se puede declarar expresamente por el Tribunal Constitucional por la vía de la declaración de inconstitucionalidad de la ley de la cual se trate en cada caso.", "Sólo se puede declarar expresamente por el Tribunal Supremo por la vía del recurso de casación en defensa de la autonomía local.", "Se puede declarar expresamente por el Tribunal Constitucional por la vía del conflicto en defensa de la autonomía local, sin perjuicio de que, además, la ley de que se trate en cada caso pueda ser declarada inconstitucional por el mismo Tribunal Constitucional.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 19, "La resolución de los conflictos en defensa de la autonomía local en los que se aprecie la vulneración de la autonomía local constitucionalmente garantizada:", "Implica automáticamente la inconstitucionalidad de la ley estatal o autonómica determinante de la vulneración.", "Implica automáticamente la inconstitucionalidad de la ley o del reglamento estatal o autonómico determinante de la vulneración.", "No determina automáticamente la inconstitucionalidad de la ley estatal o autonómica determinante de la vulneración, sin perjuicio que se eleve al Pleno del Tribunal Constitucional la cuestión de inconstitucionalidad correspondiente.", "No determina automáticamente la inconstitucionalidad de la ley o del reglamento estatal o autonómico determinante de la vulneración, sin perjuicio que se eleve al Pleno del Tribunal Constitucional la cuestión de inconstitucionalidad correspondiente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 20, "El envío periódico de las entidades locales a la Administración del Estado y a la Administración de la comunidad autónoma correspondiente de copias o extractos comprensivos de los actos y acuerdos adoptados por la entidad local, que regula el artículo 56 de la Ley reguladora de las bases de régimen local, se fundamenta, de acuerdo con la doctrina del Tribunal Constitucional a este respeto:", "En el control de legalidad que pueden ejercer las administraciones superiores (estatales y autonómicas) respecto de las administraciones inferiores (entidades locales).", "En el control de oportunidad que pueden ejercer las administraciones superiores (estatales y autonómicas) respecto de las administraciones inferiores (entidades locales).", "Las respuestas a) y b) son correctas.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 21, "De acuerdo con los artículos 31 y 133 de la Constitución española, las corporaciones locales:", "Tienen potestad originaria para establecer tributos propios, mediante las ordenanzas correspondientes.", "Tienen potestad derivada para exigir los tributos propios que establezca a este efecto el legislador estatal, mediante, si procede, las ordenanzas correspondientes.", "Tienen potestad derivada para exigir los tributos propios que establezca a este efecto el legislador de la respectiva comunidad autónoma, mediante, si procede, las ordenanzas correspondientes.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 22, "La regulación reglamentaria de los tributos propios de los municipios:", "Se tiene que hacer por medio de las ordenanzas fiscales que regulan los artículos 15 a 19 del Texto refundido de la Ley reguladora de las haciendas locales.", "Se tiene que hacer por medio de las ordenanzas locales que regula el artículo 49 de la Ley reguladora de las bases de régimen local.", "Se tiene que hacer por medio de las bases de ejecución de los presupuestos.", "Ninguna de las respuestas anteriores es correcta, pues los tributos propios municipales no pueden ser objeto de regulación reglamentaria local."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 23, "De acuerdo con el artículo 59.1 del Texto refundido de la Ley reguladora de las haciendas locales, constituyen impuestos obligatorios, en el sentido de que se tienen que exigir en todo caso por los ayuntamientos:", "El impuesto sobre bienes inmuebles y el impuesto sobre vehículos de tracción mecánica.", "El impuesto sobre bienes inmuebles, el impuesto sobre actividades económicas y el impuesto sobre vehículos de tracción mecánica.", "El impuesto sobre bienes inmuebles, el impuesto sobre actividades económicas, el impuesto sobre vehículos de tracción mecánica y el impuesto sobre construcciones, instalaciones y obras.", "El impuesto sobre bienes inmuebles, el impuesto sobre actividades económicas, el impuesto sobre vehículos de tracción mecánica, el impuesto sobre construcciones, instalaciones y obras y el impuesto sobre el incremento de valor de los terrenos de naturaleza urbana."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 24, "De acuerdo con el artículo 15 en relación con el artículo 59 del Texto refundido de la Ley reguladora de las haciendas locales, en caso de que un ayuntamiento no apruebe ningún acuerdo de imposición ni ninguna ordenanza fiscal respecto de los impuestos propios del municipio:", "No puede exigir ninguno de estos impuestos.", "Tiene que exigir en todo caso el impuesto sobre bienes inmuebles y el impuesto sobre vehículos de tracción mecánica a partir de las cuantías máximas que establece el mismo Texto refundido de la Ley reguladora de las haciendas locales.", "Tiene que exigir en todo caso el impuesto sobre bienes inmuebles, el impuesto sobre actividades económicas y el impuesto sobre vehículos de tracción mecánica a partir de las cuantías mínimas que establece el mismo Texto refundido de la Ley reguladora de las haciendas locales.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 25, "El establecimiento de los precios públicos por<A[para|por]> las entidades locales:", "Se tiene que hacer por el Pleno de la corporación, por medio de las ordenanzas fiscales que regulan los artículos 15 a 19 del Texto refundido de la Ley reguladora de las haciendas locales.", "Se tiene que hacer por el Pleno de la corporación, por medio de las bases de ejecución de los presupuestos.", "Se tiene que hacer por el presidente o la presidenta de la corporación, por medio de un decreto.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 26, "De acuerdo con el artículo 47 del Texto refundido de la Ley reguladora de las haciendas locales, la fijación de la cuantía concreta de un precio público establecido por la corporación local en razón de la prestación de un determinado servicio por un organismo autónomo local:", "Corresponde en todo caso al Pleno de la corporación.", "Se puede atribuir al presidente de la corporación.", "Se puede atribuir al mismo organismo autónomo.", "Se puede atribuir al mismo organismo autónomo, a menos que el precio que se prevea fijar no cubra el coste del servicio, en cuyo caso lo tiene que fijar el Pleno de la corporación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 27, "De acuerdo con la Ley general tributaria y el Texto refundido de la Ley reguladora de las haciendas locales, son tributos locales:", "Los impuestos.", "Los impuestos y las tasas.", "Los impuestos, las tasas y las contribuciones especiales.", "Los impuestos, las tasas, las contribuciones especiales y los precios públicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 28, "De acuerdo con la Ley general tributaria y el Texto refundido de la Ley reguladora de las haciendas locales, la prestación patrimonial que se pretenda exigir en razón de la utilización privativa o el aprovechamiento especial del dominio público local tiene que ser:", "Una tasa.", "Un precio público.", "Una prestación patrimonial pública no tributaria (tarifa).", "Una contribución especial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 29, "De acuerdo con la Ley general tributaria y el Texto refundido de la Ley reguladora de las haciendas locales, la prestación patrimonial que se pretenda exigir en razón de la prestación de un servicio público local en régimen de derecho administrativo a cargo de un organismo autónomo local, cuando este servicio sea imprescindible para la vida privada o social del usuario, tiene que ser:", "Una tasa.", "Una tasa, a menos que el servicio se preste también por<A[por|para]> el sector privado, en cuyo caso tiene que ser un preciopúblico.", "Un precio público en todo caso.", "Una prestación patrimonial pública no tributaria (tarifa)."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 30, "De acuerdo con la Ley general tributaria y el Texto refundido de la Ley reguladora de las haciendas locales, la prestación patrimonial que se pretenda exigir en razón de la prestación de un servicio por parte de una entidad local en régimen de derecho administrativo, cuando este servicio no se preste por el sector privado, tiene que ser:", "Un precio público.", "Una tasa.", "Una tasa, a menos que el servicio no sea imprescindible para la vida privada o social del usuario, en cuyo caso tiene que ser un precio público.", "Una contribución especial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 31, "De acuerdo con la Ley general tributaria, el Texto refundido de la Ley reguladora de las haciendas locales y la Ley de contratos del sector público, la prestación patrimonial que se pretenda exigir en razón de la prestación de un servicio público local a cargo de una sociedad mercantil local, cuando este servicio sea imprescindible para la vida privada o social del usuario, tiene que ser:", "Una contribución especial.", "Una tasa, a menos que el servicio se preste también por<A[por|para]> el sector privado, en cuyo caso tiene que ser un precio público.", "Un precio público en todo caso.", "Una prestación patrimonial pública no tributaria (tarifa)."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 32, "De acuerdo con la Ley general tributaria, el Texto refundido de la Ley reguladora de las haciendas locales y la Ley de contratos del sector público, la prestación patrimonial que se pretenda exigir en razón de la prestación de un servicio público local a cargo de una sociedad concesionaria del servicio, cuando este servicio no se preste por el sector privado, tiene que ser:", "Una contribución especial.", "Una tasa, a menos que el servicio no sea imprescindible para la vida privada o social del usuario, en cuyo caso tiene que ser un precio público.", "Un precio público en todo caso.", "Una prestación patrimonial pública no tributaria (tarifa)."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 33, "De acuerdo con el artículo 3 de la Ley reguladora de las bases de régimen local, son entidades locales territoriales:", "El municipio y la provincia.", "El municipio, la provincia y la isla en los archipiélagos balear y canario.", "El municipio, la provincia, la isla en los archipiélagos balear y canario, y las comarcas.", "El municipio, la provincia, la isla en los archipiélagos balear y canario, las comarcas y las mancomunidades de municipios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 34, "De acuerdo con el artículo 7 de la Ley reguladora de las bases de régimen local, las entidades locales:", "Sólo pueden ejercer las competencias propias de estas entidades determinadas por ley.", "Sólo pueden ejercer las competencias propias de estas entidades determinadas por ley y las competencias que se les atribuyan por delegación.", "Pueden ejercer las competencias propias de estas entidades determinadas por ley y las atribuidas por delegación, como también cualquier otra actividad o servicio en el ámbito de los intereses públicos respectivos siempre que eso no implique la ejecución simultánea del mismo servicio con otra administración pública.", "Pueden ejercer las competencias propias de estas entidades determinadas por ley y las atribuidas por delegación, como también cualquier otra actividad o servicio en el ámbito de los intereses públicos respectivos siempre que eso no implique la ejecución simultánea del mismo servicio con otra administración pública y, además, no se ponga en riesgo la sostenibilidad financiera del conjunto de la hacienda local."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 35, "De acuerdo con el artículo 11 de la Ley reguladora de las bases del régimen local:", "El municipio es la entidad local básica de la organización territorial del Estado.", "Los municipios y las provincias son las entidades locales básicas de la organización territorial del Estado.", "Los municipios, las provincias y las islas son las entidades locales básicas de la organización territorial del Estado.", "Los municipios, las provincias, las islas y las comarcas son las entidades locales básicas de la organización territorial del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 36, "De acuerdo con el artículo 16 de la Ley reguladora de las bases de régimen local, los datos del padrón municipal:", "Sólo se pueden ceder a otras administraciones públicas con el consentimiento previo del interesado.", "Se pueden ceder a las instituciones estatales y autonómicas competentes para elaborar estadísticas oficiales sometidas al secreto estadístico, sin el consentimiento del interesado.", "Se pueden ceder a otras administraciones públicas que lo soliciten, sin el consentimiento del interesado, cuando sea necesario para el ejercicio de las competencias respectivas y se utilicen exclusivamente para asuntos en los que la residencia o el domicilio sean relevantes.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 37, "De acuerdo con el artículo 19 de la Ley reguladora de las bases de régimen local, el gobierno y la administración municipal corresponde:", "Al ayuntamiento en todo caso, integrado por el alcalde y los concejales.", "Al ayuntamiento, integrado por el alcalde y por los concejales, salvo los municipios que funcionen legalmente en régimen de concejo abierto.", "Al ayuntamiento, integrado por el alcalde, el teniente de alcalde y los concejales, salvo los municipios que funcionen legalmente en régimen de concejo abierto o en régimen de entidad local menor.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 38, "De acuerdo con el apartado 1 del artículo 20 de la Ley reguladora de las bases de régimen local, en todos los ayuntamientos tienen que existir necesariamente los órganos siguientes:", "El alcalde, los tenientes de alcalde y el pleno.", "El alcalde, los tenientes de alcalde, el pleno y la comisión especial de cuentas.", "El alcalde, los tenientes de alcalde, el pleno, la comisión especial de cuentas y la comisión especial de sugerencias y reclamaciones.", "El alcalde, los tenientes de alcalde, el pleno, la junta de gobierno local, la comisión especial de cuentas y la comisión especial de sugerencias y reclamaciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 39, "De acuerdo con la Ley reguladora de las bases de régimen local, las competencias que la legislación estatal y autonómica atribuyan a los municipios sin concretar el órgano competente para su ejercicio:", "Corresponden al pleno del ayuntamiento.", "Corresponden a la junta de gobierno local.", "Corresponden al concejal integrante de la junta de gobierno local competente en razón de la materia.", "Corresponden al alcalde del ayuntamiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 40, "De acuerdo con el artículo 26 de la Ley reguladora de las bases de régimen local, el servicio de prevención y extinción de incendios:", "Constituye un servicio que tienen que prestar obligatoriamente todos los municipios.", "Constituye un servicio que tienen que prestar obligatoriamente los municipios con población superior a 5.000 habitantes.", "Constituye un servicio que tienen que prestar obligatoriamente los municipios con población superior a 20.000 habitantes.", "Constituye un servicio que tienen que prestar obligatoriamente los municipios con población superior a 20.000 habitantes, bajo la coordinación de las diputaciones provinciales o la entidad equivalente en los términos que regula el apartado 2 del artículo 26 de la Ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 41, "De acuerdo con los artículos 25 y 26 de Ley reguladora de las bases del régimen local, la policía local:", "Constituye una materia respecto de la que la legislación estatal y la autonómica, en el ámbito de sus respectivas competencias legislativas, tienen que regular el ejercicio de competencias por los municipios como competencias propias de estos.", "Constituye un servicio que tienen que prestar obligatoriamente los municipios con población superior a 5.000 habitantes.", "Constituye un servicio que tienen que prestar obligatoriamente los municipios con población superior a 20.000 habitantes.", "Constituye un servicio que tienen que prestar obligatoriamente los municipios con población superior a 50.000 habitantes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 42, "De acuerdo con los artículos 26, 85 y 86 de la Ley reguladora de las bases del régimen local, el tratamiento de residuos:", "Constituye un servicio que tienen que prestar obligatoriamente los municipios con población superior a 5.000 habitantes.", "Constituye un servicio que, para los municipios con población inferior a 20.000 habitantes, se tiene que prestar bajo la coordinación de las diputaciones provinciales o la entidad equivalente en los términos que regula el apartado 2 del artículo 26 de la Ley.", "Constituye un servicio reservado legalmente a las entidades locales como servicio público local.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 43, "De acuerdo con el apartado 1 del artículo 32 de la Ley reguladora de las bases de régimen local, en todas las provincias tienen que existir necesariamente los órganos siguientes:", "El presidente y el pleno.", "El presidente, los vicepresidentes y el pleno.", "El presidente, los vicepresidentes, la junta de gobierno y el pleno.", "El presidente, los vicepresidentes, la junta de gobierno, el pleno y la comisión especial de cuentas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 44, "De acuerdo con la Ley reguladora de las bases de régimen local, la prestación de servicios de administración electrónica y la contratación centralizada en los municipios con población inferior a 20.000 habitantes:", "Es una competencia propia de los municipios.", "Es una competencia propia de los municipios, bajo la coordinación de las diputaciones provinciales o la entidad equivalente en los términos que regula el apartado 2 del artículo 26 de la Ley.", "Es una competencia propia de las diputaciones provinciales o la entidad equivalente.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 45, "De acuerdo con el apartado 1 del artículo 47 de la Ley reguladora de las bases de régimen local, los acuerdos de las corporaciones locales se adoptan, como regla general:", "Por mayoría simple de los miembros presentes.", "Por mayoría simple del número legal de miembros de la corporación.", "Por mayoría absoluta de los miembros presentes.", "Por mayoría absoluta del número legal de miembros de la corporación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 46, "De acuerdo con la Ley reguladora de las bases de régimen local, los actos administrativos dictados por las entidades locales:", "Son inmediatamente ejecutivos, a menos que una ley establezca lo contrario o cuando<A[cuando|cuándo]> se suspenda su eficacia de acuerdo con la ley.", "Son ejecutivos en la fecha en que, de acuerdo con el artículo 56 de la Ley reguladora de las bases de régimen local, se envíe a la Administración estatal y al autonómica la copia o el extracto correspondiente.", "Son ejecutivos en la fecha en que, de acuerdo con el artículo 65 de la Ley reguladora de las bases de régimen local, finalice el plazo de que disponen la Administración estatal y la autonómica para hacer el requerimiento de anulación correspondiente de que.", "Son ejecutivos en la fecha en que la Administración estatal y la autonómica comuniquen expresamente su conformidad a la entidad local."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 47, "La revisión de oficio de una liquidación tributaria nula de pleno derecho dictada por un órgano de una entidad local corresponde:", "Al presidente de la corporación.", "A la junta de gobierno de la corporación.", "Al pleno de la corporación.", "Al mismo órgano de la corporación que haya dictado el acto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 48, "La declaración de lesividad de un acto administrativo favorable al interesado dictado por<A[por|para]> un órgano de una entidad local corresponde:", "A la junta de gobierno de la corporación.", "Al pleno de la corporación.", "Al presidente de la corporación.", "Al<A[En|A]> mismo órgano de la corporación que haya dictado el acto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 49, "La rectificación de errores materiales, aritméticos o de hecho en los actos dictados por órganos de las entidades locales corresponde:", "Al pleno de la corporación.", "A la junta de gobierno de la corporación.", "Al presidente de la corporación.", "Al mismo órgano de la corporación que haya dictado el acto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 50, "De acuerdo con el artículo 112 de la Ley reguladora de las bases de régimen local, la estructura de los presupuestos de las entidades locales se tiene que determinar:", "Por el presidente de la misma entidad local.", "Por la junta de gobierno de la misma entidad local.", "Por la Administración del Estado.", "Por la Administración de la respectiva comunidad autónoma."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 51, "De acuerdo con el apartado 1 del artículo 121 de la Ley reguladora de las bases de régimen local, se consideran en todo caso municipios de gran población a efectos de aplicar la normativa que contiene el título X de la Ley:", "Los municipios con población superior a 200.000 habitantes.", "Los municipios con población superior a 200.000 habitantes, siempre que, además, sean capital de provincia.", "Los municipios con población superior a 250.000 habitantes y, además, los municipios que sean capital de provincia con población superior a 200.000 habitantes.", "Los municipios con población superior a 250.000 habitantes y, además, los municipios que sean capital de provincia con población superior a 175.000 habitantes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 52, "Contra los actos dictados por las entidades locales en materia tributaria:", "Sólo se puede interponer el recurso de reposición que regula el artículo 14.2 del Texto refundido de la Ley reguladora de las haciendas locales.", "Se puede interponer el recurso de reposición que regula el artículo 14.2 del Texto refundido de la Ley reguladora de las haciendas locales y también, con carácter preceptivo, la reclamación económico administrativa.", "Se puede interponer el recurso de reposición que regula el artículo 14.2 del Texto refundido de la Ley reguladora de las haciendas locales y también, en caso de municipios de gran población, con carácter preceptivo, la reclamación económico administrativa.", "Se puede interponer el recurso potestativo de reposición o el recurso de alzada, según el acto impugnado agote o no la vía administrativa, que regula la Ley de procedimiento administrativo común de las administraciones públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 53, "De acuerdo con el artículo 141 de la Ley reguladora de las bases de régimen local, las multas por la comisión de infracciones de ordenanzas locales tienen que respetar, a menos que una ley establezca otra cosa, los límites máximos siguientes:", "Las sanciones por<A[por|para]> infracciones muy graves, hasta 6.000 euros; las sanciones por<A[por|para]> infracciones graves, hasta 3.000 euros, y las sanciones por<A[por|para]> infracciones leves, hasta 1.500 euros.", "Las sanciones por<A[por|para]> infracciones muy graves, hasta 5.000 euros; las sanciones por<A[por|para]> infracciones graves, hasta 2.500 euros, y las sanciones por<A[por|para]> infracciones leves, hasta 1.000 euros.", "Las sanciones por<A[por|para]> infracciones muy graves, hasta 3.000 euros; las sanciones por<A[por|para]> infracciones graves, hasta 1.500 euros, y las sanciones por<A[por|para]> infracciones leves, hasta 750 euros.", "Las sanciones por<A[por|para]> infracciones muy graves, hasta 2.500 euros; las sanciones por<A[por|para]> infracciones graves, hasta 1.000 euros, y las sanciones por<A[por|para]> infracciones leves, hasta 500 euros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 54, "De acuerdo con el artículo 1 de la Ley municipal y de régimen local de las Illes Balears, la Comunidad Autónoma de las Illes Balears articula suorganización territorial en:", "Islas.", "Islas y municipios.", "Islas, municipios y agrupaciones de municipios.", "Islas, municipios, agrupaciones de municipios y entidades locales menores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 55, "De acuerdo con el artículo 5 de la Ley municipal y de régimen local de las Illes Balears, las entidades locales se rigen, además de por la legislación estatal básica y la misma Ley municipal y de régimen local de las Illes Balears:", "Por<A[Por|Para]> los reglamentos autonómicos sobre régimen local y por<A[por|para]> las otras disposiciones autonómicas conexas o complementarias.", "Por<A[Para|Por]> los reglamentos y las ordenanzas propias de cada entidad local.", "Las respuestas a) y b) son correctas.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 56, "De acuerdo con el artículo 8 de la Ley municipal y de régimen local de las Illes Balears, los consejos insulares se rigen, además de por la legislación estatal básica que les sea aplicable:", "Por una ley autonómica específica.", "Por la misma Ley municipal y de régimen local de las Illes Balears.", "Las respuestas a) y b) son correctas.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 57, "De acuerdo con el artículo 28 de la Ley municipal y de régimen local de las Illes Balears, una ley del Parlamento de las Illes Balears puede regular un régimen especial para los municipios:", "En los que radiquen las sedes de los consejos insulares.", "En los que se verifiquen circunstancias o funciones supramunicipales que lo aconseje.", "Las respuestas a) y b) son correctas.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 58, "De acuerdo con el artículo 65 de la Ley municipal y de régimen local de las Illes Balears, la dispensa en los municipios de la prestación de los servicios municipales obligatorios:", "No es posible.", "Es posible si así se establece reglamentariamente.", "Es posible si así se establece reglamentariamente, y se prevén los mecanismos de sustitución de la inactividad.", "Es posible si así se establece reglamentariamente o mediante un acuerdo del Gobierno de las Illes Balears."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 59, "De acuerdo con el artículo 66 de la Ley municipal y de régimen local de las Illes Balears, la utilización de técnicas de supervisión y control de los actos de las entidades locales:", "No es posible.", "Se puede fundamentar en una norma autonómica de rango legal autonómica y tiene que tener por objeto exclusivamente garantizar la legalidad.", "Se puede fundamentar en una noma autonómica de rango legal y tiene que tener por objeto garantizar la legalidad o asegurar el respeto a los intereses generales supraordenados a los intereses locales.", "Se tiene que limitar a las establecidas en la legislación estatal básica de régimen local."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 60, "De acuerdo con el artículo 85 de la Ley municipal y de régimen local de las Illes Balears, es necesario el informe previo del secretario o la secretaria y, si procede, del interventor o la interventora para la adopción de acuerdos en los casos, entre otros, siguientes:", "Cuando se trate de materias para las cuales se exija mayoría absoluta.", "Cuando se trate de materias para las cuales se exija mayoría absoluta o cualificada.", "Cuando se trate de acuerdos cuya resolución sea competencia del pleno o del presidente o la presidenta de la corporación.", "Cuándo lo ordene el presidente o la presidenta de la corporación o lo solicite una cuarta parte de los miembros de la corporación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 61, "De acuerdo con el artículo 101 de la Ley municipal y de régimen local de las Illes Balears, las disposiciones generales que corresponde aprobar a las entidades locales en el ejercicio de su potestad reglamentaria:", "Se denominan en todo caso reglamentos.", "Se denominan reglamentos si tienen por objeto regular la organización y el funcionamiento de la entidad local, y ordenanzas si tienen por objeto regular servicios públicos o cualquier otra materia.", "Se denominan reglamentos si tienen por objeto regular la organización y el funcionamiento de la entidad local o la prestación de servicios públicos, y ordenanzas si tienen por objeto regular cualquier otra materia.", "Se denominan ordenanzas si tienen por objeto regular tributos locales, y reglamentos si tienen por objeto regular cualquier otra materia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 62, "De acuerdo con el artículo 103 de la Ley municipal y de régimen local de las Illes Balears, los reglamentos, las ordenanzas y el contenido normativo de los planes urbanísticos, empiezan a regir:", "Cuando se publiquen íntegramente en el Boletín Oficial de las Illes Balears.", "Cuando<A[Cuando|Cuándo]> se publiquen íntegramente en el Boletín Oficial de las Illes Balears y, además, haya transcurrido el plazo de quince días hábiles de que dispone el Gobierno de las Illes Balears, el consejo insular y la Delegación del Gobierno para requerir, si procede, su anulación, de acuerdo con el artículo 113 de la misma Ley.", "Cuando<A[Cuando|Cuándo]> se publiquen íntegramente en el Boletín Oficial de las Illes Balears y, además, haya transcurrido el plazo de quince días hábiles de que dispone el Gobierno de las Illes Balears, el consejo insular y la Delegación del Gobierno para requerir, si procede<A[pega|ocurre]>, su anulación, de acuerdo con el artículo 113 de la misma Ley, con excepción de las ordenanzas fiscales, las cuales empiezan a regir cuando se haya publicado íntegramente el acuerdo definitivo y el texto de estas en el Boletín Oficial de las Illes Balears.", "Cuando se publiquen íntegramente en el Boletín Oficial del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 63, "De acuerdo con el artículo 123 de la Ley municipal y de régimen local de las Illes Balears, los alcaldes de los ayuntamientos pueden someter a consulta popular asuntos de competencia municipal:", "En ningún caso.", "Con el acuerdo previo del pleno de la corporación, adoptado por mayoría simple.", "Con el acuerdo previo del pleno de la corporación, adoptado por mayoría absoluta.", "Con el acuerdo previo del pleno de la corporación, adoptado por mayoría absoluta, siempre que no se trate de asuntos relativos a la hacienda local."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 64, "De acuerdo con el artículo 125 de la Ley municipal y de régimen local de las Illes Balears, los bienes de las entidades locales se clasifican en:", "Bienes de dominio público y bienes patrimoniales.", "Bienes de dominio público, bienes comunales y bienes patrimoniales.", "Bienes de uso público y bienes de uso privado.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 7, 65, "De acuerdo con el artículo 152 de la Ley municipal y de régimen local de las Illes Balears, la prestación de servicios públicos locales en régimen de monopolio:", "No es posible.", "Sólo es posible respecto de los servicios públicos esenciales reservados expresamente a las entidades locales por<A[por|para]> una norma de rango legal.", "Sólo es posible respecto de los servicios que las entidades locales tienen que prestar con carácter obligatorio de acuerdo con la legislación básica estatal de régimen local.", "Es posible respecto de todos los servicios que las entidades locales presten en el ámbito de sus competencias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 1, "Según el art. 25.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, la potestad sancionadora de las Administraciones Públicas se ejercerá cuando:", "No esté prohibida por una norma con rango de Ley.", "Haya sido expresamente reconocida por una norma con rango de Ley.", "Haya sido expresamente reconocida por una norma de rango legal o reglamentario.", "No esté prohibida por una norma de rango legal o reglamentario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 2, "Según el art. 25.3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, las disposiciones de este Capítulo:", "Podrán hacerse extensivas al ejercicio por las Administraciones Públicas de su potestad disciplinaria respecto del personal a su servicio.", "Serán extensivas al ejercicio por las Administraciones Públicas de su potestad disciplinaria respecto del personal a su servicio.", "No podrán hacerse extensivas al ejercicio por las Administraciones Públicas de su potestad disciplinaria respecto del personal a su servicio.", "Serán extensivas al ejercicio por las entidades del sector público de su potestad disciplinaria respecto del personal a su servicio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 3, "De acuerdo con el art. 25.4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, las disposiciones de este Capítulo, relativas al ejercicio por las Administraciones Públicas de la potestad sancionadora:", "No serán de aplicación respecto de quienes estén vinculados a ellas por relaciones reguladas por la legislación de contratos del sector público o por la legislación patrimonial de las Administraciones Públicas.", "Serán de aplicación respecto de quienes estén vinculados a ellas por relaciones reguladas por la legislación de contratos del sector público o por la legislación patrimonial de las Administraciones Públicas.", "Podrán ser de aplicación respecto de quienes estén vinculados a ellas por relaciones reguladas por la legislación de contratos del sector público o por la legislación patrimonial de las Administraciones Públicas.", "No serán de aplicación respecto de quienes estén vinculados a ellas por relaciones reguladas por la legislación sobre función pública o por la legislación patrimonial de las Administraciones Públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 4, "Según el art. 26.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, serán de aplicación las disposiciones sancionadoras vigentes:", "En el momento de resolver el procedimiento sancionador.", "En el momento de producirse los hechos que constituyan infracción administrativa.", "En el momento de la iniciación del procedimiento sancionador.", "En el momento que sean probados los hechos constitutivos de una infracción administrativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 5, "Según el art. 26.2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, las disposiciones sancionadoras producirán efecto retroactivo en cuanto favorezcan al presunto infractor:", "Salvo las sanciones pendientes de recurso al entrar en vigor la nueva disposición.", "Salvo las sanciones pendientes de cumplimiento al entrar en vigor la nueva disposición.", "Incluso respecto de las sanciones pendientes de cumplimiento al entrar en vigor la nueva disposición.", "Incluso respecto de las sanciones cumplidas al entrar en vigor la nueva disposición."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 6, "Según el art. 27.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público:", "Las infracciones administrativas se clasificarán por la Ley en leves, graves y muy graves.", "Las infracciones y las sanciones administrativas se clasificarán por la Ley en leves, graves y muy graves.", "Las infracciones administrativas se clasificarán en leves, graves y muy graves.", "Las infracciones y las sanciones administrativas se clasificarán en leves, graves y muy graves."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 7, "Según el art. 27.4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público:", "Las normas definidoras de infracciones y sanciones serán susceptibles de aplicación analógica.", "Las normas definidoras de infracciones y sanciones no serán susceptibles de aplicación analógica.", "Las normas definidoras de infracciones y sanciones podrán ser susceptibles de aplicación analógica.", "Las normas definidoras de infracciones no serán susceptibles de aplicación analógica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 8, "Según el art. 28.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, los patrimonios independientes o autónomos:", "Podrán ser sancionados por hechos constitutivos de infracción administrativa.", "Podrán ser sancionados por hechos constitutivos de infracción administrativa cuando una ley les reconozca capacidad de obrar.", "No podrán ser sancionados por hechos constitutivos de infracción administrativa.", "No podrán ser sancionados por hechos constitutivos de infracción administrativa cuando una ley les reconozca capacidad de obrar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 9, "Según el art. 28.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿cuándo pueden ser sancionados los grupos de afectados?", "Cuando una ley les reconozca capacidad de obrar.", "Cuando su estatuto les reconozca capacidad de obrar.", "Cuando una ley o un reglamento les reconozca capacidad de obrar.", "Cuando una ley, un reglamento o su estatuto les reconozca capacidad de obrar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 10, "Según el art. 28.2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, la indemnización por los daños y perjuicios que se deriven de una infracción administrativa:", "Será determinada y exigida por los órganos competentes.", "Será determinada y exigida por el órgano al que corresponda el ejercicio de la potestad sancionadora.", "Será determinada por el órgano perjudicado y exigida por el órgano al que corresponda el ejercicio de la potestad sancionadora.", "Será determinada y exigida por el órgano al que corresponda instruir el procedimiento de apremio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 11, "Según el art. 28.4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, las leyes reguladoras de los distintos regímenes sancionadores:", "No podrán tipificar como infracción el incumplimiento de la obligación de prevenir la comisión de infracciones administrativas por quienes se hallen sujetos a una relación de dependencia o vinculación.", "Podrán tipificar como infracción el incumplimiento de la obligación de prevenir la comisión de infracciones administrativas por quienes se hallen sujetos a una relación de dependencia o vinculación.", "Deberán tipificar como infracción el incumplimiento de la obligación de prevenir la comisión de infracciones administrativas por quienes se hallen sujetos a una relación de dependencia o vinculación.", "Podrán tipificar como infracción el incumplimiento de la obligación de prevenir la comisión de infracciones administrativas por quienes no se hallen sujetos a una relación de dependencia o vinculación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 12, "Según el art. 29.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, las sanciones administrativas:", "No pueden implicar privación de libertad.", "Pueden ser de naturaleza no pecuniaria.", "Pueden ser de naturaleza pecuniaria.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 13, "El art. 29.2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, dispone que:", "El establecimiento de sanciones pecuniarias podrá prever que la comisión de las infracciones tipificadas no resulte más beneficioso para el infractor que el cumplimiento de las normas infringidas.", "El establecimiento de sanciones pecuniarias deberá prever que la comisión de las infracciones tipificadas no resulte más beneficioso para el infractor que el cumplimiento de las normas infringidas.", "El establecimiento de sanciones deberá prever que la comisión de las infracciones tipificadas no resulte más beneficioso para el infractor que el cumplimiento de las normas infringidas.", "El establecimiento de sanciones podrá prever que la comisión de las infracciones tipificadas no resulte más beneficioso para el infractor que el cumplimiento de las normas infringidas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 14, "Según el art. 29.3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, se puede apreciar reincidencia:", "Por comisión en el término de un año de más de una infracción cuando así haya sido declarado por resolución definitiva en vía administrativa.", "Por comisión en el término de un año de más de una infracción de la misma naturaleza cuando así haya sido declarado por resolución definitiva en vía administrativa.", "Por comisión en el término de un año de más de una infracción cuando así haya sido declarado por resolución firme en vía administrativa.", "Por comisión en el término de un año de más de una infracción de la misma naturaleza cuando así haya sido declarado por resolución firme en vía administrativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 15, "Según el art. 29.4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, cuando lo justifique la debida adecuación entre la sanción que deba aplicarse con la gravedad del hecho constitutivo de la infracción y las circunstancias concurrentes, el órgano competente para resolver:", "Podrá calificar la infracción en el grado inferior.", "Deberá imponer la sanción en el grado inferior.", "Podrá imponer la sanción en el grado inferior.", "Deberá calificar la infracción en el grado inferior."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 16, "Según el art. 29.6 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, constituye una infracción continuada:", "La realización de una pluralidad de acciones u omisiones en ejecución de un plan preconcebido o aprovechando idéntica ocasión.", "La realización de una pluralidad de acciones u omisiones que infrinjan el mismo o semejantes preceptos administrativos.", "La realización de una pluralidad de acciones u omisiones que infrinjan el mismo o semejantes preceptos administrativos, en ejecución de un plan preconcebido o aprovechando idéntica ocasión.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 17, "Según el art. 30.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, en defecto de una ley específica las infracciones leves prescriben:", "Al año.", "A los seis meses.", "A los tres meses.", "Al mes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 18, "Según el art. 30.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, las sanciones impuestas por faltas graves prescriben:", "Según lo dispuesto en las leyes que las establezcan, y en su defecto, a los dos años.", "A los dos años.", "Según lo dispuesto en las leyes que las establezcan, y en su defecto, al año.", "A los tres años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 19, "Según el art. 30.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, en defecto de una ley específica prescriben al año:", "Las infracciones leves y las sanciones impuestas por faltas leves.", "Las sanciones impuestas por faltas leves.", "Las infracciones leves.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 20, "Según el art. 30.2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el plazo de prescripción de las infracciones continuadas o permanentes comenzará a contarse:", "Desde que se inició la conducta infractora.", "Desde el día en que se cometió la primera infracción.", "Desde que finalizó la conducta infractora.", "Desde que finalizó la primera infracción cometida."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 21, "Según el art. 30.2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿cuándo se interrumpe la prescripción de la infracción?", "Con la iniciación de un procedimiento administrativo de naturaleza sancionadora.", "Con la iniciación, con conocimiento del interesado, de un procedimiento administrativo de naturaleza sancionadora.", "Con la iniciación, con conocimiento del órgano instructor y del interesado, de un procedimiento administrativo de naturaleza sancionadora.", "Con la iniciación, con conocimiento del interesado, de un procedimiento de información reservada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 22, "Según el art. 30.2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿cuándo se reinicia el plazo de prescripción de la infracción?", "Cuando el expediente sancionador estuviera paralizado durante más de un mes.", "Cuando el expediente sancionador estuviera paralizado durante más de un mes por causa no imputable al presunto responsable.", "Cuando se inicie, con conocimiento del interesado, un procedimiento administrativo de naturaleza sancionadora.", "Cuando el expediente sancionador estuviera paralizado durante más de un mes por causa imputable al presunto responsable."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 23, "Según el art. 30.3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿cuándo se interrumpe la prescripción de las sanciones?", "Cuando se inicia, con conocimiento del interesado, el procedimiento de ejecución.", "Cuando se inicia el procedimiento de ejecución.", "Cuando se inicia, con conocimiento del interesado, un procedimiento administrativo de naturaleza sancionadora.", "Cuando se inicia un procedimiento administrativo de naturaleza sancionadora."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 24, "Según el art. 30.3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿cuándo vuelve a transcurrir el plazo de prescripción de las sanciones?", "Cuando el procedimiento esté paralizado durante menos de un mes por causa no imputable al infractor.", "Cuando el procedimiento esté paralizado durante más de un mes.", "Cuando el procedimiento esté paralizado durante más de un mes por causa imputable al infractor.", "Cuando el procedimiento esté paralizado durante más de un mes por causa no imputable al infractor."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 25, "Según el art. 32.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, los particulares tendrán derecho a ser indemnizados por las Administraciones Públicas correspondientes, de toda lesión que sufran en cualquiera de sus bienes y derechos, siempre que la lesión sea consecuencia del funcionamiento:", "Normal o anormal de los servicios públicos.", "Anormal o irregular de los servicios públicos.", "Normal de los servicios públicos.", "Normal, anormal o regular de los servicios públicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 26, "Según el art. 32.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, se excluye la responsabilidad patrimonial de las administraciones públicas:", "En los casos de fuerza mayor.", "En los casos de emergencia.", "En los casos de daños imprevistos.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 27, "Según el art. 32.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público:", "La anulación en vía administrativa o por el orden jurisdiccional contencioso administrativo de los actos administrativos no presupone, por sí misma, derecho a la indemnización.", "La anulación en vía administrativa de los actos o disposiciones administrativas no presupone, por sí misma, derecho a la indemnización.", "La anulación en vía administrativa o por el orden jurisdiccional contencioso administrativo de los actos o disposiciones administrativas no presupone, por sí misma, derecho a la indemnización.", "La anulación por el orden jurisdiccional contencioso administrativo de los actos o disposiciones administrativas no presupone, por sí misma, derecho a la indemnización."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 28, "Según el art. 32.2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, en los supuestos de responsabilidad patrimonial el daño alegado debe ser:", "Efectivo y evaluable económicamente.", "Efectivo, evaluable económicamente e individualizado con relación a una persona o grupo de personas.", "Efectivo, material, evaluable económicamente e individualizado.", "Efectivo, material, evaluable económicamente e individualizado con relación a una persona o grupo de personas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 29, "Según el art. 32.3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿en cuál de los siguientes supuestos puede surgir la responsabilidad patrimonial del Estado legislador?", "Cuando los daños deriven de la aplicación de una norma con rango de ley declarada inconstitucional.", "Cuando los daños deriven de la aplicación de una norma contraria al ordenamiento jurídico.", "Cuando los daños deriven de la aplicación de una ley o una disposición general contraria al ordenamiento jurídico.", "Cuando los daños deriven de la aplicación de una norma contraria al derecho internacional."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 30, "Según el art. 32.4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿en cuál de los siguientes supuestos procede la indemnización por las lesiones que sean consecuencia de la aplicación de una norma con rango de ley declarada inconstitucional?", "Cuando el particular hubiera obtenido sentencia firme desestimatoria de un recurso contra la actuación administrativa que ocasionó el daño.", "Cuando el particular hubiera obtenido sentencia firme estimatoria de un recurso contra la actuación administrativa que ocasionó el daño, siempre que se hubiera alegado la inconstitucionalidad posteriormente declarada.", "Cuando el particular hubiera obtenido sentencia firme estimatoria de un recurso contra la actuación administrativa que ocasionó el daño.", "Cuando el particular hubiera obtenido sentencia firme desestimatoria de un recurso contra la actuación administrativa que ocasionó el daño, siempre que se hubiera alegado la inconstitucionalidad posteriormente declarada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 31, "Según el art. 32.6 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, la sentencia que declare la inconstitucionalidad de una norma con rango de ley producirá efectos:", "Desde la fecha de su publicación en el «Boletín Oficial del Estado».", "Desde la fecha de su publicación en el «Boletín Oficial del Estado», salvo que en ella se establezca otra cosa.", "Desde la fecha en que se dicte.", "Desde la fecha en que se dicte, salvo que en ella se establezca otra cosa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 32, "Según el art. 32.7 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, la responsabilidad patrimonial del Estado por el funcionamiento de la Administración de Justicia se regirá por:", "La Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público.", "La Ley 1/2000, de 7 de enero, de Enjuiciamiento Civil.", "La Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial.", "La Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial y la Ley 1/2000, de 7 de enero, de Enjuiciamiento Civil."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 33, "Según el art. 32.8 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, cuando el Tribunal Constitucional haya declarado, a instancia de parte interesada, la existencia de un funcionamiento anormal en la tramitación de los recursos de amparo o de las cuestiones de inconstitucionalidad:", "El Consejo de Ministros fijará el importe de las indemnizaciones que proceda abonar.", "El Consejo de Ministros o el órgano de gobierno de la Comunidad Autónoma fijará el importe de las indemnizaciones que proceda abonar.", "La sentencia fijará el importe de las indemnizaciones que proceda abonar.", "La sentencia fijará el importe de las indemnizaciones que proceda abonar, con el informe previo del Consejo de Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 34, "Según el art. 32.9 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿en cuál de los siguientes supuestos habrá responsabilidad de las Administraciones Públicas por los daños y perjuicios causados a terceros durante la ejecución de contratos?", "Cuando sean consecuencia de una orden inmediata y directa del contratista.", "Cuando sean consecuencia de una orden inmediata y directa de la Administración.", "Cuando sean consecuencia de los vicios del proyecto elaborado por el contratista.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 35, "Según el art. 33.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, cuando de la gestión dimanante de fórmulas conjuntas de actuación entre varias Administraciones públicas se derive responsabilidad en los términos previstos en la presente Ley, las Administraciones intervinientes responderán frente al particular:", "En todo caso, de forma solidaria.", "De forma mancomunada, salvo que en los acuerdos se establezca la responsabilidad solidaria.", "En todo caso, de forma mancomunada.", "De forma mancomunada, salvo que en los acuerdos se establezca un régimen distinto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 36, "Según el art. 34.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, solo serán indemnizables las lesiones producidas al particular provenientes de daños:", "Que éste no tenga el deber jurídico de soportar.", "Que éste no tenga el deber jurídico de soportar de acuerdo con la Ley.", "Que éste tenga el deber jurídico de soportar de acuerdo con la Ley.", "Que éste tenga el deber jurídico de soportar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 37, "¿Qué daños no son indemnizables según el art. 34.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público?", "Los que sean consecuencia del funcionamiento normal de los servicios públicos.", "Los que se deriven de hechos o circunstancias que no se hubiesen podido prever o evitar según el estado de los conocimientos de la ciencia o de la técnica existentes en el momento de producción de aquéllos.", "Los causados por una norma con rango de ley.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 38, "Según el art. 34.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, en los casos de responsabilidad patrimonial que sean consecuencia de la aplicación de una norma con rango de ley declarada inconstitucional, serán indemnizables los daños producidos en el plazo de los cinco años anteriores:", "A la fecha de la notificación de la sentencia.", "A la fecha de la notificación de la sentencia, salvo que la sentencia disponga otra cosa.", "A la fecha de la publicación de la sentencia.", "A la fecha de la publicación de la sentencia, salvo que la sentencia disponga otra cosa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 39, "Según el art. 34.2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, para calcular la indemnización en los casos de muerte o lesiones corporales:", "Se podrá tomar como referencia la valoración incluida en los baremos de la normativa vigente en materia de Seguros obligatorios y de la Seguridad Social.", "Se tomará como referencia la valoración incluida en los baremos de la normativa vigente en materia de Seguros obligatorios y de la Seguridad Social.", "Se podrá tomar como referencia la valoración incluida en los baremos de la Ley sobre responsabilidad civil y seguro en la circulación de vehículos a motor.", "Se tomará como referencia la valoración incluida en los baremos de la Ley sobre responsabilidad civil y seguro en la circulación de vehículos a motor."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 40, "Según el art. 34.3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, en los procedimientos de responsabilidad patrimonial la cuantía de la indemnización se actualizará:", "En la fecha en que se inicie el procedimiento con arreglo al Índice de Precios al Consumo.", "En la fecha en que se ponga fin al procedimiento con arreglo al Índice de Precios al Consumo.", "En la fecha en que se inicie el procedimiento con arreglo al Índice de Garantía de la Competitividad.", "En la fecha en que se ponga fin al procedimiento con arreglo al Índice de Garantía de la Competitividad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 41, "Según el art. 34.3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿de acuerdo con qué norma se exigirán los intereses que procedan por la demora en el pago de la indemnización fijada en los procedimientos de responsabilidad patrimonial?", "La Ley 47/2003, de 26 de noviembre, General Presupuestaria, o, en su caso, a las normas presupuestarias de las Comunidades Autónomas.", "La Ley 47/2003, de 26 de noviembre, General Presupuestaria.", "La Ley 58/2003, de 17 de diciembre, General Tributaria, o, en su caso, a las normas presupuestarias de las Comunidades Autónomas.", "La Ley 58/2003, de 17 de diciembre, General Tributaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 42, "Según el art. 34.4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, en los casos de responsabilidad patrimonial la indemnización procedente:", "Se sustituirá por una compensación en especie o será abonada mediante pagos periódicos.", "Podrá sustituirse por una compensación en especie o ser abonada mediante pagos periódicos.", "Se sustituirá por una compensación en especie cuando haya razones imperiosas de interés general.", "Será abonada mediante pagos periódicos cuando no exista disponibilidad presupuestaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 43, "Según el art. 34.4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, en los casos de responsabilidad patrimonial, ¿cuál de los siguientes requisitos es necesario para sustituir la indemnización por una compensación en especie?", "Que exista acuerdo con el interesado y se prevea en las normas sectoriales específicas.", "Que exista acuerdo con el interesado y no esté prohibido en las normas sectoriales específicas.", "Que exista acuerdo con el interesado.", "Que exista acuerdo con el interesado y no haya disponibilidad presupuestaria para abonar la indemnización durante el año en curso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 44, "Según el art. 35 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, cuando las Administraciones Públicas actúen, directamente o a través de una entidad de derecho privado, en relaciones de esta naturaleza:", "Su responsabilidad se exigirá de conformidad con lo previsto en los artículos 32 y siguientes, salvo cuando concurra con sujetos de derecho privado.", "Su responsabilidad se exigirá de conformidad con el derecho privado.", "Su responsabilidad se exigirá de conformidad con lo previsto en los artículos 32 y siguientes, incluso cuando concurra con sujetos de derecho privado.", "Su responsabilidad se exigirá de conformidad con el derecho privado cuando concurra con sujetos de derecho privado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 45, "Según el art. 36.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, para exigir responsabilidad patrimonial por los daños y perjuicios causados por las autoridades y personal al servicio de las Administraciones Públicas, los particulares se dirigirán:", "Directamente a la Administración Pública correspondiente.", "Directamente a las autoridades y personal a su servicio.", "Indistintamente a la Administración Pública o a las autoridades y personal a su servicio.", "Directamente a las autoridades y personal a su servicio, y subsidiariamente a la Administración Pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 46, "Según el art. 36.2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, la Administración exigirá responsabilidad patrimonial a las autoridades y personal a su servicio:", "De oficio en vía administrativa o por vía judicial, previa instrucción del correspondiente procedimiento.", "De oficio por vía judicial.", "De oficio por vía judicial, previa instrucción del correspondiente procedimiento.", "De oficio en vía administrativa, previa instrucción del correspondiente procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 47, "¿Cuál de los siguientes criterios de cuantificación de la sanción no se cita en el art. 36.2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, relativo a la responsabilidad patrimonial de las autoridades y personal al servicio de las Administraciones Públicas?", "El resultado dañoso producido.", "El grado de culpabilidad.", "La responsabilidad profesional del personal al servicio de las Administraciones públicas y su relación con la producción del resultado dañoso.", "La reiteración."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 48, "Según el art. 36 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿cómo debe exigir la Administración la responsabilidad a sus empleados por los daños y perjuicios causados en sus bienes o derechos?", "De oficio en vía administrativa, previa instrucción del correspondiente procedimiento.", "Mediante resolución que se dictará en el plazo de diez días desde la constatación de los daños y perjuicios.", "De oficio en vía administrativa o por vía judicial.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 49, "Según el art. 36.4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el plazo para realizar alegaciones en los procedimientos de responsabilidad patrimonial a las autoridades y al personal al servicio de las Administraciones Públicas es:", "De diez días.", "De quince días.", "No inferior a quince días.", "No inferior a diez días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 50, "Según el art. 36.4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el plazo para la práctica de pruebas en los procedimientos de responsabilidad patrimonial a las autoridades y al personal al servicio de las Administraciones Públicas es:", "De diez días.", "No inferior a diez días ni superior a treinta.", "Inferior a quince días.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 51, "Según el art. 36.4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el plazo de audiencia en los procedimientos de responsabilidad patrimonial a las autoridades y al personal al servicio de las Administraciones Públicas es:", "De diez días.", "No inferior a diez días.", "Inferior a quince días.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 52, "Según el art. 36.4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, en los procedimientos de responsabilidad patrimonial a las autoridades y al personal al servicio de las Administraciones Públicas, la propuesta de resolución se formulará en un plazo de:", "Cinco días a contar desde la finalización del trámite de audiencia.", "Cinco días a contar desde la conclusión de la fase de prueba.", "Diez días a contar desde la finalización del trámite de audiencia.", "Diez días a contar desde la conclusión de la fase de prueba."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 53, "Según el art. 36.4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el plazo para dictar resolución en los procedimientos de responsabilidad patrimonial a las autoridades y al personal al servicio de las Administraciones Públicas es de:", "Cinco días a contar desde la finalización del trámite de audiencia.", "Cinco días.", "Diez días a contar desde la finalización del trámite de audiencia.", "Diez días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 54, "Según el art. 37.2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, la exigencia de responsabilidad penal del personal al servicio de las Administraciones Públicas:", "Suspenderá los procedimientos de reconocimiento de responsabilidad patrimonial que se instruyan.", "No suspenderá los procedimientos de reconocimiento de responsabilidad patrimonial que se instruyan, salvo que la determinación de los hechos en el orden jurisdiccional penal sea necesaria para la fijación de la responsabilidad patrimonial.", "No suspenderá los procedimientos de reconocimiento de responsabilidad patrimonial que se instruyan.", "Suspenderá los procedimientos de reconocimiento de responsabilidad patrimonial que se instruyan, salvo que la determinación de los hechos en el orden jurisdiccional penal sea necesaria para la fijación de la responsabilidad patrimonial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 55, "Según el art. 64.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, la incoación de un procedimiento de naturaleza sancionadora se comunicará al denunciante:", "En ningún caso.", "Cuando sea interesado en el procedimiento.", "Cuando las normas reguladoras del procedimiento así lo prevean.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 56, "Según el art. 64.2.b) de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el acuerdo de iniciación de los procedimientos de naturaleza sancionadora contendrá:", "Los hechos que motivan la incoación del procedimiento.", "La posible calificación de los hechos.", "Las sanciones que pudieran corresponder.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 57, "Según el art. 64.2.f) de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, en caso de no efectuar alegaciones en el plazo previsto sobre el contenido del acuerdo de iniciación del procedimiento de naturaleza sancionadora:", "Éste podrá ser considerado resolución cuando contenga un pronunciamiento preciso acerca de la responsabilidad imputada.", "Éste podrá ser considerado propuesta de resolución cuando no contenga un pronunciamiento preciso acerca de la responsabilidad imputada.", "Éste podrá ser considerado resolución cuando no contenga un pronunciamiento preciso acerca de la responsabilidad imputada.", "Éste podrá ser considerado propuesta de resolución cuando contenga un pronunciamiento preciso acerca de la responsabilidad imputada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 58, "Según el art. 67.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el derecho a reclamar responsabilidad patrimonial:", "Prescribe al año de producido el hecho o el acto que motive la indemnización.", "Prescribe al año de producido el hecho o el acto que motive la indemnización o se manifieste su efecto lesivo.", "Caduca al año de producido el hecho o el acto que motive la indemnización o se manifieste su efecto lesivo.", "Caduca al año de producido el hecho o el acto que motive la indemnización."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 59, "Según el art. 67.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, las solicitudes de responsabilidad patrimonial irán acompañadas de:", "Cuantas alegaciones se estimen oportunas.", "Cuantas alegaciones, documentos e informaciones se estimen oportunos.", "Cuantas alegaciones, documentos e informaciones se estimen oportunos y de la proposición de prueba.", "Cuantas alegaciones, documentos e informaciones se estimen oportunos, de la proposición de prueba y del trámite de audiencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 60, "Según el art. 81.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, en los procedimientos de responsabilidad patrimonial el plazo para la emisión del informe del servicio cuyo funcionamiento haya ocasionado la presunta lesión indemnizable:", "No podrá ser inferior a diez días.", "No podrá exceder de quince días.", "No podrá exceder de diez días.", "Será de quince días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 61, "Según el art. 81.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, en los procedimientos de responsabilidad patrimonial será preceptivo solicitar dictamen del Consejo de Estado o, en su caso, del órgano consultivo de la Comunidad Autónoma cuando las indemnizaciones reclamadas sean:", "De cuantía igual o superior a 50.000 euros.", "De cuantía igual o superior a 50.000 euros o a la que se establezca en la correspondiente legislación autonómica.", "De cuantía igual o superior a 30.000 euros.", "De cuantía igual o superior a 30.000 euros o a la que se establezca en la correspondiente legislación autonómica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 62, "Según el art. 81.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el dictamen emitido por el Consejo de Estado en los procedimientos de responsabilidad patrimonial debe pronunciarse sobre:", "La existencia o no de relación de causalidad entre el funcionamiento del servicio público y la lesión producida.", "En su caso, la valoración del daño causado y la cuantía y modo de la indemnización.", "La existencia de negligencia en la actuación administrativa.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 63, "Según el art. 81.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el dictamen emitido por el Consejo de Estado en los procedimientos de responsabilidad patrimonial debe pronunciarse sobre:", "La continuidad o persistencia en la conducta infractora.", "La existencia o no de relación de causalidad entre el funcionamiento del servicio público y la lesión producida.", "El grado de culpabilidad o la existencia de intencionalidad.", "La reincidencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 64, "Según el art. 81.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿cuánto tiempo podrá quedar suspendido el plazo para resolver los procedimientos de responsabilidad patrimonial del Estado por el funcionamiento anormal de la Administración de Justicia?", "Un máximo de dos meses.", "Un mínimo de dos meses.", "Un máximo de un mes.", "No se establece ningún plazo de suspensión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 65, "Según el art. 85.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, la efectividad de las reducciones del importe de la sanción:", "Estará condicionada al desistimiento o renuncia de cualquier acción o recurso en vía administrativa contra la sanción.", "Estará condicionada al desistimiento o renuncia de cualquier acción o recurso en vía administrativa o judicial contra la sanción.", "No estará condicionada al desistimiento o renuncia de cualquier acción o recurso en vía administrativa contra la sanción.", "Estará condicionada al desistimiento o renuncia de cualquier acción o recurso en vía judicial contra la sanción."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 66, "Según el art. 90.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, la resolución de los procedimientos de carácter sancionador incluirá:", "La valoración de las pruebas practicadas, en especial aquellas que constituyan los fundamentos básicos de la decisión.", "La valoración de las pruebas que no se han podido practicar.", "La valoración de las pruebas practicadas, con excepción de aquellas que constituyan los fundamentos básicos de la decisión.", "La valoración de las pruebas practicadas después del trámite de audiencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 15, 67, "Según el art. 91.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, en los procedimientos de responsabilidad patrimonial será necesario que la resolución se pronuncie sobre:", "La valoración del daño causado, cuando proceda.", "La cuantía y el modo de la indemnización, cuando proceda.", "La existencia o no de la relación de causalidad entre el funcionamiento del servicio público y la lesión producida.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 1, "La normativa sobre prevención de riesgos laborales queda constituida por:", "Por la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales.", "Por la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales y las disposiciones de desarrollo o complementarias.", "Por la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales, las disposiciones de desarrollo o complementarias, y las normas internacionales.", "Por la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales, disposiciones de desarrollo o complementarias, y todas aquellas otras normas legales o convencionales, que contengan prescripciones relativas a la adopción de medidas preventivas en el ámbito laboral."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 2, "La Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales tiene por objeto:", "Mejorar las condiciones laborales de los trabajadores.", "Promover la seguridad y la salud de las personas trabajadoras.", "Disponer las medidas preventivas adecuadas a los puestos de trabajo.", "Establecer la forma de evaluación de los riesgos en los puestos de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 3, "Las disposiciones de carácter laboral que contiene la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales tendrán el carácter de:", "De derecho necesario mínimo indisponible, y pueden ser mejoradas y desarrolladas en los convenios colectivos.", "De derecho mínimo indisponible, pero no se pueden desarrollar con los convenios colectivos.", "Carecen de carácter de derecho mínimo.", "Tienen carácter de máximo derecho."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 4, "La Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales es de aplicación en el ámbito de:", "Policía, seguridad y resguardo aduanero.", "Las relaciones laborales reguladas por el Estatuto de los trabajadores y en las relaciones de carácter administrativo o estatutario del personal al servicio de las administraciones públicas.", "Servicios operativos de protección civil y peritaje forense en los casos de grave riesgo, catástrofe y calamidad pública.", "Fuerzas Armadas y actividades militares de la Guardia Civil."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 5, "La Ley 31/1995, de 8 de noviembre, de Prevención de riesgos laborales no es aplicable en las actividades cuyas particularidades lo impidan en el ámbito de las funciones públicas de:", "Policía, seguridad y resguardo aduanero.", "Servicios operativos de protección civil, peritaje forense en los casos de grave riesgo, catástrofe y calamidad pública.", "Fuerzas armadas y actividades militares de la Guardia Civil.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 6, "¿Cuál es la definición de daños derivados del trabajo según la Ley de Prevención de riesgos laborales?", "Los problemas de salud relacionados con las condiciones de trabajo.", "Las enfermedades, patologías o lesiones sufridas con motivo u ocasión del trabajo.", "Cualquier alteración de la salud relacionada, causada o agravada por las condiciones de trabajo.", "Las lesiones corporales y psíquicas que el trabajador sufra con ocasión o por consecuencia del trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 7, "¿Cuál es la definición de prevención según la Ley 31/1995, de 8 de noviembre, de Prevención de riesgos laborales?", "El conjunto de actividades o medidas adoptadas o previstas en todas las fases de la actividad de la empresa con el fin de evitar o disminuir los riesgos derivados del trabajo.", "El conjunto de medios disponibles para ayudar en el desarrollo de la labor laboral.", "El conjunto de medios auxiliares y equipos de protección individual.", "Los procedimientos de trabajo y normativas derivadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 8, "¿Cuál es la definición de riesgo laboral según la Ley 31/1995, de 8 de noviembre, de Prevención de riesgos laborales?", "Es el foco de emisión de gases y vapores.", "Es la casualidad de que una persona trabajadora sufra un accidente.", "Es la gravedad de un daño en la salud.", "Es la posibilidad de que un trabajador sufra un determinado daño derivado del trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 9, "Para calificar un riesgo laboral desde el punto de vista de su gravedad debe valorarse conjuntamente:", "El grado de afectación a la persona trabajadora.", "La probabilidad de que se produzca el daño y su severidad.", "Sólo se valora la severidad.", "La probabilidad de que haya sufrimiento físico y no psicológico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 10, "¿Cuál es la definición de riesgo laboral grave e inminente según la Ley 31/1995, de 8 de noviembre, de Prevención de riesgos laborales?", "Es aquél en el que las consecuencias y el daño tienen lugar a corto plazo.", "Es el hecho en el que la gravedad hace que el riesgo sea imposible prevenir.", "Es aquel que racionalmente se materializa en un futuro inmediato y pueda suponer un grave daño para la salud de la persona trabajadora.", "Es la situación inesperada que tiene graves consecuencias para la seguridad y salud de los trabajadores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 11, "¿Cuál es la definición de equipo de trabajo según la Ley 31/1995, de 8 de noviembre, de Prevención de riesgos laborales?", "Es cualquier máquina, aparato, instrumento o instalación utilizada en el trabajo.", "Es todo aparato con el que se desarrolla el trabajo diario.", "Es todo sistema con el que se desarrolla el trabajo.", "Son las instalaciones de los centros de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 12, "¿Cuál es la definición de condición de trabajo según la Ley 31/1995, de 8 de noviembre, de Prevención de Riesgos Laborales?", "Son todas las circunstancias derivadas del trabajo.", "Es la situación más habitual en el entorno laboral.", "Son las características inherentes al desarrollo de la labor diaria.", "Es cualquier característica del trabajo que pueda tener una influencia significativa en la generación de riesgos para la seguridad y salud del trabajador o trabajadora."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 13, "¿Cuál es la definición de equipo de protección individual según la Ley 31/1995 de Prevención de riesgos laborales?", "Es todo ese equipamiento destinado a proteger la seguridad y salud del personal.", "Es cualquier equipo destinado a ser llevado o sujetado por el trabajador o trabajadora para que lo proteja de uno o varios riesgos que puedan amenazar su seguridad o salud en el trabajo, así como cualquier complemento o accesorio destinado a tal fin.", "Es cualquier elemento que protege de un riesgo laboral a varios trabajadores.", "Todo sistema de sujeción individual con el fin de evitar las caídas a nivel."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 14, "La política en materia de prevención de riesgos laborales tiene como objetivo:", "Promover la mejora de las condiciones de trabajo a fin de elevar el nivel de protección de la seguridad y la salud de los trabajadores en el trabajo.", "Mejorar las condiciones salariales y sociales de los trabajadores afiliados a la seguridad social.", "Alcanzar unas condiciones dignas de trabajo.", "Respetar la salud de los trabajadores en el trabajo adoptando medidas preventivas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 15, "Las administraciones públicas competentes en materia laboral deben llevar a cabo las funciones de:", "Promoción de la seguridad y asesoramiento jurídico en su ámbito de aplicación.", "Prevención de accidentes laborales y enfermedades profesionales.", "Promoción de la prevención, asesoramiento técnico, vigilancia y control del cumplimiento por los sujetos comprendidos en su ámbito de aplicación de la normativa de prevención de riesgos laborales, y sanción de las infracciones en caso necesario.", "Sanción de las infracciones administrativas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 16, "En relación al Instituto Nacional de Seguridad y Salud en el Trabajo (anteriormente, Instituto Nacional de Seguridad e Higiene en el Trabajo), cuál no es una función de este organismo:", "Apoyo técnico y colaboración con la Inspección de Trabajo y Seguridad Social.", "Promoción y, en su caso, realización de actividades de formación, información, investigación, estudio y divulgación en materia de prevención de riesgos laborales.", "Asesoramiento técnico en la elaboración de la normativa legal y en el desarrollo de la normalización, tanto en el ámbito nacional como internacional.", "Vigilancia del cumplimiento de la normativa sobre prevención de riesgos laborales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 17, "De acuerdo con la Ley 31/1995, de 8 de noviembre, de prevención de riesgo laborales, la función de la Inspección de Trabajo y Seguridad Social es:", "Desarrollar la normativa que incide en las condiciones de trabajo.", "Evaluar las condiciones de seguridad y salud.", "Vigilar y controlar el cumplimiento de la normativa en prevención de riesgos laborales.", "Sancionar en temas relativos a la seguridad social exclusivamente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 18, "Es un principio básico de la política de prevención de riesgos laborales", "La participación de empresarios y de trabajadores, mediante las organizaciones empresariales y sindicales más representativas, en la planificación, programación, organización y control de la gestión relacionadas con la mejora de las condiciones de trabajo y la protección de la seguridad y salud de los trabajadores.", "La elaboración de normativa laboral.", "La conciliación de la vida familiar y laboral.", "Sólo la mejora de las condiciones de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 19, "El artículo 14 de la Ley de Prevención de Riesgos Laborales establece:", "Que cuando se haya producido un daño para la salud (física o psíquica) debe investigarse.", "Que el empresario debe garantizar la seguridad y la salud de los trabajadores en todos los aspectos relacionados con el trabajo.", "Que como acción preventiva debe promocionarse la salud.", "Que debe atenuarse el trabajo monótono y repetitivo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 20, "Señale la respuesta correcta en relación al Plan de Prevención de riesgos laborales:", "Deben realizarlo aquellas empresas de más de cincuenta trabajadores.", "Las empresas, según el número de trabajadores y la naturaleza y peligrosidad de las actividades realizadas, pueden realizar el Plan de prevención de riesgos laborales de forma simplificada.", "Deben realizarlo aquellas empresas de más de cien trabajadores.", "Las empresas, según el número de trabajadores y la naturaleza y peligrosidad de las actividades realizadas, pueden realizar el Plan de prevención de riesgos laborales de forma extensa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 21, "El artículo 15 de la Ley 31/1995, de 8 de noviembre, de Prevención de riesgos laborales establece que:", "El empresario no tendrá en cuenta la capacitación profesional de los trabajadores.", "Las empresas de más de 150 empleados deben disponer de plan de emergencias.", "El diseño del puesto de trabajo no se contempla en la prevención de riesgos laborales.", "El empresario debe aplicar los principios de la acción preventiva."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 22, "El principio de sustituir lo que sea peligroso por lo que comporte poco peligro o no comporte ninguno es:", "Un principio de la acción preventiva.", "Una acción del estudio inicial.", "Un caso aplicable a productos químicos.", "No es un principio de acción preventiva."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 23, "De acuerdo con el artículo 16 de la Ley de Prevención de Riesgos Laborales, cuando se haya producido un daño para la salud de los trabajadores, el empresario:", "Debe realizar un nuevo Plan de Prevención que incluya los daños de los trabajadores.", "Debe llevar a cabo una investigación sobre el caso, a fin de detectar las causas de los hechos.", "Debe comunicar los hechos a la fiscalía.", "Debe llevar a cabo el seguimiento de la actividad preventiva a fin de perfeccionar de forma continua las actividades de identificación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 24, "El artículo 17 de la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales dice que:", "El empresario debe proporcionar a sus empleados sólo equipos de protección individual.", "El empresario debe velar para que se haga un uso efectivo de los equipos de protección individual.", "El empresario debe proporcionar a sus empleados equipos de protección individual adecuados para el ejercicio de sus funciones y velar para que se haga un uso efectivo cuando sea necesario.", "Son necesarios los equipos de trabajo y los equipos de protección individual."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 25, "De acuerdo con el artículo 18 de la Ley de Prevención de Riesgos Laborales, el empresario debe adoptar las medidas adecuadas para que los trabajadores reciban todas las informaciones necesarias en relación con:", "Los derechos laborales que les corresponden.", "Las obligaciones en referencia a la prevención de riesgos laborales.", "Los riesgos, las medidas y las actividades de protección y prevención y las medidas adoptadas.", "El empresario no tiene ninguna obligación de informar a los trabajadores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 26, "En relación a la información a la que se refiere el artículo 18 de la Ley de Prevención de Riesgos Laborales establece que:", "Si hay representantes de los trabajadores, debe proporcionarlo el empresario a los trabajadores a través de los representantes; no obstante, se informará directamente a cada trabajador de los riesgos específicos que afecten a su puesto de trabajo o función y de las medidas de protección y prevención aplicables a los riesgos.", "El empresario únicamente debe darlo a los representantes de los trabajadores que la harán llegar a los trabajadores.", "El empresario siempre debe darlo a los trabajadores sin la intermediación de los representantes de los trabajadores.", "La información se establece en el artículo 23 de la Ley de prevención de riesgos laborales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 27, "La formación en el ámbito de la prevención de riesgos laborales debe ser:", "Voluntaria para el empresario, pero obligatoria por el personal.", "Voluntaria para el empresario y voluntaria por el personal.", "El empresario debe garantizar para todo el personal la formación teórica y práctica en materia preventiva.", "La formación no debe centrarse específicamente en el puesto de trabajo o la función del personal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 28, "Cuando el personal esté o puedan estar expuesto a un riesgo grave e inminente a causa de su trabajo, el empresario está obligado a:", "A dar aviso a la Inspección de trabajo y a la seguridad social.", "Informar de esta situación a todo el personal afectado lo antes posible, adoptar las medidas para que se pueda interrumpir la actividad laboral inmediatamente y disponer de lo necesario para adoptar las medidas necesarias para evitar las consecuencias de dicho peligro.", "Precintar el centro de trabajo.", "Dar aviso con el tiempo suficiente para aplicar las medidas preventivas necesarias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 29, "En referencia a lo establecido en el artículo 22 de la Ley de Prevención de Riesgos Laborales en cuanto a la vigilancia de la salud, señale la respuesta incorrecta:", "Los datos relativos a la vigilancia de la salud de los trabajadores no se pueden realizar servir con fines discriminatorios ni en perjuicio del trabajador.", "El empresario debe garantizar a los trabajadores a su servicio la vigilancia periódica de su estado de salud en función de los riesgos inherentes al trabajo.", "Los resultados de la vigilancia se comunicarán a los trabajadores afectados, al empresario ya los representantes de los trabajadores.", "Las medidas de vigilancia y control de la salud deben llevarse a cabo respetando siempre el derecho a la intimidad ya la dignidad de la persona y la confidencialidad de toda la información relacionada con su estado de salud."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 30, "En relación al derecho a la vigilancia de la salud:", "Siempre debe prolongarse más allá de la finalización de la relación laboral.", "Se prolongará más allá de la finalización de la relación laboral sólo cuando el trabajador lo solicite expresamente.", "En ningún caso debe prolongarse más allá de la finalización de la relación laboral.", "Se debe prolongar en los supuestos en los que la naturaleza de los riesgos inherentes al trabajo lo haga necesario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 31, "¿Qué documentación debe elaborar y conservar el empresario de acuerdo con la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales?", "La evaluación de riesgos laborales de cada puesto de trabajo específico y la documentación relativa al estado de salud del personal.", "El plan de prevención y la relación de accidentes laborales, pero no la de enfermedades profesionales.", "El plan de prevención y la relación de accidentes laborales y la de enfermedades profesionales.", "El plan de prevención, la evaluación de riesgos para la seguridad y la salud del personal, la planificación preventiva, la práctica de los controles del estado de salud del personal y la relación de accidentes de trabajo y enfermedades profesionales que hayan causado al trabajador una incapacidad laboral superior a un día de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 32, "De acuerdo con el artículo 26 de la Ley de Prevención de Riesgos Laborales, las mujeres embarazadas tienen derecho:", "A ausentarse del trabajo, con derecho a remuneración, para realizar exámenes prenatales y técnicas de preparación al parto, con aviso previo al empresario y justificando la necesidad de hacerlo dentro de la jornada de trabajo.", "A ausentarse del trabajo, sin derecho a remuneración, para realizar exámenes prenatales y técnicas de preparación al parto, con aviso previo al empresario y con la justificación de la necesidad de hacerlo dentro de la jornada de trabajo.", "A ausentarse del trabajo, con derecho a remuneración, para realizar exámenes prenatales y técnicas de preparación al parto, sin la obligación de avisar previamente al empresario.", "No tienen derecho a ausentarse del trabajo, para realizar exámenes prenatales y técnicas de preparación al parto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 33, "La coordinación de actividades empresariales implica que:", "En uno o más centros de trabajo haya más de dos empresas implicadas en el desarrollo laboral.", "En un centro de trabajo hay más de tres empresas trabajando a la vez, pero no implica ninguna responsabilidad al titular del centro.", "Cuando en un mismo centro de trabajo lleven a cabo actividades el personal de dos o más empresas, éstas deben cooperar en la aplicación de la normativa sobre prevención de riesgo laborales.", "Sólo es necesaria la cooperación documental del plan de prevención."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 34, "El artículo 25 de la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales establece que:", "El plan de prevención debe revisarse anualmente.", "La evaluación de riesgos laborales debe revisarse anualmente.", "El plan de prevención y la evaluación de riesgos laborales caducan a los tres años.", "El empresario debe garantizar específicamente la protección del personal que por sus características personales o su estado biológico conocido sean especialmente sensibles a los riesgos derivados del trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 35, "¿Cuándo es necesaria la presencia de los recursos preventivos?", "Cuando se realicen actividades o procesos que por reglamento sean considerados como peligrosos o con riesgos especiales.", "Cuando los riesgos puedan verse agravados o modificados en el desarrollo del proceso o la actividad, por la concurrencia de operaciones diversas que se llevan a cabo sucesiva o simultáneamente y que hagan necesario el control de la aplicación correcta de los métodos de trabajo.", "Cuando la necesidad de esta presencia sea requerida por la Inspección de Trabajo y Seguridad Social, si las circunstancias del caso así lo exigen debido a las condiciones de trabajo detectadas.", "Todas las anteriores respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 36, "Las obligaciones del personal en materia de prevención de riesgos laborales son:", "Velar por la seguridad y salud de uno mismo.", "Velar por su propia seguridad y salud en el trabajo y por la de aquellas otras personas cuya actividad profesional pueda afectar, debido a sus actos y omisiones en el trabajo.", "Adoptar las medidas preventivas necesarias del plan de prevención.", "Implantar las instrucciones de seguridad y salud en el puesto de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 37, "El derecho de participación regulado en el Capítulo V de la Ley de Prevención de Riesgos Laborales:", "Se ejerce en el ámbito de las administraciones públicas con las adaptaciones que sean procedentes atendiendo a la diversidad de las actividades que llevan a cabo y las diferentes condiciones en que éstas se realizan, la complejidad y dispersión de la estructura organizativa y sus peculiaridades en materia de representación colectiva.", "Se ejerce de igual forma en el ámbito de la empresa privada y en el ámbito de las administraciones públicas sin adaptaciones particulares en ninguno de ambos ámbitos.", "Se ejerce siempre y únicamente a través de los representantes de los trabajadores, tanto en el ámbito de la empresa privada como en el ámbito de las administraciones públicas.", "Se ejerce siempre y únicamente a través de los trabajadores, tanto en el ámbito de la empresa privada como en el ámbito de las administraciones públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 38, "¿Cuál de las siguientes no es una competencia de los delegados de prevención?", "Ejercer una labor de vigilancia y control sobre el cumplimiento de la normativa de prevención de riesgos laborales.", "Promover y fomentar la cooperación de los trabajadores en la ejecución de la normativa sobre prevención de riesgos laborales", "Informar a la autoridad laboral sobre los accidentes de trabajo.", "Colaborar con la dirección de la empresa en la mejora de la acción preventiva."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 39, "Los delegados de prevención están facultados para:", "Realizar visitas a los puestos de trabajo para desempeñar una tarea de vigilancia y control del estado de las condiciones de trabajo.", "Ser informados por las autoridades laborales sobre los daños producidos en la salud de los trabajadores.", "Paralizar la actividad laboral cuando se detecten riesgos muy graves para la salud de los trabajadores", "Tener acceso, sin limitación alguna, a la información y la documentación relativa a las condiciones de trabajo y de los trabajadores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 40, "El comité de seguridad y salud:", "Es el órgano científico y técnico especializado cuya misión es el análisis y estudio de las condiciones de seguridad y salud en el trabajo.", "Es el órgano paritario y colegiado de participación destinado a la consulta regular y periódica de las actuaciones de la empresa en materia de prevención de riesgos.", "Es el órgano al que le corresponde la función de la vigilancia y el control de la normativa sobre prevención de riesgos laborales.", "Es el órgano colegiado asesor de las administraciones públicas en la formulación de las políticas de prevención."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 41, "Indique la respuesta incorrecta en referencia al Comité de Seguridad y Salud:", "Se debe constituir un comité de seguridad y salud en todas las empresas o centros de trabajo que dispongan de cincuenta o más trabajadores.", "El Comité está formado por los delegados de prevención, por un lado, y por el empresario y/o sus representantes en número igual al de los delegados de prevención, por otro.", "El comité de seguridad y salud debe reunirse trimestralmente y siempre que lo solicite alguna de las representaciones en el mismo Comité.", "Las normas de funcionamiento del Comité de Seguridad y Salud las adopta el empresario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 42, "¿Qué es un servicio de prevención de acuerdo con el artículo 31 de la Ley de Prevención de riesgos laborales?", "Es el conjunto de medios humanos y materiales necesarios para llevar a cabo las actividades preventivas a fin de garantizar la protección adecuada de la seguridad y la salud del personal.", "Es una empresa que se contrata para gestionar los reconocimientos médicos y la asistencia a accidentes de trabajo y enfermedades profesionales.", "Es un conjunto de medios auxiliares para establecer el plan de prevención.", "Es la empresa que se encarga de la gestión de accidentes y enfermedades profesionales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 43, "De acuerdo con el artículo 32 de la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales, las mutuas de accidentes de trabajo y enfermedades profesionales", "Tienen prohibido la participación en actividades mercantiles de prevención.", "Pueden ejercer actividades preventivas sólo en casos concretos.", "Ejercen sus funciones de acuerdo con lo establecido en la ley.", "Las mutuas y los servicios de prevención son lo mismo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 44, "¿Qué son los delegados de prevención?", "Son elegidos en las elecciones sindicales.", "Son los representantes de los trabajadores con funciones específicas en materia de prevención de riesgos en el trabajo.", "Son las personas que realizan las evaluaciones de riesgos laborales.", "Los elige el empresario entre los representantes sindicales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 45, "¿Cuántos delegados de prevención son necesarios en la Administración Autonómica de las Islas Baleares con más de 5000 trabajadores?", "Al menos un delegado de prevención.", "Entre cuatro a cinco delegados de prevención.", "Ocho delegados de prevención.", "Sólo es necesario un delegado de personal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 46, "¿A qué están obligados los delegados de prevención con arreglo al artículo 37 de la Ley 31/1995, de prevención de riesgos laborales?", "A cumplir el deber de ejecución de las medidas preventivas.", "A cumplir con secreto profesional respecto a las informaciones a las que tengan acceso como consecuencia de su actuación en la empresa.", "Están obligados a formarse por cuenta propia.", "A seguir las indicaciones y instrucciones del empresario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 47, "¿Cuáles son las competencias y facultades del Comité de Seguridad y Salud?", "Elaborar el plan de prevención y evaluar las consecuencias en la aplicación.", "Evaluar los riesgos inherentes a los puestos de trabajo.", "Promover la aplicación de medidas correctoras.", "Participar en la elaboración, puesta en práctica y evaluación de los planes y programas de prevención de riesgos de la empresa, y promover iniciativas sobre métodos y procedimientos para la prevención de los riesgos en la empresa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 48, "¿Qué establece el artículo 41 de la Ley 31/1995, de 8 de noviembre, de Prevención de Riesgos Laborales?", "Los fabricantes, pero no los importadores deben cumplir con la Ley 31/1995, de 8 de noviembre, de prevención de riesgo laborales.", "Los fabricantes, los importadores y suministradores de maquinaria, equipos, productos y útiles de trabajo están obligados a asegurar que éstos no constituyan una fuente de peligro para el trabajador.", "Los fabricantes y suministradores deben cumplir con las disposiciones reglamentarias.", "El empresario debe hacer cumplir la ley a los fabricantes, importadores y suministradores de herramientas y servicios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 49, "El Real decreto 486/1997, de 14 de abril, por el que se establecen las disposiciones mínimas de seguridad y salud en los puestos de trabajo no es aplicable:", "A los medios de transporte, las obras de construcción, temporales o móviles, las industrias de extracción, los buques de pesca ni campos de cultivo, bosques u otros terrenos que se encuentren fuera de la zona edificada de estos terrenos.", "A los centros de trabajo de la administración pública.", "A los centros de trabajo del ámbito hospitalario.", "A los centros de trabajo de hostelería y restauración."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 50, "¿Cómo deben ser las puertas de emergencia de un centro de trabajo?", "Las puertas de emergencia deben abrirse hacia el interior y deben estar cerradas con cerradura.", "El Real decreto 486/1997, no regula cómo son las puertas de emergencia.", "Las puertas de emergencia deben abrirse hacia el exterior y no deben estar cerradas, por lo que cualquier persona que necesite usarlas en caso de urgencia pueda abrirlas fácil e inmediatamente.", "Tienen que ser de color rojo y pueden ser correderas o giratorias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 51, "En cuanto al orden, limpieza y mantenimiento de un centro de trabajo debe tenerse en cuenta que:", "El mantenimiento preventivo será realizado por el personal no especializado.", "Las zonas de paso, salidas y vías de circulación de los puestos de trabajo y, en especial, las salidas y vías de circulación previstas para la evacuación en casos de emergencia, deben permanecer libres de obstáculos de forma que sea posible utilizarlas en todo momento sin dificultades.", "La instalación eléctrica no debe revisarse periódicamente.", "La limpieza de centros de trabajo no es ámbito de aplicación de la ley de prevención de riesgo laborales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 52, "¿A qué riesgos laborales se ve sometido al personal que utiliza pantallas de visualización de datos?", "Solo fatiga visual.", "Fatiga física y visual.", "Somnolencia y sordera.", "Las principales alteraciones de la salud se deben, básicamente, a riesgos para la vista y los problemas físicos y de carga mental, así como el posible efecto combinado de los mismos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 53, "La iluminación de los puestos de trabajo debe cumplir con las condiciones siguientes:", "La distribución de los niveles de iluminación debe ser lo más uniforme posible y adecuado a la exigencia visual.", "No existen condiciones mínimas de iluminación.", "Con 500 lux es insuficiente para sitios administrativos.", "No es necesario tener en cuenta la iluminación en los puestos de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 54, "¿Cómo debe ser el material de primeros auxilios de un centro de trabajo?", "No es necesario el material porque el trabajador accidentado debe dirigirse a la Mutua de trabajo.", "Si el acceso al centro de asistencia médica es cercano no es necesario disponer de material de primeros auxilios.", "Debe ser adecuado, en cuanto a su cantidad y características, al número de trabajadores, a los riesgos a los que estén expuestos ya las facilidades de acceso al centro de asistencia médica más cercano.", "La Mutua de trabajo no proporciona el material necesario para actuar en caso de primeros auxilios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 55, "En la manipulación manual de cargas, ¿que características del medio laboral pueden aumentar el riesgo dorsolumbar?", "El estado de salud del personal.", "El espacio de trabajo es insuficiente, el terreno es irregular y la iluminación es escasa.", "La carga a trasladar.", "La carencia de información y formación al personal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 56, "¿Qué condiciones deben cumplir los equipos de protección individual?", "Deben de adecuarse al portador, después de los ajustes necesarios.", "Deben de tener en cuenta las condiciones anatómicas y fisiológicas y el estado de salud del trabajador", "Tienen que cumplir con la normativa vigente.", "Deben responder a las condiciones existentes en el puesto de trabajo, tener en cuenta las condiciones anatómicas y fisiológicas y el estado de salud del trabajador y adecuarse al portador, después de los ajustes necesarios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 57, "¿Qué disposiciones mínimas deben cumplir los puestos de trabajo?", "Las de orden y limpieza.", "Las condiciones constructivas, orden, limpieza y mantenimiento, señalización, instalaciones de servicio o protección, condiciones ambientales, iluminación, servicios higiénicos y locales de descanso; y material y locales de primeros auxilios.", "La iluminación y puertas de emergencia.", "Las condiciones ambientales y sonoras."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 58, "El diseño y las características constructivas de los puestos de trabajo deben ofrecer seguridad frente a los riesgos:", "Sólo por riesgos higiénicos.", "De fatiga visual y postural.", "De trauma auditivo.", "De los riesgos de resbalones o caídas, choques o golpes contra objetos y derrumbes o caída de materiales sobre los trabajadores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 59, "La exposición a los agentes físicos, químicos y biológicos del ambiente de trabajo se rige:", "Por normativa específica.", "Sólo por normativa internacional.", "Por normativa autonómica.", "Por la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 60, "Las condiciones ambientales y termo higrométricas de los puestos de trabajo:", "Son valores mínimos y máximos sólo de humedad.", "No pueden ocasionar ningún riesgo para la seguridad y salud del personal.", "Son la temperatura absoluta.", "Son la humedad relativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 61, "¿Qué aspectos de los puestos de trabajo deben tenerse en cuenta para que el personal con diversidad funcional se incorpore al puesto de trabajo teniendo en cuenta su seguridad y salud?", "Sólo se tienen en cuenta las rampas de acceso.", "Los servicios higiénicos deben estar adaptados.", "Las puertas, las vías de circulación, las escaleras, los servicios higiénicos y los puestos de trabajo, utilizados u ocupados por personal con diversidad funcional, deben estar condicionados para que estos trabajadores puedan utilizarlos.", "No es necesario realizar adaptaciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 62, "¿Deben los puestos de trabajo disponer de vestuarios cuando los trabajadores tengan que llevar ropa especial de trabajo?", "No.", "Sí.", "Nunca porque no es necesario.", "La ropa especial de trabajo no es ámbito de la prevención de riesgos laborales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 63, "¿Qué artículo de la Ley 31/1995, de prevención de riesgos laborales establece la información, consulta y participación del personal?", "El artículo 118.", "Los artículos 5 y 8.", "Los artículos 1 y 3.", "El artículo 18."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 64, "El artículo 17 de la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales hace referencia:", "A los equipos de trabajo y medios de protección.", "A la promoción de la salud.", "Al personal sensible.", "A la formación e información a los trabajadores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 29, 65, "¿Es necesario disponer de servicios externos a la empresa para aplicar las medidas de emergencia?", "Sí. En particular en materia de primeros auxilios, asistencia médica de urgencia, salvamento y lucha contra incendios para garantizar la rapidez y eficacia de las mismas.", "No es necesario.", "Se establece en el artículo 22 de la Ley 31/1995, de Prevención de Riesgos Laborales.", "Sí pero no es necesario tener en cuenta ninguna particularidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 1, "Los consejos insulares deben adecuar su funcionamiento a:", "Lo dispuesto en el título VI de la Ley 4/2022, de 28 de junio, de consejos insulares, y el respectivo reglamento orgánico.", "Lo que disponen el título V de la Ley 4/2022, de 28 de junio, de consejos insulares, y el reglamento orgánico respectivo.", "Lo que disponen el Estatuto de autonomía, el título V de la Ley 4/2022, de 28 de junio, de consejos insulares, y el respectivo reglamento orgánico.", "Lo que disponen el Estatuto de autonomía, el título VI de la Ley 4/2022, de 28 de junio, de consejos insulares, y el respectivo reglamento orgánico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 2, "El uso del catalán y del castellano en todo tipo de actuaciones institucionales y administrativas se regula:", "Preceptivamente en el reglamento orgánico.", "Preceptivamente en disposiciones específicas.", "En el reglamento orgánico o en disposiciones específicas.", "Únicamente puede ser regulado por el Estatuto de Autonomía y las leyes de la comunidad autónoma."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 3, "La urgencia de las sesiones del Consejo Ejecutivo:", "Corresponde a la presidencia su determinación.", "La ratificará la mayoría de los miembros del Consejo Ejecutivo que estén presentes.", "Debe proponerla la mayoría de los miembros del Consejo Ejecutivo que estén presentes.", "Tienen que ratificarla por unanimidad los miembros del Consejo Ejecutivo que estén presentes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 4, "Los acuerdos del Consejo Ejecutivo:", "Se adoptan por mayoría simple de los miembros presentes. El presidente dirime con su voto los empates.", "Se adoptan por mayoría calificada de los miembros presentes.", "Se adoptan por unanimidad de sus miembros.", "En el Consejo Ejecutivo no se producen votaciones, por ser un órgano de especial asesoramiento de la presidencia, que es quien resuelve."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 5, "Las sesiones del Consejo Ejecutivo:", "Son siempre públicas.", "Son públicas únicamente si así lo establece el reglamento orgánico.", "No son públicas, pero deben serlo, al menos, cuando se debatan asuntos en los que este órgano ejerza competencias por delegación del Pleno. No obstante, podrán convocarse otros miembros del Consell Insular, titulares de órganos directivos, empleados públicos o expertos cuyo parecer se considere necesario.", "No son públicas, pero deben serlo, al menos, cuando se debatan asuntos en los que este órgano ejerza competencias por delegación del Pleno. No obstante, pueden convocarse otros miembros del Consell Insular o expertos cuyo parecer se considere necesario, exclusivamente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 6, "La cuestión de confianza puede plantearla al Pleno del Consell Insular:", "El presidente sobre su programa en su conjunto, sobre una declaración de política especial o sobre la aprobación de cualquier asunto de trascendencia general.", "El presidente sobre su programa en su conjunto, sobre una declaración de política general o sobre la aprobación de cualquier asunto de trascendencia especial.", "Cualquier grupo político sobre su programa en su conjunto, sobre una declaración de política general o sobre la aprobación de cualquier asunto de trascendencia especial.", "El presidente o cualquier grupo político sobre su programa en su conjunto, sobre una declaración de política general o sobre la aprobación de cualquier asunto de trascendencia especial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 7, "El Pleno puede acordar celebrar una sesión extraordinaria que tenga por objeto debatir la gestión del Consejo Ejecutivo en áreas determinadas:", "A propuesta del presidente oa solicitud de al menos una cuarta parte de sus miembros.", "A propuesta del presidente oa solicitud de al menos una tercera parte de sus miembros.", "A propuesta del presidente oa solicitud de al menos dos grupos políticos que representen a una tercera parte de sus miembros.", "A propuesta del presidente oa solicitud de al menos dos grupos políticos que representen a una cuarta parte de sus miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 8, "Las mociones:", "Tienen un carácter de impulso, tramitación o adopción de una posición institucional, se sustancian ante el Pleno y pueden incluir una propuesta de resolución.", "Tienen un carácter de impulso, de tramitación o de adopción de una posición institucional, se sustancian ante el Pleno y deben incluir una propuesta de resolución.", "Tienen un carácter de impulso, resolución o adopción de una posición institucional, se sustancian ante el Pleno y deben incluir una propuesta de tramitación.", "Tienen un carácter de impulso, tramitación o adopción de una posición institucional, se sustancian ante el Pleno y pueden incluir una propuesta de recomendación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 9, "Las interpelaciones:", "Deben versar sobre la actuación del presidente, del Consejo Ejecutivo o de algún departamento en cuestiones de política general.", "Tienen que versar sobre la actuación del Pleno, del presidente, del Consejo Ejecutivo o de algún departamento en cuestiones de política general.", "Tienen que versar sobre la actuación del presidente, del Consejo Ejecutivo o de algún departamento en cuestiones de política insular.", "Tienen que versar sobre la actuación del pleno, del presidente, del Consejo Ejecutivo o de algún departamento en cuestiones de política insular."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 10, "Las preguntas:", "Tienen una respuesta oral o una respuesta escrita.", "Tienen una respuesta oral y una respuesta escrita.", "Tienen una respuesta únicamente oral.", "Tienen una respuesta únicamente escrita."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 11, "Con carácter general, y sin perjuicio de lo dispuesto en los artículos 54 y 55 de la Ley 4/2022, de 28 de junio, de consejos insulares, los órganos de los consejos insulares aplican, en todo lo no previsto en el capítulo III del título V de la mencionada ley:", "La legislación de régimen jurídico de la Administración de la Comunidad Autónoma.", "La legislación de régimen jurídico del Estado.", "La legislación de régimen jurídico de la administración local.", "La legislación de procedimiento administrativo de la administración local."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 12, "Ponen fin a la vía administrativa:", "Los acuerdos del Pleno y de las comisiones reguladas en el artículo 18 de la Ley 4/2022, de 28 de junio, de consejos insulares, los del presidente, los del Consejo Ejecutivo, los que resuelvan recursos de alzada y los así previstos en los estatutos de los entes del sector público instrumental.", "Los acuerdos del Pleno y de las comisiones reguladas en el artículo 18 de la Ley 4/2022, de 28 de junio, de consejos insulares, los del presidente, los del Consejo Ejecutivo, los de los consejeros ejecutivos y los así previstos en los estatutos de los entes del sector público instrumental.", "Los acuerdos del Pleno y de las comisiones reguladas en el artículo 18 de la Ley 4/2022, de 28 de junio, de consejos insulares, los del presidente y los que resuelvan recursos de alzada.", "Los acuerdos del Pleno y de las comisiones reguladas en el artículo 18 de la Ley 4/2022, de 28 de junio, de consejos insulares, los del presidente, los que resuelvan recursos de alzada y los así previstos en los estatutos de los entes del sector público instrumental."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 13, "Contra los actos dictados por los consejeros ejecutivos se puede interponer:", "Un recurso de alzada ante el Consejo Ejecutivo.", "Un recurso de alzada ante el Consejo Ejecutivo, salvo los que pongan fin a la vía administrativa de acuerdo con el apartado 1 d del artículo 66 de la Ley 4/2022, de 28 de junio, de consejos insulares.", "Un recurso de alzada ante la Presidencia.", "Un recurso de alzada ante el Pleno, salvo quienes pongan fin a la vía administrativa de acuerdo con el apartado 1 d del artículo 66 de la Ley 4/2022, de 28 de junio, de consejos insulares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 14, "Los órganos competentes para iniciar e instruir los procedimientos de revisión de oficio de disposiciones y actas:", "Los establece la Ley 4/2022, de 28 de junio, de consejos insulares.", "Los establece la legislación de régimen jurídico de la comunidad autónoma.", "Los establece el reglamento orgánico de cada consejo insular.", "Los establece el Pleno en la primera sesión que celebre en cada mandato."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 15, "La declaración de lesividad de los actos de los consejos insulares y de los entes que integran el sector público instrumental:", "Corresponde al Pleno.", "Corresponde a los mismos órganos que son competentes para resolver los procedimientos de revisión de oficio.", "Corresponde al presidente.", "Corresponde al Consejo Ejecutivo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 16, "Los procedimientos de responsabilidad patrimonial de la Administración insular los resuelve el Pleno:", "Si se trata de reclamaciones por importe igual o inferior al que fije el reglamento orgánico de cada consejo, y el Consejo Ejecutivo en el resto de casos. Supletoriamente, este importe será de 500.000.", "Si se trata de reclamaciones por importe igual o superior al que fije el reglamento orgánico de cada consejo, y el Consejo Ejecutivo en el resto de casos. Supletoriamente, este importe será de 500.000.", "Si se trata de reclamaciones por importe igual o superior al que fije el reglamento orgánico de cada consejo, y el Consejo Ejecutivo en el resto de casos. Supletoriamente, este importe será de 1.000.000.", "Si se trata de reclamaciones por importe igual o inferior al que fije el reglamento orgánico de cada consejo, y el Consejo Ejecutivo en el resto de casos. Supletoriamente, este importe será de 1.000.000."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 17, "El ejercicio de la potestad sancionadora corresponde:", "A los órganos insulares determinados legal o reglamentariamente por razón de la materia o, en su defecto, al presidente.", "A los órganos insulares determinados legal o reglamentariamente por razón de la materia o, en su defecto, al Consejo Ejecutivo.", "A los órganos insulares determinados legal o reglamentariamente por razón de la materia o, en su defecto, al consejero ejecutivo competente.", "A los órganos insulares determinados legal o reglamentariamente por razón de la materia o, en su defecto, al Pleno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 18, "El presidente del Consell Insular puede dictar disposiciones generales:", "Para la creación y extinción de departamentos al margen de lo que disponga el reglamento orgánico, incluida la modificación de la denominación y de las competencias que les corresponden, así como la fijación del ámbito funcional de los distintos órganos de cada departamento.", "Para la creación y extinción de departamentos en el marco de lo dispuesto en el reglamento orgánico, incluida la modificación de la denominación y de las competencias que les corresponden, así como la fijación del ámbito funcional de los diferentes órganos de cada departamento.", "Para la creación y extinción de departamentos en el marco de lo dispuesto en el reglamento orgánico, salvo la modificación de la denominación y de las competencias que les corresponden, así como la fijación del ámbito funcional de los distintos órganos de cada departamento.", "Para la creación y extinción de departamentos en el marco de lo dispuesto en el reglamento orgánico, incluida la modificación de la denominación y de las competencias que les corresponden, pero no la fijación del ámbito funcional de los distintos órganos de cada departamento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 19, "Los reglamentos ejecutivos son:", "Disposiciones generales dictadas para el desarrollo y ejecución de las leyes.", "Disposiciones especiales dictadas para el desarrollo y ejecución de las leyes.", "Disposiciones generales dictadas para el desarrollo y ejecución de las normas.", "Disposiciones especiales dictadas para el desarrollo y ejecución de las normas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 20, "Los presupuestos generales y los instrumentos de planificación general y sectorial y de ordenación territorial y urbanística tienen rango de:", "Disposición especial.", "Disposición reglamentaria.", "Disposición legal.", "Disposición especializada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 21, "La elaboración, contenido y aprobación de los instrumentos de planificación sectorial y de los de ordenación territorial y urbanística deben llevarse a cabo de conformidad:", "Con su legislación específica, sin que sea de aplicación lo previsto en el capítulo II del título VI de la Ley 4/2022, de 28 de junio, de consejos insulares.", "Con su legislación específica y lo que prevé el capítulo II del título VI de la Ley 4/2022, de 28 de junio, de consejos insulares.", "Con su legislación específica, y supletoriamente con lo que prevé el capítulo II del título VI de la Ley 4/2022, de 28 de junio, de consejos insulares.", "Con su legislación específica, y opcionalmente por lo que prevé el capítulo II del título VI de la Ley 4/2022, de 28 de junio, de consejos insulares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 22, "La potestad reglamentaria en las materias del artículo 70 del Estatuto de Autonomía corresponde:", "En los consejos insulares y en el Gobierno.", "En los consejos insulares y, supletoriamente, en el Gobierno.", "En los consejos insulares, sin posibilidad de intervención del Gobierno.", "A los consejos insulares, sin perjuicio de la facultad del Gobierno de establecer los principios generales en la materia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 23, "Las relaciones entre los reglamentos de cada consejo insular se rigen por los principios de:", "Competición y especialidad.", "Competencia y transparencia.", "Competición y transparencia.", "Competencia y especialidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 24, "Los reglamentos ejecutivos de los consejos insulares entran en vigor:", "Ensoldemano de su aprobación definitiva.", "Treinta días después de su publicación oficial, salvo que establezcan otra fecha.", "Después de veinte días de su publicación oficial, salvo que establezcan otra fecha.", "Veinte días después de su publicación oficial en cualquier caso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 25, "La consulta pública previa al inicio del procedimiento de elaboración de disposiciones reglamentarias y en los supuestos previstos en la normativa básica estatal no será preceptiva cuando se trate de iniciativas:", "De reglamentos técnicos y de organización.", "De reglamentos orgánicos.", "De reglamentos ejecutivos.", "De reglamentos de despliegue."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 26, "El proyecto de reglamento ejecutivo debe ser adoptado por:", "El Consejo Ejecutivo.", "El consejero ejecutivo competente por razón de la materia.", "El presidente.", "El Pleno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 27, "El plazo de los trámites de audiencia, consultas e información pública para la aprobación de reglamentos ejecutivos debe ser adecuado a la naturaleza de la disposición y, en todo caso:", "No inferior a cuarenta días.", "No inferior a treinta días.", "No inferior a veinte días.", "No inferior a diez días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 28, "¿Cuál de los siguientes informes y dictámenes no es obligatorio para la aprobación de un reglamento ejecutivo?", "Informe de evaluación de impacto de género.", "Dictamen del Consejo Consultivo de las Islas Baleares.", "Informe del Secretario General de la Corporación.", "Dictamen del Gobierno de las Islas Baleares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 29, "La Memoria del análisis del impacto normativo debe prever, en cualquier caso:", "La identificación de las cargas económicas que comporta para los ciudadanos.", "La identificación de las cargas administrativas que comporta para los ciudadanos.", "La mejora de las cargas económicas que conlleva para los ciudadanos.", "La mejora de las cargas administrativas que comporta para los ciudadanos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 30, "La propuesta previa del reglamento ejecutivo que se someta a aprobación definitiva debe ir acompañada de:", "La última versión del proyecto, la memoria de análisis de impacto normativo y el dictamen del Consejo Consultivo.", "La última versión del proyecto, la memoria de análisis de impacto de género y el dictamen del Consell Consultiu.", "La última versión del proyecto, la memoria de análisis de impacto normativo y el dictamen del Govern.", "La última versión del proyecto, la memoria de análisis de impacto de género y el dictamen del Govern."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 31, "La tramitación de urgencia de un procedimiento de elaboración de disposiciones reglamentarias implica:", "La priorización del procedimiento frente a otros procedimientos en curso.", "La reducción a la mitad de los plazos previstos para la realización de los trámites del procedimiento.", "La eliminación del trámite de audiencia pública.", "La eliminación del trámite de solicitud de informes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 32, "Para la elaboración del reglamento orgánico deben seguirse, en cualquier caso, los siguientes trámites:", "Información pública por plazo no inferior a un mes, informe sobre alegaciones, informe de los servicios jurídicos, dictamen del Consejo Consultivo y aprobación definitiva por el Pleno.", "Aprobación inicial por el Pleno, información pública por plazo no inferior a 45 días, informe sobre alegaciones, informe de los servicios jurídicos, dictamen del Consejo Consultivo y aprobación definitiva por el Pleno.", "Aprobación inicial por el Pleno, información pública por un plazo no inferior a un mes, informe sobre alegaciones, informe de los servicios jurídicos y aprobación definitiva por el Pleno.", "Aprobación inicial por el Pleno, información pública por plazo no inferior a un mes, informe sobre alegaciones, informe de los servicios jurídicos, dictamen del Consejo Consultivo y aprobación definitiva por el Pleno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 33, "Previamente a la elaboración de una proposición de ley, los consejos insulares deben:", "Solicitar informe al Consejo Consultivo de las Islas Baleares.", "Llevar a cabo la consulta ciudadana a través del sitio web correspondiente.", "Solicitar informe a la secretaría técnica competente.", "Realizar la consulta pública en el plazo de diez días hábiles."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 34, "Atribuyen competencias a los consejos insulares:", "El Estatuto de Autonomía.", "Las leyes del Estado.", "La Ley de consejos insulares.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 35, "¿El fomento y la difusión de la creación y la producción teatral, musical, cinematográfica y audiovisual, literaria, de danza y de artes combinadas son competencia de los consejos insulares?", "Sí, de acuerdo con el arte. 70 del Estatuto de Autonomía.", "Sí, de acuerdo con el arte. 71 del Estatuto de eutonomía.", "No, son competencia del Estado.", "No, son competencia del Gobierno de las Islas Baleares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 36, "Para defender sus proposiciones de ley, cada consejo insular puede designar hasta:", "Tres miembros de la Corporación.", "Cuatro miembros de la Corporación.", "Dos miembros de la Corporación.", "Cinco miembros de la Corporación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 37, "El texto de las proposiciones de ley de los consejos insulares debe contener:", "Un texto articulado.", "Una exposición de motivos.", "Una memoria sobre la oportunidad de la regulación.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 38, "¿Cuándo produce efectos el acuerdo de renuncia a la delegación de competencias en los consejos insulares?", "A partir de los dos meses siguientes a su publicación en el Boletín Oficial de las Illes Balears.", "La delegación de competencias en los consejos insulares es irrenunciable.", "Cuando así lo establezca el Gobierno de la comunidad autónoma.", "Cuando así lo establezca el consejo insular correspondiente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 39, "Si un consejo insular no acepta la atribución de una competencia:", "Podrá reclamarla en la propia legislatura.", "No podrá reclamarla en el mismo ejercicio presupuestario de distintas legislaturas.", "No podrá reclamarla en la propia legislatura.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 40, "¿Qué plazo tiene el consejo insular para acordar la propuesta de delegación de competencias municipales antes de que se entienda desestimada?", "Dos meses desde la presentación de la propuesta.", "Tres meses desde la presentación de la propuesta.", "Un mes desde la presentación de la propuesta.", "Un mes desde la aprobación de la propuesta por parte de la Corporación municipal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 41, "¿Pueden los entes instrumentales de los consejos insulares aceptar encargos de gestión de otras administraciones públicas?", "No, no pueden aceptar encargos de gestión de otras administraciones.", "Sí, y el encargo de gestión debe formalizarse mediante convenio.", "Sí, si comporta la atribución de facultades de resolución.", "Sí, pero no pueden dictar actos de trámite que no sean susceptibles de recurso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 42, "En la fecha de efectividad de la transferencia de competencias, ¿qué expedientes deben traspasarse a los consejos insulares?", "Los expedientes cerrados en la fecha de efectividad de la transferencia de competencias.", "Los expedientes iniciados y no cerrados en la fecha de efectividad de la transferencia de competencias no pueden traspasarse a los consejos insulares.", "Los expedientes en curso, cualquiera que sea su estado de tramitación.", "Los expedientes en curso y expedientes cerrados en la fecha de efectividad de la transferencia de competencias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 43, "¿Quién designa a los representantes de los consejos insulares en la Comisión General de Consejos Insulares?", "La Presidencia de los consejos insulares.", "El Consejo Ejecutivo de los consejos insulares.", "El Pleno de los consejos insulares.", "La Conferencia de Presidentes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 44, "¿Quién integra las conferencias sectoriales?", "Los consejeros responsables de la materia de cada consejo insular.", "El consejero autonómico correspondiente, que las preside, y los consejeros insulares responsables en la materia.", "El presidente del Gobierno de las Islas Baleares y los presidentes de los cuatro consejos insulares.", "El consejero autonómico correspondiente, que las preside, y los presidentes de los consejos insulares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 45, "En relación con las directrices de coordinación de la actividad de los consejos insulares, indique la respuesta correcta", "Las fija el Gobierno de las Islas Baleares y son vinculantes para los consejos insulares.", "Las fija el Gobierno de las Islas Baleares y no son vinculantes para los consejos insulares.", "Pueden adoptarse por acuerdo del Consejo de Gobierno en cualquier caso.", "Es preceptivo que el Gobierno de las Islas Baleares fije directrices de coordinación de la actividad de los consejos insulares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 46, "Mediante qué instrumentos la comunidad autónoma y los consejos insulares articulan la colaboración y cooperación mutuas?", "El ejercicio común de la iniciativa económica mediante la creación de sociedades mixtas.", "El Acuerdo marco.", "La Conferencia de Presidentes.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 47, "De acuerdo con el art.117 de la Ley 4/2022 de consejos insulares, los consejos insulares se relacionan con el resto de administraciones públicas respecto a la autonomía, colaboración, cooperación y coordinación, de acuerdo con los principios:", "Establecidos en la legislación básica del Estado y especialmente los de lealtad institucional.", "Establecidos en la legislación básica del Estado y especialmente los de legalidad.", "Establecidos en la legislación básica del Estado y especialmente los de eficacia.", "Establecidos en la legislación básica del Estado y especialmente los de jerarquía."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 48, "Los órganos de gobierno de los consejos insulares son:", "El Pleno.", "El Presidente.", "El Consejo Ejecutivo.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 49, "¿Cuáles de estas atribuciones no corresponde al Pleno?", "Aprobar el diseño de la bandera de la isla, su día de celebración, himno y otros símbolos distintivos.", "Establecer precios públicos.", "Aprobar las transferencias y delegaciones de competencias, así como los encargos de gestión, a otras administraciones.", "Todas las anteriores son atribuciones del Pleno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 50, "¿Cuál de estas opciones no tiene la consideración de miembros no adscritos?", "Los consejeros insulares que no se integren en el grupo político que forma parte de la candidatura electoral por la que fueron elegidos.", "Las candidaturas presentadas como coalición electoral, cuando alguno de los dos partidos políticos que la integran decida abandonarla.", "Los consejeros insulares que hayan concurrido a las elecciones en una agrupación, partido, federación o coalición política declarado ilegal por sentencia judicial firme.", "Los consejeros insulares que abandonen su grupo de procedencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 51, "¿Cuál de las siguientes reglas debe seguirse para la elección del presidente de los consejos insulares?", "La mesa de edad debe proponer al Pleno el candidato que presente más firmas de consejeros en apoyo a su candidatura y, en caso de empate, el que pertenezca a la lista electoral más votada.", "En caso de que hayan transcurrido cuarenta y ocho horas a partir de la primera votación para la investidura y ningún candidato haya obtenido la confianza del Pleno, será proclamando presidente quien encabece la lista electoral que haya obtenido el mayor número de votos.", "El candidato propuesto no debe presentar al ?le su programa político ni debe solicitar la confianza.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 52, "¿Cuál de estas atribuciones corresponde al vicepresidente del Consell Insular?", "Establecer las directrices generales de la acción de gobierno y dar las instrucciones pertinentes a los miembros del Consejo Ejecutivo para mantener la unidad de dirección política y administrativa.", "Sustituir en sus funciones al presidente en los casos de ausencia, enfermedad u otra circunstancia temporal que le impida el ejercicio de sus funciones.", "Plantear ante el Pleno la cuestión de confianza.", "Revocar las delegaciones que el presidente haya otorgado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 53, "En cuál de estas actuaciones debe justificar debidamente la concurrencia de la urgencia o razones de especial interés general el Gobierno en funciones:", "Las delegaciones acordadas en favor de otros órganos.", "La aprobación de contratos y concesiones por valor superior a 100.000 euros y la adquisición y enajenación de bienes por el mismo importe.", "La aprobación de ofertas de empleo público.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 54, "Los reglamentos orgánicos de los consejos insulares pueden prever:", "Reglas e instrumentos para conseguir una transparencia restringida de la institución.", "Medidas para mejorar el impulso, desarrollo y ordenación de la administración electrónica.", "El régimen de publicidad activa de la información institucional, administrativa y organizativa, de relevancia jurídica, presupuestaria y estadística.", "La creación de comisionados insulares, encargados de supervisar el funcionamiento de la administración insular para la protección de los derechos de los ciudadanos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 55, "¿Cuáles de éste nos no integran el sector público instrumental de los consejos insulares?", "Organismos autónomos.", "Fundaciones del sector público.", "Consorcios insulares.", "Entidades empresariales y sociedades mercantiles."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 56, "¿Pueden los consejos insulares aprobar otros reglamentos de carácter organizativo destinados a desplegar o completar las previsiones del reglamento orgánico?", "Sí, cuando se reglamente la organización de los servicios de los departamentos.", "En algunos casos.", "Sí, pueden aprobar otros reglamentos orgánicos.", "No pueden aprobar otros reglamentos orgánicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 57, "Cuál de estas afirmaciones no corresponde a la naturaleza de los consejos insulares:", "Los consejos insulares son las instituciones de gobierno de cada una de las islas.", "Los consejos insulares son entidades locales dotadas de personalidad jurídica propia.", "Los consejos insulares son entes instrumentales de la comunidad autónoma de las Illes Balears.", "Los consejos insulares son administraciones públicas territoriales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 58, "¿Cuál de estas atribuciones corresponde al presidente de los consejos insulares?", "Solicitar el dictamen del Consejo Consultivo de las Islas Baleares.", "Las respuestas a) y c) son correctas.", "Ordenar la publicación de las disposiciones generales en el Boletín Oficial de las Islas Baleares.", "Establecer precios públicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 59, "¿Cuál de las siguientes afirmaciones, en relación a los consejeros ejecutivos, no es correcta?", "Los consejeros ejecutivos son nombrados libremente por el presidente del Consell Insular.", "Inician su mandato en el momento de la toma de posesión.", "Los consejeros ejecutivos son los órganos jerárquicamente inferiores en los departamentos de la administración insular.", "Los consejeros ejecutivos son los titulares de los departamentos de la Administración insular."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 60, "Al reglamento orgánico de los consejos insulares, no le corresponde:", "Crear órganos colegiados a los que se le atribuyan funciones decisorias, de propuesta, de emisión de informes preceptivos o de seguimiento y control de otros órganos de la Administración insular.", "Crear y regular los órganos específicos para el ejercicio de las competencias del Consell Insular y concentrar las competencias atribuidas a los órganos de gobierno ya los órganos de administración con los límites previstos legalmente.", "Concretar las atribuciones y régimen de funcionamiento de los órganos previstos en la Ley de consejos insulares.", "Desconcentrar las competencias del Pleno en el presidente, en el Consejo Ejecutivo o en las comisiones reguladas en el artículo 18 de la Ley de consejos insulares, con los límites legalmente previstos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 61, "El plan de actuación inicial de los entes instrumentales debe incluir, al menos:", "Memoria que justifique la conveniencia y oportunidad de su creación.", "Órganos de gobierno del ente.", "Un estudio económico-financiero justificativo de la suficiencia de la dotación prevista para el comienzo de su actividad.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 62, "¿Cuál de estos criterios no procede para el nombramiento de los titulares de los órganos directivos de los consejos insulares?", "Por la formación.", "Por la experiencia.", "Por la competencia profesional.", "Por un procedimiento de comisión de servicios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 63, "El Consejo Ejecutivo de los consejos insulares está integrado por:", "Vicepresidente o vicepresidentes.", "Los consejeros ejecutivos jefes de los departamentos.", "El presidente.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 64, "Una vez producida la vacante del presidente, ¿en qué plazo el presidente interino debe convocar al Pleno para elegir a un nuevo presidente?", "En el plazo de 10 dias.", "En el plazo de 4 dias.", "En el plazo de un mes.", "En el plazo de 5 dias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 65, "¿Cuáles de estas atribuciones, el presidente, no puede delegar en el vicepresidente?", "Ordenar la ejecución directa de obras, la prestación de servicios o la realización de suministros en caso de catástrofes, de infortunios públicos o supuestos de grave riesgo, dando cuenta al Pleno en la primera sesión que tenga.", "Plantear ante el Pleno la cuestión de confianza.", "Ordenar la publicación de las disposiciones generales en el Boletín Oficial de las Islas Baleares.", "Solicitar el dictamen del Consejo Consultivo de las Islas Baleares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 8, 66, "En la sesión constitutiva del pleno de los consejos insulares, qué afirmación no es correcta:", "Los consejeros deben tomar posesión ante la mesa de edad mediante juramento o promesa.", "En la sesión constitutiva se procede a la elección del presidente", "La mesa de edad tiene que declarar constituida la nueva corporación si concurren la mayoria absoluta de los consejeros electos.", "Todas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 1, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, los tratamientos de datos a los que no sea directamente aplicable el Reglamento (UE) 2016/679 por afectar a actividades no comprendidas en el ámbito de aplicación del Derecho de la Unión Europea:", "Se regirán únicamente por lo dispuesto en su legislación específica si la hubiere.", "Se regirán por lo dispuesto en la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales y supletoriamente por lo establecido en el citado reglamento.", "Se regirán por lo dispuesto en su legislación específica si la hubiere y supletoriamente por lo establecido en el citado reglamento y en la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales.", "Se regirán por lo dispuesto en su legislación específica si la hubiere y supletoriamente por lo establecido en la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 2, "¿A cuál de los siguientes tratamientos de datos no le es de aplicación directa el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), por afectar a actividades no comprendidas en el ámbito de aplicación del Derecho de la Unión Europea?", "Tratamientos realizados al amparo de la legislación orgánica del régimen electoral general.", "Tratamiento de datos de alumnos de una Universidad.", "Tratamiento de datos realizado por empresas de telecomunicaciones.", "Tratamiento de datos realizado por un banco."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 3, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), ¿En que consiste el derecho de acceso del interesado?", "El interesado tendrá derecho a obtener del responsable del tratamiento confirmación de si se están tratando o no datos personales que le conciernen y, en tal caso, derecho de acceso a los datos personales y a la información indicada en el artículo 15 del reglamento indicado.", "El interesado ya debe conocer si se están tratando o no datos personales que le conciernen y, en todo caso, tiene derecho de acceso a los datos personales y a la información indicada en el artículo 15 del reglamento indicado.", "El interesado tendrá derecho a obtener del responsable del tratamiento confirmación de si se están tratando o no datos personales que le conciernen y, en este caso, puede solicitar el acceso a la Agencia Española de protección de datos.", "El interesado ya debe conocer si se están tratando o no datos personales que le conciernen y, en todo caso, tiene derecho de acceso a los datos personales y a la información indicada en el artículo 16 del reglamento indicado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 4, "Indica cuál de los siguientes no es un derecho digital reconocido en la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales:", "Derecho al testamento digital.", "Protección de datos de personas vulnerables en Internet.", "Derecho al olvido en servicios de redes sociales y servicios equivalentes.", "Derecho de portabilidad en servicios de redes sociales y servicios equivalentes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 5, "Indica cual de las siguientes respuestas no es un principio de la protección de datos de acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales.", "Exactitud de los datos referida unicamente al momento de su obtención.", "Deber de confidencialidad de los responsables y encargados del tratamiento de datos así como todas las personas que intervengan en cualquier fase de este.", "Tratamiento basado en el consentimiento del afectado, ya sea mediante una declaración o una clara acción afirmativa.", "Consentimiento de los menores de edad, cuando éstos sean mayores de catorce años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 6, "Indica cual de las siguientes respuestas no es un principio de la protección de datos de acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos).", "Limitación del plazo de conservación.", "Integridad y publicidad.", "Responsabilidad proactiva.", "Exactitud."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 7, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), cuando el responsable del tratamiento esté obligado a suprimir unos datos y los haya hecho públicos:", "Adoptará cualquier medida posible, incluidas medidas técnicas, con miras a informar a los responsables que estén tratando los datos objeto de supresión.", "Adoptará medidas razonables, incluidas medidas técnicas,teniendo en cuenta la tecnología disponible y el coste de su aplicación, con miras a informar a los responsables que estén tratando los datos objeto de supresión.", "Adoptará cualquier medida posible, incluidas medidas técnicas, con miras a informar al delegado de protección de datos que esté tratando los datos objeto de supresión.", "Adoptará medidas razonables, incluidas medidas técnicas,teniendo en cuenta la tecnología disponible y el coste de su aplicación, con miras a informar al delegado de protección de datos que esté tratando los datos objeto de supresión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 8, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), el interesado tendrá derecho a obtener del responsable del tratamiento la limitación del tratamiento de los datos cuando se cumpla alguna de las condiciones siguientes (indica la respuesta correcta):", "El tratamiento sea lícito y el interesado se oponga a la supresión de los datos personales y solicite en su lugar la limitación de su uso.", "El responsable necesita los datos personales para los fines del tratamiento, pero el interesado no los necesita para la formulación, el ejercicio o la defensa de reclamaciones.", "El interesado se haya opuesto al tratamiento en virtud del artículo 21, apartado 1, mientras se verifica si los motivos legítimos del responsable prevalecen sobre los del interesado.", "El interesado impugne la exactitud de los datos personales, durante un plazo que permita al responsable la supresión de los mismos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 9, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, cuando el responsable o el encargado del tratamiento hubieran designado un delegado de protección de datos:", "Deberán encargarle llevar el registro de actividades.", "Deberán comunicarle cualquier adición, modificación o exclusión en el contenido del registro de actividades.", "Éste será el responsable de cualquier adición, modificación o exclusión en el contenido del registro de actividades.", "Éste no tiene competencia ni debe conocer de las adiciones, modificaciones o exclusiones en el contenido del registro de actividades."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 10, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), el principio de limitación de la finalidad en el tratamiento de datos supone que los datos personales serán:", "Adecuados, pertinentes y limitados a lo necesario en relación con los fines para los que son tratados.", "Exactos y, si fuera necesario, actualizados.", "Recogidos con fines determinados, explícitos y legítimos, y no serán tratados ulteriormente de manera incompatible con dichos fines.", "Tratados de manera lícita, leal y transparente en relación con el interesado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 11, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, ¿que significa que los usuarios tienen derecho a la neutralidad de Internet?", "Los proveedores de servicios de Internet proporcionarán una oferta neutral de servicios sin discriminación por motivos políticos.", "El acceso a Internet de hombres y mujeres procurará la superación de la brecha de género tanto en el ámbito personal como laboral.", "El acceso a Internet deberá garantizar condiciones de igualdad para las personas que cuenten con necesidades especiales.", "Los proveedores de servicios de Internet proporcionarán una oferta transparente de servicios sin discriminación por motivos técnicos o económicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 12, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, cuando para el cumplimiento de la obligación de bloqueo, la configuración del sistema de información no permita éste o se requiera una adaptación que implique un esfuerzo desproporcionado:", "Se procederá a un copiado seguro de la información de modo que conste evidencia digital, o de otra naturaleza, que permita acreditar la autenticidad de la misma, la fecha del bloqueo y la no manipulación de los datos durante el mismo.", "Se procederá a un copiado seguro de la información de modo que se pueda bloquear esta copia.", "Se procederá a un copiado seguro de la información de modo que conste evidencia digital, o de otra naturaleza, que permita acreditar el correcto tratamiento de los datos.", "Se procederá a un copiado seguro de la información de modo que conste evidencia digital, o de otra naturaleza, hasta acreditar el incorrecto tratamiento de los datos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 13, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), cuando el interesado ejerza su derecho de oposición al tratamiento de sus datos personales cuando éste es necesario para el cumplimiento de una misión realizada en interés público:", "El responsable del tratamiento dejará de tratar los datos personales en todo caso.", "El responsable del tratamiento puede presentar una reclamación ante la autoridad de control competente.", "El responsable del tratamiento dejará de tratar los datos personales, salvo que acredite motivos legítimos imperiosos para el tratamiento que prevalezcan sobre los intereses, los derechos y las libertades del interesado, o para la formulación, el ejercicio o la defensa de reclamaciones.", "El responsable del tratamiento dejará de tratar los datos personales en el plazo de un mes, salvo que el interesado revoque su oposición."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 14, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, cuando finalice la prestación de los servicios del encargado, no procederá la destrucción de los datos cuando exista una previsión legal que obligue a su conservación, en cuyo caso:", "Deberán ser devueltos al responsable, que garantizará su correcta destrucción.", "Deberán ser devueltos al responsable, que garantizará su conservación mientras tal obligación persista.", "Deberán ser devueltos al responsable, que garantizará su conservación por el plazo de un año.", "Deberán ser devueltos al responsable, que garantizará su envío a la Autoridad de Control."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 15, "Indica cuál de las siguientes respuestas no está incluida entre las exigencias establecidas por la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales para garantizar el Derecho de acceso universal a Internet:", "Se garantizará un acceso universal, asequible, de calidad y no discriminatorio para toda la población.", "Los usuarios tienen derecho a la seguridad de las comunicaciones que transmitan y reciban a través de Internet.", "La garantía efectiva del derecho de acceso a Internet atenderá la realidad específica de los entornos rurales.", "El acceso a Internet deberá garantizar condiciones de igualdad para las personas que cuenten con necesidades especiales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 16, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, señala la respuesta correcta en relación al bloqueo de datos:", "El encargado del tratamiento podrá conservar, debidamente bloqueados, los datos en tanto pudieran derivarse responsabilidades de su relación con el responsable del tratamiento.", "El responsable del tratamiento podrá conservar, debidamente bloqueados, los datos en tanto pudieran derivarse responsabilidades de su relación con el encargado del tratamiento.", "El encargado del tratamiento podrá conservar, debidamente bloqueados, los datos en tanto pudieran derivarse responsabilidades de su relación con el delegado de protección de datos.", "El responsable del tratamiento podrá conservar, debidamente bloqueados, los datos en tanto pudieran derivarse responsabilidades de su relación con el delegado de protección de datos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 17, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), todo interesado tendrá derecho a no ser objeto de una decisión basada únicamente en el tratamiento automatizado,", "Incluida la elaboración de perfiles, que no produzca efectos jurídicos en él o no le afecte significativamente de modo similar.", "Incluida la elaboración de perfiles, que produzca efectos jurídicos en él o le afecte significativamente de modo similar.", "Excluida la elaboración de perfiles, que no produzca efectos jurídicos en él o no le afecte significativamente de modo similar.", "Excluida la elaboración de perfiles, que produzca efectos jurídicos en él o le afecte significativamente de modo similar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 18, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, ¿Que implica el Derecho a la educación digital en el ámbito del acceso a la función pública?", "La Constitución Española debe reflejar que el acceso a la función pública se ará de acuerdo con los principios de mérito, capacidad y protección de datos.", "Las Administraciones Públicas incorporarán cursos de formación continua en el acceso a datos personales i materias relacionadas con la garantía de los derechos digitales y con la protección de datos.", "Las  Administraciones Públicas incorporarán protocolos para no incluir en sus registros de personal datos personales de especial protección.", "Las Administraciones Públicas incorporarán a los temarios de las pruebas de acceso a los cuerpos superiores y a aquéllos en que habitualmente se desempeñen funciones que impliquen el acceso a datos personales materias relacionadas con la garantía de los derechos digitales y en particular el de protección de datos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 19, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, el deber de confidencialidad y de secreto profesional de los responsables y encargados del tratamiento de datos:", "se mantendrán aun cuando hubiese finalizado la relación del obligado con el responsable o encargado del tratamiento.", "se mantendrán hasta cinco años después de que finalice la relación del obligado con el responsable o encargado del tratamiento.", "se mantendrán hasta tres años después de que finalice la relación del obligado con el responsable o encargado del tratamiento.", "se mantendrán hasta que finalice la relación del obligado con el responsable o encargado del tratamiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 20, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, se entiende por consentimiento del afectado toda manifestación de voluntad libre, específica, informada e inequívoca por la que este acepta:", "De forma obligatoria mediante una declaración, el tratamiento de datos personales que le conciernen.", "Mediante una declaración o una clara acción afirmativa, el tratamiento de datos personales que le conciernen.", "Mediante una acción de no prohibición, el tratamiento de datos personales que le conciernen.", "Necesariamente mediante una declaración de no oposición al tratamiento de datos personales que le conciernen."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 21, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), el encargado del tratamiento y cualquier persona que actúe bajo la autoridad del responsable o del encargado y tenga acceso a datos personales solo podrán tratar dichos datos siguiendo instrucciones:", "del delegado de protección de datos, a no ser que estén obligados a ello en virtud del Derecho de la Unión o de los Estados miembros.", "del encargado, a no ser que estén obligados a ello en virtud del Derecho de la Unión o de los Estados miembros.", "del responsable, a no ser que estén obligados a ello en virtud del Derecho de la Unión o de los Estados miembros.", "de la autoridad de control, a no ser que estén obligados a ello en virtud del Derecho de la Unión o de los Estados miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 22, "De acuerdo con el Título V de la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, los responsables y encargados del tratamiento deberán designar un delegado de protección de datos (señala la respuesta incorrecta):", "Los establecimientos financieros de crédito.", "Las entidades aseguradoras y reaseguradoras.", "Los colegios profesionales y sus consejos generales.", "Los centros sanitarios no obligados al mantenimiento de las historias clínicas de los pacientes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 23, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, el tratamiento de datos personales solo podrá considerarse fundado en el cumplimiento de una obligación legal exigible al responsable, en los términos previstos en el artículo 6.1.c) del Reglamento (UE) 2016/679:", "Cuando así lo prevea una norma de Derecho de la Unión Europea o una norma con rango de ley.", "Cuando así lo prevea una norma reglamentaria de desarrollo de esta ley.", "Cuando así lo prevea exclusivamente una norma de Derecho de la Unión Europea.", "Cuando así lo prevea exclusivamente una norma con rango de ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 24, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), ¿cuál de las siguientes condiciones no suponen la licitud del tratamiento de datos personales¿", "El interesado dio su consentimiento para el tratamiento de sus datos personales para uno o varios fines específicos.", "El tratamiento es necesario para la satisfacción de intereses legítimos perseguidos por el responsable del tratamiento o por un tercero, siempre que el particular sea un niño.", "El tratamiento es necesario para proteger intereses vitales del interesado o de otra persona física.", "El tratamiento es necesario para el cumplimiento de una obligación legal aplicable al responsable del tratamiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 25, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, ¿Que implica el Derecho de rectificación en Internet?", "Que los trabajadores y los empleados públicos tendrán derecho a la desconexión digital a fin de garantizar, fuera del tiempo de trabajo legal o convencionalmente establecido, el respeto de su tiempo de descanso, permisos y vacaciones, así como de su intimidad personal y familiar.", "que cuando los medios de comunicación digitales deban atender la solicitud de rectificación formulada contra ellos deberán proceder a la publicación en sus archivos digitales de un aviso aclaratorio que ponga de manifiesto que la noticia original no refleja la situación actual del individuo", "Que toda persona tiene derecho a que sean suprimidos, a su simple solicitud, los datos personales que hubiese facilitado para su publicación por servicios de redes sociales y servicios de la sociedad de la información equivalentes.", "Que los usuarios tienen derecho a la seguridad de las comunicaciones que transmitan y reciban a través de Internet. Los proveedores de servicios de Internet informarán a los usuarios de sus derechos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 26, "De acuerdo con el Título V de la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, cuando  los responsables y encargados del tratamiento no estén obligados a designar un delegado de protección de datos:", "No podrán designarlo de manera voluntaria.", "Podrán designar de manera voluntaria un delegado de protección de datos, que quedará sometido al régimen establecido en el Reglamento (UE) 2016/679 y en la presente ley orgánica.", "Podrán designar de manera voluntaria un delegado de protección de datos, que no quedará sometido al régimen establecido en el Reglamento (UE) 2016/679 y en la presente ley orgánica.", "Podrán designar de manera voluntaria un delegado de protección de datos, que quedará sometido al régimen establecido en la presente ley orgánica pero no al Reglamento (UE) 2016/679."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 27, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), cuando el tratamiento se base en el consentimiento del interesado, la retirada del consentimiento:", "Afectará a la licitud del tratamiento basada en el consentimiento previo a su retirada, suponiendo este tratamiento una infracción leve.", "No afectará a la licitud del tratamiento basada en el consentimiento previo a su retirada.", "Afectará a la licitud del tratamiento basada en el consentimiento previo a su retirada, suponiendo una infracción grave.", "Afectará a la licitud del tratamiento basada en el consentimiento previo a su retirada, suponiendo una infracción muy grave."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 28, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, la Agencia Española de Protección de Datos es una autoridad administrativa independiente de ámbito estatal:", "De las previstas en la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, con personalidad jurídica y plena capacidad pública y privada, que actúa bajo las órdenes de los poderes públicos en el ejercicio de sus funciones.", "De las previstas en la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, con personalidad jurídica y plena capacidad pública y privada, que actúa bajo las órdenes de los poderes públicos en el ejercicio de sus funciones.", "De las previstas en la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, con personalidad jurídica y plena capacidad pública y privada, que actúa con plena independencia de los poderes públicos en el ejercicio de sus funciones.", "De las previstas en la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, con personalidad jurídica y plena capacidad pública y privada, que actúa con plena independencia de los poderes públicos en el ejercicio de sus funciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 29, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, la Agencia Española de Protección de Datos:", "Elaborará su presupuesto y lo remitirá al Gobierno para su aprobación e integración en los Presupuestos Generales del Estado.", "Propondrá su presupuesto al Gobierno para que sea elaborado, aprobado e integrado en los Presupuestos Generales del Estado.", "Propondrá su presupuesto al Ministerio de Justicia para que sea elaborado, aprobado e integrado en los Presupuestos Generales del Estado.", "Elaborará y aprobará su presupuesto y lo remitirá al Gobierno para que sea integrado, con independencia, en los Presupuestos Generales del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 30, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, ¿Que implica el Derecho a la intimidad y uso de dispositivos digitales en el ámbito laboral?", "Que los trabajadores y los empleados públicos tendrán derecho a la desconexión digital a fin de garantizar, fuera del tiempo de trabajo legal o convencionalmente establecido, el respeto de su tiempo de descanso, permisos y vacaciones, así como de su intimidad personal y familiar.", "Que los empleadores podrán tratar las imágenes obtenidas a través de sistemas de cámaras o videocámaras para el ejercicio de las funciones de control de los trabajadores o los empleados públicos previstas, respectivamente, en el artículo 20.3 del Estatuto de los Trabajadores y en la legislación de función pública, siempre que estas funciones se ejerzan dentro de su marco legal y con los límites inherentes al mismo.", "Que se preservará el derecho a la desconexión digital en los supuestos de realización total o parcial del trabajo a distancia así como en el domicilio del empleado vinculado al uso con fines laborales de herramientas tecnológicas.", "Que los trabajadores y los empleados públicos tendrán derecho a la protección de su intimidad en el uso de los dispositivos digitales puestos a su disposición por su empleador."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 31, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), cuando el consentimiento para el tratamiento de datos personales, es dado por el titular de la patria potestad o tutela sobre el niño menor de 16 años.", "El encargado del tratamiento hará esfuerzos razonables para verificar que el consentimiento fue dado o autorizado por el titular de la patria potestad o tutela sobre el niño, teniendo en cuenta la tecnología disponible.", "El encargado del tratamiento debe verificar con total certeza que el consentimiento fue dado o autorizado por el titular de la patria potestad o tutela sobre el niño.", "El responsable del tratamiento hará esfuerzos razonables para verificar que el consentimiento fue dado o autorizado por el titular de la patria potestad o tutela sobre el niño, teniendo en cuenta la tecnología disponible.", "El responsable del tratamiento debe verificar con total certeza que el consentimiento fue dado o autorizado por el titular de la patria potestad o tutela sobre el niño."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 32, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, la Presidencia y el Adjunto solo cesarán antes de la expiración de su mandato, a petición propia o por separación acordada por el Consejo de Ministros, por (señala la incorrecta):", "Incapacidad sobrevenida para el ejercicio de su función.", "Incumplimiento grave de sus obligaciones.", "Incompatibilidad.", "Condena provisional o firme por delito doloso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 33, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, la Agencia Española de Protección de Datos podrá:", "La Presidencia de la Agencia Española de Protección de Datos podrá acordar la realización de planes de auditoría preventiva.", "La Presidencia de la Agencia Española de Protección de Datos podrá acordar la realización de planes de auditoría correctiva.", "El Consejo Consultivo de la Agencia Española de Protección de Datos podrá acordar la realización de planes de auditoría preventiva.", "El Consejo Consultivo de la Agencia Española de Protección de Datos podrá acordar la realización de planes de auditoría correctiva."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 34, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), si los fines para los cuales un responsable trata datos personales ya no requieren que el responsable identifique un interesado:", "Este estará obligado en todo caso a comunicar este hecho al interesado con la única finalidad de cumplir el presente Reglamento.", "Este estará obligado en todo caso a volver a identificar al interesado con la única finalidad de cumplir el presente Reglamento.", "Este estará obligado a mantener, obtener o tratar información adicional con vistas a identificar al interesado con la única finalidad de cumplir el presente Reglamento.", "Este no estará obligado a mantener, obtener o tratar información adicional con vistas a identificar al interesado con la única finalidad de cumplir el presente Reglamento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 35, "Indica cuál de las siguientes respuestas no está incluida entre las exigencias establecidas por la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales para garantizar el derecho a la intimidad ante la utilización de sistemas de geolocalización en el ámbito laboral.", "Con carácter previo, los empleadores habrán de informar de forma expresa, clara e inequívoca a los trabajadores o los empleados públicos y, en su caso, a sus representantes, acerca de la existencia y características de estos dispositivos de geolocalización en el ámbito laboral.", "Los empleadores podrán tratar los datos obtenidos a través de sistemas de geolocalización para el ejercicio de las funciones de control de los trabajadores o los empleados públicos previstas, respectivamente, en el Estatuto de los Trabajadores y en la legislación de función pública, siempre que estas funciones se ejerzan dentro de su marco legal y con los límites inherentes al mismo.", "Con carácter previo, los empleadores deberán informar a los trabajadores acerca de la posibilidad de baja voluntaria en la empresa ante la utilización  de dispositivos de geolocalización.", "Con carácter previo, los empleadores deberán informar a los trabajadores o los empleados públicos acerca del posible ejercicio de los derechos de acceso, rectificación, limitación del tratamiento y supresión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 36, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, indica cual de las siguientes es una infracción muy grave:", "El incumplimiento de la obligación de bloqueo de los datos establecida en el artículo 32 de esta ley orgánica cuando la misma sea exigible.", "Encargar el tratamiento de datos a un tercero sin la previa formalización de un contrato u otro acto jurídico escrito con el contenido exigido por el artículo 28.3 del Reglamento (UE) 2016/679.", "No poner a disposición de la autoridad de protección de datos que lo haya solicitado, el registro de actividades de tratamiento, conforme al apartado 4 del artículo 30 del Reglamento (UE) 2016/679.", "No cooperar con las autoridades de control en el desempeño de sus funciones en los supuestos no previstos en el artículo 72 de esta ley orgánica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 37, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, indica cual de las siguientes es una infracción leve:", "El incumplimiento por parte de un organismo de certificación de los principios y deberes a los que está sometido según lo previsto en los artículos 42 y 43 de Reglamento (UE) 2016/679.", "El tratamiento de datos personales sin llevar a cabo una previa valoración de los elementos mencionados en el artículo 28 de esta ley orgánica.", "La falta de atención por el representante en la Unión del responsable o del encargado del tratamiento de las solicitudes efectuadas por la autoridad de protección de datos o por los afectados.", "El incumplimiento del principio de transparencia de la información o el derecho de información del afectado por no facilitar toda la información exigida por los artículos 13 y 14 del Reglamento (UE) 2016/679."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 38, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, cuando los datos personales sean obtenidos del afectado y fueran a ser tratados para la elaboración de perfiles, el afectado deberá ser informado de su derecho a:", "Oponerse a la adopción de decisiones individuales automatizadas independientemente de los efectos que produzcan.", "Conocer los resultados de la elaboración de su perfil.", "Conocer los resultados de la elaboración de su perfil y oponerse a su uso.", "Oponerse a la adopción de decisiones individuales automatizadas que produzcan efectos jurídicos sobre él."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 39, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, ¿Qué implica el Derecho al olvido en búsquedas de Internet?", "Que toda persona tiene derecho a que los motores de búsqueda en Internet eliminen de las listas de resultados que se obtuvieran, tras una búsqueda efectuada a partir de su nombre, los enlaces publicados que contuvieran información relativa a esa persona cuando fuesen inadecuados, entre otros motivos.", "Que toda persona tiene derecho a que sean suprimidos, a su simple solicitud, los datos personales que hubiese facilitado para su publicación por servicios de redes sociales y servicios de la sociedad de la información equivalentes.", "Que los responsables de redes sociales y servicios equivalentes adoptarán protocolos adecuados para posibilitar el ejercicio del derecho de rectificación ante los usuarios que difundan contenidos que atenten contra el derecho al honor, la intimidad personal y familiar en Internet.", "Que los usuarios tienen derecho a la seguridad de las comunicaciones que transmitan y reciban a través de Internet."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 40, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, indica cuál de las siguientes es una infracción grave:", "El incumplimiento de la obligación de bloqueo de los datos establecida en el artículo 32 de esta ley orgánica cuando la misma sea exigible.", "La falta de adopción de aquellas medidas técnicas y organizativas que resulten apropiadas para garantizar un nivel de seguridad adecuado al riesgo del tratamiento, en los términos exigidos por el artículo 32.1 del Reglamento (UE) 2016/679.", "El incumplimiento de la obligación de bloqueo de los datos establecida en el artículo 32 de esta ley orgánica cuando la misma sea exigible.", "El impedimento o la obstaculización o la no atención reiterada del ejercicio de los derechos establecidos en los artículos 15 a 22 del Reglamento (UE) 2016/679."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 41, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, una vez interrumpida la prescripción de la infracción por la iniciación, con conocimiento del interesado, del procedimiento sancionador, se reinicirá el plazo de prescripción:", "Si el expediente sancionador estuviere paralizado durante más de nueve meses por causas no imputables al presunto infractor.", "Si el expediente sancionador estuviere paralizado durante más de nueve meses por causas imputables al presunto infractor.", "Si el expediente sancionador estuviere paralizado durante más de seis meses por causas no imputables al presunto infractor.", "Si el expediente sancionador estuviere paralizado durante más de seis meses por causas imputables al presunto infractor."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 42, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), al decidir la imposición de una multa administrativa y su cuantía en cada caso individual se tendrá debidamente en cuenta (indica la respuesta incorrecta):", "Las categorías de los datos de carácter personal afectados por la infracción.", "La adhesión a códigos de conducta en virtud del artículo 40 o a mecanismos de certificación aprobados con arreglo al artículo 42.", "La forma en que la autoridad de control tuvo conocimiento de la infracción, en particular si hubo una denuncia de la infracción.", "La intencionalidad o negligencia en la infracción."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 43, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, al decidir la imposición de una multa administrativa y su cuantía se tendrá en cuenta en cada caso individual (indica la respuesta incorrecta):", "El carácter continuado de la infracción.", "La afectación a los derechos de los menores.", "La existencia de un proceso de fusión por absorción anterior a la comisión de la infracción.", "La posibilidad de que la conducta del afectado hubiera podido inducir a la comisión de la infracción."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 44, "En cualquier caso, ¿Quién podrá ejercitar en nombre y representación de los menores de catorce años los derechos de acceso, rectificación, cancelación, oposición o cualesquiera otros que pudieran corresponderles en el contexto de la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales?", "Los titulares de la patria potestad.", "Los propios menores.", "La Fiscalía.", "El defensor del Pueblo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 45, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, ¿Que implica el Derecho al olvido en servicios de redes sociales y servicios equivalentes?", "Que toda persona tiene derecho a que los motores de búsqueda en Internet eliminen de las listas de resultados que se obtuvieran, tras una búsqueda efectuada a partir de su nombre, los enlaces publicados que contuvieran información relativa a esa persona cuando fuesen inadecuados, entre otros motivos.", "Que toda persona tiene derecho a que sean suprimidos, a su simple solicitud, los datos personales que hubiese facilitado para su publicación por servicios de redes sociales y servicios de la sociedad de la información equivalentes.", "Que los responsables de redes sociales y servicios equivalentes adoptarán protocolos adecuados para posibilitar el ejercicio del derecho de rectificación ante los usuarios que difundan contenidos que atenten contra el derecho al honor, la intimidad personal y familiar en Internet.", "Que los usuarios tienen derecho a la seguridad de las comunicaciones que transmitan y reciban a través de Internet."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 46, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, indica la respuesta correcta en relación a la prescripción de las sanciones impuestas en aplicación del Reglamento (UE) 2016/679 y de esta ley orgánica:", "Las sanciones impuestas por infracciones leves prescriben en el plazo de un año.", "Las sanciones por importe igual o inferior a 40.000 euros, prescriben en el plazo de un año.", "Las sanciones impuestas por infracciones leves prescriben en el plazo de 6 meses.", "Las sanciones por importe igual o inferior a 40.000 euros, prescriben en el plazo de 6 meses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 47, "De acuerdo con el derecho a la transparencia de la información regulado en el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), el responsable del tratamiento facilitará al interesado información relativa a sus actuaciones en el plazo:", "De un mes a partir de la recepción de la solicitud, con posibilidad de una prórroga de dos meses.", "De dos meses a partir de la recepción de la solicitud, con posibilidad de una prórroga de otros dos meses.", "De un mes a partir de la recepción de la solicitud, sin posibilidad de prórroga.", "De dos meses a partir de la recepción de la solicitud, sin posibilidad de prórroga."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 48, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), ¿cual de las siguientes condiciones no suponen la licitud del tratamiento de datos personales?", "El tratamiento es necesario para la ejecución de un contrato en el que el interesado es parte o para la aplicación a petición de este de medidas precontractuales.", "El tratamiento es necesario para el cumplimiento de una obligación legal aplicable al particular.", "El tratamiento es necesario para proteger intereses vitales del interesado o de otra persona física.", "El interesado dio su consentimiento para el tratamiento de sus datos personales para uno o varios fines específicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 49, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, cuando los datos personales sean obtenidos del afectado, el responsable del tratamiento deberá facilitar al afectado la información básica del tratamiento de esos datos, que debe contener:", "La identidad del responsable y del encargado del tratamiento.", "La posibilidad de ejercer los derechos establecidos en los artículos 15 a 22 del Reglamento (UE) 2016/679.", "Los resultados del tratamiento.", "Los medios de consentimiento del tratamiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 50, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, la Presidencia de la Agencia Española de Protección de Datos estará asesorada por un Consejo Consultivo compuesto por los siguientes miembros (señala la incorrecta):", "Un experto propuesto por la Federación Española de Municipios y Provincias.", "Un experto propuesto por las organizaciones empresariales.", "Un experto propuesto por el Consejo de Consumidores y Usuarios.", "Un Senador, propuesto por el Senado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 51, "De acuerdo con el derecho a la Transparencia de la información regulado en el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), si el responsable del tratamiento prorroga el plazo para facilitar al interesado información relativa a sus actuaciones:", "El responsable no debe informar al interesado de la prórroga sino que debe facilitar al interesado información relativa a sus actuaciones en el menor tiempo posible.", "El responsable informará al interesado de la prórroga en el plazo de un mes a partir de la recepción de la solicitud, sin necesidad de indicar los motivos de la dilación.", "El responsable informará al interesado de la prórroga en el plazo de un mes a partir de la recepción de la solicitud, indicando los motivos de la dilación.", "El responsable no puede prorrogar el plazo para facilitar al interesado información relativa a sus actuaciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 52, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, ¿Qué implica el derecho de portabilidad en servicios de redes sociales y servicios equivalentes?", "Que los usuarios de servicios de redes sociales y servicios de la sociedad de la información equivalentes tendrán derecho a que los datos que hubieran facilitado a los prestadores de dichos servicios sean transmitidos directamente a otro prestador designado por el usuario, en todo caso.", "Que los usuarios de servicios de redes sociales y servicios de la sociedad de la información equivalentes tendrán derecho a recibir y transmitir los contenidos que hubieran facilitado a los prestadores de dichos servicios, pero no a que los prestadores los transmitan directamente a otro prestador designado por el usuario.", "Que los usuarios de servicios de redes sociales y servicios de la sociedad de la información equivalentes tendrán derecho a recibir y transmitir los contenidos que hubieran facilitado a los prestadores de dichos servicios, así como a que los prestadores los transmitan directamente a otro prestador designado por el usuario, siempre que sea técnicamente posible.", "Que los prestadores no podrán conservar copia de los contenidos, en ningún caso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 53, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, cuando los datos personales no hubieran sido obtenidos del afectado, el responsable podrá dar cumplimiento al deber de información establecido en el artículo 14 del Reglamento (UE) 2016/679 facilitando a aquel la información básica del tratamiento de esos datos, entre la que no se incluye:", "Las categorías de datos objeto de tratamiento.", "Las fuentes de las que procedieran los datos.", "Los medios de consentimiento del tratamiento.", "La identidad del responsable del tratamiento y de su representante, en su caso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 54, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, los derechos reconocidos en los artículos 15 a 22 del Reglamento (UE) 2016/679, podrán ejercerse (señale la respuesta incorrecta):", "Por medio de representante legal.", "Directamente.", "Por medio de representante voluntario.", "Por medio del encargado del tratamiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 55, "De acuerdo con el derecho a la transparencia de la información regulado en el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), ¿cuando puede el responsable negarse a actuar a petición del interesado con el fin de ejercer sus derechos?", "Nunca.", "Cuando por causes técnicas no pueda atenderle.", "Cuando pueda demostrar que no está en condiciones de identificar al interesado.", "Cuando el encargado del tratamiento de datos no cumpla con su contrato."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 56, "De acuerdo con el derecho a la Transparencia de la información regulado en el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), cuando el responsable del tratamiento considere que las solicitudes sean manifiestamente infundadas o excesivas:", "El responsable del tratamiento soportará la carga de demostrar el carácter manifiestamente infundado o excesivo de la solicitud.", "El encargado del tratamiento soportará la carga de demostrar el carácter manifiestamente infundado o excesivo de la solicitud.", "El interesado soportará la carga de demostrar la inexistencia de carácter infundado o excesivo de la solicitud.", "No se regula en el Reglamento (UE) 2016/679 el carácter infundado o excesivo de la solicitud."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 57, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, los responsables y encargados, teniendo en cuenta los elementos enumerados en los artículos 24 y 25 del Reglamento (UE) 2016/679, determinarán las medidas técnicas y organizativas apropiadas que deben aplicar a fin de garantizar y acreditar que el tratamiento es conforme, entre otros, con:", "Con la legislación sectorial aplicable.", "Con la finalidad del tratamiento.", "Con el contrato que regule las obligaciones de ambos.", "Con la legislación local."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 58, "De acuerdo con el derecho a la Transparencia de la información regulado en el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), si el responsable del tratamiento no da curso a la solicitud del interesado:", "Le informará sin dilación, y a más tardar transcurridos 15 días de la recepción de la solicitud, de las razones de su no actuación.", "Le informará sin dilación, y a más tardar transcurridos 10 días de la recepción de la solicitud, de las razones de su no actuación.", "Le informará sin dilación, y a más tardar transcurridos dos meses de la recepción de la solicitud, de las razones de su no actuación.", "Le informará sin dilación, y a más tardar transcurrido un mes de la recepción de la solicitud, de las razones de su no actuación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 59, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, a los efectos establecidos en el artículo 12.5 del Reglamento (UE) 2016/679 se podrá considerar repetitivo el ejercicio del derecho de acceso:", "Cuando del derecho de acceso sea ejercido en más de una ocasión durante el plazo de seis meses, en todo caso.", "Cuando del derecho de acceso sea ejercido en más de una ocasión durante el plazo de un año, en todo caso.", "Cuando del derecho de acceso sea ejercido en más de una ocasión durante el plazo de seis meses, a menos que exista causa legítima para ello.", "Cuando del derecho de acceso sea ejercido en más de una ocasión durante el plazo de un año, a menos que exista causa legítima para ello."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 60, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, para la adopción de las medidas técnicas y organizativas apropiadas que deben aplicar los responsables y encargados del tratamiento tendrán en cuenta, en particular, los mayores riesgos que podrían producirse cuando (señala la incorrecta):", "Cuando el tratamiento implicase una evaluación de aspectos personales de los afectados con el fin de crear o utilizar perfiles personales de los mismos.", "Cuando se lleve a cabo el tratamiento de datos de grupos de afectados en situación de especial vulnerabilidad.", "Cuando el tratamiento garantice a los afectados sus derechos y libertades.", "Cuando el tratamiento pudiera generar situaciones de discriminación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 61, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, ¿Que implica el Derecho a la desconexión digital en el ámbito laboral?", "Que los trabajadores y los empleados públicos tendrán derecho a la desconexión digital a fin de garantizar, fuera del tiempo de trabajo legal o convencionalmente establecido, el respeto de su tiempo de descanso, permisos y vacaciones, así como de su intimidad personal y familiar.", "Que los empleadores podrán tratar las imágenes obtenidas a través de sistemas de cámaras o videocámaras para el ejercicio de las funciones de control de los trabajadores o los empleados públicos previstas, respectivamente, en el artículo 20.3 del Estatuto de los Trabajadores y en la legislación de función pública.", "Que los empleadores podrán tratar los datos obtenidos a través de sistemas de geolocalización para el ejercicio de las funciones de control de los trabajadores o los empleados públicos.", "Que los trabajadores y los empleados públicos tendrán derecho a la protección de su intimidad en el uso de los dispositivos digitales puestos a su disposición por su empleador."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 62, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), ¿qué información debe facilitar el responsable del tratamiento al interesado en el momento en que los datos personales se obtengan?", "La identidad y los datos de contacto del responsable y, en su caso, de su encargado.", "Los datos de contacto del encargado, en su caso.", "Los fines del tratamiento a que se destinan los datos personales y la base jurídica del tratamiento.", "El derecho a presentar una reclamación ante el propio responsable."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 63, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, a los efectos establecidos en el artículo 12.5 del Reglamento (UE) 2016/679 se podrá considerar repetitivo el ejercicio del derecho de acceso en más de una ocasión durante el plazo de:", "3 meses, a menos que exista causa legítima para ello.", "6 meses, a menos que exista causa legítima para ello.", "9 meses, a menos que exista causa legítima para ello.", "1 año, a menos que exista causa legítima para ello."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 64, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), cuando el interesado se oponga al tratamiento con fines de mercadotecnia directa:", "El encargado valorará los motivos legítimos imperiosos para continuar el tratamiento.", "El responsable valorará los motivos legítimos imperiosos para continuar el tratamiento.", "Los datos personales pueden dejar de ser tratados para dichos fines teniendo en cuenta el estado de la técnica.", "Los datos personales dejarán de ser tratados para dichos fines."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 65, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, los responsables y encargados del tratamiento o, en su caso, sus representantes deberán mantener el registro de actividades de tratamiento al que se refiere el artículo 30 del Reglamento (UE) 2016/679:", "En todo caso.", "Salvo que no se prevea el registro de actividades en el contrato que regula las obligaciones del encargado con el responsable.", "Salvo que sea de aplicación la excepción prevista en su apartado 5.", "Salvo que la Autoridad de Control lo autorice."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 66, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, indica cuál de las siguientes respuestas no es uno de los objetivos del Plan de Acceso a Internet para el impulso de los derechos digitales:", "Superar las brechas digitales y garantizar el acceso a Internet de colectivos vulnerables o con necesidades especiales y de entornos familiares y sociales económicamente desfavorecidos", "Fomentar medidas educativas que promuevan la formación en competencias y habilidades digitales básicas a personas y colectivos en riesgo de exclusión digital.", "Fomentar medidas educativas que promuevan la capacidad de todas las personas para realizar un uso autónomo y responsable de Internet y de las tecnologías digitales.", "Impulsar la existencia de espacios de conexión de acceso privado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 30, 67, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, cuando la solicitud en el ejercicio del derecho de acceso se considere excesiva:", "Se exige al responsable del tratamiento la satisfacción del derecho de acceso sin dilaciones indebidas.", "Se exige al responsable del tratamiento la satisfacción del derecho de acceso en el plazo de un mes y sin dilaciones indebidas.", "Se exige al responsable del tratamiento la satisfacción del derecho de acceso en el plazo de tres meses y sin dilaciones indebidas.", "Se exige al responsable del tratamiento la satisfacción del derecho de acceso sin importar el plazo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 1, "El Gobierno dirige:", "La Administración civil y militar.", "La política interior y exterior.", "La defensa del Estado.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 2, "El presidente del Gobierno dirige la acción de éste y coordina las funciones de los demás miembros del Gobierno:", "Sin perjuicio de la competencia y responsabilidad directa de los demás miembros del Gobierno en su organización.", "Sin perjuicio de la competencia y responsabilidad directa de los demás miembros del Gobierno en su gestión.", "Sin perjuicio de la competencia y responsabilidad indirecta de los demás miembros del Gobierno en su organización.", "Con el perjuicio de la competencia y responsabilidad directa de los demás miembros del Gobierno en su gestión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 3, "Los miembros del Gobierno:", "No podrán ejercer otras funciones representativas que las propias del mandato imperativo.", "Podrán ejercer otras funciones representativas, tanto derivadas del mandato parlamentario como las que no lo sean.", "No podrán ejercer otras funciones representativas que las propias del mandato parlamentario.", "No podrán ejercer otras funciones representativas que las propias del mandato gubernativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 4, "Los Miembros del Gobierno:", "Podrán ejercer otra función pública, pero no podrán ejercer actividad profesional o mercantil alguna.", "No podrán ejercer otra función pública que no derive de su cargo, ni actividad profesional o mercantil alguna.", "Únicamente podrán ejercer actividades profesionales o mercantiles, no siendo posible ejercer otra función pública que no derive de su cargo.", "Únicamente podrán ejercer otra función pública que no derive de su cargo, o alguna actividad profesional o mercantil, cuando sean autorizados por el Consejo de ministros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 5, "El rey, previa consulta con los representantes designados por los grupos políticos con representación parlamentaria, y a través del presidente del Congreso, propondrá un candidato a la Presidencia del Gobierno:", "Después de cada renovación de las Cortes Generales, y en los demás supuestos que la ley establezca.", "Solamente después de cada renovación de las Cortes Generales.", "Después de cada renovación del Congreso de los Diputados  y en los demás supuestos constitucionales en que así proceda.", "Después de cada renovación de las Cortes Generales, y en los demás supuestos constitucionales en que así proceda y cuando se presente una moción de censura."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 6, "En primera votación, a tenor de lo previsto en el artículo 99 de la Constitución, la confianza al candidato a la Presidencia del Gobierno se entiende otorgada:", "Con la mayoría absoluta de los miembros del Congreso de los Diputados.", "Con la mayoría simple de los miembros del Congreso de los Diputados.", "Con la mayoría de dos tercios de los miembros del Congreso de los Diputados.", "Con la mayoría de tres quintos de los miembros del Congreso de los Diputados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 7, "Si en primera votación el candidato a la Presidencia del Gobierno no obtiene la confianza del Congreso de los Diputados:", "Se someterá la misma propuesta a una nueva votación setenta y dos horas después de la anterior.", "Se someterá la misma propuesta a una nueva votación cuarenta y ocho horas después de la anterior.", "Se someterá la misma propuesta a una nueva votación veinticuatro horas después de la anterior.", "Se repetirá la votación en la misma sesión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 8, "Si ninguno de los candidatos a la Presidencia del Gobierno obtiene la confianza del Congreso en el plazo previsto en el artículo 99.5 de la Constitución:", "En el artículo 99.5 no se recoge ningún plazo en relación a la elección del presidente del Gobierno.", "El rey disolverá ambas Cámaras y convocará nuevas elecciones.", "El rey nombrará presidente del Gobierno al candidato que hubiera obtenido mayor apoyo parlamentario.", "El rey disolverá el Congreso de los Diputados y convocará nuevas elecciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 9, "Conforme al artículo 101 de la Constitución, el Gobierno cesa:", "Tras la celebración de elecciones generales.", "En los casos de pérdida de la confianza parlamentaria previstos en la Constitución.", "A propuesta del presidente del Gobierno.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 10, "Señale la respuesta correcta:", "La responsabilidad criminal del presidente y de los demás miembros del Gobierno será exigible, en todo caso, ante la Sala de lo Penal del Tribunal Supremo.", "La responsabilidad del presidente y de los demás miembros del Gobierno será exigible, en todo caso, ante la Sala de lo Penal del Tribunal Supremo.", "La responsabilidad civil  y criminal del presidente y de los demás miembros del Gobierno será exigible, en todo caso, ante la Sala de lo Penal del Tribunal Supremo.", "La responsabilidad civil y criminal del presidente y de los demás miembros del Gobierno será exigible, en todo caso, ante la Sala de lo Civil del Tribunal Supremo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 11, "La acusación por traición o por cualquier delito contra la seguridad del Estado, en el ejercicio de sus funciones, de los miembros del Gobierno:", "Podrá ser planteada por iniciativa de la mayoría simple de los miembros del Congreso.", "Podrá ser planteada por iniciativa de la mayoría absoluta de los miembros del Congreso.", "Podrá ser planteada por iniciativa de la cuarta parte de los miembros del Congreso.", "Podrá ser planteada por iniciativa de la quinta parte de los miembros del Congreso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 12, "Según el artículo 103 de la Constitución, se regularán por ley:", "El sistema de compatibilidades de los funcionarios públicos.", "El acceso a la función pública de acuerdo con los principios de mérito, capacidad y compatibilidad.", "El estatuto de los funcionarios públicos.", "Las peculiaridades del sistema sanitario de los funcionarios públicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 13, "Las Fuerzas y Cuerpos de Seguridad tienen como misión:", "Defender el ordenamiento constitucional.", "Defender la integridad territorial.", "Garantizar la seguridad ciudadana.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 14, "Señala la respuesta correcta. Conforme al artículo 105 de la Constitución, la ley regulará:", "La audiencia de los ciudadanos, directamente o a través de las organizaciones y asociaciones reconocidas por la ley, en el procedimiento de elaboración de disposiciones administrativas que les afecten.", "El acceso de los ciudadanos a los archivos y registros administrativos, salvo en lo que afecte a la seguridad y defensa del Estado, la averiguación de los delitos y la intimidad de las personas.", "El procedimiento, a través del cual deben producirse los actos administrativos, garantizando, cuando proceda, la audiencia al interesado.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 15, "La potestad reglamentaria y la legalidad de la actuación administrativa es controlada:", "Por los Juzgados y Tribunales.", "Por la administración de Justicia.", "Por los Jueces.", "Por los Tribunales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 16, "Corresponde proponer al rey la disolución del Congreso, del Senado o de las Cortes Generales:", "Al presidente del Gobierno.", "Al presidente del Congreso de los Diputados, al del Senado o al de las Cortes Generales, según corresponda.", "Al Consejo de ministros.", "Al Letrado Mayor de las Cortes Generales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 17, "Corresponde proponer al rey la convocatoria de un referéndum consultivo:", "Al presidente del Gobierno, previa autorización del Congreso de los Diputados.", "Al Consejo de ministros, previa autorización del Congreso de los Diputados.", "Al presidente del Gobierno, previa autorización del Consejo de ministros.", "Al Consejo de ministros, previa autorización del presidente del Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 18, "Como norma general, corresponde convocar, presidir y fijar el orden del día de las reuniones del Consejo de ministros:", "Al Consejo de ministros", "Al presidente del Gobierno.", "Al rey.", "Al Secretario del Consejo de ministros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 19, "Corresponde proponer al rey el nombramiento y la separación de los vicepresidentes y de los ministros:", "Al presidente del Congreso de los Diputados.", "Al Consejo de ministros.", "Al presidente del Gobierno.", "Al presidente del Consejo de Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 20, "La aprobación de los Reales Decretos-leyes y los Reales Decretos Legislativos corresponde:", "Al Consejo de Estado.", "Al presidente del Gobierno.", "Al Consejo de ministros.", "A los ministros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 21, "Los Tratados Internacionales son remitidos a las Cortes Generales en los términos previstos en los artículos 94 y 96.2 de la Constitución:", "Por el Presidente del Gobierno.", "Por el Consejo de ministros.", "Por el Presidente del Congreso de los Diputados.", "Por el Rey."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 22, "Corresponde proponer al Congreso de los diputados la declaración del estado de sitio:", "Al Senado.", "Al Congreso de los Diputados.", "Al Consejo de ministros.", "Al Congreso de los Diputados y al Senado, en sesión conjunta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 23, "Los reglamentos para el desarrollo y ejecución de las leyes corresponde:", "Al presidente del Gobierno, previa deliberación del Consejo de ministros.", "Al Consejo de ministros, a propuesta del presidente del Gobierno.", "Al presidente del Gobierno, previo dictamen del Consejo de Estado.", "Al Consejo de ministros, previo dictamen del Consejo de Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 24, "El examen de las cuestiones de carácter general que tengan relación con varios Departamentos Ministeriales que integran la Comisión corresponde:", "Al ministro de la Presidencia", "A la Comisión General de Secretarios, Subsecretarios y Directores Generales.", "A las Comisiones Delegadas del Gobierno.", "Al Consejo de ministros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 25, "Salvo los nombramientos, ceses, ascensos a cualquiera de los empleos de la categoría de oficiales generales y los que, excepcionalmente y por razones de urgencia, deban ser sometidos directamente al Consejo de ministros, el examen de todos los demás asuntos que vayan a someterse a aprobación del Consejo de ministros es una competencia:", "De la Comisión General de Secretarios de Estado y Subsecretarios.", "De las Comisiones Delegadas del Gobierno.", "Del Consejo de Estado.", "Del ministro de la Presidencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 26, "¿A qué Comisión corresponde el análisis o discusión de aquellos asuntos que, sin ser competencia del Consejo de ministros o sus Comisiones Delegadas, afecten a varios Ministerios y sean sometidos a la Comisión por su presidente?:", "A la Comisión General del Ministerio de la Presidencia.", "A la Comisión General de Secretarios de Estado y Subsecretarios.", "A la Comisión General de Directores Generales.", "A la Comisión Especial del Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 27, "La función de colaboración con las Secretarías Técnicas de las Comisiones Delegadas del Gobierno corresponde:", "Al Secretariado del Gobierno.", "Al ministro de la Presidencia.", "Al presidente del Gobierno, en ausencia del vicepresidente del Gobierno.", "Al vicepresidente del Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 28, "La tramitación de los actos y disposiciones del rey, cuyo refrendo corresponde al presidente del Gobierno es una función:", "Del ministro de la Presidencia", "Del presidente del Gobierno.", "Del Secretariado del Gobierno.", "Del presidente del Congreso de los Diputados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 29, "¿Quién propondrá al ministro de la Presidencia la aprobación de las instrucciones que han de seguirse para la tramitación de los asuntos ante los órganos colegiados del Gobierno?", "El Secretario de Estado de Presidencia.", "El Secretariado del Gobierno.", "El Jefe de Gabinete del presidente del Gobierno.", "El ministro competente por razón de la materia a tratar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 30, "¿ Quién convoca el Consejo de ministros?", "El ministro de la Presidencia.", "El presidente del Gobierno.", "El Secretariado del Gobierno.", "El Gabinete de la Presidencia del Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 31, "Actuar como Secretario de las reuniones del Consejo de ministros es función:", "Del Secretariado del Gobierno.", "Del ministro de la Presidencia.", "Del vicepresidente del Gobierno.", "Del Gabinete del presidente del Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 32, "Coordinar el Plan Anual Normativo, que se recoge en la Ley 50/1997, de 27 de noviembre, del Gobierno, es una función:", "Del presidente del Gobierno.", "Del ministro de la Presidencia.", "Del ministro competente por razón de la materia.", "Del Secretariado del Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 33, "¿Cuál de las siguientes funciones no le corresponde al Consejo de ministros, según el artículo 5 de la Ley 50/1997, de 27 de noviembre, del Gobierno?", "Crear, modificar y suprimir los órganos directivos de los Departamentos Ministeriales.", "Aprobar los Reales Decretos-leyes y los Reales Decretos Legislativos.", "Aprobar  proyecto de Ley de Presupuestos Generales del Estado.", "Resolver los conflictos de atribuciones que puedan surgir entre los diferentes Ministerios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 34, "De acuerdo con el artículo 5 de la Ley 50/1997, corresponde al Consejo de Ministros:", "Dirigir la política de defensa.", "Representar al Gobierno.", "Declarar los estados de alarma y de excepción.", "Crear, modificar y suprimir, por Real Decreto, los Departamentos Ministeriales y las Secretarías de Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 35, "Según la Ley 50/1997, el Gobierno se compone:", "Del presidente, del vicepresidente o vicepresidentes, en su caso y de los ministros. salvo aquellos que no tengan cartera ministerial.", "Del presidente, del vicepresidente o vicepresidentes, en su caso, y de los ministros.", "Del presidente, de los ministros y de los Secretarios de Estado.", "Del presidente, del vicepresidente o vicepresidentes, en su caso, de los ministros y de los Secretarios de Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 36, "El presidente del Gobierno en funciones no podrá ejercer una de las siguientes facultades:", "Interponer recurso de inconstitucionalidad.", "Resolver conflictos de atribuciones entre los diferentes ministerios.", "Convocar, presidir y fijar el orden del día de las reuniones del Consejo de ministros.", "Proponer al rey la convocatoria de referéndum consultivo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 37, "No son órganos de colaboración y apoyo al Gobierno, teniendo en cuenta la Ley 50/1997, del Gobierno:", "La Comisión General de Secretarios de Estado y Subsecretarios.", "Los vicepresidentes.", "Los Secretarios de Estado.", "El Secretariado del Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 38, "La creación, modificación y supresión de las Comisiones Delegadas del Gobierno será acordada:", "Por el presidente del Gobierno, mediante Real Decreto, a propuesta del Consejo de ministros.", "Por el Consejo de ministros, mediante Real Decreto, a propuesta del presidente del Gobierno.", "Por el presidente del Gobierno, mediante Real Decreto.", "Por el Consejo de ministros, mediante Real Decreto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 39, "Según la Ley 50/1997, de 27 de noviembre, del Gobierno, en las reuniones del Consejo de ministros:", "No podrán asistir los Secretarios de Estado, en ningún caso.", "Podrán asistir los Secretarios de Estado y excepcionalmente, otros altos cargos, cuando sean convocados para ello.", "Deberán asistir los Secretarios de Estado, en los casos de ausencia del ministro correspondiente.", "Únicamente, podrán asistir, además de los miembros del Gobierno, los Secretarios de Estadio cuando sean convocados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 40, "Según el artículo 20 de la Ley 50/1997, del Gobierno, en ningún caso son delegables por el Gobierno:", "Las competencias administrativas del Consejo de ministros en las Comisiones Delegadas del Gobierno.", "Las competencias de los ministros en los Secretarios de Estado.", "Las competencias atribuidas directamente por la Constitución.", "Las competencias del presidente del Gobierno en otros miembros del Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 41, "¿Cómo se denomina el Título V de la Constitución Española?", "De las relaciones entre el Gobierno y las Cortes Generales.", "De las relaciones entre el Gobierno, la Administración y las Cortes Generales.", "De las relaciones entre el Gobierno y la Administración.", "De las Cortes Generales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 42, "Las Cámaras y sus Comisiones podrán recabar la información y ayuda que precisen del Gobierno y de sus Departamentos:", "A través del presidente del Gobierno.", "A través de las Mesas de las Cámaras.", "A través de los presidentes de las Cámaras y de los de las Comisiones.", "A través de los presidentes de las Cámaras."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 43, "Podrán reclamar la presencia de los miembros del Gobierno:", "Únicamente el Congreso de los Diputados.", "Las Cámaras y sus Comisiones.", "Únicamente las Cámaras.", "Únicamente el Congreso de los Diputados y sus Comisiones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 44, "Según el texto del artículo 110 de la Constitución Española y en relación con los miembros del Gobierno:", "Podrán reclamar la presencia de los miembros de las Cámaras.", "No tendrán la facultad de hacerse oír en las Cámaras y sus Comisiones.", "Tendrán acceso a las sesiones de las Cámaras y sus Comisiones.", "Podrán solicitar que cualquier persona que consideren conveniente informe ante las Cámaras y sus Comisiones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 45, "Según el texto literal del artículo 111 de la Constitución ¿qué podrá dar lugar a una moción en la que la Cámara manifieste su posición?", "Toda intervención.", "Toda interpelación.", "Toda pregunta.", "Toda interpelación o pregunta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 46, "El presidente del Gobierno puede plantear la cuestión de confianza:", "Sobre un asunto de interés público.", "Sobre una declaración legislativa general.", "Sobre una declaración de política particular", "Sobre su programa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 47, "¿Cuándo se entenderá otorgada la confianza al presidente del Gobierno una vez presentada la cuestión de confianza?", "Cuando vote a favor de la misma la mayoría simple de los Diputados.", "Cuando vote en contra de la misma la mayoría simple de los Diputados.", "Cuando vote a favor de la misma la mayoría absoluta de los Diputados.", "Cuando vote a favor de la misma la mayoría absoluta de los miembros de ambas Cámaras."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 48, "El Congreso de los Diputados puede exigir la responsabilidad política del Gobierno mediante la adopción de una moción de censura:", "Por mayoría simple.", "Por mayoría absoluta.", "Por mayoría de tres quintos de sus miembros.", "Por mayoría de dos tercios de sus miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 49, "En relación a la moción de censura:", "En el primer día desde su presentación podrán presentarse mociones alternativas.", "En los dos primeros días desde su presentación podrán presentarse mociones alternativas.", "En los tres primeros días desde su presentación podrán presentarse mociones alternativas.", "En los cuatro primeros días desde su presentación podrán presentarse mociones alternativas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 50, "Señala la respuesta correcta. Según el artículo 114 de la Constitución, si el Congreso niega su confianza al Gobierno, ocurrirá una de las siguientes situaciones:", "El candidato incluido en la cuestión de confianza se entenderá investido de la confianza de la Cámara.", "Se tendrá  que proceder a la designación de presidente del Gobierno, según lo dispuesto en el artículo 99 de la Constitución.", "El rey procederá a nombrar presidente del Gobierno al candidato incluido en la cuestión de confianza.", "Se disolverá el Congreso de los Diputados y se convocarán elecciones a esta Cámara."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 51, "El presidente del Gobierno puede proponer la disolución del Senado:", "Previo Acuerdo del Consejo de ministros.", "Previa deliberación de los Portavoces de los Grupos Parlamentarios de la Cámara.", "Previa deliberación del Consejo de ministros.", "Bajo su exclusiva responsabilidad y sin ningún otro trámite."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 52, "Los estados de alarma, de excepción y de sitio:", "El estado de alarma se regulará mediante un Real Decreto-Ley y los estados de excepción y de sitio mediante una Ley orgánica.", "Se regularán mediante una Ley ordinaria.", "Se regularán mediante una Ley orgánica.", "Se regulan, en todos sus términos, en la propia Constitución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 53, "El estado de alarma será declarado:", "Por la mayoría simple del Congreso de los Diputados.", "Mediante Decreto del presidente del Gobierno.", "Por la mayoría absoluta del Congreso de los Diputados.", "Mediante Decreto acordado en un Consejo de ministros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 54, "Señala la respuesta correcta. Conforme al artículo 116 de la Constitución y en relación con el estado de alarma:", "Se dará cuenta de su prórroga por parte del Gobierno a las Cortes Generales.", "Su prórroga por parte del Gobierno será inmediatamente comunicada al Congreso de los Diputados.", "No es posible prorrogar el plazo fijado inicialmente por el Gobierno, en ningún caso.", "Es necesaria la autorización del Congreso de los Diputados para prorrogar el plazo máximo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 55, "El estado de excepción será declarado:", "Por la mayoría simple del Congreso de los Diputados.", "Mediante una Ley orgánica.", "Mediante Decreto acordado en un Consejo de ministros.", "Por la mayoría absoluta del Congreso de los Diputados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 56, "El ámbito territorial, la duración y las condiciones del estado de sitio lo determina:", "El Congreso de los Diputados, a propuesta del Gobierno.", "El Congreso de los Diputados.", "El Gobierno, de acuerdo con las Cortes Generales.", "El presidente del Gobierno, a propuesta del Consejo de ministros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 57, "Si se declara alguno de los estados definidos en el artículo 116 de la Constitución:", "Quedarán automáticamente convocadas las Cámaras si no estuvieren en período de sesiones.", "Quedará automáticamente convocado el Congreso de los Diputados si no estuviere en período de sesiones, pudiendo el Gobierno convocar también el Senado.", "Si las Cámaras no estuvieran en período de sesiones, pasarán a ejercer sus funciones las Diputaciones Permanentes durante la duración de dichos estados.", "Si las Cámaras no estuvieran en período de sesiones, pasarán a ejercer sus funciones las Mesas de cada Cámara durante la duración de dichos estados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 58, "El impulso y la supervisión, con carácter general, de la actividad de los restantes órganos de la Administración General del Estado y sus Organismos Públicos en el territorio de una Comunidad Autónoma corresponde:", "Al Director General.", "Al Delegado del Gobierno.", "Al Delegado Autonómico.", "Al Subdelegado del Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 59, "La Administración del Estado está integrada por:", "Por órganos jerárquicamente ordenados.", "Por órganos centrales.", "Por órganos unipersonales y colegiados.", "Por órganos de los diferentes entes territoriales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 60, "Los contratos relativos a los asuntos propios de su Departamento son firmados en nombre del Estado:", "Por el presidente del Gobierno.", "Por el rey.", "Por los ministros y los Secretarios de Estado.", "Por los ministros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 61, "Los órganos de la Administración General del Estado que actúan como instrumento de comunicación con los demás Departamentos ministeriales son:", "Los ministros.", "Los Secretarios de Estado.", "Los Secretarios Generales Técnicos.", "Los Subsecretarios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 62, "Las disposiciones y resoluciones de los ministros adoptan la forma:", "De decretos.", "De órdenes.", "De decretos leyes.", "De decretos legislativos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 63, "El anteproyecto de ley de los Presupuestos Generales del Estado es elaborado:", "Por las Cortes Generales.", "Por el Congreso de los Diputados.", "Por el Consejo de ministros.", "Por el Ministerio competente en materia de hacienda."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("local", "A1", 3, 64, "Si la Ley de presupuestos Generales del Estado no fuera aprobada por las Cortes antes del primer día del ejercicio económico en que haya de regir:", "Se transferirán las cantidades sobrantes de ejercicios anteriores.", "Se publicará un anexo complementario de validez temporal.", "Se adecuará , provisionalmente, un programa de ingresos y gastos.", "Se considerarán automáticamente prorrogados los del ejercicio anterior."); 
